INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('photovoltaik-foerderung-2027-speicher-statt-kleine-anlagen','Photovoltaik-Förderung 2027: Speicher statt kleiner PV-Anlagen','Die Photovoltaik-Förderung des Bundes wird ab 2027 umgebaut: Statt kleiner Dachanlagen stehen Stromspeicher im Fokus, das „Klick-Rennen“ um Fördertickets soll enden.','Die Photovoltaik-Förderung 2027 wird grundlegend neu aufgestellt: Wirtschaftsminister Wolfgang Hattmannsdorfer (ÖVP) hat im August angekündigt, dass der Bund künftig vor allem Stromspeicher und intelligentes Energiemanagement unterstützt und die breite Förderung kleiner Dachanlagen auslaufen lässt. Für Hausbesitzer, die heuer oder im kommenden Jahr eine Anlage planen, ist das eine wichtige Weichenstellung.

## Photovoltaik-Förderung 2027: Was das Ministerium plant

Als Begründung nennt das Ministerium die Erfahrungen aus dem Hitzesommer. An sonnigen Tagen wird zu Mittag so viel Solarstrom erzeugt, dass die Großhandelspreise tief fallen, während am Abend teurer Strom zugekauft werden muss. Laut Bericht lag der Großhandelspreis an einem Samstag im August zwischen 10 und 16 Uhr bei rund 14 Euro pro Megawattstunde und stieg am Abend auf etwa 180 Euro. Mehr Speicher sollen den eigenen Solarstrom über den Tag verteilen, die Netze entlasten und Importe reduzieren.

Gefördert werden sollen nach der Reform des Erneuerbaren-Ausbau-Gesetzes (EAG) vor allem:

- intelligente Speicher und Energiemanagementsysteme,
- die Nachrüstung von Batterien bei bestehenden PV-Anlagen (eigener Bonus),
- ein Zusatzbonus für europäische Produktion zentraler Komponenten,
- Sonderformen wie gebäudeintegrierte PV, Agri-PV, Überdachungen von Parkplätzen, schwimmende Anlagen und PV auf Lärmschutzwänden.

## Ende des Klick-Rennens bei der PV-Förderung

Besonders umstritten war bisher das Vergabeverfahren nach dem Prinzip „First come, first served“. Bei früheren Fördercalls waren die Mittel teils nach wenigen Sekunden vergeben, wer zu spät klickte, ging leer aus. Künftig soll der Antrag erst nach Installation und Rechnungslegung gestellt werden – ähnlich wie beim Handwerkerbonus. Damit entfällt der Wettlauf um Tickets, gleichzeitig tragen Bauherren die Vorfinanzierung.

Der Branchenverband PV Austria begrüßt die Richtung, drängt aber auf rasche, konkrete Regeln und fordert zusätzlich steuerliche Erleichterungen. Hattmannsdorfer verlangt von der Regulierungsbehörde E-Control Nachbesserungen bei den Kriterien, wann ein Speicher als „systemdienlich“ gilt.

## Was bei der PV-Förderung 2026 noch gilt

Für heuer gilt noch das bisherige System des EAG-Investitionszuschusses. Laut Übersicht der Raiffeisenbank liegen die Fördersätze je nach Kategorie und Anlagengröße bei rund 120 bis 150 Euro pro Kilowatt-Peak. Wer zusätzlich einen Speicher errichtet oder nachrüstet, kann bis zu 150 Euro pro kWp zusätzlich erhalten. Dazu kommt der Made-in-Europe-Bonus: Für jede in Europa gefertigte Hauptkomponente – Module, Wechselrichter, Speicher – gibt es zehn Prozent mehr, maximal 30 Prozent. Der Bonus muss bereits beim Antrag gewählt werden.

Der letzte Fördercall nach altem Muster startete am 8. Oktober. Zusätzlich bieten mehrere Bundesländer eigene Programme an, deren Bedingungen sich unterscheiden.

## Was Hausbesitzer jetzt tun sollten

- **Planung nicht übereilen:** Wer heuer keinen Fördertermin mehr erreicht, sollte die finalen Richtlinien für 2027 abwarten, bevor Verträge unterschrieben werden.
- **Speicher mitdenken:** Eine Anlage, die später um eine Batterie erweitert werden kann, passt besser zur neuen Förderlogik.
- **Vorfinanzierung klären:** Wenn Zuschüsse erst nach der Rechnung fließen, braucht es Eigenmittel oder eine Zwischenfinanzierung.
- **Fachbetrieb einbinden:** Seriöse Installateure kennen die aktuellen Fristen der EAG-Abwicklungsstelle und der Länder.

Die genauen Fördersätze für 2027 stehen noch nicht fest. Verbindlich sind ausschließlich die Richtlinien des Bundes und der Länder, sobald sie veröffentlicht werden.','energie','Förderungen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/photovoltaik-foerderung-2027-speicher-statt-kleine-anlagen.webp','Salzburg24','https://www.salzburg24.at/news/oesterreich/photovoltaik-foerderung-kuenftig-fuer-speicher-statt-kleiner-pv-anlagen-art-335575','published','2026-09-23T05:50:00.000Z','2026-10-22T00:17:07.867Z','Photovoltaik-Förderung 2027: Speicher statt Klick-Rennen','Photovoltaik-Förderung 2027: Der Bund fördert künftig Speicher statt kleiner PV-Anlagen. Was 2026 noch gilt und was sich ändert – jetzt informieren.','Photovoltaik-Förderung 2027','["Photovoltaik-Förderung 2027","PV Förderung Speicher","EAG Investitionszuschuss","Stromspeicher Förderung Österreich","pv förderung 2027 kleine anlagen","made in europe bonus photovoltaik","pv fördercall klick rennen ende","batteriespeicher nachrüsten förderung"]','Photovoltaik-Förderung 2027: Batteriespeicher im Technikraum eines modernen Einfamilienhauses in Österreich','Photorealistic editorial photo of a modern wall-mounted home battery storage unit in a bright utility room of an Austrian single-family house, cables neatly routed to an inverter, soft morning light through a small window, no text, no logos, no readable signs, no people','[{"q":"Wird es 2027 noch eine Förderung für kleine PV-Anlagen geben?","a":"Laut Ankündigung des Wirtschaftsministeriums läuft die breite Förderung klassischer kleiner Dachanlagen aus. Gefördert werden sollen vor allem Speicher, Energiemanagement und Sonderformen wie gebäudeintegrierte PV."},{"q":"Wie hoch ist die PV-Förderung 2026?","a":"Der EAG-Investitionszuschuss liegt 2026 je nach Kategorie bei rund 120 bis 150 Euro pro kWp, für Speicher kommen bis zu 150 Euro pro kWp dazu. Verbindlich sind die Angaben der EAG-Abwicklungsstelle."},{"q":"Was ändert sich beim Antrag?","a":"Das bisherige Prinzip „wer zuerst klickt“ soll fallen. Anträge sollen künftig erst nach Installation und Rechnungslegung gestellt werden, ähnlich wie beim Handwerkerbonus."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('waermepumpe-im-bestand-eignung-worauf-achten','Wärmepumpe im Bestand: Eignung prüfen und worauf es ankommt','Eine Wärmepumpe funktioniert auch in vielen älteren Häusern. Entscheidend sind Vorlauftemperatur, Heizkörper und eine saubere Heizlastberechnung – nicht das Baujahr.','Eine Wärmepumpe im Bestand ist längst keine Ausnahme mehr: Auch in Häusern aus den 1960er- bis 1990er-Jahren laufen heute viele Anlagen effizient. Ob sich ein konkretes Gebäude eignet, hängt aber weniger vom Baujahr ab als von einigen messbaren Faktoren. Wer sie vor dem Kauf prüft, vermeidet teure Fehlplanungen und hohe Stromrechnungen.

## Wärmepumpe im Bestand: Die Vorlauftemperatur entscheidet

Der wichtigste Wert ist die Vorlauftemperatur, also wie heiß das Heizungswasser sein muss, damit die Räume an kalten Tagen warm werden. Je niedriger dieser Wert, desto effizienter arbeitet die Wärmepumpe. Als Faustregel gilt: Bis etwa 55 Grad ist ein wirtschaftlicher Betrieb gut möglich, ideal sind 35 bis 45 Grad. Moderne Geräte mit dem Kältemittel Propan (R290) erreichen zwar auch höhere Temperaturen, die Effizienz sinkt dann aber deutlich.

Ein einfacher Selbsttest: Reduzieren Sie in einer kalten Woche die Vorlauftemperatur am bestehenden Kessel schrittweise. Bleibt es in allen Räumen behaglich, ist das ein gutes Zeichen. Werden einzelne Zimmer zu kühl, liegt der Engpass meist bei den dortigen Heizkörpern.

## Heizkörper und Fußbodenheizung im Altbau

Eine Fußbodenheizung ist keine Voraussetzung. Entscheidend ist die Fläche, über die Wärme abgegeben wird. Große Plattenheizkörper oder alte Gussradiatoren können gut geeignet sein. Zu kleine Heizkörper lassen sich gezielt gegen größere Modelle oder Gebläsekonvektoren tauschen – das ist meist deutlich günstiger als eine komplette Umrüstung.

Wichtig ist außerdem ein hydraulischer Abgleich. Er sorgt dafür, dass jeder Heizkörper die richtige Wassermenge erhält, und senkt die nötige Vorlauftemperatur oft spürbar.

## Heizlast berechnen statt schätzen

Viele alte Kessel sind überdimensioniert. Wer die neue Wärmepumpe einfach nach der Leistung des alten Geräts auswählt, kauft häufig zu groß. Das verteuert die Anschaffung und führt zu häufigem Takten. Eine Heizlastberechnung nach Norm durch einen Fachbetrieb ermittelt, wie viel Leistung das Haus tatsächlich braucht. Als Anhaltspunkt dient auch der bisherige Öl- oder Gasverbrauch der letzten Jahre.

## Checkliste für die Wärmepumpe im Altbau

- **Verbrauch dokumentieren:** Öl- oder Gasrechnungen der letzten drei Jahre sammeln.
- **Vorlauftemperatur testen:** Im Winter mit reduziertem Wert heizen und Räume beobachten.
- **Heizkörper prüfen:** Größe und Typ je Raum notieren.
- **Gebäudehülle ansehen:** Oberste Geschoßdecke, Kellerdecke und Fenster sind oft günstige Hebel.
- **Aufstellort klären:** Abstand zu Nachbarn, Schallschutz und Fundament für das Außengerät.
- **Stromanschluss prüfen:** Gegebenenfalls Abstimmung mit dem Netzbetreiber.
- **Warmwasser planen:** Speichergröße an den tatsächlichen Bedarf anpassen.

## Effizienz und Kosten realistisch einschätzen

Die Jahresarbeitszahl (JAZ) zeigt, wie viel Wärme pro Kilowattstunde Strom erzeugt wird. Im gut geplanten Bestand sind Werte um drei oder höher realistisch, bei hohen Vorlauftemperaturen liegt sie darunter. Eine Photovoltaikanlage kann einen Teil des Stroms liefern, vor allem in der Übergangszeit.

Für den Umstieg von Öl oder Gas gibt es Förderungen des Bundes und vieler Bundesländer. Die Aktion Kesseltausch des Bundes öffnet laut Klimaschutzministerium am 2. November 2026 wieder, die Bedingungen ändern sich jedoch laufend. Aktuelle Werte sollten vor der Auftragsvergabe bei der Förderstelle und beim Land geprüft werden.

Fazit: Eine Wärmepumpe im Bestand ist in vielen Fällen sinnvoll – vorausgesetzt, Vorlauftemperatur, Heizflächen und Heizlast werden vor dem Kauf ehrlich geprüft.','energie','Heizen',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/waermepumpe-im-bestand-eignung-worauf-achten.webp',NULL,NULL,'published','2026-09-24T07:12:00.000Z','2026-10-22T00:17:07.868Z','Wärmepumpe im Bestand: So prüfen Sie die Eignung','Wärmepumpe im Bestand: Vorlauftemperatur, Heizkörper, Heizlast und Dämmung entscheiden. So prüfen Sie Ihr Altbau-Haus richtig – mit Checkliste.','Wärmepumpe im Bestand','["Wärmepumpe im Bestand","Wärmepumpe Altbau","Wärmepumpe Eignung","Vorlauftemperatur Wärmepumpe","wärmepumpe altbau heizkörper geeignet","heizlastberechnung wärmepumpe bestand","jahresarbeitszahl wärmepumpe altbau","wärmepumpe ohne fußbodenheizung"]','Wärmepumpe im Bestand: Außengerät neben einem älteren Einfamilienhaus im Herbst','Photorealistic editorial photo of an air-to-water heat pump outdoor unit standing on a concrete base beside a renovated 1960s Austrian brick house with a garden, overcast autumn afternoon, leaves on the lawn, no text, no logos, no readable signs, no people','[{"q":"Funktioniert eine Wärmepumpe mit normalen Heizkörpern?","a":"Ja, wenn die Heizkörper groß genug sind und das Haus mit einer Vorlauftemperatur von etwa 55 Grad oder weniger warm wird. Oft reicht es, einzelne Heizkörper zu tauschen."},{"q":"Muss ein Altbau vorher gedämmt werden?","a":"Nicht zwingend. Günstige Maßnahmen wie die Dämmung der obersten Geschoßdecke oder neue Fenster senken aber die Heizlast und damit Gerätegröße und Stromverbrauch."},{"q":"Wie finde ich heraus, ob mein Haus geeignet ist?","a":"Mit einer Heizlastberechnung durch einen Fachbetrieb und einem Test: Wird es im Winter auch mit reduzierter Kesseltemperatur warm, ist das ein gutes Zeichen."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pv-foerdercall-oktober-2026-eag-investitionszuschuss','PV-Fördercall Oktober 2026: Letzte Runde nach altem System','Am 8. Oktober startete der dritte und letzte PV-Fördercall des Jahres. Es ist zugleich die letzte Runde nach dem bisherigen System mit Ticketziehung.','Der PV-Fördercall im Oktober 2026 ist gestartet: Seit dem 8. Oktober um 17 Uhr können Interessenten bei der EAG-Abwicklungsstelle wieder Tickets für den Investitionszuschuss für Photovoltaikanlagen ziehen. Es handelt sich um den dritten Call des Jahres – und laut Ankündigung des Wirtschaftsministeriums um den letzten nach dem bisherigen Muster, bevor die Förderung ab 2027 umgestellt wird.

## PV-Fördercall: Die Termine im Überblick

Laut Information der Wirtschaftskammer gilt folgender Ablauf:

- **8. Oktober 2026, ab 17 Uhr:** Ticketziehung startet. Der Zeitpunkt der Ziehung gilt automatisch als Einreichzeitpunkt.
- **9. Oktober 2026, ab 8 Uhr:** Das Projekt kann mit allen Unterlagen eingereicht werden.
- **22. Oktober 2026:** Letzter Tag für die Einreichung.

Die WKO weist ausdrücklich darauf hin, dass ein gezogenes Ticket allein noch kein Förderantrag ist. Wer nach der Ticketziehung das Projekt nicht während des offenen Calls einreicht, verliert seinen Platz.

## Fördersätze beim EAG-Investitionszuschuss

Die Fördersätze werden nach Größe und Kategorie der Anlage gestaffelt. Laut Übersicht der Raiffeisenbank lagen sie 2026 bei rund 120 bis 150 Euro pro Kilowatt-Peak, für Speicher kommt ein Zuschlag hinzu. Zusätzlich gibt es einen Bonus für europäische Komponenten. Die verbindlichen Werte für diesen Call stehen in den Leitfäden der EAG-Abwicklungsstelle.

Die bisherigen Calls des Jahres liefen von 23. April bis 11. Mai sowie von 16. bis 30. Juni. Weil die Budgets begrenzt sind, waren Fördermittel in der Vergangenheit teils sehr schnell vergeben.

## Warum dieser PV-Fördercall der letzte seiner Art ist

Wirtschaftsminister Wolfgang Hattmannsdorfer hat im August eine Neuausrichtung angekündigt. Ab 2027 soll die breite Förderung kleiner Dachanlagen auslaufen. Im Mittelpunkt stehen dann Stromspeicher, Energiemanagement und Sonderformen wie gebäudeintegrierte PV. Anträge sollen künftig erst nach Installation und Rechnung gestellt werden, das bisherige Rennen um Tickets entfällt damit.

Für Haushalte bedeutet das: Wer eine klassische Dachanlage ohne Speicher plant und auf Bundesförderung angewiesen ist, hat mit diesem Call vorerst die letzte Gelegenheit nach den bisherigen Regeln.

Für Installateure ist die Lage ebenfalls angespannt. Viele Betriebe berichten seit Monaten von Kunden, die ihre Entscheidung vom Fördererfolg abhängig machen. Gelingt die Einreichung nicht, werden Projekte oft verschoben. Branchenvertreter mahnen deshalb, die neuen Regeln für 2027 möglichst früh zu veröffentlichen, damit es über den Winter nicht zu einem Auftragsloch kommt.

## Tipps für die Einreichung

- **Unterlagen vorbereiten:** Angebot, Zählpunktnummer und Anlagendaten sollten vor der Ticketziehung bereitliegen.
- **Kategorie richtig wählen:** Die Größe der Anlage bestimmt die Förderkategorie und damit den Satz.
- **Bonus gleich angeben:** Der Made-in-Europe-Bonus muss beim Antrag gewählt werden und lässt sich danach nicht mehr ändern.
- **Netzzugang klären:** Die Anmeldung beim Netzbetreiber ist ein eigener Schritt und sollte parallel laufen.
- **Landesförderungen prüfen:** Einige Bundesländer haben eigene Programme, die sich mit der Bundesförderung kombinieren lassen oder sie ausschließen.

## Was nach dem Call kommt

Die finalen Richtlinien für die Photovoltaik-Förderung 2027 sind noch nicht veröffentlicht. Branchenvertreter fordern rasche Klarheit, damit Installateure und Kunden planen können. Wer nicht zum Zug kommt, sollte die neuen Bedingungen abwarten und die Anlage so planen, dass ein Speicher später ergänzt werden kann.','energie','Photovoltaik',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/pv-foerdercall-oktober-2026-eag-investitionszuschuss.webp','WKO – Elektro-, Gebäude-, Alarm- und Kommunikationstechniker','https://www.wko.at/gewerbe-handwerk/elektro-gebaeude-alarm-kommunikation/foerdercall-fuer-photovoltaik','published','2026-10-08T15:42:00.000Z','2026-10-22T00:17:07.868Z','PV-Fördercall Oktober 2026: Termine und Ablauf','PV-Fördercall Oktober 2026: Ticketziehung ab 8. Oktober, Einreichung bis 22. Oktober. Was Antragsteller beachten müssen – alle Termine im Überblick.','PV-Fördercall','["PV-Fördercall","PV Förderung Oktober 2026","EAG Investitionszuschuss","Photovoltaik Fördercall","pv fördercall ticket ziehen","eag abwicklungsstelle antrag photovoltaik","pv förderung 2026 dritter call","photovoltaik förderung frist 22 oktober"]','PV-Fördercall: Laptop und Angebotsunterlagen für die Photovoltaik-Förderung am Küchentisch','Photorealistic editorial photo of a laptop on a wooden kitchen table showing an abstract blurred online form, next to printed solar panel quotes and a cup of coffee, evening lamp light in a Viennese apartment, no text, no logos, no readable signs, no people visible','[{"q":"Bis wann läuft der PV-Fördercall im Oktober 2026?","a":"Die Ticketziehung startete am 8. Oktober ab 17 Uhr, Projekte konnten ab 9. Oktober eingereicht werden. Letzter Tag für die Einreichung ist laut WKO der 22. Oktober 2026."},{"q":"Reicht ein Ticket als Förderantrag?","a":"Nein. Das Ticket sichert nur den Zeitpunkt. Der eigentliche Projektantrag muss innerhalb des offenen Calls vollständig eingereicht werden."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('stromnetztarife-2027-pv-wallbox-leistungspreis','Stromnetztarife 2027: Was der Leistungspreis für PV und Wallbox heißt','Ab 1. Jänner 2027 werden die Stromnetzgebühren umgebaut. Ein Leistungspreis ersetzt die Fixpauschalen – Haushalte mit Wallbox und PV-Speicher sollten sich vorbereiten.','Die Stromnetztarife 2027 bringen die größte Reform der Netzgebühren seit rund zwei Jahrzehnten. Die Regulierungsbehörde E-Control hat die neue Systemnutzungsentgelte-Grundsatzverordnung erlassen, sie wurde am 12. Oktober kundgemacht. Ab 1. Jänner 2027 zahlen Haushalte nicht mehr nur nach verbrauchten Kilowattstunden, sondern auch nach der höchsten Leistung, die sie aus dem Netz beziehen. Für Besitzer von Photovoltaikanlagen, Speichern und Wallboxen ist das relevant.

## Stromnetztarife 2027: Leistungspreis statt Fixpauschale

Bisher wurden die Netzgebühren laut Bericht zu rund 79 Prozent über den Arbeitspreis und zu 21 Prozent über Pauschalen verrechnet. Die Pauschalen entfallen nun und werden durch einen Leistungspreis ersetzt. Zunächst soll dieser Anteil bei etwa 30 bis 40 Prozent liegen, innerhalb von drei Jahren ist ein Verhältnis von 50 zu 50 geplant.

Gemessen wird mit dem Smart Meter: Maßgeblich ist der höchste Viertelstundenwert eines Kalendermonats, mindestens 2 kW. Bis 10 kW gilt der reguläre Leistungspreis, für jedes Kilowatt darüber wird der doppelte Satz fällig. Insgesamt sollen die Netzausbaukosten laut E-Control um rund 300 Millionen Euro pro Jahr sinken.

## Was die Reform für PV-Anlagen und Speicher bedeutet

Für die meisten Haushalte mit PV-Anlage ändert sich wenig. Interessant ist das bereits seit April 2026 geltende Sommerfenster: Zwischen 10 und 16 Uhr sind die Netzkosten im Sommerhalbjahr um rund 20 Prozent niedriger. Ab 1. Oktober 2027 kommt ein Winterfenster dazu, in dem von Oktober bis März zwischen 23 und 5 Uhr ein günstigerer Netztarif gilt.

Kritik kommt von den Erneuerbaren-Verbänden. Sie bemängeln vor allem die Regeln für Batteriespeicher. Laut E-Control werden Speicher nur dann von Netzentgelten befreit, wenn sie nachweislich netzdienlich betrieben werden. Photovoltaic Austria bezeichnete die Verordnung als „Batterieverzögerungs-Verordnung“, der Dachverband Erneuerbare Energie Österreich fordert flexiblere Rahmenbedingungen. Die Netzbetreiber halten die Reform dagegen für notwendig.

## Wallbox: Rabatt bei flexibler Netznutzung

Wer ein Elektroauto zu Hause lädt, sollte genauer hinsehen. Für steuerbare Anlagen wie Wallboxen ab 4 kW gibt es 75 Prozent Rabatt auf den Leistungspreis, wenn der Netzbetreiber die Leistung zweimal täglich für höchstens zwei Stunden drosseln darf. Diese Regelung ersetzt die bisherigen unterbrechbaren Tarife und ist laut Bericht für zehn Jahre garantiert. Wärmepumpen profitieren häufig von ihrer gleichmäßigen Last.

## So bereiten sich Haushalte auf die Stromnetztarife 2027 vor

- **Smart Meter prüfen:** Klären, ob die viertelstündliche Auslesung aktiviert ist (Opt-in).
- **Ladeleistung anpassen:** Die Wallbox auf etwa 4 kW zu begrenzen, kann Leistungsspitzen vermeiden.
- **Verbraucher staffeln:** Backofen, Durchlauferhitzer und Ladevorgang nicht gleichzeitig laufen lassen.
- **PV-Strom tagsüber nutzen:** Waschmaschine oder Speicherladung ins Sommerfenster legen.
- **Netzbetreiber kontaktieren:** Ab Ende 2026 informieren die Netzbetreiber über Tarife und die Anmeldung zur flexiblen Netznutzung.

Konkrete Beträge je Netzgebiet stehen noch aus, weil die zugehörige Tarifverordnung noch nicht veröffentlicht ist. Nachverrechnungen für die Vergangenheit gibt es nicht, bestehende Anschlüsse werden mit mindestens 10 kW angesetzt.','energie','Photovoltaik',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/stromnetztarife-2027-pv-wallbox-leistungspreis.webp','Salzburg24','https://www.salzburg24.at/news/oesterreich/neue-stromnetztarife-ab-2027-das-aendert-sich-fuer-oesterreichs-haushalte-art-341061','published','2026-10-13T07:15:00.000Z','2026-10-22T00:17:07.868Z','Stromnetztarife 2027: Leistungspreis, PV und Wallbox','Stromnetztarife 2027: E-Control führt einen Leistungspreis ein. Was das für Haushalte mit PV-Anlage, Speicher und Wallbox bedeutet – jetzt vorbereiten.','Stromnetztarife 2027','["Stromnetztarife 2027","Netzentgelte 2027","Leistungspreis Strom","E-Control Netztarife","netztarife 2027 wallbox 4 kw","leistungspreis smart meter viertelstunde","netzentgelte photovoltaik speicher","sommer nieder arbeitspreis snap"]','Stromnetztarife 2027: Wallbox im Carport mit Photovoltaik-Dach in der Dämmerung','Photorealistic editorial photo of a wall-mounted electric car charger in a modern Austrian carport with a compact car plugged in, solar panels visible on the carport roof, dusk with warm lights, no text, no logos, no readable signs, no people','[{"q":"Ab wann gelten die neuen Stromnetztarife?","a":"Die Umstellung beginnt am 1. Jänner 2027. Bis Mitte 2028 müssen alle Netzbetreiber das neue System umgesetzt haben."},{"q":"Wird Strom für Haushalte teurer?","a":"Laut E-Control bleibt das Gesamtaufkommen gleich, für durchschnittliche Haushalte ohne leistungsstarke Geräte ändert sich wenig. Wer ungesteuert mit hoher Leistung lädt, kann mehr zahlen."},{"q":"Was ist der Rabatt für flexible Netznutzung?","a":"Bei steuerbaren Anlagen wie Wallboxen ab 4 kW gibt es 75 Prozent Rabatt auf den Leistungspreis, wenn der Netzbetreiber die Leistung zweimal täglich bis zu zwei Stunden drosseln darf."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('kesseltausch-foerderung-november-2026-pauschalen','Kesseltausch-Förderung: Neustart am 2. November mit Pauschalen','Die Bundesförderung für den Tausch von Öl- und Gasheizungen öffnet am 2. November wieder – mit fixen Pauschalen und aus frei gewordenen Mitteln.','Die Kesseltausch-Förderung des Bundes geht in eine neue Runde: Ab 2. November 2026 können Besitzer von Ein- und Zweifamilienhäusern sowie Reihenhäusern wieder Anträge für den Umstieg von Öl oder Gas auf eine klimafreundliche Heizung stellen. Das gaben Umweltminister Norbert Totschnig und Wirtschaftsminister Wolfgang Hattmannsdorfer (beide ÖVP) im Rahmen der Sanierungsoffensive 2027 bekannt.

## Kesseltausch-Förderung: Diese Pauschalen gelten

Statt prozentueller Berechnungen gibt es für die neue Aktion fixe Beträge:

- **Wärmepumpe:** 5.000 Euro
- **Fernwärmeanschluss:** 4.000 Euro
- **Holzheizung:** 6.000 Euro

Der Bohrbonus für Erdwärmepumpen und der Solarbonus bleiben erhalten. Laut Ministerium werden die Förderhöhen beim Neustart bereits an das Niveau für 2027 angepasst.

Die Mittel für den Kesseltausch 2026 waren bereits im Juli ausgeschöpft, die Registrierung wurde damals geschlossen. Die neue Aktion speist sich aus Rückflüssen: Geld aus stornierten, nicht umgesetzten Projekten und verfallenen Registrierungen. Bis Jahresende rechnet das Ministerium mit rund 20 Millionen Euro. Wie schnell dieses Budget vergeben ist, bleibt abzuwarten – angesichts der hohen Nachfrage im Frühjahr ist rasches Handeln ratsam.

## Förderquote sinkt deutlich

Die Förderung wird über die Jahre schrittweise zurückgefahren. Laut Ministerium sinkt die Förderquote von rund 75 Prozent in der vorigen Legislaturperiode über rund 30 Prozent im Jahr 2026 auf rund 20 Prozent im Jahr 2027. Für 2027 stehen für den Kesseltausch 179 Millionen Euro bereit, getrennt vom Budget für thermische Sanierung.

Für Haushalte heißt das: Der Eigenanteil steigt. Umso wichtiger ist eine saubere Planung, damit die neue Heizung dauerhaft niedrige Betriebskosten verursacht.

## Was Antragsteller bei der Kesseltausch-Förderung beachten sollten

- **Angebote einholen:** Mehrere Fachbetriebe vergleichen und auf Heizlastberechnung bestehen.
- **Bedingungen lesen:** Das Informationsblatt auf sanierungsoffensive.gv.at regelt, welche Kosten förderfähig sind.
- **Reihenfolge beachten:** Bei Bundesförderungen ist meist eine Registrierung vor Umsetzung nötig – Details im Infoblatt prüfen.
- **Landesförderung kombinieren:** Viele Bundesländer fördern den Heizungstausch zusätzlich, oft mit eigenen Fristen.
- **Fernwärme prüfen:** In Städten ist ein Anschluss häufig die einfachste Lösung, sofern das Netz verfügbar ist.

## Welche Heizung zum Haus passt

Die Pauschalen unterscheiden sich je nach System. Ob Wärmepumpe, Fernwärme oder Holzheizung sinnvoll ist, hängt aber vor allem vom Gebäude ab. Eine Luft-Wasser-Wärmepumpe arbeitet dann effizient, wenn das Haus mit niedriger Vorlauftemperatur auskommt. Ein Fernwärmeanschluss ist nur dort möglich, wo ein Netz in der Straße liegt. Holzheizungen brauchen Platz für Lager und Kamin. Eine unabhängige Energieberatung, wie sie die Länder anbieten, hilft bei der Entscheidung und kostet meist wenig oder nichts.

## Einordnung

Die Wiedereröffnung ist eine Brücke bis zum Start der neuen Sanierungsoffensive am 4. Jänner 2027. Die finalen Förderbestimmungen für das kommende Jahr sollen laut Ministerium im Dezember beschlossen werden. Für einkommensschwache Haushalte wird das Programm „Sauber Heizen für Alle“ künftig in die Sanierungsoffensive integriert.

Wer jetzt einen Heizungstausch plant, sollte das Projekt technisch vorbereiten und die Antragsmöglichkeit ab 2. November im Blick behalten. Maßgeblich sind ausschließlich die zum Antragszeitpunkt gültigen Bedingungen.','energie','Heizen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/kesseltausch-foerderung-november-2026-pauschalen.webp','BMLUK – Klimaschutzministerium','https://www.bmluk.gv.at/service/presse/klima-umwelt/2026/totschnig-hattmannsdorfer-500-millionen-euro-booster-fuer-klimamasnahmen-sowie-bau-und-handwerk.html','published','2026-10-15T12:20:00.000Z','2026-10-22T00:17:07.869Z','Kesseltausch-Förderung: Neustart am 2. November','Kesseltausch-Förderung startet am 2. November neu: 5.000 Euro für Wärmepumpe, 4.000 für Fernwärme, 6.000 für Holz. Bedingungen jetzt prüfen.','Kesseltausch-Förderung','["Kesseltausch-Förderung","Kesseltausch 2026","Heizungstausch Förderung","Wärmepumpe Förderung Bund","kesseltausch förderung 2 november","pauschale wärmepumpe 5000 euro","fernwärme anschluss förderung 4000","raus aus gas förderung einfamilienhaus"]','Kesseltausch-Förderung: Alter Ölkessel im Heizraum wird gegen Wärmepumpe getauscht','Photorealistic editorial photo of an old oil boiler being disconnected in a basement boiler room of an Austrian house, tools and copper pipes on the floor, cool fluorescent light, a new heat pump indoor unit in the background, no text, no logos, no readable signs, no identifiable faces','[{"q":"Wie hoch ist die Kesseltausch-Förderung ab 2. November?","a":"Laut Klimaschutzministerium gibt es Pauschalen von 5.000 Euro für eine Wärmepumpe, 4.000 Euro für einen Fernwärmeanschluss und 6.000 Euro für eine Holzheizung. Bohrbonus und Solarbonus bleiben bestehen."},{"q":"Wer kann den Antrag stellen?","a":"Die Aktion richtet sich an Ein- und Zweifamilienhäuser sowie Reihenhäuser, die von fossilen Heizsystemen umsteigen. Die genauen Bedingungen stehen im Informationsblatt auf sanierungsoffensive.gv.at."},{"q":"Wie viel Geld steht zur Verfügung?","a":"Die Aktion wird aus Rückflüssen stornierter oder verfallener Projekte finanziert. Bis Jahresende erwartet das Ministerium rund 20 Millionen Euro."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('fernwaerme-wien-2026-27-rabatt-kosten-steigen','Fernwärme Wien: 30 Prozent Rabatt, trotzdem steigen die Kosten','Wien Energie senkt den Arbeitspreis der Fernwärme für die Heizperiode 2026/27 um 30 Prozent. Weil Gas teurer wurde, steigen die Gesamtkosten trotzdem leicht.','Bei der Fernwärme Wien steigen die Kosten in der Heizperiode 2026/27 trotz eines kräftigen Rabatts leicht an. Wien Energie gewährt einen Nachlass von 30 Prozent auf den verbrauchsabhängigen Arbeitspreis und stellt dafür laut eigenen Angaben rund 70 Millionen Euro bereit. Der Grund sind die seit Jahresbeginn deutlich gestiegenen Erdgaspreise.

## Fernwärme Wien: Was der Rabatt bewirkt

Laut einer Musterrechnung, über die VIENNA.AT berichtet, erhöhen sich die Kosten für eine 73-Quadratmeter-Wohnung mit 6.000 Kilowattstunden Jahresverbrauch um rund sechs Prozent. Das entspricht etwa 4,60 Euro pro Monat oder rund 55 Euro im Jahr. Ohne den Rabatt wäre der Anstieg deutlich höher ausgefallen. Die Rechnung lässt sich allerdings nicht eins zu eins auf jeden Haushalt übertragen, weil Wohnungsgröße, Lage und Heizverhalten stark variieren.

## Warum die Fernwärme vom Gaspreis abhängt

Die Wiener Fernwärme wird laut Bericht zu gut der Hälfte mit Erdgas erzeugt. Steigen die Gaspreise am europäischen Markt, schlägt das auf die Erzeugungskosten durch. Den Preisanstieg seit Jahresbeginn bringt der Bericht mit dem Krieg im Iran in Verbindung. Für die aktuelle Heizperiode bleibt Erdgas ein wichtiger Bestandteil.

Langfristig will Wien Energie die Fernwärme unabhängiger machen – unter anderem mit Geothermie, Großwärmepumpen und industrieller Abwärme. Diese Projekte wirken aber erst über mehrere Jahre.

## Neue Teilbeträge bei der Fernwärme Wien

Neu ist auch der Zahlungsrhythmus: Statt sechs Zahlungen alle zwei Monate werden künftig zehn gleich hohe monatliche Teilbeträge pro Abrechnungsperiode fällig. Die Umstellung erfolgt automatisch, ein Antrag ist nicht nötig. Die Schreiben werden ab Mitte Oktober gemeinsam mit der Jahresabrechnung verschickt. Die Umstellung selbst ist laut Bericht keine Preiserhöhung, sie verteilt die Kosten nur gleichmäßiger.

Für Haushalte, die überlegen, von Gas auf Fernwärme umzusteigen, ändert der aktuelle Preisanstieg wenig an der Grundrechnung. Auch Gasetagenheizungen sind von den gestiegenen Großhandelspreisen betroffen. Entscheidend ist, ob das Haus an das Netz angeschlossen werden kann und welche Anschlusskosten anfallen. Der Bund fördert den Umstieg auf Fernwärme im Rahmen des Kesseltauschs, der ab 2. November wieder geöffnet ist, mit einer Pauschale von 4.000 Euro für Ein- und Zweifamilienhäuser.

## Hilfe für Haushalte mit wenig Einkommen

Wien Energie verweist auf Entlastungspakete von insgesamt über 770 Millionen Euro seit 2022. Zusätzlich gibt es Energiegutscheine im Umfang von 22 Millionen Euro, davon zehn Millionen für die kommenden Jahre. Sie werden über Organisationen wie Caritas, Rotes Kreuz, Volkshilfe, Wiener Hilfswerk und Licht ins Dunkel vergeben.

## Was Fernwärme-Kunden jetzt tun können

- **Jahresabrechnung prüfen:** Verbrauch mit dem Vorjahr vergleichen und den neuen Teilbetrag kontrollieren.
- **Heizverhalten anpassen:** Jedes Grad weniger Raumtemperatur spart spürbar Energie.
- **Heizkörper entlüften:** Gluckernde Heizkörper geben weniger Wärme ab.
- **Thermostatventile nutzen:** Wenig genutzte Räume gezielt kühler halten.
- **Unterstützung beantragen:** Bei Zahlungsschwierigkeiten frühzeitig Sozialorganisationen oder den Kundenservice kontaktieren.

Für Mieter und Eigentümer bleibt Fernwärme in Wien eine der verbreitetsten Heizformen. Der Rabatt dämpft den Preisanstieg, vollständig ausgleichen kann er die höheren Gaskosten in dieser Heizperiode aber nicht.','energie','Heizen','wien','news','Presseinfo Redaktion','/assets/img/artikel/fernwaerme-wien-2026-27-rabatt-kosten-steigen.webp','VIENNA.AT','https://www.vienna.at/wien-energie-30-rabatt-trotzdem-wird-heizen-teurer/10532357','published','2026-10-11T08:25:00.000Z','2026-10-22T00:17:07.869Z','Fernwärme Wien: 30 % Rabatt, Kosten steigen trotzdem','Fernwärme Wien 2026/27: Wien Energie gewährt 30 Prozent Rabatt, die Kosten steigen dennoch um rund 6 Prozent. Was Haushalte jetzt wissen müssen.','Fernwärme Wien','["Fernwärme Wien","Wien Energie Fernwärme","Fernwärme Preis 2026","Fernwärme Rabatt","fernwärme wien teilbeträge monatlich","fernwärme wien kosten 2026 27","wien energie fernwärme jahresabrechnung","fernwärme gas anteil wien"]','Fernwärme Wien: Übergabestation mit gedämmten Rohren im Keller eines Wohnhauses','Photorealistic editorial photo of a district heating substation with insulated pipes and valves in the basement of a Viennese Gemeindebau apartment building, warm yellow light, clean concrete walls, no text, no logos, no readable signs, no people','[{"q":"Wie stark steigt die Fernwärme in Wien?","a":"In einer Musterrechnung für 73 Quadratmeter und 6.000 kWh Jahresverbrauch steigen die Kosten trotz Rabatt um rund sechs Prozent, das sind etwa 4,60 Euro pro Monat. Der Wert ist nicht auf jeden Haushalt übertragbar."},{"q":"Muss ich für die monatlichen Teilbeträge etwas beantragen?","a":"Nein. Die Umstellung von sechs auf zehn Teilbeträge erfolgt automatisch, die Schreiben kommen ab Mitte Oktober mit der Jahresabrechnung."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('sanierungsoffensive-2027-500-millionen-foerderung','Sanierungsoffensive 2027: 500 Millionen Euro für Dämmen und Heizen','Die Bundesregierung stellt 2027 insgesamt 500 Millionen Euro für Sanierung und Heizungstausch bereit – deutlich mehr für die Dämmung, weniger Förderquote beim Kessel.','Die Sanierungsoffensive 2027 fällt größer aus als zunächst geplant: Die Bundesregierung hat 500 Millionen Euro für thermische Sanierung und den Tausch fossiler Heizungen angekündigt. Bundeskanzler Christian Stocker, Umweltminister Norbert Totschnig und Wirtschaftsminister Wolfgang Hattmannsdorfer (alle ÖVP) präsentierten das Paket am 10. Oktober. Ziel sind laut Regierung Impulse für die Bauwirtschaft, gesicherte Arbeitsplätze und niedrigere Energiekosten für Haushalte.

## Sanierungsoffensive 2027: So wird das Geld verteilt

Laut Klimaschutzministerium setzt sich das Budget so zusammen:

- **179 Millionen Euro** für den Kesseltausch (Klimaschutzministerium)
- **181 Millionen Euro** für thermische Sanierungen, vor allem im mehrgeschoßigen Wohnbau (Klimaschutzministerium)
- **90 Millionen Euro** für Ein-, Zweifamilien- und Reihenhäuser (Wirtschaftsministerium)
- **50 Millionen Euro** für gemeinnützige Bauvereinigungen (Wirtschaftsministerium)

Der Anteil des Wirtschaftsministeriums von 140 Millionen Euro stammt aus dem Energieeffizienzfonds. Zusammen ergeben sich damit 321 Millionen Euro für die thermische Sanierung – im Sommer war man noch von 181 Millionen Euro ausgegangen.

## Mehr für Dämmung, weniger Quote beim Heizungstausch

Zum Vergleich: 2026 standen für Sanierung und Heizungstausch gemeinsam 360 Millionen Euro bereit, die Mittel waren bereits zur Jahreshälfte erschöpft. Neu ist die Trennung der Budgets, damit die Sanierung nicht vom Kesseltausch verdrängt wird.

Gleichzeitig sinkt die Förderquote beim Kesseltausch weiter. Laut Ministerium lag sie in der vorigen Legislaturperiode bei rund 75 Prozent, 2026 bei rund 30 Prozent und soll 2027 rund 20 Prozent betragen. Der Eigenanteil für Hausbesitzer steigt damit deutlich.

## Was sich beim Verfahren ändert

Die Regierung verspricht ein einfacheres Verfahren. Vorabregistrierungen sollen entfallen, Anträge laufen künftig grundsätzlich in zwei Schritten: Antrag mit Genehmigung und Endabrechnung. Bei rasch umsetzbaren Projekten soll eine Auftragsbestätigung die Mittel verbindlicher reservieren. Die Programme im Energieeffizienzfonds werden von 13 auf vier reduziert.

## Sanierungsoffensive 2027: Zeitplan

- **2. November 2026:** Wiedereröffnung des Kesseltauschs aus Restmitteln
- **Dezember 2026:** Beschluss der finalen Förderbestimmungen und Informationsblätter
- **4. Jänner 2027:** Start der Sanierungsoffensive 2027

Das Ministerium rechnet mit einer Einsparung von rund 242.700 Tonnen CO2 pro Jahr und einer jährlichen Wertschöpfung von 2,1 Milliarden Euro. Bei thermischen Sanierungen sollen rund 90 Prozent der Wertschöpfung im Inland bleiben. Für die Bauwirtschaft kommt das Paket in einer schwierigen Phase: Die Zahl der bewilligten Wohnungen in neuen Gebäuden lag 2025 mit 31.979 auf dem niedrigsten Stand seit 2010.

Die Wirtschaftskammer und Vertreter des Baugewerbes hatten seit Monaten eine verlässliche Förderkulisse gefordert. Laut Konjunkturerhebung des Ministeriums bewerteten im zweiten Quartal 2026 rund 35 Prozent der befragten Baubetriebe ihre Lage als schlecht, nur 19 Prozent als gut. Ein Drittel erwartete sinkende Auftragseingänge. Die Aufstockung der Sanierungsmittel soll hier gegensteuern, weil Dämmung, Fenstertausch und Heizungsumbau vor allem von regionalen Klein- und Mittelbetrieben ausgeführt werden.

## Was Hausbesitzer jetzt tun können

Wer 2027 sanieren will, sollte schon jetzt Angebote einholen, einen Energieausweis erstellen lassen und mit dem Land klären, welche Landesförderungen dazukommen. Konkrete Förderhöhen stehen erst mit den Informationsblättern auf sanierungsoffensive.gv.at fest.','energie','Förderungen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/sanierungsoffensive-2027-500-millionen-foerderung.webp','ORF.at','https://orf.at/stories/3444749/','published','2026-10-10T13:30:00.000Z','2026-10-22T00:17:07.869Z','Sanierungsoffensive 2027: 500 Mio. Euro Förderung','Sanierungsoffensive 2027: Die Regierung stockt auf 500 Millionen Euro auf. So verteilt sich das Geld auf Sanierung und Kesseltausch – alle Details hier.','Sanierungsoffensive 2027','["Sanierungsoffensive 2027","Sanierungsförderung 2027","Förderung Dämmung","Kesseltausch 2027","sanierungsoffensive 2027 budget aufteilung","thermische sanierung förderung einfamilienhaus","förderquote kesseltausch 20 prozent","sanierungsbonus 2027 start"]','Sanierungsoffensive 2027: Wohnhaus mit Gerüst bei der Fassadendämmung','Photorealistic editorial photo of a scaffolded 1970s apartment building in an Austrian town receiving thick facade insulation panels, workers'' tools visible on the scaffold, clear autumn morning sky, no text, no logos, no readable signs, no identifiable faces','[{"q":"Wie viel Geld gibt es in der Sanierungsoffensive 2027?","a":"Insgesamt 500 Millionen Euro: 179 Millionen für den Kesseltausch und 321 Millionen für thermische Sanierungen, aufgeteilt auf Klimaschutz- und Wirtschaftsministerium."},{"q":"Wann startet die Sanierungsoffensive 2027?","a":"Laut Klimaschutzministerium startet sie am 4. Jänner 2027. Die finalen Förderbestimmungen sollen im Dezember 2026 beschlossen werden."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('sauber-heizen-fuer-alle-klimasozialfonds-2027','Sauber Heizen für Alle: Programm wandert in die Sanierungsoffensive','Das Programm für einkommensschwache Haushalte wird neu aufgestellt: Ab 2027 läuft es über den Klimasozialfonds und unter dem Dach der Sanierungsoffensive.','Das Förderprogramm Sauber Heizen für Alle wird neu aufgestellt. Wie das Klimaschutzministerium im Zuge der Sanierungsoffensive 2027 mitteilte, wird das Angebot für einkommensschwache Haushalte künftig in die Sanierungsoffensive integriert und über den Klimasozialfonds der EU weiterentwickelt. Bis 2032 sind dafür laut Ministerium rund 439 Millionen Euro vorgesehen.

## Sauber Heizen für Alle: Was bisher galt

Das Programm richtet sich an Haushalte mit geringem Einkommen, die ihre Öl-, Gas- oder Kohleheizung gegen ein klimafreundliches System tauschen wollen. Abgewickelt wurde es bisher gemeinsam von Bund und Ländern. Die Bundesländer prüfen dabei in der Regel die Einkommensgrenzen, viele haben eigene Richtlinien veröffentlicht, etwa das Burgenland für 2026.

Für heuer ist die Registrierung bereits geschlossen. Das Ministerium hatte im Juli mitgeteilt, dass sowohl beim Kesseltausch als auch bei Sauber Heizen für Alle 2026 alle Mittel abgeholt sind. Bereits registrierte oder eingereichte Anträge werden nach den jeweils geltenden Bedingungen weiter bearbeitet.

## Neuer Rahmen über den Klimasozialfonds

Der Klimasozialfonds ist ein EU-Instrument, das Haushalte bei den Folgen der CO2-Bepreisung entlasten soll. Österreich will daraus künftig sowohl Sauber Heizen für Alle als auch Förderungen im mehrgeschoßigen Wohnbau finanzieren. Die Umsetzung erfolgt im Einvernehmen mit der Europäischen Kommission und braucht deren Genehmigung. Konkrete Förderhöhen und Einkommensgrenzen für 2027 wurden noch nicht veröffentlicht.

Für Haushalte mit geringem Einkommen ist die Nachricht zweischneidig. Einerseits ist die Finanzierung bis 2032 langfristig abgesichert. Andererseits gibt es bis zur Genehmigung durch Brüssel und zur Veröffentlichung der neuen Richtlinien eine Übergangsphase, in der keine neuen Anträge möglich sind.

## Sauber Heizen für Alle: So bereiten Sie sich vor

- **Einkommensnachweise sammeln:** Lohnzettel, Pensionsbescheide und Haushaltsgröße dokumentieren.
- **Beratung nutzen:** Energieberatungsstellen der Länder geben kostenlos Auskunft über passende Heizsysteme.
- **Angebote einholen:** Ein Kostenvoranschlag eines Fachbetriebs beschleunigt den späteren Antrag.
- **Landesstelle kontaktieren:** Die zuständige Abteilung im Land kennt die regionalen Abläufe.
- **Nicht vorschnell beauftragen:** Ohne Förderzusage begonnene Projekte sind häufig nicht förderfähig.

## Warum das Programm wichtig ist

Gerade Haushalte mit niedrigem Einkommen leben häufig in älteren Gebäuden mit veralteten Heizungen. Sie sind von steigenden Öl- und Gaspreisen besonders betroffen, können sich einen Heizungstausch ohne Unterstützung aber kaum leisten. Dazu kommt die geplante EU-weite CO2-Bepreisung für Gebäude und Verkehr. Genau dafür wurde der Klimasozialfonds geschaffen: Er soll verhindern, dass die Klimapolitik sozial schwächere Haushalte überproportional belastet.

## Einordnung im Gesamtpaket

Die Sanierungsoffensive 2027 umfasst insgesamt 500 Millionen Euro. Der reguläre Kesseltausch öffnet bereits am 2. November 2026 wieder, allerdings mit Pauschalen und deutlich niedrigerer Förderquote als in den Vorjahren. Für Menschen mit geringem Einkommen bleibt Sauber Heizen für Alle daher der wichtigste Weg zu einer neuen Heizung.

Sobald die Informationsblätter veröffentlicht sind, sollten Interessierte rasch handeln. Erfahrungsgemäß sind die Mittel bei hoher Nachfrage schnell vergeben. Verbindlich sind nur die Angaben auf sanierungsoffensive.gv.at und der Landesförderstellen.','energie','Förderungen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/sauber-heizen-fuer-alle-klimasozialfonds-2027.webp','BMLUK – Klimaschutzministerium','https://www.bmluk.gv.at/themen/klima-und-umwelt/klima/klima-initiativen-und-foerderungen/ufg/sanierung-kesselaustausch-2027.html','published','2026-10-16T06:40:00.000Z','2026-10-22T00:17:07.870Z','Sauber Heizen für Alle: Neuregelung ab 2027','Sauber Heizen für Alle wird ab 2027 Teil der Sanierungsoffensive und über den Klimasozialfonds finanziert. Was einkommensschwache Haushalte wissen müssen.','Sauber Heizen für Alle','["Sauber Heizen für Alle","Sauber Heizen für Alle 2027","Klimasozialfonds Österreich","Heizungstausch einkommensschwach","sauber heizen für alle antrag 2026 beendet","förderung heizungstausch geringes einkommen","klimasozialfonds 439 millionen","sauber heizen burgenland niederösterreich"]','Sauber Heizen für Alle: Wohnzimmer mit altem Kachelofen und neuem Heizkörper','Photorealistic editorial photo of an elderly couple''s modest living room in a rural Burgenland house with an old tiled stove and a new slim radiator under the window, soft winter daylight, figures seen only from behind, no text, no logos, no readable signs','[{"q":"Kann ich 2026 noch Sauber Heizen für Alle beantragen?","a":"Nein, die Registrierung für 2026 wurde im Juli beendet. Bereits registrierte oder eingereichte Anträge werden nach den geltenden Bedingungen abgewickelt."},{"q":"Wie geht es 2027 weiter?","a":"Das Programm wird in die Sanierungsoffensive integriert und über den Klimasozialfonds weiterentwickelt. Bis 2032 sind rund 439 Millionen Euro vorgesehen, die EU-Kommission muss zustimmen."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('sanierungsbonus-2027-fenster-daemmung-begruenung','Sanierungsbonus 2027: Fenster, Dämmung und neuer Begrünungsbonus','Ab 4. Jänner 2027 fördert der Bund wieder thermische Sanierungen – auch einzelne Bauteile wie Fenster. Neu ist ein Bonus für Verschattung und Gebäudebegrünung.','Der Sanierungsbonus 2027 wird breiter aufgestellt als bisher. Wie das Klimaschutzministerium mitteilte, startet die neue Sanierungsoffensive am 4. Jänner 2027. Gefördert werden dann nicht nur umfassende Sanierungen, sondern auch Teilsanierungen und einzelne Bauteile. Neu ist ein Bonus für Verschattung und Gebäudebegrünung.

## Sanierungsbonus 2027: Diese Maßnahmen sind geplant

Laut Ministerium sollen folgende Maßnahmen förderfähig sein:

- umfassende Sanierungen und Teilsanierungen,
- Einzelbauteile wie Fenstertausch,
- Dämmung von Außenwänden,
- Dämmung der obersten und der untersten Geschoßdecke,
- im mehrgeschoßigen Wohnbau zusätzlich der Fenstertausch in einzelnen Wohnungen sowie Gebäudebegrünung.

Der neue Bonus für Verschattung und Begrünung reagiert auf die zunehmende Hitzebelastung. Der Sommer 2026 war laut GeoSphere Austria der heißeste der Messgeschichte.

## Wer für welchen Sanierungsbonus zuständig ist

Die Zuständigkeit wird zwischen zwei Ministerien aufgeteilt. Das Wirtschaftsministerium übernimmt den Sanierungsbonus für Ein-, Zweifamilien- und Reihenhäuser aus Mitteln des Energieeffizienzfonds (90 Millionen Euro) sowie die Förderung für gemeinnützige Bauvereinigungen (50 Millionen Euro). Das Klimaschutzministerium ist für den mehrgeschoßigen Wohnbau (181 Millionen Euro) und für den Kesseltausch in allen Gebäudetypen zuständig.

Bisher mussten Projekte vorab registriert werden, was bei knappen Budgets zu Wettläufen führte. Künftig sollen Vorabregistrierungen entfallen. Das Verfahren läuft grundsätzlich in zwei Schritten: Antrag mit Genehmigung, danach die Endabrechnung. Bei rasch umsetzbaren Projekten soll eine Auftragsbestätigung die Mittel verbindlicher reservieren. Geplant ist außerdem, Zuschüsse in pauschalierten Teilbeträgen über einen bestimmten Zeitraum auszuzahlen. Die Wohnbauförderungen sollen unter einem gemeinsamen Dach gebündelt werden.

## So bereiten Sie den Sanierungsbonus 2027 vor

- **Energieausweis erstellen:** Er zeigt den Ist-Zustand und ist für viele Förderungen Voraussetzung.
- **Prioritäten setzen:** Oberste Geschoßdecke und Kellerdecke sind oft günstige Maßnahmen mit großer Wirkung.
- **Angebote vergleichen:** Fachbetriebe für Fenster, Fassade und Dach frühzeitig anfragen, da die Nachfrage im Frühjahr steigt.
- **Wohnungseigentum abstimmen:** In Mehrparteienhäusern braucht es Beschlüsse der Eigentümergemeinschaft.
- **Landesförderung prüfen:** Die Wohnbauförderungen der Länder ergänzen den Bund oft.

## Welche Maßnahmen sich besonders lohnen

Fachleute raten, mit der Gebäudehülle zu beginnen, bevor die Heizung getauscht wird. Eine gedämmte oberste Geschoßdecke ist vergleichsweise günstig und reduziert die Wärmeverluste über das Dach spürbar. Neue Fenster verbessern neben der Energiebilanz auch Schallschutz und Behaglichkeit. Wer zuerst dämmt, kann die neue Heizung kleiner dimensionieren und spart damit bei Anschaffung und Betrieb. Ein durchdachtes Sanierungskonzept, das alle Schritte sinnvoll zeitlich ordnet und Gewerke koordiniert, hilft, Doppelarbeit zu vermeiden.

## Was noch offen ist

Die konkreten Förderhöhen und technischen Mindestanforderungen sind noch nicht bekannt. Die finalen Förderbestimmungen und Informationsblätter sollen im Dezember 2026 beschlossen werden. Wer sanieren möchte, sollte bis dahin keine verbindlichen Aufträge unterschreiben, ohne die Fördervoraussetzungen zu kennen.

Insgesamt stehen 2027 für die thermische Sanierung 321 Millionen Euro zur Verfügung. Laut Ministerium sollen rund 90 Prozent der Wertschöpfung bei Sanierungen im Inland bleiben – ein Impuls für das regionale Baugewerbe.','energie','Förderungen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/sanierungsbonus-2027-fenster-daemmung-begruenung.webp','BMLUK – Klimaschutzministerium','https://www.bmluk.gv.at/service/presse/klima-umwelt/2026/totschnig-hattmannsdorfer-500-millionen-euro-booster-fuer-klimamasnahmen-sowie-bau-und-handwerk.html','published','2026-10-15T14:05:00.000Z','2026-10-22T00:17:07.870Z','Sanierungsbonus 2027: Was ab Jänner gefördert wird','Sanierungsbonus 2027: Ab 4. Jänner werden Fenstertausch, Dämmung und Teilsanierungen gefördert, neu ist ein Bonus für Begrünung. Jetzt Projekt planen.','Sanierungsbonus 2027','["Sanierungsbonus 2027","Förderung Fenstertausch","Förderung Dämmung 2027","Teilsanierung Förderung","sanierungsbonus 2027 einzelbauteile","förderung fassadendämmung einfamilienhaus","bonus gebäudebegrünung verschattung","sanierungsoffensive 4 jänner 2027"]','Sanierungsbonus 2027: Neue Fenster werden in ein älteres Einfamilienhaus eingebaut','Photorealistic editorial photo of new triple-glazed windows being installed in an older Upper Austrian single-family house, window frames leaning against the wall, sunny autumn midday, garden in the foreground, no text, no logos, no readable signs, no identifiable faces','[{"q":"Wird 2027 auch ein einzelner Fenstertausch gefördert?","a":"Laut Ministerium sind Angebote für einzelne Bauteile geplant, darunter Fenster, Außenwände sowie oberste und unterste Geschoßdecken. Die genauen Bedingungen folgen in den Informationsblättern."},{"q":"Brauche ich eine Vorabregistrierung?","a":"Laut Ankündigung sollen Vorabregistrierungen entfallen. Das Verfahren läuft künftig über Antrag mit Genehmigung und anschließende Endabrechnung."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('klimagesetz-oesterreich-entwurf-klimaneutralitaet-2040','Klimagesetz Österreich: Entwurf mit Ziel Klimaneutralität 2040','Nach mehr als fünf Jahren ohne verbindliches Klimagesetz hat die Regierung einen Entwurf in Begutachtung geschickt. Kernstück ist ein Klimafahrplan bis Ende 2027.','Das Klimagesetz Österreich nimmt Gestalt an: Die Bundesregierung hat sich nach intensiven Verhandlungen auf einen Entwurf geeinigt und ihn am 18. September in Begutachtung geschickt. Damit soll erstmals seit mehr als fünf Jahren wieder ein verbindlicher Rahmen für die Klimapolitik entstehen. Das alte Klimaschutzgesetz hatte keine Reduktionspfade mehr festgelegt.

## Klimagesetz Österreich: Die Eckpunkte

Laut Klimaschutzministerium ist das Gesetz ein Rahmen- und Steuerungsgesetz. Es soll Strukturen und Instrumente für eine abgestimmte Klima- und Umweltpolitik schaffen. Ziel ist, die EU-Klimaziele einzuhalten und bis 2040 Klimaneutralität für jene Emissionen zu erreichen, die nicht unter den EU-Emissionshandel fallen – also vor allem Verkehr, Gebäude, Landwirtschaft und Abfall.

Das Gesetz stützt sich auf drei Säulen:

- Klimaschutz,
- Anpassung an den Klimawandel,
- Kreislaufwirtschaft.

## Der Klimafahrplan als zentrales Instrument

Kernstück ist ein Klimafahrplan. Er soll für die Sektoren außerhalb des Emissionshandels indikative Reduktionspfade und konkrete Maßnahmen von Bund und Ländern enthalten. Der erste Fahrplan ist bis Ende 2027 vorzulegen und danach regelmäßig zu aktualisieren.

Wichtig ist der Korrekturmechanismus: Fällt Österreich vom Zielpfad ab, muss die Regierung innerhalb von sechs Monaten mit einem Sofortprogramm reagieren.

## Neue Gremien im Klimagesetz

Eine neue Steuerungsgruppe soll den Klimafahrplan und den Nationalen Energie- und Klimaplan vorbereiten. Ihr gehören alle relevanten Bundesministerien und die Länder an, den Vorsitz auf Bundesseite führt das Klimaschutzministerium. Zusätzlich wird ein interdisziplinärer wissenschaftlicher Klimabeirat eingerichtet. Er bündelt Expertise aus Technik, Natur-, Rechts-, Sozial- und Wirtschaftswissenschaften und gibt Empfehlungen ab.

Umstritten dürfte die sogenannte Standortklausel werden: Treten schwerwiegende wirtschaftliche oder soziale Folgen auf, kann der Klimafahrplan evaluiert und angepasst werden.

## Reaktionen aus den Regierungsparteien

Umweltminister Norbert Totschnig (ÖVP) betont Technologie und Innovation und sieht im Ausbau erneuerbarer Energie einen Weg, die Abhängigkeit von fossilen Importen zu senken. SPÖ-Umweltsprecherin Julia Herr verweist darauf, dass Österreich seit über fünf Jahren kein verbindliches Klimagesetz hatte, und hebt das Ziel 2040 hervor. NEOS-Umweltsprecher Michael Bernhard sieht Planungssicherheit für Unternehmen und verbindliche Kurskorrekturen bei Zielverfehlung.

Hintergrund des Drucks ist auch die EU-Ebene. Österreich muss im Rahmen der europäischen Lastenteilung seine Emissionen außerhalb des Emissionshandels bis 2030 deutlich senken. Verfehlt ein Mitgliedstaat diese Ziele, drohen Ankäufe von Emissionszertifikaten anderer Staaten, die das Budget belasten. Ein verbindlicher Fahrplan mit Korrekturmechanismus soll solche Kosten vermeiden helfen, indem Abweichungen früher erkannt werden.

## Was das Klimagesetz für Haushalte bedeutet

Unmittelbare Pflichten für Bürger enthält der Entwurf als Rahmengesetz nicht. Mittelbar ist er aber relevant: Der Gebäudesektor zählt zu den Bereichen außerhalb des Emissionshandels. Förderprogramme wie die Sanierungsoffensive oder der Kesseltausch dürften im Klimafahrplan eine zentrale Rolle spielen. Wer heute über eine neue Heizung oder Dämmung entscheidet, sollte davon ausgehen, dass der Ausstieg aus fossilen Heizsystemen politisch weiter vorangetrieben wird.

Nach der Begutachtung muss der Entwurf noch den Ministerrat und den Nationalrat passieren. Änderungen sind möglich.','energie','Klima',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/klimagesetz-oesterreich-entwurf-klimaneutralitaet-2040.webp','BMLUK – Klimaschutzministerium','https://www.bmluk.gv.at/service/presse/klima-umwelt/2026/totschnig-herr-bernhard-klimagesetz-auf-schiene-klimaschutz-hand-in-hand-mit-wirtschaftswachstum-und-arbeitsplaetzen.html','published','2026-09-22T09:10:00.000Z','2026-10-22T00:17:07.870Z','Klimagesetz Österreich: Was der Entwurf vorsieht','Klimagesetz Österreich: Der Entwurf bringt Klimafahrplan, Sofortprogramme und einen Klimabeirat. Was das neue Gesetz regelt und wie es weitergeht.','Klimagesetz Österreich','["Klimagesetz Österreich","Klimaschutzgesetz 2026","Klimaneutralität 2040","Klimafahrplan","klimagesetz begutachtung 2026","klimagesetz sofortprogramm klimabeirat","klimagesetz standortklausel","österreich klimaziele nicht ets"]','Klimagesetz Österreich: Regierungsgebäude in der Wiener Innenstadt an einem Herbstmorgen','Photorealistic editorial photo of the exterior of a classical government building in Vienna''s first district on a misty September morning, autumn trees in front, wide angle from street level, no text, no logos, no readable signs, no people','[{"q":"Was ist das Ziel des neuen Klimagesetzes?","a":"Das Gesetz soll die Einhaltung der EU-Klimaziele sichern und Klimaneutralität bis 2040 in den Bereichen außerhalb des EU-Emissionshandels erreichen."},{"q":"Was passiert, wenn Österreich die Ziele verfehlt?","a":"Weicht Österreich vom Zielpfad ab, muss die Regierung binnen sechs Monaten ein Sofortprogramm vorlegen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pv-anlage-wien-kosten-foerderung-ablauf','PV-Anlage in Wien: Kosten, Förderung und Ablauf 2026','Eine PV-Anlage in Wien rechnet sich vor allem bei hohem Eigenverbrauch. Wir zeigen, welche Kostenfaktoren zählen und wie Planung, Anmeldung und Förderung ablaufen.','Eine PV-Anlage in Wien ist für viele Hausbesitzer am Stadtrand die naheliegende Antwort auf hohe Strompreise. In Bezirken wie Floridsdorf, Donaustadt, Liesing oder Hietzing gibt es zahlreiche Einfamilienhäuser mit gut nutzbaren Dachflächen. Wer plant, sollte aber Kosten, Genehmigung, Netzanmeldung und Förderungen gemeinsam betrachten.

## Was eine PV-Anlage in Wien kostet

Pauschale Preise sind wenig aussagekräftig, weil jedes Dach anders ist. Die wichtigsten Kostenfaktoren sind:

- **Anlagengröße:** Angegeben in Kilowatt-Peak (kWp). Größere Anlagen sind pro kWp meist günstiger.
- **Dachform und Eindeckung:** Ziegel-, Blech- oder Flachdach erfordern unterschiedliche Montagesysteme.
- **Gerüst und Zugang:** Mehrgeschoßige Häuser oder schwer erreichbare Dächer verteuern die Montage.
- **Wechselrichter und Speicher:** Ein Batteriespeicher erhöht die Investition deutlich, steigert aber den Eigenverbrauch.
- **Elektrische Anpassungen:** Zählerkasten, Überspannungsschutz und Leitungen können zusätzliche Arbeiten erfordern.

Empfehlenswert ist es, mindestens drei Angebote einzuholen und auf vergleichbare Leistungsumfänge zu achten.

## Wie groß soll die PV-Anlage sein?

Die Größe richtet sich nach Dachfläche und Verbrauch. Ein Haushalt mit Wärmepumpe oder Elektroauto braucht deutlich mehr Strom als einer ohne. Weil die Einspeisevergütung meist niedriger ist als der Strompreis, lohnt sich vor allem selbst verbrauchter Strom. Wer tagsüber zu Hause ist oder Geräte zeitlich verschiebt, profitiert stärker. Bei der Planung hilft ein Blick auf den Lastgang des Smart Meters.

## Genehmigung und Netzanmeldung in Wien

Für viele Dachanlagen auf Einfamilienhäusern genügt nach der Wiener Bauordnung eine einfache Anzeige oder es ist gar keine Bewilligung erforderlich. In Schutzzonen, bei denkmalgeschützten Gebäuden oder größeren Anlagen gelten strengere Vorgaben. Die Baupolizei (MA 37) gibt verbindlich Auskunft.

Unabhängig davon muss jede Anlage beim Netzbetreiber, in Wien die Wiener Netze, angemeldet werden. Der Netzbetreiber prüft, ob die gewünschte Einspeiseleistung möglich ist. Erst nach der Freigabe darf eingespeist werden. Für den Verkauf von Überschussstrom braucht es zusätzlich einen Abnahmevertrag mit einem Energieversorger.

## Förderung für die PV-Anlage in Wien

2026 gab es den EAG-Investitionszuschuss des Bundes mit drei Fördercalls, der letzte lief im Oktober. Ab 2027 will das Wirtschaftsministerium die Förderung auf Speicher und Energiemanagement umstellen. Die Stadt Wien hat in den vergangenen Jahren eigene Programme angeboten, deren Bedingungen sich ändern. Vor der Beauftragung sollte man daher die aktuellen Richtlinien von Bund und Stadt prüfen und klären, ob Förderungen kombinierbar sind.

Wer den Nutzen der Anlage steigern will, sollte den Verbrauch gezielt in die Sonnenstunden legen. Geschirrspüler, Waschmaschine und Warmwasserbereitung lassen sich oft per Zeitschaltung oder über ein Energiemanagementsystem steuern. Besonders wirkungsvoll ist die Kombination mit einer Wärmepumpe oder einem Elektroauto, das tagsüber zu Hause lädt. Seit April 2026 sind die Netzkosten im Sommerhalbjahr zwischen 10 und 16 Uhr zudem rund 20 Prozent niedriger, was den Bezug in diesen Stunden zusätzlich verbilligt. Ein Batteriespeicher kann sinnvoll sein, sollte aber auf den tatsächlichen Abendverbrauch abgestimmt werden.

## Ablauf in fünf Schritten

1. **Verbrauch analysieren:** Jahresverbrauch und Tagesprofil ermitteln.
2. **Dach prüfen lassen:** Statik, Ausrichtung, Verschattung und Zustand der Eindeckung.
3. **Angebote vergleichen:** Leistung, Komponenten, Garantie und Service gegenüberstellen.
4. **Anmelden und fördern:** Netzanmeldung und Förderantrag fristgerecht stellen.
5. **Montage und Inbetriebnahme:** Abnahme durch den Elektriker, Zählertausch durch den Netzbetreiber.

Eine PV-Anlage in Wien ist eine Investition über 20 Jahre und mehr. Sorgfältige Planung und ein erfahrener Fachbetrieb sind deshalb wichtiger als der niedrigste Angebotspreis.','energie','Photovoltaik','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/pv-anlage-wien-kosten-foerderung-ablauf.webp',NULL,NULL,'published','2026-09-25T06:34:00.000Z','2026-10-22T00:17:07.872Z','PV-Anlage in Wien: Kosten, Förderung, Ablauf 2026','PV-Anlage in Wien: Was eine Solaranlage am Einfamilienhaus kostet, welche Genehmigungen nötig sind und wie der Ablauf funktioniert. Jetzt informieren.','PV-Anlage in Wien','["PV-Anlage Wien","Photovoltaik Wien","Solaranlage Wien Kosten","PV Anlage Einfamilienhaus","pv anlage wien kosten einfamilienhaus","photovoltaik wien genehmigung bauordnung","pv anlage wien netzanmeldung","photovoltaik wien förderung 2026"]','PV-Anlage in Wien: Solarmodule auf dem Ziegeldach eines Einfamilienhauses am Stadtrand','Photorealistic editorial photo of black solar panels on the tiled roof of a detached house in a green outer district of Vienna, view from a neighbouring garden, late morning sun, vineyards on a hill in the distance, no text, no logos, no readable signs, no people','[{"q":"Was kostet eine PV-Anlage in Wien?","a":"Die Kosten hängen von Größe, Dachform, Modulqualität und Speicher ab. Seriöse Aussagen liefern nur konkrete Angebote mehrerer Fachbetriebe, die Montage, Wechselrichter und Netzanschluss einschließen."},{"q":"Brauche ich in Wien eine Baugenehmigung für eine PV-Anlage?","a":"Für viele Dachanlagen auf Einfamilienhäusern reicht eine Anzeige oder es ist keine Bewilligung nötig. In Schutzzonen und bei größeren Anlagen gelten strengere Regeln, daher vorab bei der Baupolizei (MA 37) nachfragen."},{"q":"Wie lange dauert die Umsetzung?","a":"Die Montage selbst dauert oft nur ein bis drei Tage. Mit Planung, Netzanmeldung und Lieferzeiten sollte man insgesamt mehrere Wochen bis wenige Monate einplanen."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('stromspeicher-nachruesten-pv-anlage-worauf-achten','Stromspeicher nachrüsten: Wann sich ein PV-Speicher lohnt','Viele PV-Anlagen speisen mittags billig ein und kaufen abends teuer zu. Ein nachgerüsteter Stromspeicher kann das ändern – wenn Größe und Technik passen.','Einen Stromspeicher nachrüsten wollen derzeit viele Besitzer von Photovoltaikanlagen. Der Grund ist einfach: Mittags wird oft mehr Solarstrom erzeugt als verbraucht, der Überschuss wird zu niedrigen Preisen eingespeist. Am Abend muss dann Strom zum vollen Tarif zugekauft werden. Ein Batteriespeicher verschiebt den eigenen Strom in die Abendstunden.

## Stromspeicher nachrüsten: Die zwei technischen Wege

Wie ein Speicher angeschlossen wird, hängt vom vorhandenen Wechselrichter ab:

- **DC-gekoppelt:** Ist bereits ein Hybridwechselrichter verbaut, kann die Batterie direkt angeschlossen werden. Das ist effizient, weil der Strom seltener umgewandelt wird.
- **AC-gekoppelt:** Bei älteren Anlagen mit reinem Netzwechselrichter wird ein eigener Batteriewechselrichter installiert. Diese Lösung ist flexibler, hat aber etwas höhere Umwandlungsverluste.

Ein Fachbetrieb prüft, welche Variante wirtschaftlicher ist und ob Zählerkasten und Absicherung angepasst werden müssen.

## Die richtige Speichergröße

Ein häufiger Fehler ist ein zu großer Speicher. Im Sommer wird er zwar voll, im Winter reicht der Solarertrag aber oft nicht einmal für den Tagesverbrauch. Als Orientierung gilt: Die nutzbare Kapazität sollte ungefähr dem Verbrauch zwischen Sonnenuntergang und Sonnenaufgang entsprechen. Einen guten Anhaltspunkt liefern die Viertelstundenwerte des Smart Meters, die beim Netzbetreiber abrufbar sind.

## Wann sich der Stromspeicher lohnt

Die Wirtschaftlichkeit hängt von mehreren Faktoren ab:

- Differenz zwischen Bezugspreis und Einspeisevergütung,
- Höhe des Abendverbrauchs, etwa durch Kochen, Wärmepumpe oder E-Auto,
- Anschaffungskosten und Lebensdauer der Batterie,
- mögliche Förderungen.

Seit der Reform der Netztarife spielen auch Leistungsspitzen eine Rolle. Ab 2027 wird ein Teil der Netzgebühren nach der höchsten bezogenen Leistung berechnet. Ein Speicher kann solche Spitzen glätten. Die E-Control betont allerdings, dass Speicher nur bei nachweislich netzdienlichem Betrieb von Netzentgelten befreit werden.

## Förderung für die Speicher-Nachrüstung

Wirtschaftsminister Wolfgang Hattmannsdorfer hat angekündigt, die Bundesförderung ab 2027 auf Speicher und Energiemanagement auszurichten, einschließlich eines Bonus für die Nachrüstung bei bestehenden Anlagen. Die genauen Bedingungen sind noch nicht veröffentlicht. Einige Bundesländer haben eigene Speicherprogramme aufgelegt oder wieder eingestellt. Wer jetzt plant, sollte die Richtlinien des Bundes und seines Landes vor der Bestellung prüfen.

Moderne Heimspeicher arbeiten überwiegend mit Lithium-Eisenphosphat-Zellen. Sie gelten als vergleichsweise robust und langlebig. Hersteller geben meist eine Garantie auf eine bestimmte Anzahl von Ladezyklen oder eine Restkapazität nach zehn Jahren. Wichtig ist die fachgerechte Installation durch einen Elektriker, der auch die Absicherung und den Brandschutz am Aufstellort prüft. In Oberösterreich und anderen Bundesländern empfehlen die Energieberatungsstellen, den Speicher nicht in Fluchtwegen oder Wohnräumen aufzustellen und auf ausreichende Belüftung zu achten.

## Checkliste vor dem Kauf

- **Kompatibilität:** Passt der Speicher zum vorhandenen Wechselrichter?
- **Notstrom:** Soll der Speicher bei Netzausfall weiterliefern? Das erfordert eine eigene Umschaltung.
- **Garantie:** Auf Zyklen und Restkapazität nach zehn Jahren achten.
- **Aufstellort:** Trocken, frostfrei und nicht zu heiß, etwa im Keller oder Technikraum.
- **Energiemanagement:** Eine Steuerung, die Wärmepumpe oder Wallbox einbindet, erhöht den Nutzen.

Fazit: Wer einen Stromspeicher nachrüsten will, sollte nicht nach Gefühl kaufen, sondern Verbrauchsdaten auswerten und die Förderlage 2027 im Blick behalten.','energie','Photovoltaik','oberoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/stromspeicher-nachruesten-pv-anlage-worauf-achten.webp',NULL,NULL,'published','2026-09-26T08:18:00.000Z','2026-10-22T00:17:07.872Z','Stromspeicher nachrüsten: Wann sich ein Speicher lohnt','Stromspeicher nachrüsten: Wann eine Batterie zur bestehenden PV-Anlage passt, welche Größe sinnvoll ist und worauf Sie achten müssen. Jetzt prüfen.','Stromspeicher nachrüsten','["Stromspeicher nachrüsten","PV Speicher","Batteriespeicher Photovoltaik","Speicher Größe berechnen","stromspeicher nachrüsten bestehende pv anlage","ac gekoppelter speicher nachrüsten","pv speicher förderung 2027","batteriespeicher eigenverbrauch erhöhen"]','Stromspeicher nachrüsten: Batteriespeicher wird in der Garage an die PV-Anlage angeschlossen','Photorealistic editorial photo of an electrician''s hands connecting a battery storage cabinet in a tidy garage of an Upper Austrian family home, existing inverter on the wall, cool daylight from an open garage door, no text, no logos, no readable signs, no faces','[{"q":"Kann man jede PV-Anlage mit einem Speicher nachrüsten?","a":"Grundsätzlich ja. Je nach Wechselrichter wird der Speicher DC-seitig über einen Hybridwechselrichter oder AC-seitig mit eigenem Batteriewechselrichter angeschlossen."},{"q":"Wie groß sollte ein Stromspeicher sein?","a":"Als grobe Orientierung gilt: Der Speicher sollte etwa den abendlichen und nächtlichen Verbrauch eines Tages abdecken. Zu große Speicher werden im Winter selten voll."},{"q":"Gibt es eine Förderung für die Nachrüstung?","a":"Das Wirtschaftsministerium hat für 2027 einen eigenen Bonus für die Nachrüstung von Batterien angekündigt. Details stehen noch aus, einige Bundesländer haben eigene Programme."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('balkonkraftwerk-oesterreich-anmeldung-regeln','Balkonkraftwerk in Österreich: Regeln, Anmeldung und Ertrag','Steckerfertige Mini-PV-Anlagen sind auch in Österreich beliebt. Was erlaubt ist, wie man sie meldet und was Mieter und Wohnungseigentümer beachten sollten.','Ein Balkonkraftwerk in Österreich ist für viele Menschen ohne eigenes Dach der einfachste Einstieg in die Solarenergie. Die kleinen Anlagen bestehen meist aus ein oder zwei Modulen und einem Wechselrichter, der direkt in eine Steckdose eingesteckt wird. Der erzeugte Strom deckt vor allem die Grundlast im Haushalt, etwa Kühlschrank, Router oder Standby-Geräte.

## Balkonkraftwerk Österreich: Was erlaubt ist

Für steckerfertige Anlagen gelten in Österreich vereinfachte Regeln, wenn die Wechselrichterleistung im zulässigen Rahmen für Kleinstanlagen liegt, der derzeit bei 800 Watt angesetzt wird. Die Modulleistung darf etwas höher sein, entscheidend ist die Leistung, die ins Hausnetz abgegeben wird. Wer größere Anlagen plant, fällt unter die normalen Vorgaben für PV-Anlagen und braucht einen Elektriker.

Wichtig ist eine sichere Installation. Die Steckdose sollte in einem einwandfreien Zustand sein, idealerweise auf einem eigenen Stromkreis. Bei älteren Elektroinstallationen in Altbauten lohnt ein Check durch einen Fachbetrieb.

## Anmeldung beim Netzbetreiber

Auch ein Balkonkraftwerk muss beim zuständigen Netzbetreiber gemeldet werden – in Wien bei den Wiener Netze, in anderen Bundesländern beim jeweiligen Landesnetzbetreiber. Viele Netzbetreiber bieten dafür ein vereinfachtes Online-Formular an. Benötigt werden in der Regel Zählpunktnummer, Angaben zum Wechselrichter und zur Leistung.

Ist ein alter Ferraris-Zähler ohne Rücklaufsperre verbaut, tauscht der Netzbetreiber ihn meist gegen einen Smart Meter. Eine Einspeisevergütung gibt es nur mit einem eigenen Abnahmevertrag, was sich bei kleinen Mengen selten lohnt.

## Mieter und Wohnungseigentümer

In Mietwohnungen und Eigentumswohnungen ist die rechtliche Lage der heikelste Punkt. Balkon und Fassade gehören häufig zu den allgemeinen Teilen des Hauses. Für die Montage am Geländer braucht es daher in der Regel die Zustimmung des Vermieters oder der Eigentümergemeinschaft. Ohne diese Zustimmung riskiert man eine Aufforderung zum Rückbau. Eine aufgestellte Anlage auf dem Balkonboden, die nicht über das Geländer ragt, wird oft weniger streng beurteilt – verbindlich ist das aber nicht.

## Ertrag realistisch einschätzen

Wie viel ein Balkonkraftwerk bringt, hängt stark vom Standort ab:

- **Ausrichtung:** Süd ist ideal, Ost und West liefern morgens bzw. abends.
- **Neigung:** Senkrecht am Geländer montierte Module bringen weniger als schräg aufgestellte.
- **Verschattung:** Bäume, Nachbargebäude und Vordächer reduzieren den Ertrag deutlich.
- **Eigenverbrauch:** Nur der tatsächlich im Haushalt genutzte Strom spart Geld.

Eine sturmsichere Befestigung ist Pflicht. Gerade an exponierten Balkonen in oberen Stockwerken wirken bei Unwettern große Kräfte auf die Module. Lose oder schlecht montierte Paneele können herabfallen und Menschen oder Autos gefährden. Es empfiehlt sich, bei der Haushalts- oder Haftpflichtversicherung nachzufragen, ob die Anlage mitversichert ist oder gemeldet werden muss. Auch die Kabelführung verdient Aufmerksamkeit: Kabel sollten nicht durch Fensterdichtungen gequetscht werden und keine Stolperfallen bilden. Verlängerungskabel und Mehrfachsteckdosen sind für den Anschluss ungeeignet.

## Checkliste für den Kauf

1. Zustimmung von Vermieter oder Eigentümergemeinschaft einholen.
2. Leistung des Wechselrichters prüfen.
3. Stabile, sturmsichere Halterung wählen.
4. Steckdose und Stromkreis kontrollieren lassen.
5. Anlage beim Netzbetreiber melden.

Ein Balkonkraftwerk in Österreich ersetzt keine große Dachanlage, kann aber die Stromrechnung spürbar entlasten und ist mit überschaubarem Aufwand umsetzbar.','energie','Photovoltaik','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/balkonkraftwerk-oesterreich-anmeldung-regeln.webp',NULL,NULL,'published','2026-09-29T15:06:00.000Z','2026-10-22T00:17:07.873Z','Balkonkraftwerk Österreich: Regeln und Anmeldung','Balkonkraftwerk in Österreich: Welche Leistung erlaubt ist, wie die Anmeldung beim Netzbetreiber funktioniert und was Mieter beachten müssen. Jetzt lesen.','Balkonkraftwerk','["Balkonkraftwerk Österreich","Balkonkraftwerk anmelden","Mini-PV","Steckerfertige PV-Anlage","balkonkraftwerk 800 watt österreich","balkonkraftwerk mietwohnung wien erlaubnis","balkonkraftwerk netzbetreiber meldung","balkonkraftwerk ertrag pro jahr"]','Balkonkraftwerk in Österreich: Zwei Solarmodule am Balkongeländer eines Wiener Wohnhauses','Photorealistic editorial photo of two solar panels mounted on the railing of a balcony of a Viennese apartment block, potted plants and a small table, golden late-afternoon light, courtyard trees in the background, no text, no logos, no readable signs, no people','[{"q":"Muss ein Balkonkraftwerk in Österreich angemeldet werden?","a":"Ja, steckerfertige Anlagen sind beim zuständigen Netzbetreiber zu melden. Für kleine Anlagen gibt es ein vereinfachtes Verfahren, das meist online funktioniert."},{"q":"Darf ich als Mieter ein Balkonkraftwerk montieren?","a":"Da die Fassade meist zu den allgemeinen Teilen des Hauses gehört, ist die Zustimmung des Vermieters bzw. der Eigentümergemeinschaft nötig. Vorher schriftlich abklären."},{"q":"Wie viel Strom liefert ein Balkonkraftwerk?","a":"Das hängt von Ausrichtung, Neigung und Verschattung ab. Ein südseitiger, unverschatteter Balkon bringt deutlich mehr als ein Nordbalkon oder ein stark verbauter Innenhof."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('energiegemeinschaft-gruenden-oesterreich-ablauf','Energiegemeinschaft gründen: So teilen Nachbarn Solarstrom','In Energiegemeinschaften teilen Nachbarn, Gemeinden und Betriebe ihren Ökostrom. Wir erklären die Formen, den Gründungsablauf und worauf es ankommt.','Eine Energiegemeinschaft gründen – diese Idee verbreitet sich in Österreich seit einigen Jahren rasant. In Energiegemeinschaften teilen Privatpersonen, Gemeinden, Vereine und Betriebe selbst erzeugten Strom, meist aus Photovoltaik. Wer tagsüber Überschüsse hat, liefert an Mitglieder, die gerade Strom brauchen. Besonders in Niederösterreich und anderen ländlichen Regionen sind zahlreiche Gemeinschaften entstanden.

## Energiegemeinschaft gründen: Die drei Modelle

Das österreichische Recht kennt mehrere Formen:

- **Gemeinschaftliche Erzeugungsanlage:** Innerhalb eines Gebäudes, etwa eines Mehrparteienhauses, teilen sich Bewohner den Strom einer PV-Anlage am Dach.
- **Erneuerbare-Energie-Gemeinschaft (EEG):** Mitglieder im selben Netzgebiet teilen Ökostrom. Je nachdem, welche Netzebenen genutzt werden, unterscheidet man lokale und regionale EEGs.
- **Bürgerenergiegemeinschaft (BEG):** Sie kann österreichweit über mehrere Netzgebiete hinweg organisiert werden, erhält aber keine reduzierten Netzentgelte.

## Vorteile für Mitglieder

Bei lokalen und regionalen Erneuerbare-Energie-Gemeinschaften fallen für den innerhalb der Gemeinschaft geteilten Strom reduzierte Netzentgelte an, weil das übergeordnete Netz weniger beansprucht wird. Zudem können Mitglieder einen Strompreis vereinbaren, der für Erzeuger über der üblichen Einspeisevergütung und für Verbraucher unter dem Marktpreis liegt. Daneben stärkt die Gemeinschaft die regionale Wertschöpfung.

Wichtig: Strom aus der Gemeinschaft deckt nur einen Teil des Bedarfs. Für den Rest bleibt ein regulärer Liefervertrag mit einem Energieversorger nötig.

## Ablauf der Gründung

1. **Mitstreiter finden:** Erzeuger mit PV-Anlagen und Verbraucher im selben Netzgebiet zusammenbringen.
2. **Netzgebiet klären:** Beim Netzbetreiber erfragen, welche Zählpunkte zum lokalen oder regionalen Bereich gehören.
3. **Rechtsform wählen:** Häufig Verein oder Genossenschaft, mit Statuten und Vorstand.
4. **Verträge aufsetzen:** Teilnahmeverträge, Verteilschlüssel und Preise festlegen.
5. **Beim Netzbetreiber anmelden:** Die Gemeinschaft wird registriert, die Smart Meter der Mitglieder müssen viertelstündliche Werte liefern.
6. **Abrechnung organisieren:** Selbst oder über einen Dienstleister.

- **Smart Meter:** Ohne aktivierte Viertelstundenwerte funktioniert die Zuordnung nicht.
- **Verwaltungsaufwand:** Mitgliederwechsel, Abrechnung und Buchhaltung brauchen Zeit.
- **Ungleiche Erzeugung:** Im Winter liefert Photovoltaik wenig, das Verhältnis von Erzeugern zu Verbrauchern sollte ausgewogen sein.
- **Steuerliche Fragen:** Je nach Größe können Umsatz- und Ertragsteuerthemen auftreten.

## Welche Rolle Speicher und Wärmepumpen spielen

Je mehr Mitglieder ihren Verbrauch an die Erzeugung anpassen, desto besser funktioniert die Gemeinschaft. Wärmepumpen, Elektroautos oder Gewerbebetriebe mit hohem Tagesverbrauch sind deshalb wertvolle Mitglieder. Gemeinsame Batteriespeicher können Überschüsse in die Abendstunden verschieben, ihre Wirtschaftlichkeit hängt aber stark von den Netztarifen ab. Mit der Reform der Netzentgelte ab 2027 lohnt es sich, solche Pläne mit dem Netzbetreiber durchzusprechen. Auch Gemeinden mit Kläranlagen, Schulen oder Bauhöfen sind attraktive Partner, weil sie tagsüber viel Strom verbrauchen.

## Unterstützung für Gründer

Die Österreichische Koordinationsstelle für Energiegemeinschaften bietet Leitfäden und Musterverträge. Auch die Energieberatungen der Länder, etwa die Energie- und Umweltagentur in Niederösterreich, beraten kostenlos oder günstig. Viele Gemeinden treten selbst als Gründungsmitglied auf und stellen Dachflächen öffentlicher Gebäude zur Verfügung.

Wer eine Energiegemeinschaft gründen möchte, braucht vor allem engagierte Mitglieder und eine klare Organisation. Dann kann geteilter Solarstrom Kosten senken und die Energiewende vor Ort sichtbar machen.','energie','Photovoltaik','niederoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/energiegemeinschaft-gruenden-oesterreich-ablauf.webp',NULL,NULL,'published','2026-10-01T07:47:00.000Z','2026-10-22T00:17:07.873Z','Energiegemeinschaft gründen: Ablauf und Vorteile','Energiegemeinschaft gründen: Wie Nachbarn, Gemeinden und Betriebe Solarstrom teilen, welche Formen es gibt und welche Vorteile sie bringen. Jetzt starten.','Energiegemeinschaft gründen','["Energiegemeinschaft gründen","Erneuerbare Energiegemeinschaft","EEG Österreich","Bürgerenergiegemeinschaft","energiegemeinschaft gründen niederösterreich","energiegemeinschaft netzentgelt reduziert","pv strom mit nachbarn teilen","energiegemeinschaft verein genossenschaft"]','Energiegemeinschaft gründen: Dorf in Niederösterreich mit PV-Anlagen auf mehreren Dächern','Photorealistic editorial photo of a small Lower Austrian village street with several houses carrying solar panels on their roofs, church tower in the background, early autumn morning with light mist, aerial view from a low drone height, no text, no logos, no readable signs, no people','[{"q":"Welche Arten von Energiegemeinschaften gibt es?","a":"In Österreich gibt es vor allem Erneuerbare-Energie-Gemeinschaften (lokal oder regional) und Bürgerenergiegemeinschaften. Dazu kommen gemeinschaftliche Erzeugungsanlagen innerhalb eines Gebäudes."},{"q":"Welche Rechtsform braucht eine Energiegemeinschaft?","a":"Häufig werden Vereine oder Genossenschaften gegründet. Möglich sind auch andere Rechtsformen, entscheidend sind die Vorgaben des Erneuerbaren-Ausbau-Gesetzes."},{"q":"Wo bekomme ich Unterstützung?","a":"Die Österreichische Koordinationsstelle für Energiegemeinschaften sowie die Energieberatungsstellen der Länder bieten Informationen und Musterunterlagen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('waermepumpe-r290-propan-vorteile-aufstellung','Wärmepumpe R290: Vorteile, Sicherheit und Aufstellung','Wärmepumpen mit dem natürlichen Kältemittel Propan (R290) setzen sich durch. Sie erreichen hohe Vorlauftemperaturen, brauchen aber eine sorgfältige Aufstellung.','Die Wärmepumpe R290 ist derzeit eines der meistdiskutierten Themen beim Heizungstausch. Immer mehr Hersteller setzen bei Luft-Wasser-Wärmepumpen auf Propan als Kältemittel. Für Hausbesitzer stellt sich die Frage, welche Vorteile das bringt und was bei der Aufstellung zu beachten ist.

## Was hinter der Wärmepumpe R290 steckt

R290 ist die technische Bezeichnung für Propan. Es zählt zu den natürlichen Kältemitteln und hat ein sehr geringes Treibhauspotenzial. Viele bisher verwendete synthetische Kältemittel wirken im Falle eines Austritts um ein Vielfaches stärker auf das Klima. Die EU schränkt solche fluorierten Gase über die F-Gase-Verordnung schrittweise ein. Hersteller stellen deshalb ihre Produktlinien um.

## Vorteile der Propan-Wärmepumpe

- **Hohe Vorlauftemperaturen:** Viele R290-Geräte erreichen Vorlauftemperaturen von über 60 Grad. Das ist für Häuser mit klassischen Heizkörpern interessant.
- **Gute Effizienz:** Propan hat günstige thermodynamische Eigenschaften.
- **Zukunftssicherheit:** Natürliche Kältemittel sind von künftigen Verboten kaum betroffen.
- **Klimabilanz:** Bei Leckagen ist die Klimawirkung gering.

Trotzdem gilt: Auch mit R290 arbeitet eine Wärmepumpe umso effizienter, je niedriger die benötigte Vorlauftemperatur ist. Ein Gerät, das dauernd 65 Grad liefern muss, verbraucht deutlich mehr Strom.

## Sicherheit und Aufstellung der Wärmepumpe R290

Propan ist brennbar. Die Füllmengen in Hauswärmepumpen sind zwar gering, dennoch sind bei der Aufstellung Regeln einzuhalten. Meist werden R290-Geräte als Monoblock gebaut: Der gesamte Kältekreis befindet sich im Außengerät, ins Haus führen nur Wasserleitungen. So gelangt kein Kältemittel in Wohnräume.

Die Hersteller definieren rund um das Außengerät einen Schutzbereich. In diesem Bereich dürfen sich unter anderem keine Zündquellen, Kellerfenster, Lichtschächte oder Kanaleinläufe befinden, in denen sich schweres Propangas sammeln könnte. Die genauen Abstände unterscheiden sich je nach Modell und stehen in der Installationsanleitung.

## Checkliste für die Planung

1. **Heizlast berechnen lassen:** Grundlage für die richtige Gerätegröße.
2. **Vorlauftemperatur ermitteln:** Welche Temperatur braucht das Haus an kalten Tagen?
3. **Aufstellort prüfen:** Schutzbereich, Abstand zu Nachbarn und Schallschutz beachten.
4. **Fundament und Kondensat:** Stabiler Sockel und frostsichere Ableitung des Kondenswassers.
5. **Stromanschluss klären:** Eigener Stromkreis, eventuell Abstimmung mit dem Netzbetreiber.
6. **Bauordnung beachten:** Je nach Bundesland können Anzeige- oder Abstandsregeln gelten.

Neben der Sicherheit ist der Schall ein häufiger Konfliktpunkt. Außengeräte erzeugen durch Ventilator und Verdichter Geräusche, die besonders nachts als störend empfunden werden können. Moderne Geräte haben oft einen leisen Nachtmodus. Trotzdem sollte das Gerät nicht direkt unter dem Schlafzimmerfenster der Nachbarn stehen. Ecken und Nischen zwischen Wänden verstärken den Schall. Die Bundesländer haben teilweise eigene Regeln für Abstände und Schallpegel. Ein Schallgutachten oder eine Berechnung durch den Installateur schafft Sicherheit, bevor Ärger entsteht.

## Kosten und Förderung

Die Investitionskosten hängen von Leistung, Hersteller und Installationsaufwand ab. Für den Umstieg von Öl oder Gas gibt es Förderungen. Der Bund zahlt im Kesseltausch ab 2. November 2026 laut Klimaschutzministerium eine Pauschale von 5.000 Euro für Wärmepumpen. In der Steiermark und anderen Bundesländern gibt es zusätzliche Landesförderungen mit eigenen Bedingungen.

Fazit: Die Wärmepumpe R290 ist eine zukunftssichere Wahl, gerade im Bestand. Entscheidend sind fachgerechte Planung und die Einhaltung der Aufstellregeln durch einen erfahrenen Installateur.','energie','Heizen','steiermark','ratgeber','Presseinfo Redaktion','/assets/img/artikel/waermepumpe-r290-propan-vorteile-aufstellung.webp',NULL,NULL,'published','2026-10-02T09:23:00.000Z','2026-10-22T00:17:07.873Z','Wärmepumpe R290: Vorteile und Aufstellregeln','Wärmepumpe R290: Warum Propan als Kältemittel gefragt ist, welche Sicherheitsabstände gelten und für welche Häuser es passt. Ratgeber mit Checkliste.','Wärmepumpe R290','["Wärmepumpe R290","Propan Wärmepumpe","natürliches Kältemittel","Wärmepumpe Kältemittel","wärmepumpe r290 sicherheitsabstand","r290 wärmepumpe altbau vorlauftemperatur","f gase verordnung wärmepumpe","monoblock wärmepumpe propan"]','Wärmepumpe R290: Monoblock-Außengerät vor einem Bauernhaus in der Steiermark','Photorealistic editorial photo of a modern monobloc heat pump outdoor unit placed in front of a freshly plastered Styrian farmhouse wall, gravel bed, hills and autumn forest behind, soft overcast light, no text, no logos, no readable signs, no people','[{"q":"Ist eine R290-Wärmepumpe gefährlich?","a":"Propan ist brennbar, die Füllmengen sind aber gering und die Geräte sind dafür ausgelegt. Hersteller schreiben Schutzbereiche um das Außengerät vor, in denen keine Zündquellen oder Kellerschächte liegen dürfen."},{"q":"Warum ist R290 für Altbauten interessant?","a":"R290-Geräte erreichen höhere Vorlauftemperaturen als viele ältere Modelle. Das macht sie für Häuser mit Heizkörpern attraktiv, wobei die Effizienz bei hohen Temperaturen sinkt."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('heizungstausch-ablauf-oel-gas-ersetzen','Heizungstausch: So läuft der Umstieg von Öl und Gas ab','Ein Heizungstausch ist mehr als ein neues Gerät. Wer Bestandsaufnahme, Förderung und Zeitplan richtig ordnet, vermeidet Stillstand und Ärger.','Ein Heizungstausch steht in vielen Haushalten an: Öl- und Gaskessel kommen in die Jahre, Energiepreise schwanken und Förderungen sollen den Umstieg erleichtern. Damit der Wechsel ohne kalte Wohnung und unnötige Kosten gelingt, lohnt ein strukturierter Ablauf.

## Heizungstausch Schritt 1: Bestandsaufnahme

Am Anfang steht die Frage, was das Haus braucht. Wichtige Grundlagen sind:

- Öl- oder Gasverbrauch der vergangenen drei Jahre,
- Art der Wärmeabgabe: Heizkörper oder Fußbodenheizung,
- benötigte Vorlauftemperatur an kalten Tagen,
- Zustand von Dach, Fenstern und Fassade,
- Warmwasserbedarf und Anzahl der Bewohner.

Ein Energieausweis oder eine Energieberatung des Landes hilft, die Situation einzuschätzen. In Tirol bietet etwa Energie Tirol unabhängige Beratung an.

## Schritt 2: Das passende System wählen

Je nach Gebäude kommen verschiedene Lösungen in Frage. Eine Wärmepumpe ist häufig die erste Wahl, wenn das Haus mit moderaten Vorlauftemperaturen auskommt. Fernwärme bietet sich an, wo ein Netz verfügbar ist. Holz- und Pelletsheizungen eignen sich für Häuser mit Lagerraum und hohem Wärmebedarf, besonders in ländlichen Regionen. Eine Heizlastberechnung durch einen Fachbetrieb ist die Basis für die richtige Dimensionierung.

## Schritt 3: Förderung vor dem Auftrag klären

Bei vielen Förderungen ist die Reihenfolge entscheidend. Der Bund fördert den Kesseltausch über die Sanierungsoffensive, die Aktion öffnet laut Klimaschutzministerium am 2. November 2026 wieder. Dazu kommen Landesförderungen mit eigenen Fristen und Einkommensgrenzen. Wichtig ist, die Bedingungen vor der Auftragsvergabe zu lesen, damit keine Ansprüche verloren gehen.

Bevor es an den Umbau geht, sollten Angebote verglichen werden. Mindestens drei Angebote einzuholen ist sinnvoll. Achten Sie darauf, dass alle Angebote dieselben Leistungen umfassen: Demontage und Entsorgung des alten Kessels, Tankentsorgung, hydraulischer Abgleich, Elektroarbeiten, Fundament und Inbetriebnahme. Billige Angebote ohne Heizlastberechnung sind ein Warnsignal.

## Schritt 5: Umbau und Inbetriebnahme beim Heizungstausch

Der Umbau selbst dauert bei guter Vorbereitung oft nur wenige Tage. Im Winter überbrücken viele Betriebe die Zeit mit mobilen Heizgeräten. Der alte Öltank muss gereinigt und fachgerecht entsorgt oder stillgelegt werden, hier gelten je nach Bundesland eigene Vorschriften. Nach der Inbetriebnahme sollte der Installateur die Anlage einregulieren und eine Einschulung geben.

Ein Heizungstausch ist ein guter Anlass, auch die Gebäudehülle zu betrachten. Wer zuerst die oberste Geschoßdecke dämmt oder alte Fenster tauscht, senkt die Heizlast und kann eine kleinere, günstigere Heizung wählen. Nicht jede Maßnahme muss sofort umgesetzt werden, ein Sanierungsfahrplan hilft aber, die Reihenfolge sinnvoll zu planen. Ab 4. Jänner 2027 fördert der Bund laut Klimaschutzministerium im Rahmen der Sanierungsoffensive auch einzelne Bauteile wie Fenster und Dämmung. Damit lassen sich Heizungstausch und Sanierung besser kombinieren.

## Häufige Fehler beim Heizungstausch vermeiden

- **Überdimensionierung:** Das neue Gerät nach der Leistung des alten Kessels zu wählen.
- **Förderfristen übersehen:** Auftrag oder Rechnung vor der Registrierung.
- **Hydraulik vergessen:** Ohne Abgleich steigt der Verbrauch.
- **Schallschutz ignorieren:** Außengeräte von Wärmepumpen nicht direkt neben Nachbarfenster stellen.
- **Warmwasser falsch planen:** Zu große Speicher erhöhen Verluste.

Ein gut geplanter Heizungstausch senkt langfristig Kosten und Emissionen. Wer sich Zeit für die Vorbereitung nimmt, profitiert über Jahrzehnte.','energie','Heizen','tirol','ratgeber','Presseinfo Redaktion','/assets/img/artikel/heizungstausch-ablauf-oel-gas-ersetzen.webp',NULL,NULL,'published','2026-10-03T06:51:00.000Z','2026-10-22T00:17:07.874Z','Heizungstausch: Ablauf beim Umstieg von Öl und Gas','Heizungstausch Schritt für Schritt: Von der Bestandsaufnahme über den Förderantrag bis zur Inbetriebnahme. So gelingt der Umstieg. Jetzt planen.','Heizungstausch','["Heizungstausch","Ölheizung tauschen","Gasheizung ersetzen","Heizungstausch Ablauf","heizungstausch ablauf schritt für schritt","ölheizung durch wärmepumpe ersetzen","öltank entsorgen kosten","heizungstausch im winter"]','Heizungstausch: Leerer Kellerraum nach Ausbau des Öltanks in einem Tiroler Haus','Photorealistic editorial photo of an empty basement room in a Tyrolean house after removal of an oil tank, clean concrete floor, new pipes on the wall, small window showing snowy mountains outside, cold morning light, no text, no logos, no readable signs, no people','[{"q":"Wie lange dauert ein Heizungstausch?","a":"Der eigentliche Umbau dauert bei guter Vorbereitung oft nur wenige Tage. Mit Planung, Förderantrag und Lieferzeiten sollte man mehrere Wochen bis Monate einplanen."},{"q":"Kann man die Heizung im Winter tauschen?","a":"Ja, viele Betriebe tauschen auch im Winter und überbrücken mit mobilen Heizgeräten. Ruhiger ist es im Frühjahr oder Sommer."},{"q":"Was passiert mit dem alten Öltank?","a":"Er muss fachgerecht gereinigt, entleert und entsorgt oder stillgelegt werden. Je nach Bundesland gelten dafür eigene Vorschriften."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('fernwaerme-oder-waermepumpe-vergleich','Fernwärme oder Wärmepumpe: Was passt besser zum Haus?','Wer von Gas oder Öl umsteigt, hat in Städten oft die Wahl zwischen Fernwärmeanschluss und Wärmepumpe. Ein Vergleich der wichtigsten Kriterien.','Fernwärme oder Wärmepumpe – vor dieser Entscheidung stehen viele Hausbesitzer in Städten und größeren Gemeinden, wenn die alte Gas- oder Ölheizung ersetzt werden muss. Beide Systeme gelten als klimafreundlichere Alternativen, unterscheiden sich aber bei Kosten, Platzbedarf und Abhängigkeiten deutlich.

## Fernwärme oder Wärmepumpe: Die Grundprinzipien

**Fernwärme** wird zentral erzeugt, etwa in Heizkraftwerken, Biomasseanlagen oder aus industrieller Abwärme, und über ein Rohrnetz verteilt. Im Haus ersetzt eine kompakte Übergabestation den Kessel. **Eine Wärmepumpe** entzieht der Umgebungsluft, dem Erdreich oder dem Grundwasser Wärme und hebt sie mit Strom auf Heiztemperatur.

## Kosten im Vergleich

Bei der Fernwärme fallen Anschlusskosten an, die je nach Entfernung zur Leitung und Versorger stark schwanken. Die Übergabestation ist meist günstiger als eine Wärmepumpe. Laufend zahlt man Grund- und Arbeitspreis an den Versorger.

Die Wärmepumpe ist in der Anschaffung teurer, besonders mit Tiefenbohrung. Die Betriebskosten hängen von Strompreis und Jahresarbeitszahl ab. Wer eine Photovoltaikanlage besitzt, kann einen Teil des Stroms selbst erzeugen.

## Abhängigkeit und Preisentwicklung

Bei Fernwärme ist man an einen Anbieter gebunden, ein Wechsel ist nicht möglich. Die Preise hängen vom Erzeugungsmix ab. In Wien etwa wird die Fernwärme laut Wien Energie noch zu gut der Hälfte mit Erdgas erzeugt, weshalb höhere Gaspreise auf die Tarife durchschlagen. Andere Netze, etwa mit Biomasse, sind anders aufgestellt.

Bei der Wärmepumpe wählt man den Stromanbieter frei. Ab 2027 ändern sich allerdings die Netztarife, ein Teil wird dann nach der höchsten bezogenen Leistung berechnet.

Auch beim Platzbedarf unterscheiden sich die Systeme:

- **Fernwärme:** Kaum Platzbedarf, kein Außengerät, keine Geräusche, wenig Wartung.
- **Wärmepumpe:** Außengerät oder Bohrung nötig, Abstände und Schallschutz zu Nachbarn beachten, regelmäßige Wartung empfohlen.

In dicht verbauten Reihenhaussiedlungen ist Fernwärme deshalb oft die einfachere Lösung, sofern ein Netz vorhanden ist.

## Förderung für Fernwärme oder Wärmepumpe

Der Bund fördert beide Varianten im Rahmen des Kesseltauschs. Laut Klimaschutzministerium gibt es ab 2. November 2026 eine Pauschale von 4.000 Euro für den Fernwärmeanschluss und 5.000 Euro für eine Wärmepumpe. In Salzburg und anderen Bundesländern kommen Landesförderungen hinzu, deren Bedingungen man direkt beim Land prüfen sollte.

Wie klimafreundlich die beiden Varianten sind, hängt von der Energiequelle ab. Fernwärme aus Biomasse, Abwärme oder Geothermie schneidet sehr gut ab, Fernwärme mit hohem Gasanteil weniger. Viele Versorger arbeiten daran, den fossilen Anteil zu senken. Eine Wärmepumpe ist so sauber wie der Strom, mit dem sie betrieben wird. Österreich erzeugt einen großen Teil seines Stroms aus Wasserkraft, Wind und Photovoltaik. In beiden Fällen gilt: Je besser das Haus gedämmt ist, desto weniger Energie wird gebraucht, egal welches System zum Einsatz kommt.

## Entscheidungshilfe

- Liegt eine Fernwärmeleitung in der Straße? Dann Angebot des Versorgers einholen.
- Kommt das Haus mit niedriger Vorlauftemperatur aus? Dann spricht viel für eine Wärmepumpe.
- Gibt es eine PV-Anlage oder ist eine geplant? Das verbessert die Bilanz der Wärmepumpe.
- Ist wenig Platz und Lärmschutz kritisch? Dann hat Fernwärme Vorteile.

Am Ende entscheidet die konkrete Situation. Eine unabhängige Energieberatung und Vergleichsangebote beider Varianten schaffen Klarheit, ob Fernwärme oder Wärmepumpe besser passt.','energie','Heizen','salzburg','ratgeber','Presseinfo Redaktion','/assets/img/artikel/fernwaerme-oder-waermepumpe-vergleich.webp',NULL,NULL,'published','2026-10-05T11:37:00.000Z','2026-10-22T00:17:07.874Z','Fernwärme oder Wärmepumpe: Der große Vergleich','Fernwärme oder Wärmepumpe? Kosten, Platzbedarf, Abhängigkeit und Förderung im Vergleich. So finden Sie die passende Heizung für Ihr Haus. Jetzt lesen.','Fernwärme oder Wärmepumpe','["Fernwärme oder Wärmepumpe","Fernwärme Vergleich","Wärmepumpe Vergleich","Heizsystem wählen","fernwärme oder wärmepumpe einfamilienhaus","fernwärme anschlusskosten einfamilienhaus","wärmepumpe vs fernwärme betriebskosten","heizung tauschen welches system"]','Fernwärme oder Wärmepumpe: Baugrube für Fernwärmeleitungen vor Reihenhäusern in Salzburg','Photorealistic editorial photo of a residential street in the city of Salzburg with an open trench for district heating pipes in front of row houses, construction barriers without signage, crisp October afternoon light, fortress hill in the far background, no text, no logos, no readable signs, no people','[{"q":"Ist Fernwärme günstiger als eine Wärmepumpe?","a":"Das lässt sich nicht pauschal sagen. Bei Fernwärme fallen geringere Anschaffungskosten an, aber laufende Tarife des Versorgers. Die Wärmepumpe ist teurer in der Anschaffung, die Betriebskosten hängen vom Strompreis und der Effizienz ab."},{"q":"Welche Förderung gibt es für Fernwärme?","a":"Im Bundes-Kesseltausch gibt es laut Klimaschutzministerium ab 2. November 2026 eine Pauschale von 4.000 Euro für den Fernwärmeanschluss, für Wärmepumpen 5.000 Euro."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('waermepumpe-foerderung-wien-stadt-bund-kombinieren','Wärmepumpe Förderung Wien: Stadt und Bund kombinieren','Wer in Wien von Gas oder Öl auf eine Wärmepumpe umsteigt, kann Landes- und Bundesförderung kombinieren. Worauf es bei Antrag und förderfähigen Kosten ankommt.','Die Wärmepumpe Förderung Wien ist für viele Hausbesitzer und Eigentümergemeinschaften ein wichtiger Baustein bei der Finanzierung des Heizungstauschs. In Wien sind noch Hunderttausende Wohnungen mit Gas beheizt. Wer umsteigen will, kann in vielen Fällen Zuschüsse der Stadt Wien und des Bundes kombinieren – vorausgesetzt, die Bedingungen werden eingehalten.

## Wärmepumpe Förderung Wien: Die Stadt als erste Anlaufstelle

Laut einem Bericht von VIENNA.AT aus dem Februar 2026 fördert die Stadt Wien den Umstieg von fossilen Heizungen auf Wärmepumpen mit 35 Prozent der anerkannten Kosten, höchstens 8.000 Euro. Gemeinsam mit der Bundesförderung waren damals bis zu 15.500 Euro möglich. Die Förderprogramme werden jedoch regelmäßig angepasst. Vor jeder Planung sollten die aktuellen Richtlinien auf den Seiten der Stadt Wien geprüft werden.

## Bundesförderung über den Kesseltausch

Der Bund fördert den Heizungstausch über die Sanierungsoffensive. Die Mittel für 2026 waren im Sommer ausgeschöpft. Laut Klimaschutzministerium öffnet die Aktion am 2. November 2026 wieder, diesmal mit einer Pauschale von 5.000 Euro für Wärmepumpen in Ein- und Zweifamilienhäusern sowie Reihenhäusern. Ab 2027 sinkt die Förderquote laut Ministerium auf rund 20 Prozent. Für den mehrgeschoßigen Wohnbau gibt es eigene Programme.

## Welche Kosten förderfähig sind

Ein häufiger Stolperstein sind die förderfähigen Kosten. Laut dem Bericht erkennt die Stadt Wien reine Eigenleistungen, Pauschalen und Materialkosten ohne Montage nicht an. Der Bund fördert keine in Eigenregie errichteten Anlagen. Wer selbst Hand anlegt, riskiert also, Förderansprüche zu verlieren. Typischerweise förderfähig sind dagegen:

- Wärmepumpe inklusive Montage durch einen befugten Betrieb,
- Demontage und Entsorgung der alten Heizung,
- notwendige Anpassungen an Heizkörpern und Leitungen,
- Elektroinstallation für den Anschluss,
- Planung und Heizlastberechnung, sofern in den Richtlinien vorgesehen.

## Ablauf für die Förderung in Wien

1. **Beratung nutzen:** Die Hauskunft und die Energieberatung der Stadt informieren kostenlos.
2. **Angebote einholen:** Auf vollständige, nachvollziehbare Positionen achten.
3. **Fristen prüfen:** Bei manchen Programmen muss vor Auftragsvergabe registriert werden.
4. **Umsetzen lassen:** Nur durch befugte Fachbetriebe.
5. **Abrechnen:** Rechnungen, Zahlungsnachweise und Fotos sammeln und fristgerecht einreichen.

Laut dem Bericht liegen die Gesamtkosten für einen Heizungstausch auf eine Wärmepumpe meist im Bereich von etwa 20.000 bis 30.000 Euro, häufig bei 20.000 bis 25.000 Euro. Der tatsächliche Betrag hängt stark vom Gebäude ab: Müssen Heizkörper getauscht, Leitungen neu verlegt oder Fundamente errichtet werden, steigen die Kosten. Wer frühzeitig mehrere Angebote einholt und die Förderungen von Stadt und Bund einrechnet, erhält ein realistisches Bild des Eigenanteils. Eine Finanzierungszusage der Bank sollte vor Auftragsvergabe vorliegen.

## Besonderheiten im Wiener Altbau

In Gründerzeithäusern mit Gasetagenheizungen ist eine Wärmepumpe pro Wohnung oft schwierig. Hier kommen zentrale Lösungen für das ganze Haus, Fernwärme oder Großwärmepumpen in Frage. Für solche Projekte braucht es Beschlüsse der Eigentümer und häufig auch eine Abstimmung mit der Baupolizei, etwa wegen Aufstellung am Dach oder im Hof.

Fazit: Die Wärmepumpe Förderung Wien kann einen erheblichen Teil der Kosten abdecken. Entscheidend sind aktuelle Richtlinien, korrekte Reihenfolge und die Ausführung durch Fachbetriebe.','energie','Förderungen','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/waermepumpe-foerderung-wien-stadt-bund-kombinieren.webp','VIENNA.AT','https://www.vienna.at/heizungstausch-in-wien-worauf-haushalte-beim-umstieg-von-gas-oder-oel-auf-moderne-systeme-achten-sollten/9950027','published','2026-10-06T05:58:00.000Z','2026-10-22T00:17:07.874Z','Wärmepumpe Förderung Wien: Stadt und Bund kombinieren','Wärmepumpe Förderung Wien: Wie sich Zuschüsse der Stadt Wien und des Bundes kombinieren lassen und welche Kosten förderfähig sind. Jetzt Förderung prüfen.','Wärmepumpe Förderung Wien','["Wärmepumpe Förderung Wien","Heizungstausch Förderung Wien","Stadt Wien Förderung Heizung","Raus aus Gas Wien","wärmepumpe förderung wien 2026 höhe","förderung heizungstausch wien eigenleistung","wien förderung wärmepumpe und bund kombinieren","gasheizung tauschen wien förderung"]','Wärmepumpe Förderung Wien: Außengerät auf der Dachterrasse eines Wiener Altbaus','Photorealistic editorial photo of a compact heat pump outdoor unit on the flat roof terrace of a renovated Viennese Gründerzeit building, chimneys and church domes of Vienna in the background, blue hour lighting, no text, no logos, no readable signs, no people','[{"q":"Wie hoch ist die Wärmepumpen-Förderung in Wien?","a":"Laut einem Bericht von Anfang 2026 fördert die Stadt Wien 35 Prozent der anerkannten Kosten, maximal 8.000 Euro. Die aktuellen Bedingungen sollten direkt bei der Stadt Wien geprüft werden."},{"q":"Werden Eigenleistungen gefördert?","a":"Nein. Laut Bericht erkennt die Stadt Wien reine Eigenleistungen, Pauschalen und Materialkosten nicht an, der Bund fördert keine in Eigenregie errichteten Anlagen."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pv-foerderung-bundeslaender-ueberblick','PV-Förderung der Bundesländer: Worauf Antragsteller achten','Neben dem Bund fördern viele Bundesländer und Gemeinden Photovoltaik oder Speicher. Wie man den Überblick behält und typische Fehler vermeidet.','Die PV-Förderung der Bundesländer ist ein unübersichtliches Feld. Neben dem bundesweiten EAG-Investitionszuschuss haben die Länder eigene Programme für Photovoltaik, Stromspeicher oder Energiegemeinschaften aufgelegt – manche laufend, manche nur zeitweise. Dazu kommen Zuschüsse von Gemeinden. Wer eine Anlage plant, sollte die Ebenen systematisch prüfen.

## PV-Förderung der Bundesländer: Warum sie so unterschiedlich sind

Jedes Bundesland setzt eigene Schwerpunkte. Einige fördern vor allem Stromspeicher, andere Photovoltaik im Rahmen der Wohnbauförderung oder bei Sanierungen. Das Burgenland etwa hat für 2026 eine eigene Richtlinie für Stromspeicher veröffentlicht. In anderen Ländern wurden Speicherprogramme nach Ausschöpfung der Mittel eingestellt. Förderhöhen, Einkommensgrenzen und Fristen unterscheiden sich daher stark.

## Zusammenspiel mit der Bundesförderung

Auf Bundesebene gab es 2026 den EAG-Investitionszuschuss mit drei Fördercalls, der letzte endete am 22. Oktober. Ab 2027 will das Wirtschaftsministerium die Bundesförderung auf Speicher, Energiemanagement und Sonderformen konzentrieren. Für Länder bedeutet das: Manche werden ihre Programme anpassen, um Lücken bei kleinen Dachanlagen zu schließen oder Doppelungen bei Speichern zu vermeiden.

Ob Bundes- und Landesförderung kombinierbar sind, regelt jede Landesrichtlinie selbst. Häufig gibt es Obergrenzen, etwa einen maximalen Anteil der Gesamtkosten, der gefördert werden darf.

## Typische Voraussetzungen

Auch wenn die Details variieren, kehren einige Bedingungen immer wieder:

- Hauptwohnsitz im Bundesland,
- Errichtung durch einen befugten Fachbetrieb,
- Nachweis der Netzanmeldung bzw. Fertigmeldung,
- Einreichung innerhalb bestimmter Fristen nach Rechnungslegung,
- teilweise Kombination mit einer Energieberatung.

## Fehler, die Förderungen kosten

1. **Zu früh beauftragt:** Manche Programme verlangen den Antrag vor Auftragsvergabe.
2. **Frist verpasst:** Nach Inbetriebnahme läuft oft nur ein begrenztes Zeitfenster.
3. **Unterlagen unvollständig:** Fehlende Rechnungen oder Zahlungsbelege verzögern die Auszahlung.
4. **Doppelförderung übersehen:** Eine nicht erlaubte Kombination kann zu Rückforderungen führen.
5. **Gemeinde vergessen:** Viele Gemeinden zahlen kleine Zuschüsse, die selten beworben werden.

Im Burgenland und in Teilen Niederösterreichs sind die Stromnetze durch den starken Ausbau von Wind und Photovoltaik vielerorts stark ausgelastet. Netzbetreiber begrenzen deshalb mitunter die Einspeiseleistung neuer Anlagen. Speicher und Eigenverbrauch gewinnen damit an Bedeutung, was sich auch in den Förderschwerpunkten der Länder widerspiegelt. In alpinen Regionen wie Tirol oder Vorarlberg spielen dagegen Schneelasten und Dachneigung eine größere Rolle bei der Planung. Wer regional plant, sollte daher auch technische Vorgaben des Netzbetreibers vor der Förderung abklären.

## So gehen Sie vor

- **Bundesland prüfen:** Website der Landesregierung, Bereich Energie oder Wohnbauförderung.
- **Energieberatung kontaktieren:** Die Beratungsstellen der Länder kennen aktuelle Programme.
- **Gemeindeamt fragen:** Nach kommunalen Zuschüssen erkundigen.
- **Fachbetrieb einbinden:** Erfahrene Installateure kennen die regionalen Abläufe.
- **Alles dokumentieren:** Angebote, Rechnungen, Fotos und Fertigmeldung aufbewahren.

Gerade bei kombinierten Projekten mit Speicher, Wärmepumpe oder Sanierung lohnt eine Gesamtbetrachtung, weil unterschiedliche Förderstellen zuständig sein können. Konkrete Beträge nennen wir bewusst nicht, weil sie sich häufig ändern. Verbindlich ist ausschließlich die jeweils gültige Richtlinie des Landes. Wer die PV-Förderung der Bundesländer richtig nutzt, kann die Investition aber spürbar senken.','energie','Förderungen','burgenland','ratgeber','Presseinfo Redaktion','/assets/img/artikel/pv-foerderung-bundeslaender-ueberblick.webp',NULL,NULL,'published','2026-10-07T13:12:00.000Z','2026-10-22T00:17:07.874Z','PV-Förderung Bundesländer: Überblick und Tipps','PV-Förderung der Bundesländer: Warum Landesprogramme unterschiedlich sind, wie sie mit der Bundesförderung zusammenspielen und wie Sie richtig einreichen.','PV-Förderung','["PV-Förderung Bundesländer","Photovoltaik Förderung Land","Landesförderung PV","Speicherförderung Bundesland","pv förderung niederösterreich burgenland steiermark","photovoltaik landesförderung kombinieren bund","pv förderung gemeinde zuschuss","stromspeicher förderung burgenland 2026"]','PV-Förderung Bundesländer: Photovoltaik auf einer Scheune im Burgenland mit Windrädern','Photorealistic editorial photo of a farmhouse in Burgenland with a large solar array on a barn roof, flat Pannonian landscape with wind turbines on the horizon, warm late-afternoon autumn light, no text, no logos, no readable signs, no people','[{"q":"Kann ich Bundes- und Landesförderung für PV kombinieren?","a":"Das hängt vom jeweiligen Landesprogramm ab. Manche Länder erlauben die Kombination, andere schließen Doppelförderungen aus. Die Richtlinie des Landes gibt Auskunft."},{"q":"Wo finde ich die Förderungen meines Bundeslandes?","a":"Auf der Website der Landesregierung, meist im Bereich Wohnbauförderung oder Energie, sowie bei den Energieberatungsstellen der Länder. Viele Gemeinden bieten zusätzlich eigene Zuschüsse."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('hitzesommer-2026-oesterreich-bilanz-geosphere','Hitzesommer 2026: Österreich erlebte den heißesten Sommer','Der Sommer 2026 war der heißeste der Messgeschichte. Erstmals wurden in Österreich mehr als 41 Grad gemessen. Was die Bilanz für Haushalte bedeutet.','Der Hitzesommer 2026 hat in Österreich Rekorde gebrochen. Laut Bilanz der GeoSphere Austria war es der heißeste Sommer der Messgeschichte. Erstmals wurde die Marke von 41 Grad überschritten, an mehr als hundert Messstationen fielen Rekorde. Für Haushalte, Gemeinden und Landwirtschaft hat das spürbare Folgen.

## Hitzesommer 2026: Die Rekordwerte

Am 5. August wurden in Bad Deutsch-Altenburg in Niederösterreich 41,2 Grad gemessen – der höchste Wert, der in Österreich je registriert wurde. Bereits im Juni wurde erstmals die 40-Grad-Marke erreicht. Am 31. Juli zeigte das Thermometer in Wieselburg 40,3 Grad. Insgesamt meldeten zehn Stationen an sechs Tagen 40 Grad oder mehr.

Im Durchschnitt lag die Temperatur 2,6 Grad über dem Mittel der Jahre 1991 bis 2020 und 4,4 Grad über dem Mittel 1961 bis 1990. Alle zehn wärmsten Sommer der Messreihe fallen ins 21. Jahrhundert.

## Hitzetage und Stationsrekorde

Laut GeoSphere verzeichneten 103 Stationen neue Temperaturrekorde, 157 einen neuen Höchstwert an Hitzetagen mit mindestens 30 Grad. Den höchsten Wert erreichten Bad Deutsch-Altenburg, Ferlach und St. Andrä im Lavanttal mit je 55 Hitzetagen. In Lagen unter 500 Metern gab es im Schnitt 42 Hitzetage, ein Plus von rund 170 Prozent gegenüber dem Klimamittel.

## Extreme Trockenheit

Neben der Hitze war vor allem der fehlende Regen ein Problem. Im Sommer fiel rund ein Drittel weniger Niederschlag als üblich. Bereits das Frühjahr hatte nur etwa die Hälfte der üblichen Menge gebracht. Im Waldviertel und im nördlichen Weinviertel lag das Defizit bei bis zu 70 Prozent. Die ersten acht Monate 2026 waren laut GeoSphere die trockensten seit Beginn der Aufzeichnungen im Jahr 1858.

Die Folgen für die Landwirtschaft sind gravierend: Die Hagelversicherung bezifferte die Schäden durch die Dürre bis Mitte August auf rund eine Milliarde Euro.

Auch in den Bergen war der Sommer außergewöhnlich. Die Zahl der Frosttage im Hochgebirge ging laut GeoSphere drastisch zurück. In Lagen zwischen 500 und 1.000 Metern gab es im Schnitt 27 Hitzetage, rund viermal so viele wie im Klimamittel. Für Gletscher, Permafrost und Wasserversorgung sind solche Werte eine erhebliche Belastung. Zugleich steigt in Hitzeperioden der Strombedarf für Kühlung, während Flusskraftwerke bei Niedrigwasser weniger liefern. Photovoltaik erreicht dagegen zu Mittag Höchstwerte, was die Bedeutung von Speichern unterstreicht.

## Was der Hitzesommer 2026 für Haushalte bedeutet

Die Zahlen zeigen, dass Hitzeschutz in Wohnungen und Häusern immer wichtiger wird. Mögliche Maßnahmen:

- **Außenliegender Sonnenschutz:** Rollläden und Markisen halten Wärme draußen, bevor sie ins Haus gelangt.
- **Dämmung:** Eine gute Dämmung schützt nicht nur im Winter, sondern auch vor Überhitzung.
- **Begrünung:** Bäume, Fassaden- und Dachbegrünung kühlen die unmittelbare Umgebung.
- **Wärmepumpe mit Kühlfunktion:** Viele Geräte können im Sommer über Fußbodenheizung sanft kühlen.
- **Regenwasser sammeln:** Zisternen entlasten in Trockenperioden die Gartenbewässerung.

Auch die Politik reagiert: Die Sanierungsoffensive 2027 enthält einen neuen Bonus für Verschattung und Gebäudebegrünung. Der Hitzesommer 2026 dürfte die Debatte um Klimaanpassung in Gemeinden und Städten weiter verstärken.','energie','Klima','niederoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/hitzesommer-2026-oesterreich-bilanz-geosphere.webp','GeoSphere Austria','https://geosphere.at/en/news-and-events/news/hottest-summer-on-record-record-temperatures-at-more-than-100-geosphere-austria-monitoring-stations','published','2026-09-27T10:44:00.000Z','2026-10-22T00:17:07.875Z','Hitzesommer 2026: Bilanz der GeoSphere Austria','Hitzesommer 2026: 41,2 Grad, Rekorde an über 100 Stationen und extreme Trockenheit. Was die Bilanz der GeoSphere zeigt und was Haushalte daraus lernen.','Hitzesommer 2026','["Hitzesommer 2026","Hitzerekord Österreich","heißester Sommer Österreich","GeoSphere Austria Bilanz","hitzesommer 2026 41 grad bad deutsch altenburg","trockenheit österreich 2026 waldviertel","hitzetage rekord österreich","klimawandel österreich folgen haushalte"]','Hitzesommer 2026: Ausgetrocknete Felder und rissiger Boden im niederösterreichischen Weinviertel','Photorealistic editorial photo of a parched yellow meadow and dried-out maize field in the Lower Austrian Weinviertel under a hazy hot sky, cracked soil in the foreground, harsh midday sun, no text, no logos, no readable signs, no people','[{"q":"Wie heiß war es im Sommer 2026 in Österreich?","a":"Laut GeoSphere Austria wurden am 5. August in Bad Deutsch-Altenburg 41,2 Grad gemessen, der höchste je in Österreich registrierte Wert. Der Sommer lag 2,6 Grad über dem Mittel 1991 bis 2020."},{"q":"Wie trocken war der Sommer?","a":"Es fiel rund ein Drittel weniger Niederschlag als üblich. Die ersten acht Monate 2026 waren die trockensten seit Beginn der Aufzeichnungen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('hitzeschutz-wohnung-tipps-sommer','Hitzeschutz in der Wohnung: Was wirklich gegen Überhitzung hilft','Nach dem Rekordsommer 2026 suchen viele nach dauerhaftem Hitzeschutz. Welche Maßnahmen in Wohnung und Haus am meisten bringen – von Beschattung bis Dämmung.','Hitzeschutz in der Wohnung ist nach dem Sommer 2026 für viele kein Randthema mehr. Laut GeoSphere Austria war es der heißeste Sommer der Messgeschichte, in Wien und anderen Städten blieben Wohnungen oft wochenlang über 28 Grad. Besonders betroffen sind Dachgeschoße und Wohnungen mit großen Süd- oder Westfenstern. Wer jetzt im Herbst plant, kann bis zum nächsten Sommer viel verbessern.

## Hitzeschutz Wohnung: Die Sonne draußen halten

Die wirksamste Maßnahme ist außenliegender Sonnenschutz. Rollläden, Raffstores oder Markisen halten die Strahlung ab, bevor sie durch das Glas in den Raum gelangt. Innenliegende Jalousien oder Vorhänge helfen deutlich weniger, weil die Wärme dann schon im Zimmer ist. Auch Sonnenschutzfolien auf den Scheiben können die Einstrahlung reduzieren, sie dunkeln den Raum aber dauerhaft ab.

In Mietwohnungen und im Wohnungseigentum braucht es für Änderungen an der Fassade die Zustimmung von Vermieter oder Eigentümergemeinschaft. In Wien sind je nach Gebäude zusätzlich baurechtliche Vorgaben zu beachten, etwa in Schutzzonen.

## Richtig lüften und Wärmequellen reduzieren

- **Nachts und früh morgens lüften:** Querlüften, wenn die Außentemperatur unter der Innentemperatur liegt.
- **Tagsüber geschlossen halten:** Fenster und Beschattung schließen, sobald es draußen wärmer wird.
- **Geräte abschalten:** Alte Kühlschränke, Standby-Geräte und Halogenlampen geben Wärme ab.
- **Kochen und Backen verlegen:** Backofen in die kühleren Stunden verschieben.
- **Ventilatoren gezielt einsetzen:** Sie kühlen nicht die Luft, sorgen aber für ein angenehmeres Empfinden.

## Bauliche Maßnahmen gegen Überhitzung

Langfristig hilft die Gebäudehülle. Eine gut gedämmte oberste Geschoßdecke oder ein gedämmtes Dach verhindert, dass sich Hitze aus dem Dachraum in die Wohnung überträgt. Neue Fenster mit Sonnenschutzverglasung reduzieren den Wärmeeintrag. Fassaden- und Dachbegrünung kühlen durch Verdunstung und Verschattung die unmittelbare Umgebung.

Für Häuser mit Fußbodenheizung und Wärmepumpe gibt es eine weitere Möglichkeit: Viele Geräte können im Sommer über die Fußbodenheizung sanft kühlen. Das ist energiesparender als klassische Klimageräte, erreicht aber keine großen Temperaturabsenkungen.

## Klimageräte: Wenn es nicht anders geht

In stark überhitzten Wohnungen greifen viele zu Klimageräten. Mobile Monoblockgeräte mit Abluftschlauch sind günstig, aber wenig effizient und laut. Fest installierte Split-Geräte arbeiten deutlich effizienter, brauchen aber ein Außengerät, für das wiederum Zustimmungen und teils baurechtliche Genehmigungen nötig sind. Eine Kombination mit Photovoltaik ist sinnvoll, weil Kühlbedarf und Solarertrag zeitlich zusammenfallen. Kältemittel und Montage sollten Fachbetrieben überlassen werden.

## Förderung für Hitzeschutz ab 2027

Das Klimaschutzministerium hat für die Sanierungsoffensive 2027 einen neuen Bonus für Verschattung und Gebäudebegrünung angekündigt. Die Details sollen mit den Informationsblättern im Dezember 2026 veröffentlicht werden. Auch manche Städte und Länder fördern Begrünungsprojekte. Wer Hitzeschutz in der Wohnung plant, sollte die Programme vor der Auftragsvergabe prüfen und Angebote rechtzeitig vor dem Frühjahr einholen, wenn die Nachfrage erfahrungsgemäß steigt.

Klar ist: Hitzeperioden werden häufiger. Wer heute in Beschattung und Dämmung investiert, gewinnt Wohnkomfort und schützt vor allem ältere Menschen und Kinder vor Hitzestress.','energie','Klima','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/hitzeschutz-wohnung-tipps-sommer.webp',NULL,NULL,'published','2026-09-28T08:52:00.000Z','2026-10-22T00:17:07.875Z','Hitzeschutz Wohnung: Was gegen Überhitzung hilft','Hitzeschutz in der Wohnung: Außenliegende Beschattung, richtiges Lüften und bauliche Maßnahmen gegen Überhitzung. So bleibt es kühler – jetzt planen.','Hitzeschutz','["Hitzeschutz Wohnung","Wohnung kühlen ohne Klimaanlage","Sonnenschutz außen","Dachgeschoß Hitze","hitzeschutz wohnung dachgeschoss wien","außenliegender sonnenschutz mietwohnung","wohnung kühl halten tipps sommer","verschattung förderung 2027"]','Hitzeschutz Wohnung: Außenjalousien an den Fenstern einer Wiener Dachgeschoßwohnung','Photorealistic editorial photo of external venetian blinds half lowered on the windows of a renovated attic apartment in Vienna, rooftops and chimneys around, bright summer midday sun casting sharp shadows, no text, no logos, no readable signs, no people','[{"q":"Was hilft am besten gegen Hitze in der Wohnung?","a":"Am wirksamsten ist außenliegender Sonnenschutz, weil er die Sonnenstrahlung abhält, bevor sie durch das Glas gelangt. Dazu kommt richtiges Lüften in den kühlen Nacht- und Morgenstunden."},{"q":"Dürfen Mieter Außenjalousien montieren?","a":"Da die Fassade meist zu den allgemeinen Teilen gehört, braucht es die Zustimmung des Vermieters bzw. der Eigentümer. In Wien kann zusätzlich eine baubehördliche Prüfung nötig sein."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('hagel-unwetter-haus-schuetzen-photovoltaik','Hagel und Unwetter: So schützen Sie Haus und PV-Anlage','Hagelkörner können Dächer, Fassaden und Solarmodule schwer beschädigen. Welche Vorsorge sinnvoll ist und wie man im Schadensfall richtig vorgeht.','Hagel und Unwetter richten in Österreich jedes Jahr Schäden in Millionenhöhe an. Anfang September traf ein Hagelunwetter Teile der Steiermark besonders hart: Laut Bericht von 5min.at meldete ein Gartenbaubetrieb in Stainz unter Berufung auf die Österreichische Hagelversicherung einen Schaden von knapp drei Millionen Euro, insgesamt beliefen sich die Schäden in der steirischen Landwirtschaft an diesem Abend auf rund 3,5 Millionen Euro. Betroffen waren auch die Bezirke Voitsberg und Murtal. Für Hausbesitzer stellt sich die Frage, wie sie sich schützen können.

## Hagel und Unwetter: Wo am Haus die Risiken liegen

Besonders gefährdet sind Bauteile, die der Witterung direkt ausgesetzt sind:

- **Dach:** Beschädigte Ziegel oder Blecheindeckungen führen zu Wassereintritt.
- **Fassade:** Wärmedämmverbundsysteme können bei großen Hagelkörnern eingedellt oder durchschlagen werden.
- **Fenster und Dachfenster:** Glas und Rahmen sind empfindlich.
- **Außenjalousien und Markisen:** Sie sollten bei Unwetterwarnung eingefahren werden.
- **Photovoltaikanlagen:** Module, Kabel und Montagesysteme sind exponiert.

## Photovoltaik und Hagel

PV-Module werden in der Regel nach internationalen Normen auf Hagelschlag geprüft. Diese Tests decken aber nicht jede Korngröße ab. Bei dem Unwetter in der Steiermark fiel laut Hagelversicherung zwar nur wenig Hagel, die Körner waren jedoch extrem groß. Solche Ereignisse können auch geprüfte Module beschädigen. Wer neu plant, kann auf Module mit dickerem Frontglas oder höherer Hagelwiderstandsklasse achten. Nach einem Unwetter sollte die Anlage auf Glasbruch und Ertragseinbrüche kontrolliert werden. Beschädigte Module dürfen nur Fachleute anfassen, weil weiterhin Spannung anliegen kann.

## Versicherungsschutz bei Hagel und Unwetter prüfen

Viele Eigenheim- und Haushaltsversicherungen decken Sturm- und Hagelschäden ab, die Bedingungen unterscheiden sich aber stark. Wichtige Fragen sind:

- Ist die PV-Anlage in der Polizze eingeschlossen oder muss sie gemeldet werden?
- Sind Ertragsausfälle versichert?
- Gelten Selbstbehalte oder Höchstgrenzen?
- Ist die Versicherungssumme nach Sanierungen noch aktuell?

Eine Unterversicherung führt im Schadensfall zu Kürzungen. Nach größeren Investitionen sollte die Polizze daher angepasst werden.

## Richtig handeln im Schadensfall

1. **Sicherheit zuerst:** Nicht während eines Gewitters aufs Dach steigen.
2. **Dokumentieren:** Schäden fotografieren, Hagelkörner mit Maßstab ablichten.
3. **Melden:** Versicherung so rasch wie möglich informieren.
4. **Folgeschäden verhindern:** Undichte Stellen provisorisch abdecken, Feuerwehr bei Gefahr rufen.
5. **Reparatur abstimmen:** Größere Arbeiten erst nach Rücksprache mit der Versicherung beauftragen.

Bei Dachsanierungen und Fassaden lohnt außerdem ein Blick auf die Hagelwiderstandsklasse der Materialien. Viele Hersteller lassen Ziegel, Dämmplatten, Fenster und Sonnenschutz auf ihre Widerstandsfähigkeit prüfen. Das österreichische Hagelregister listet Bauprodukte mit geprüfter Hagelwiderstandsklasse. Gerade in Regionen mit häufigen Hagelereignissen, etwa in der Süd- und Weststeiermark, kann die Wahl robusterer Materialien spätere Reparaturen vermeiden.

## Vorsorge für die nächste Saison

Die Unwettersaison 2026 hat gezeigt, dass Extremereignisse nicht nur den Sommer betreffen. Wer ein Dach saniert oder eine Fassade dämmt, sollte nach hagelbeständigen Materialien fragen. Regelmäßige Kontrollen von Dachrinnen und Abläufen beugen Wasserschäden bei Starkregen vor. Warn-Apps und Unwetterwarnungen der GeoSphere Austria helfen, Markisen, Jalousien und Fahrzeuge rechtzeitig zu sichern. Bei Hagel und Unwetter gilt: Gute Vorbereitung ist günstiger als jede Reparatur.','energie','Klima','steiermark','ratgeber','Presseinfo Redaktion','/assets/img/artikel/hagel-unwetter-haus-schuetzen-photovoltaik.webp','5min.at','https://www.5min.at/steiermark/5202609031027/hagelunwetter-zieht-spur-der-verwuestung-durch-die-steiermark/','published','2026-09-30T12:09:00.000Z','2026-10-22T00:17:07.876Z','Hagel und Unwetter: Haus und PV-Anlage schützen','Hagel und Unwetter: Wie Sie Dach, Fassade und PV-Anlage vor Schäden schützen und was im Schadensfall zu tun ist. Vorsorge-Checkliste jetzt lesen.','Hagel und Unwetter','["Hagel und Unwetter","Hagelschaden Haus","Hagelschutz Photovoltaik","Unwetterschaden Versicherung","hagelschaden pv anlage versicherung","hagelwiderstandsklasse dach fassade","unwetter steiermark hagel 2026","schaden melden versicherung unwetter"]','Hagel und Unwetter: Hagelkörner auf beschädigtem Glashaus in der Weststeiermark','Photorealistic editorial photo of large hailstones lying on a damaged greenhouse roof in the West Styrian countryside after a storm, dark clouds clearing in the evening sky, wet grass, no text, no logos, no readable signs, no people','[{"q":"Sind PV-Module hagelsicher?","a":"Viele Module werden nach Normen auf Hagelschlag geprüft, absolute Sicherheit gibt es aber nicht. Bei sehr großen Körnern können auch geprüfte Module brechen."},{"q":"Ist meine PV-Anlage gegen Hagel versichert?","a":"Das hängt von der Polizze ab. Manche Eigenheimversicherungen schließen die Anlage ein, oft braucht es eine Meldung oder eine eigene PV-Versicherung."},{"q":"Was tun nach einem Hagelschaden?","a":"Schäden fotografieren, Versicherung rasch informieren, Folgeschäden durch provisorische Abdeckung verhindern und Reparaturen erst nach Rücksprache beauftragen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('duerre-oesterreich-2026-schaeden-landwirtschaft','Dürre in Österreich 2026: Rekordschäden in der Landwirtschaft','Die Dürre 2026 hat Österreichs Landwirtschaft Rekordschäden beschert. Die Hagelversicherung beziffert sie auf über eine Milliarde Euro – ein Vielfaches der Vorjahre.','Die Dürre in Österreich hat 2026 ein historisches Ausmaß erreicht. Laut Österreichischer Hagelversicherung belief sich der Gesamtschaden in der Landwirtschaft zum Stichtag 10. August auf 1,08 Milliarden Euro, überwiegend verursacht durch Trockenheit. Zum Vergleich: Im gesamten Jahr 2025 betrug die Schadenssumme 110 Millionen Euro, 2024 waren es 260 Millionen Euro. Die Bilanz zeigt, wie stark der Klimawandel die heimische Landwirtschaft bereits trifft.

## Dürre in Österreich: Welche Kulturen betroffen sind

Laut Hagelversicherung ist praktisch ganz Österreich betroffen, und zwar fast alle Kulturen. Besonders schwer getroffen wurden:

- Grünland und damit die Futterversorgung für Tiere,
- Mais,
- Kartoffeln,
- Zuckerrüben,
- Kürbisse,
- Soja,
- regional auch Getreide.

Die GeoSphere Austria bestätigt das Bild: Die ersten acht Monate 2026 waren die trockensten seit Beginn der Aufzeichnungen 1858. Im Waldviertel und im nördlichen Weinviertel fehlten bis zu 70 Prozent des üblichen Niederschlags.

## Versicherung und Hilfspaket

Ein großer Teil der Flächen ist versichert. Laut Hagelversicherung sind 80 Prozent der Ackerflächen und 40 Prozent der Grünlandflächen gegen Dürre abgesichert. Versicherte Betriebe haben laut Vorstandsvorsitzendem Kurt Weinberger einen Rechtsanspruch auf Entschädigung. Landwirtschaftsminister Norbert Totschnig (ÖVP) bezeichnete die Schadensbilanz als zentrale Grundlage für die Entscheidungen von Bund und Ländern über ein geplantes Hilfspaket für Bauern.

## Folgen der Dürre für Konsumenten

Ernteausfälle können sich auf Preise und Verfügbarkeit regionaler Produkte auswirken. Wie stark das im Supermarkt spürbar wird, hängt von Importen, Lagerbeständen und internationalen Märkten ab. Für Tierhalter ist vor allem der Futtermangel ein Problem, wenn Grünland vertrocknet und zugekauft werden muss. Auch Hausgärten und Gemeinden spüren die Trockenheit, etwa durch Bewässerungsverbote oder sinkende Grundwasserstände in einzelnen Regionen.

## Was gegen Dürreschäden hilft

Experten sehen mehrere Ansatzpunkte, um Landwirtschaft und Regionen widerstandsfähiger zu machen:

- **Bodenschutz:** Humusaufbau und Begrünung verbessern die Wasserspeicherfähigkeit.
- **Angepasste Sorten:** Trockenheitstolerante Kulturen und Fruchtfolgen.
- **Effiziente Bewässerung:** Tropfbewässerung statt großflächiger Beregnung.
- **Wasserrückhalt:** Speicherteiche und Retentionsflächen in der Landschaft.
- **Agri-Photovoltaik:** Erhöhte Solarmodule können Flächen teilweise beschatten und zugleich Strom liefern. Die Bundesförderung soll Agri-PV laut Wirtschaftsministerium auch ab 2027 weiter unterstützen.

Auch die Energieversorgung spürt die Trockenheit. Bei Niedrigwasser liefern Flusskraftwerke weniger Strom, gleichzeitig steigt in Hitzeperioden der Bedarf für Kühlung. Photovoltaik erreicht dagegen zur Mittagszeit Spitzenwerte, was die Großhandelspreise in diesen Stunden drückt. Laut Wirtschaftsministerium hat der Hitzesommer gezeigt, wie wichtig Speicher sind, um Solarstrom in die Abendstunden zu verschieben. Die geplante Neuausrichtung der PV-Förderung ab 2027 greift genau diesen Punkt auf.

## Einordnung

Die Dürre in Österreich 2026 ist kein Einzelfall, sondern Teil eines Trends zu häufigeren Extremwetterereignissen. Hitzewellen, Trockenperioden und lokale Unwetter mit großem Hagel wechseln sich ab. Das neue Klimagesetz, das die Regierung im September in Begutachtung geschickt hat, nennt die Anpassung an den Klimawandel ausdrücklich als eine seiner drei Säulen. Wie wirksam die Maßnahmen werden, hängt von der Umsetzung in Bund, Ländern und Gemeinden ab.','energie','Klima','niederoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/duerre-oesterreich-2026-schaeden-landwirtschaft.webp','ORF.at','https://orf.at/stories/3438729/','published','2026-10-04T07:26:00.000Z','2026-10-22T00:17:07.876Z','Dürre Österreich 2026: Rekordschäden für Bauern','Dürre in Österreich 2026: Die Hagelversicherung beziffert Schäden von über einer Milliarde Euro. Welche Kulturen betroffen sind und was das bedeutet.','Dürre in Österreich','["Dürre Österreich","Dürre 2026","Dürreschäden Landwirtschaft","Hagelversicherung Dürre","dürre österreich 2026 milliarde schaden","trockenheit mais kartoffeln grünland","dürreversicherung landwirtschaft österreich","klimawandel landwirtschaft österreich folgen"]','Dürre in Österreich: Vertrocknetes Maisfeld mit staubigem Boden im niederösterreichischen Marchfeld','Photorealistic editorial photo of a withered maize field with brown curled leaves in the Lower Austrian Marchfeld plain, tractor tracks in dry dusty soil, low evening sun, wide landscape view, no text, no logos, no readable signs, no people','[{"q":"Wie hoch sind die Dürreschäden 2026?","a":"Laut Hagelversicherung lag die Schadenssumme in der Landwirtschaft zum Stichtag 10. August 2026 bei 1,08 Milliarden Euro, überwiegend durch Dürre. 2025 waren es insgesamt 110 Millionen Euro."},{"q":"Welche Kulturen sind am stärksten betroffen?","a":"Besonders betroffen sind Grünland, Mais, Kartoffeln, Zuckerrüben, Kürbisse und Soja, regional auch Getreide."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('starkregen-keller-schuetzen-rueckstauklappe','Starkregen: So schützen Sie Keller und Haus vor Wasser','Starkregen kann Keller innerhalb von Minuten fluten. Mit Rückstausicherung, dichten Lichtschächten und kluger Geländegestaltung lässt sich das Risiko deutlich senken.','Starkregen ist eine der häufigsten Ursachen für Wasserschäden an Wohnhäusern. Anders als bei Flusshochwasser kann er überall auftreten, auch weit entfernt von Gewässern. Innerhalb kurzer Zeit fallen große Mengen Regen, Kanäle laufen über und Wasser sucht sich den Weg in Keller, Tiefgaragen und Erdgeschoße. Mit einigen Maßnahmen lässt sich das Risiko deutlich verringern.

## Starkregen: Wie Wasser ins Haus gelangt

Die typischen Eintrittswege sind:

- **Rückstau aus dem Kanal:** Ist das öffentliche Netz überlastet, drückt Wasser durch Bodenabläufe, Duschen oder Toiletten im Keller zurück.
- **Oberflächenwasser:** Wasser fließt über Einfahrten, Terrassen oder Hanglagen zum Gebäude.
- **Lichtschächte und Kellerfenster:** Sie füllen sich und lassen Wasser in den Keller.
- **Undichte Wände:** Drückendes Wasser dringt durch Risse oder Fugen.
- **Dachentwässerung:** Verstopfte Rinnen laufen über und durchnässen Fassade und Fundament.

## Rückstausicherung als wichtigste Maßnahme

Eine Rückstauklappe oder Hebeanlage verhindert, dass Abwasser aus dem Kanal ins Haus zurückfließt. In vielen Gemeinden ist eine Rückstausicherung für Räume unterhalb der Rückstauebene vorgeschrieben. Wichtig ist die regelmäßige Wartung, denn verschmutzte oder blockierte Klappen schließen im Ernstfall nicht. Ein Installateur kann prüfen, ob die vorhandene Sicherung ausreicht.

## Schutz bei Starkregen rund ums Haus

- **Lichtschächte erhöhen:** Ränder über Geländeniveau anheben oder dichte Abdeckungen montieren.
- **Kellerfenster abdichten:** Druckwasserdichte Fenster in gefährdeten Lagen.
- **Gefälle prüfen:** Einfahrten und Terrassen sollten vom Haus weg entwässern.
- **Schwellen einbauen:** Kleine Aufkantungen bei Garagentoren und Kellerabgängen.
- **Versickerung schaffen:** Entsiegelte Flächen und Sickermulden nehmen Wasser auf.
- **Dachrinnen reinigen:** Besonders im Herbst nach dem Laubfall.

## Gefährdung prüfen und vorsorgen

Wie stark ein Grundstück gefährdet ist, zeigt die Plattform HORA, die Naturgefahren wie Hochwasser, Oberflächenabfluss und Erdbeben in Österreich darstellt. Auch Gemeinden und Landesregierungen informieren über Gefahrenzonen. In Kärnten, wo in den vergangenen Jahren mehrfach Unwetter mit Muren und Überflutungen auftraten, bieten Gemeinden und Land Beratungen zum Objektschutz an.

Wertvolle Gegenstände, Heizungsanlagen und Elektroverteilungen sollten nicht am tiefsten Punkt des Kellers stehen. Wer eine neue Heizung oder einen Stromspeicher installiert, kann den Aufstellort bewusst höher wählen oder auf Sockel setzen.

Bei Neubauten und Sanierungen lässt sich der Schutz besonders günstig einplanen. Eine erhöhte Lage der Kellerzugänge, eine wasserdichte Bodenplatte oder eine sogenannte weiße Wanne aus wasserundurchlässigem Beton bieten in gefährdeten Lagen Sicherheit. Auch bei der Umgestaltung von Gärten und Einfahrten sollte das Gefälle bewusst gewählt werden.

## Versicherung und Notfallplan

Viele Haushalts- und Eigenheimversicherungen decken Schäden durch Rückstau oder Überschwemmung nur eingeschränkt oder gegen Zuschlag. Ein Blick in die Polizze lohnt sich. Für den Ernstfall hilft ein einfacher Notfallplan:

1. Unwetterwarnungen der GeoSphere Austria beobachten.
2. Fahrzeuge aus Tiefgaragen holen, wenn Überflutungsgefahr besteht.
3. Strom im Keller abschalten, bevor Wasser eindringt.
4. Wertsachen und Dokumente in höhere Stockwerke bringen.
5. Schäden dokumentieren und rasch der Versicherung melden.

Starkregen lässt sich nicht verhindern. Wer aber Rückstausicherung, Lichtschächte und Geländegestaltung im Blick hat, reduziert das Risiko teurer Schäden erheblich. Die Maßnahmen sind meist deutlich günstiger als die Sanierung eines überfluteten Kellers.','energie','Klima','kaernten','ratgeber','Presseinfo Redaktion','/assets/img/artikel/starkregen-keller-schuetzen-rueckstauklappe.webp',NULL,NULL,'published','2026-10-09T06:13:00.000Z','2026-10-22T00:17:07.876Z','Starkregen: Keller und Haus vor Wasser schützen','Starkregen: Wie Rückstauklappe, Lichtschacht-Schutz und Grundstücksgestaltung Ihren Keller vor Überflutung bewahren. Checkliste für Hausbesitzer lesen.','Starkregen','["Starkregen","Keller Überflutung","Rückstauklappe","Hochwasserschutz Haus","starkregen keller schützen maßnahmen","rückstausicherung einbauen kosten","lichtschacht abdeckung wasser","hora naturgefahren karte österreich"]','Starkregen: Wasser fließt auf einer Straße in Kärnten Richtung Hauseinfahrt','Photorealistic editorial photo of heavy rain flooding a residential street in a Carinthian town, water flowing toward a house driveway with a raised threshold, grey rainy afternoon, mountains faintly visible, no text, no logos, no readable signs, no people','[{"q":"Was ist eine Rückstauklappe?","a":"Eine Rückstausicherung verhindert, dass Abwasser aus dem öffentlichen Kanal bei Überlastung in den Keller zurückdrückt. Sie sollte regelmäßig gewartet werden."},{"q":"Wie finde ich heraus, ob mein Haus gefährdet ist?","a":"Die Plattform HORA zeigt Naturgefahren wie Hochwasser und Oberflächenabfluss. Auch die Gemeinde und die Landesregierung geben Auskunft über Gefahrenzonen."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('regenwasser-nutzen-garten-zisterne-trockenheit','Regenwasser nutzen: Zisterne und Garten gegen Trockenheit','Nach dem trockensten Jahresbeginn seit Messbeginn wird Regenwasser wertvoller. Wie Zisternen, Regentonnen und eine angepasste Gartengestaltung helfen.','Regenwasser nutzen gewinnt in Österreich an Bedeutung. Laut GeoSphere Austria waren die ersten acht Monate 2026 die trockensten seit Beginn der Aufzeichnungen. In vielen Gemeinden gab es Aufrufe zum sparsamen Umgang mit Trinkwasser, Gärten litten unter Wassermangel. Wer Regenwasser sammelt und den Garten klimafit gestaltet, entlastet das Trinkwassernetz und spart Kosten.

## Regenwasser nutzen: Die Möglichkeiten im Überblick

- **Regentonne:** Die einfachste Lösung, direkt am Fallrohr. Günstig, aber mit begrenztem Volumen.
- **Oberirdischer Tank:** Mehr Kapazität, braucht aber Platz und Frostschutz.
- **Unterirdische Zisterne:** Große Volumen, kühl und dunkel gelagertes Wasser, unsichtbar im Garten. Erfordert Erdarbeiten.
- **Versickerungsanlagen:** Statt Wasser in den Kanal zu leiten, versickert es auf dem Grundstück und stärkt das Grundwasser.

## Die richtige Größe der Zisterne

Die passende Größe hängt von drei Faktoren ab: der Dachfläche, der regionalen Niederschlagsmenge und dem Bedarf. In Vorarlberg fällt im Schnitt deutlich mehr Regen als im Weinviertel, entsprechend unterschiedlich fällt die Planung aus. Für die reine Gartenbewässerung genügen oft einige Kubikmeter. Soll Regenwasser auch für Toilettenspülung oder Waschmaschine genutzt werden, braucht es ein größeres Volumen und ein eigenes Leitungsnetz.

## Regeln für Regenwasser im Haus

Wer Regenwasser im Haus verwenden will, muss strikt trennen: Das Regenwassernetz darf keine Verbindung zum Trinkwassernetz haben. Leitungen und Entnahmestellen sind zu kennzeichnen. Die Installation sollte ein befugter Fachbetrieb übernehmen. Je nach Gemeinde können Meldepflichten gegenüber dem Wasserversorger oder Vorgaben für die Ableitung von Überschusswasser bestehen. Manche Gemeinden fördern Zisternen und Versickerungsanlagen, weil sie das Kanalnetz bei Starkregen entlasten.

## Klimafitter Garten bei Trockenheit

Regenwasser nutzen ist nur ein Teil der Lösung. Ebenso wichtig ist ein Garten, der mit weniger Wasser auskommt:

- **Heimische, trockenheitstolerante Pflanzen** statt durstiger Rasenflächen.
- **Mulchen:** Eine Schicht aus Rasenschnitt oder Holzhäcksel hält die Feuchtigkeit im Boden.
- **Morgens gießen:** Weniger Verdunstung als zu Mittag.
- **Tropfbewässerung:** Gezielte Versorgung der Wurzeln statt Rasensprenger.
- **Bäume pflanzen:** Sie spenden Schatten und kühlen die Umgebung durch Verdunstung.
- **Flächen entsiegeln:** Rasengittersteine und Kies statt Asphalt lassen Regen versickern.

Auch die Kosten sind zu berücksichtigen. Eine Regentonne ist für wenig Geld zu haben, eine unterirdische Zisterne mit Pumpe und Filter erfordert eine deutlich höhere Investition, vor allem wegen der Erdarbeiten. Ob sich die Anlage rechnet, hängt vom Wasserpreis der Gemeinde, vom Bedarf und von einer möglichen Förderung ab. Wichtig ist ein Filter vor dem Speicher, damit Laub und Schmutz draußen bleiben. Im Winter müssen oberirdische Leitungen und Tanks entleert werden, um Frostschäden zu vermeiden.

## Doppelter Nutzen bei Starkregen

Zisternen und Versickerungsflächen helfen nicht nur bei Trockenheit, sondern auch bei Starkregen. Sie halten Wasser zurück, das sonst den Kanal überlasten oder in Keller fließen würde. Gerade in Hanglagen und dicht verbauten Siedlungen ist das ein wichtiger Beitrag zum Objektschutz. Der Klimawandel bringt beides: längere Trockenphasen und heftigere Niederschläge.

Wer Regenwasser nutzen will, sollte die Anlage vor der nächsten Gartensaison planen. Herbst und Winter sind gute Zeitpunkte für Erdarbeiten, und Gartenbaubetriebe haben dann meist mehr Kapazität.','energie','Klima','vorarlberg','ratgeber','Presseinfo Redaktion','/assets/img/artikel/regenwasser-nutzen-garten-zisterne-trockenheit.webp',NULL,NULL,'published','2026-10-12T09:48:00.000Z','2026-10-22T00:17:07.877Z','Regenwasser nutzen: Zisterne und Garten im Klimawandel','Regenwasser nutzen: Wie Zisterne, Regentonne und klimafitter Garten in Trockenperioden helfen. Größe, Kosten und Regeln im Überblick – jetzt planen.','Regenwasser nutzen','["Regenwasser nutzen","Zisterne Garten","Regenwassertank","klimafitter Garten","regenwasser nutzen garten zisterne größe","regenwasser toilettenspülung österreich","garten trockenheit tipps bewässerung","versickerung regenwasser grundstück"]','Regenwasser nutzen: Regentonne am Fallrohr in einem Garten in Vorarlberg','Photorealistic editorial photo of a green underground cistern lid and a wooden rain barrel connected to a downpipe in a lush Vorarlberg garden with native perennials, Rhine valley mountains in the background, soft morning light after rain, no text, no logos, no readable signs, no people','[{"q":"Wie groß sollte eine Zisterne sein?","a":"Das hängt von Dachfläche, Niederschlagsmenge und Verwendungszweck ab. Für die reine Gartenbewässerung genügen oft einige Kubikmeter, für Toilettenspülung und Waschmaschine braucht es mehr."},{"q":"Darf ich Regenwasser im Haus verwenden?","a":"Für Toilettenspülung und teils Waschmaschine ist das möglich, es braucht aber ein getrenntes Leitungsnetz ohne Verbindung zum Trinkwasser. Regeln der Gemeinde und des Wasserversorgers beachten."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pv-anlage-niederoesterreich-planung-netzzugang','PV-Anlage in Niederösterreich: Planung, Netzzugang und Tipps','Niederösterreich zählt zu den Bundesländern mit den meisten PV-Anlagen. Wer neu plant, sollte den Netzzugang früh klären und den Eigenverbrauch maximieren.','Eine PV-Anlage in Niederösterreich ist für viele Hausbesitzer längst Standard. Das größte Bundesland hat viel Fläche, zahlreiche Einfamilienhäuser und eine hohe Sonneneinstrahlung, besonders im Weinviertel und im Industrieviertel. Gleichzeitig stoßen die Stromnetze vielerorts an ihre Grenzen. Wer heute plant, sollte deshalb Netzzugang und Eigenverbrauch von Anfang an mitdenken.

## PV-Anlage in Niederösterreich: Netzzugang früh klären

Jede Anlage muss beim zuständigen Netzbetreiber angemeldet werden, in weiten Teilen des Landes ist das die Netz Niederösterreich. Der Netzbetreiber prüft, ob die gewünschte Einspeiseleistung im jeweiligen Netzabschnitt möglich ist. In stark ausgelasteten Gebieten kann die Einspeisung begrenzt werden. Das bedeutet nicht, dass sich die Anlage nicht lohnt, verändert aber die Planung: Statt möglichst viel einzuspeisen, steht der Eigenverbrauch im Vordergrund.

Tipp: Die Netzanfrage sollte vor der Auftragsvergabe gestellt werden. So vermeiden Sie, eine Anlage zu kaufen, die nur eingeschränkt einspeisen darf.

## Eigenverbrauch maximieren

Je mehr Solarstrom im eigenen Haushalt verbraucht wird, desto wirtschaftlicher ist die Anlage. Möglichkeiten sind:

- **Wärmepumpe:** Heizt und bereitet Warmwasser bevorzugt in den Sonnenstunden.
- **Elektroauto:** Laden tagsüber, wenn es zu Hause steht.
- **Batteriespeicher:** Verschiebt den Überschuss in den Abend.
- **Smarte Steuerung:** Geschirrspüler, Waschmaschine und Boiler automatisch bei Überschuss starten.
- **Energiegemeinschaft:** Überschüsse an Nachbarn im selben Netzgebiet abgeben.

Seit April 2026 gelten im Sommerhalbjahr zwischen 10 und 16 Uhr laut E-Control rund 20 Prozent niedrigere Netzkosten. Ab 2027 kommt mit der Reform der Netztarife ein Leistungspreis hinzu, der hohe Lastspitzen teurer macht.

## Schritt für Schritt zur Solaranlage

1. **Verbrauch erheben:** Jahresverbrauch und künftige Verbraucher wie Wärmepumpe oder E-Auto einrechnen.
2. **Dach prüfen:** Ausrichtung, Neigung, Statik und Verschattung durch Bäume oder Nachbarhäuser.
3. **Netzanfrage stellen:** Beim Netzbetreiber die mögliche Einspeiseleistung klären.
4. **Angebote vergleichen:** Komponenten, Garantien und Service gegenüberstellen.
5. **Bauvorschriften prüfen:** Die NÖ Bauordnung regelt, wann eine Anzeige nötig ist, in Ortsbildschutzzonen können Auflagen gelten.
6. **Förderung klären:** Bundesförderung 2027 und mögliche Landes- oder Gemeindeförderungen prüfen.

Auch die Wahl der Komponenten verdient Aufmerksamkeit. Wechselrichter mit integriertem Energiemanagement erleichtern es, Wärmepumpe, Speicher und Wallbox später einzubinden. Zudem wird politisch diskutiert, neue Anlagen für Netzbetreiber steuerbar zu machen, damit sie bei Netzengpässen abgeregelt werden können. Ein erfahrener Installateur kennt die aktuellen technischen Anschlussbedingungen des Netzbetreibers und plant die Anlage entsprechend.

## Förderung und Ausblick

Der letzte Bundes-Fördercall nach altem System lief von 8. bis 22. Oktober 2026. Ab 2027 will das Wirtschaftsministerium vor allem Speicher, Energiemanagement und Sonderformen wie Agri-PV fördern, die in einem Agrarland wie Niederösterreich besonders interessant sein können. Die genauen Bedingungen sind noch offen.

Viele niederösterreichische Gemeinden haben in den vergangenen Jahren eigene Zuschüsse oder Beratungsangebote eingerichtet. Die Energie- und Umweltagentur des Landes bietet unabhängige Energieberatung an. Wer eine PV-Anlage in Niederösterreich plant, sollte diese Angebote nutzen und sich nicht allein auf Verkaufsgespräche verlassen.','energie','Photovoltaik','niederoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/pv-anlage-niederoesterreich-planung-netzzugang.webp',NULL,NULL,'published','2026-10-14T08:36:00.000Z','2026-10-22T00:17:07.878Z','PV-Anlage Niederösterreich: Planung und Netzzugang','PV-Anlage in Niederösterreich: Worauf Hausbesitzer bei Planung, Netzanmeldung und Einspeisung achten müssen und wie Speicher helfen. Jetzt informieren.','PV-Anlage in Niederösterreich','["PV-Anlage Niederösterreich","Photovoltaik Niederösterreich","Netz NÖ Einspeisung","PV Anlage NÖ","pv anlage niederösterreich netzanmeldung","photovoltaik nö einspeisebegrenzung","pv anlage weinviertel waldviertel","pv speicher niederösterreich eigenverbrauch"]','PV-Anlage Niederösterreich: Einfamilienhaus mit Solardach am Rand eines Weinorts','Photorealistic editorial photo of a single-family house with a fresh photovoltaic array on its roof at the edge of a Lower Austrian wine village, vineyards in autumn colours behind, late afternoon golden light, no text, no logos, no readable signs, no people','[{"q":"Wie melde ich eine PV-Anlage in Niederösterreich an?","a":"Die Anlage wird beim zuständigen Netzbetreiber angemeldet, in weiten Teilen des Landes ist das die Netz Niederösterreich. Der Netzbetreiber prüft die Einspeisemöglichkeit und gibt die Anlage frei."},{"q":"Kann die Einspeisung begrenzt werden?","a":"Ja, in Netzabschnitten mit hoher Auslastung kann der Netzbetreiber die Einspeiseleistung begrenzen. Ein hoher Eigenverbrauch und ein Speicher mindern die Auswirkungen."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('e-auto-mit-solarstrom-laden-wallbox-pv','E-Auto mit Solarstrom laden: Wallbox und PV richtig kombinieren','Wer ein E-Auto mit Solarstrom vom eigenen Dach lädt, fährt besonders günstig. Worauf es bei Wallbox, Steuerung und den neuen Netztarifen ankommt.','Ein E-Auto mit Solarstrom laden ist für viele Besitzer einer Photovoltaikanlage der naheliegende nächste Schritt. Der Strom vom eigenen Dach ist meist deutlich günstiger als Netzstrom, und ein Elektroauto kann große Mengen Überschuss aufnehmen. Damit die Kombination funktioniert, müssen Wallbox, Steuerung und Ladeverhalten aufeinander abgestimmt sein.

## E-Auto mit Solarstrom laden: So funktioniert Überschussladen

Beim sogenannten PV-Überschussladen misst ein Energiemanager laufend, wie viel Strom die Anlage erzeugt und wie viel der Haushalt verbraucht. Nur die Differenz fließt ins Auto. Scheint die Sonne stärker, steigt die Ladeleistung, ziehen Wolken auf, sinkt sie. So wird möglichst wenig Netzstrom bezogen.

Wichtig ist die Mindestladeleistung: Viele Autos laden erst ab etwa 1,4 kW einphasig oder rund 4 kW dreiphasig. Wallboxen mit automatischer Phasenumschaltung können auch bei wenig Sonne laden, weil sie bei geringem Überschuss auf eine Phase wechseln.

Bei der Wallbox selbst sollten Käufer auf folgende Punkte achten:

- **Kommunikationsfähig:** Die Wallbox muss mit Wechselrichter oder Energiemanager kommunizieren können.
- **Phasenumschaltung:** Erhöht den Solaranteil an bewölkten Tagen.
- **Lastmanagement:** Verhindert, dass Hausanschluss und Sicherungen überlastet werden.
- **Steuerbarkeit durch den Netzbetreiber:** Wird mit den neuen Netztarifen wichtig.
- **Fachgerechte Installation:** Eigener Stromkreis, Fehlerstromschutz und Anmeldung beim Netzbetreiber.

## Netztarife 2027: Was sich für Wallbox-Besitzer ändert

Mit der Reform der Netztarife, die die E-Control im Oktober kundgemacht hat, wird ab 1. Jänner 2027 ein Teil der Netzgebühren nach der höchsten Viertelstundenleistung im Monat berechnet. Wer ungesteuert mit hoher Leistung lädt, während Herd und Wärmepumpe laufen, kann dadurch mehr zahlen. Für steuerbare Anlagen wie Wallboxen ab 4 kW gibt es 75 Prozent Rabatt auf den Leistungspreis, wenn der Netzbetreiber die Leistung zweimal täglich für höchstens zwei Stunden drosseln darf. Laut Bericht wird empfohlen, die Ladeleistung auf etwa 4 kW zu begrenzen. Solarladen zu Mittag passt gut zu dieser Logik, weil die Netzkosten zwischen 10 und 16 Uhr im Sommerhalbjahr ohnehin niedriger sind.

## Wie viel Solarstrom ins Auto passt

Wie hoch der Solaranteil am Ladestrom ausfällt, hängt stark vom Alltag ab. Wer im Homeoffice arbeitet oder ein Zweitauto tagsüber zu Hause stehen hat, kann im Sommerhalbjahr einen großen Teil der Ladungen mit Sonnenstrom decken. Bei Pendlern verschiebt sich das Laden auf Wochenenden und Feiertage. Ein Energiemanager mit Ladeplanung hilft, die Akkus bis zu einem gewünschten Mindeststand zu füllen und den Rest mit Überschuss nachzuladen.

## Grenzen des Solarladens

Im Winter liefert eine PV-Anlage deutlich weniger Strom. Wer täglich pendelt und das Auto nur abends zu Hause hat, kann den Solaranteil nur mit einem Batteriespeicher oder am Wochenende erhöhen. Ein Speicher, der nur das Auto laden soll, ist aber selten wirtschaftlich, weil Autobatterien sehr groß sind. Sinnvoller ist es, flexible Ladezeiten zu nutzen und den Netzstrom gezielt in günstigen Zeitfenstern zu beziehen. Auch der Stromtarif spielt eine Rolle: Mehrere Versorger, darunter Wien Energie, haben heuer Tarife mit garantierten Preisen für zwölf Monate angeboten.

## Fazit für die Praxis

Wer ein E-Auto mit Solarstrom laden möchte, braucht vor allem eine kommunikationsfähige Wallbox und eine gute Steuerung. In Salzburg und anderen Bundesländern informieren die Netzbetreiber ab Ende 2026 über die Anmeldung zur flexiblen Netznutzung. Wer ohnehin eine Wallbox plant, sollte auf Steuerbarkeit achten, um vom Rabatt auf den Leistungspreis profitieren zu können.','energie','Photovoltaik','salzburg','ratgeber','Presseinfo Redaktion','/assets/img/artikel/e-auto-mit-solarstrom-laden-wallbox-pv.webp',NULL,NULL,'published','2026-10-17T14:29:00.000Z','2026-10-22T00:17:07.878Z','E-Auto mit Solarstrom laden: Wallbox und PV','E-Auto mit Solarstrom laden: Wie Wallbox, PV-Anlage und Überschussladen zusammenspielen und was die Netztarif-Reform 2027 ändert. Jetzt Tipps lesen.','E-Auto mit Solarstrom laden','["E-Auto mit Solarstrom laden","Wallbox PV","PV Überschussladen","Wallbox Photovoltaik","e auto mit solarstrom laden wallbox einstellungen","pv überschussladen 1 phasig 3 phasig","wallbox 4 kw netztarif rabatt","eigenverbrauch erhöhen elektroauto"]','E-Auto mit Solarstrom laden: Elektroauto an der Wallbox vor Garage mit PV-Dach','Photorealistic editorial photo of an electric car charging in front of a garage of a modern house in the Salzburg Flachgau region, solar panels on the garage roof, autumn trees, bright midday sun, no text, no logos, no readable signs, no people','[{"q":"Was ist PV-Überschussladen?","a":"Die Wallbox lädt das Auto nur mit dem Solarstrom, der gerade nicht im Haushalt gebraucht wird. Dafür braucht es eine Steuerung, die Erzeugung und Verbrauch misst."},{"q":"Was ändert sich 2027 für Wallbox-Besitzer?","a":"Ab 2027 wird ein Teil der Netzgebühren nach der höchsten bezogenen Leistung berechnet. Steuerbare Wallboxen ab 4 kW erhalten 75 Prozent Rabatt auf den Leistungspreis, wenn der Netzbetreiber zeitweise drosseln darf."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('heizkosten-sparen-tipps-heizsaison','Heizkosten sparen: 10 Tipps für die Heizsaison 2026/27','Gas wurde teurer, auch die Fernwärme steigt leicht. Mit einfachen Maßnahmen lassen sich Heizkosten in der Saison 2026/27 spürbar senken – ganz ohne Komfortverlust.','Heizkosten sparen ist in der Saison 2026/27 wieder ein großes Thema. Die Gaspreise sind seit Jahresbeginn deutlich gestiegen, und selbst die Wiener Fernwärme wird trotz eines Rabatts von 30 Prozent auf den Arbeitspreis in einer Musterrechnung um rund sechs Prozent teurer. Mit einfachen Maßnahmen lässt sich der Verbrauch aber oft spürbar senken.

## Heizkosten sparen: Die Raumtemperatur

**1. Ein Grad weniger:** Als Faustregel gilt, dass jedes Grad weniger Raumtemperatur den Heizenergiebedarf um rund sechs Prozent senkt. Im Wohnzimmer reichen meist 20 bis 21 Grad, im Schlafzimmer 17 bis 18 Grad.

**2. Räume unterschiedlich heizen:** Wenig genutzte Räume dürfen kühler sein. Türen zwischen warmen und kühlen Räumen geschlossen halten, damit die Feuchtigkeit nicht in kalte Räume zieht.

**3. Nachtabsenkung nutzen:** Eine moderate Absenkung um einige Grad spart Energie. Komplett abschalten ist dagegen meist kontraproduktiv.

## Heizkörper und Technik

**4. Heizkörper entlüften:** Gluckert der Heizkörper oder wird er oben nicht warm, ist Luft im System. Mit einem Entlüftungsschlüssel lässt sich das einfach beheben.

**5. Heizkörper freihalten:** Möbel, Vorhänge oder Verkleidungen vor dem Heizkörper behindern die Wärmeabgabe.

**6. Programmierbare Thermostate:** Smarte oder programmierbare Thermostatköpfe heizen nur, wenn jemand zu Hause ist.

**7. Heizungswartung:** Eine regelmäßig gewartete Anlage arbeitet effizienter. Bei Gasthermen ist die Wartung ohnehin vorgeschrieben.

**8. Stoßlüften statt Kipplüften:** Mehrmals täglich für einige Minuten Fenster weit öffnen. Gekippte Fenster kühlen die Wände aus und verschwenden Energie.

**9. Zugluft stoppen:** Undichte Fenster und Türen mit Dichtungsbändern abdichten. Rollläden nachts schließen, das reduziert Wärmeverluste über die Fenster.

**10. Warmwasser bewusst nutzen:** Duschen statt Baden und Sparduschköpfe senken den Energieverbrauch für Warmwasser deutlich.

Wer in einer Mietwohnung lebt, hat bei der Heizung oft wenig Einfluss auf die Technik. Die genannten Verhaltenstipps wirken aber auch dort. Bei Problemen wie dauerhaft kalten Heizkörpern, undichten Fenstern oder Schimmel sollten Mieter die Hausverwaltung schriftlich informieren. Für Gasthermen in Wohnungen ist die regelmäßige Wartung meist Sache des Mieters, die Kosten sind überschaubar und die Effizienz steigt.

## Langfristig sparen

Die Tipps helfen kurzfristig. Wer dauerhaft Heizkosten sparen will, kommt um die Gebäudehülle und das Heizsystem nicht herum. Eine gedämmte oberste Geschoßdecke, neue Fenster oder eine Wärmepumpe senken den Verbrauch erheblich. Der Bund fördert ab 2. November 2026 wieder den Tausch fossiler Heizungen mit Pauschalen, ab 4. Jänner 2027 startet die Sanierungsoffensive mit Förderungen auch für einzelne Bauteile. Eine Energieberatung, wie sie die Länder und in Wien die Stadt anbieten, zeigt, welche Maßnahmen im eigenen Haus am meisten bringen.

Auch die eigene Abrechnung lohnt einen Blick. Fernwärmekunden von Wien Energie erhalten ab Mitte Oktober ihre Jahresabrechnung und zahlen künftig zehn monatliche Teilbeträge. Ein Vergleich mit dem Vorjahr zeigt, ob der Verbrauch gestiegen ist. Wer Zahlungsschwierigkeiten befürchtet, sollte frühzeitig Kontakt mit dem Versorger oder Sozialorganisationen aufnehmen. Mit den zehn Tipps lässt sich Heizkosten sparen ohne großen Aufwand umsetzen.','energie','Heizen','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/heizkosten-sparen-tipps-heizsaison.webp',NULL,NULL,'published','2026-10-18T07:05:00.000Z','2026-10-22T00:17:07.878Z','Heizkosten sparen: 10 Tipps für die Heizsaison','Heizkosten sparen in der Heizsaison 2026/27: Raumtemperatur, Entlüften, Thermostate und Lüften – mit diesen 10 Tipps senken Sie Ihre Kosten. Jetzt lesen.','Heizkosten sparen','["Heizkosten sparen","Heizkosten senken","Heizen Tipps","Energie sparen Winter","heizkosten sparen tipps wohnung","heizkörper entlüften anleitung","richtig lüften im winter stoßlüften","programmierbare thermostate sparen"]','Heizkosten sparen: Thermostatventil am Heizkörper in einem gemütlichen Wohnzimmer','Photorealistic editorial photo of a hand-free close-up of a radiator thermostatic valve in a cosy Viennese living room with wooden floor, a knitted blanket on an armchair, warm evening lamplight and rain on the window, no text, no logos, no readable signs, no people','[{"q":"Wie viel spart ein Grad weniger Raumtemperatur?","a":"Als Faustregel gilt, dass jedes Grad weniger den Heizenergieverbrauch um etwa sechs Prozent senkt. Der genaue Wert hängt vom Gebäude ab."},{"q":"Soll man die Heizung nachts ausschalten?","a":"Ganz ausschalten ist meist nicht sinnvoll, weil das Aufheizen viel Energie braucht und Schimmelgefahr steigt. Eine moderate Absenkung um einige Grad ist besser."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pelletsheizung-eignung-kosten-lagerraum','Pelletsheizung: Für welche Häuser sie sich eignet','Für Häuser mit hohem Wärmebedarf und Platz im Keller ist die Pelletsheizung oft eine Alternative zur Wärmepumpe. Was beim Umstieg von Öl zu beachten ist.','Eine Pelletsheizung ist für viele Hausbesitzer, die von Öl umsteigen wollen, eine naheliegende Option. Besonders in ländlichen Regionen wie Kärnten, der Steiermark oder Oberösterreich sind Holzheizungen weit verbreitet. Sie eignen sich vor allem für Gebäude mit hohem Wärmebedarf, in denen eine Wärmepumpe nur mit hohen Vorlauftemperaturen arbeiten würde.

## Pelletsheizung: Für welche Häuser sie passt

Eine Pelletsheizung erreicht problemlos hohe Vorlauftemperaturen. Das macht sie interessant für:

- ältere, wenig gedämmte Häuser mit klassischen Heizkörpern,
- große Gebäude wie Bauernhäuser oder Mehrfamilienhäuser,
- Häuser, in denen der Öltankraum als Lager genutzt werden kann,
- Standorte, an denen eine Wärmepumpe aus Platz- oder Lärmgründen schwierig ist.

Weniger geeignet ist sie in sehr kleinen, gut gedämmten Häusern mit geringem Wärmebedarf. Dort ist eine Wärmepumpe meist effizienter.

Wichtig ist auch der Platz: Pellets brauchen einen trockenen Lagerraum. Häufig lässt sich der ehemalige Öltankraum umbauen, wobei der alte Tank fachgerecht entsorgt werden muss. Alternativen sind Gewebesilos, die auch in kleineren Räumen Platz finden, oder unterirdische Erdtanks. Wichtig ist, dass der Lieferwagen das Lager mit dem Einblasschlauch erreichen kann. Die Größe des Lagers richtet sich nach dem Jahresbedarf, damit idealerweise eine Lieferung pro Jahr genügt.

Beim Betreten des Lagerraums ist Vorsicht geboten: Pellets können Kohlenmonoxid abgeben. Vor dem Betreten sollte gut gelüftet werden, Herstellerhinweise sind unbedingt einzuhalten.

## Kosten, Wartung und Emissionen der Pelletsheizung

Die Investitionskosten liegen in der Regel über jenen einer Gas- oder Ölheizung, die Brennstoffkosten hängen vom Pelletspreis ab, der saisonal schwankt. Hinzu kommen Kosten für Wartung, Rauchfangkehrer und Ascheentleerung. Moderne Kessel arbeiten weitgehend automatisch, müssen aber regelmäßig gereinigt werden. Moderne Pelletskessel unterliegen strengen Emissionsgrenzwerten für Feinstaub. Ein gut eingestellter Kessel und hochwertige Pellets mit Qualitätszertifikat reduzieren die Emissionen.

## Planung und Ablauf

Vor dem Umstieg sollte eine Heizlastberechnung zeigen, welche Kesselleistung das Haus tatsächlich braucht. Alte Ölkessel sind häufig überdimensioniert. Ein Pufferspeicher sorgt dafür, dass der Pelletskessel längere Zeit gleichmäßig brennt und seltener startet, was Emissionen und Verschleiß senkt. Der Rauchfang muss für die neue Feuerstätte geeignet sein, der Rauchfangkehrer prüft das vor der Inbetriebnahme. Für den Einbau sind je nach Bundesland Anzeige- oder Meldepflichten zu beachten.

## Kombination mit Solarthermie und PV

Eine Pelletsheizung lässt sich gut mit einer Solarthermieanlage kombinieren. Im Sommer übernimmt die Sonne die Warmwasserbereitung, der Kessel kann pausieren. Das schont die Anlage und spart Brennstoff. Der Bund unterstützt solche Kombinationen mit einem Solarbonus. Auch eine Photovoltaikanlage mit Heizstab im Pufferspeicher kann im Sommer Warmwasser liefern.

Für den Umstieg von fossilen Heizungen fördert der Bund Holzheizungen im Kesseltausch ab 2. November 2026 laut Klimaschutzministerium mit einer Pauschale von 6.000 Euro. Kärnten und andere Bundesländer bieten teils zusätzliche Förderungen mit eigenen Bedingungen. Vor der Auftragsvergabe sollten die aktuellen Richtlinien geprüft und mehrere Angebote verglichen werden.

Fazit: Die Pelletsheizung ist keine Lösung für jedes Haus, für Gebäude mit hohem Wärmebedarf und vorhandenem Lagerraum aber eine bewährte, klimafreundlichere Alternative zur Ölheizung.','energie','Heizen','kaernten','ratgeber','Presseinfo Redaktion','/assets/img/artikel/pelletsheizung-eignung-kosten-lagerraum.webp',NULL,NULL,'published','2026-10-19T11:56:00.000Z','2026-10-22T00:17:07.878Z','Pelletsheizung: Eignung, Lagerraum und Förderung','Pelletsheizung: Für welche Häuser sie passt, wie viel Platz das Lager braucht und welche Förderung es gibt. Ratgeber für den Umstieg von Öl – jetzt lesen.','Pelletsheizung','["Pelletsheizung","Pelletsheizung Kosten","Pellets Lagerraum","Holzheizung Förderung","pelletsheizung statt ölheizung umstieg","pelletslager größe berechnen","pelletsheizung feinstaub wartung","holzheizung förderung 6000 euro"]','Pelletsheizung: Pelletskessel und Gewebesilo im Keller eines Hauses in Kärnten','Photorealistic editorial photo of a wooden pellet storage room with a fabric silo and a modern pellet boiler in a clean basement of a Carinthian house, wood pellets visible in a scoop, warm indirect light, no text, no logos, no readable signs, no people','[{"q":"Wie viel Platz braucht ein Pelletslager?","a":"Das hängt vom Jahresbedarf ab. Oft lässt sich ein ehemaliger Öltankraum nutzen. Alternativ gibt es Gewebesilos oder Erdtanks."},{"q":"Gibt es eine Förderung für Pelletsheizungen?","a":"Im Bundes-Kesseltausch gibt es laut Klimaschutzministerium ab 2. November 2026 eine Pauschale von 6.000 Euro für Holzheizungen. Länder fördern teils zusätzlich."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('energieausweis-kosten-pflicht-foerderung','Energieausweis: Kosten, Pflicht und Nutzen für Förderungen','Der Energieausweis ist Pflicht bei Verkauf und Vermietung und oft Voraussetzung für Förderungen. Was er kostet, was die Kennzahlen bedeuten und wer ihn ausstellt.','Der Energieausweis ist das wichtigste Dokument, wenn es um die Energieeffizienz eines Gebäudes geht. Er zeigt, wie viel Energie ein Haus oder eine Wohnung für Heizung und Warmwasser benötigt. In Österreich ist er bei Verkauf und Vermietung grundsätzlich Pflicht und für viele Förderungen eine Voraussetzung. Mit der Sanierungsoffensive 2027 gewinnt er weiter an Bedeutung.

## Energieausweis: Wann er Pflicht ist

Nach dem Energieausweis-Vorlage-Gesetz muss bei Verkauf oder Vermietung eines Gebäudes oder einer Wohnung ein gültiger Energieausweis vorgelegt und übergeben werden. Bereits in Inseraten sind die Kennzahlen anzugeben. Ausnahmen gibt es etwa für bestimmte denkmalgeschützte Gebäude oder Objekte mit geringer Nutzfläche. Fehlt der Ausweis, drohen Verwaltungsstrafen. Auch bei Neubauten und größeren Renovierungen verlangen die Bauordnungen der Länder einen Energieausweis.

## Die wichtigsten Kennzahlen

- **HWB (Heizwärmebedarf):** Wie viel Wärme das Gebäude pro Quadratmeter und Jahr braucht. Er beschreibt die Qualität der Gebäudehülle.
- **PEB (Primärenergiebedarf):** Berücksichtigt auch die Energie für die Bereitstellung von Heizung und Warmwasser.
- **CO2-Emissionen:** Zeigt die Klimabelastung durch den Energieverbrauch.
- **fGEE (Gesamtenergieeffizienz-Faktor):** Vergleicht das Gebäude mit einem Referenzstandard.

Die Einteilung erfolgt in Klassen von A++ bis G, ähnlich wie bei Haushaltsgeräten.

## Kosten und Aussteller

Ausgestellt wird der Energieausweis von befugten Fachleuten, etwa Baumeistern, Ziviltechnikern, Ingenieurbüros oder Energieberatern. Die Kosten hängen von Größe und Komplexität des Gebäudes sowie von den vorhandenen Unterlagen ab. Liegen Baupläne und Angaben zu Bauteilen vor, wird es meist günstiger. Ein Vor-Ort-Termin ist bei Bestandsgebäuden üblich. Es lohnt sich, Angebote mehrerer Aussteller zu vergleichen. Ein Energieausweis ist in der Regel zehn Jahre gültig.

Für Käufer und Mieter ist der Energieausweis ein wichtiges Vergleichsinstrument. Ein schlechter Heizwärmebedarf deutet auf hohe Heizkosten hin und kann bei Kaufverhandlungen eine Rolle spielen. Wer eine ältere Immobilie erwirbt, sollte den Ausweis genau lesen und mit den tatsächlichen Verbrauchsabrechnungen der Vorbesitzer vergleichen. Die Kennzahlen beruhen auf standardisierten Annahmen und können vom realen Verbrauch abweichen, etwa wenn nur wenige Räume beheizt wurden.

## Energieausweis als Grundlage für Förderungen

Für viele Sanierungsförderungen von Bund und Ländern ist ein Energieausweis vor und nach der Sanierung erforderlich, um die Verbesserung nachzuweisen. Die Sanierungsoffensive 2027 startet laut Klimaschutzministerium am 4. Jänner 2027 und fördert neben umfassenden Sanierungen auch Teilsanierungen und Einzelbauteile wie Fenster oder Dämmung. Welche Nachweise konkret verlangt werden, steht in den Informationsblättern, die im Dezember 2026 veröffentlicht werden sollen.

Auch die Wohnbauförderungen der Länder setzen oft auf den Energieausweis. In Vorarlberg etwa gelten seit Jahren ambitionierte energetische Standards, und das Energieinstitut Vorarlberg bietet Beratung für Sanierungswillige an. Wer eine Förderung plant, sollte den Ausweis frühzeitig in Auftrag geben, damit er rechtzeitig vorliegt.

Der Energieausweis ist damit weit mehr als eine Formalität. Er zeigt Schwachstellen eines Gebäudes, hilft bei der Planung sinnvoller Maßnahmen und ist der Schlüssel zu vielen Förderungen. Wer verkaufen, vermieten oder sanieren will, kommt am Energieausweis nicht vorbei.','energie','Förderungen','vorarlberg','ratgeber','Presseinfo Redaktion','/assets/img/artikel/energieausweis-kosten-pflicht-foerderung.webp',NULL,NULL,'published','2026-10-20T06:22:00.000Z','2026-10-22T00:17:07.879Z','Energieausweis: Kosten, Pflicht und Förderung','Energieausweis: Wann er Pflicht ist, was er kostet und warum er für Sanierungs- und Heizungsförderungen wichtig ist. Alle Kennzahlen erklärt – jetzt lesen.','Energieausweis','["Energieausweis","Energieausweis Kosten","Energieausweis Pflicht","HWB Kennzahl","energieausweis verkauf vermietung pflicht","energieausweis förderung sanierung","hwb fgee kennzahlen erklärt","energieausweis gültigkeit 10 jahre"]','Energieausweis: Wärmebildkamera vor der Fassade eines Hauses in Vorarlberg','Photorealistic editorial photo of an energy consultant''s thermal imaging camera pointed at the facade of a wooden Vorarlberg house on a cold autumn morning, frost on the lawn, mountains behind, camera held by gloved hands only, no text, no logos, no readable signs, no faces','[{"q":"Wann brauche ich einen Energieausweis?","a":"Bei Verkauf und Vermietung von Gebäuden und Wohnungen muss er grundsätzlich vorgelegt werden. Auch viele Sanierungsförderungen verlangen einen Energieausweis."},{"q":"Wie lange ist ein Energieausweis gültig?","a":"In der Regel zehn Jahre. Nach umfassenden Sanierungen ist ein neuer Ausweis sinnvoll, weil er die Verbesserung dokumentiert."},{"q":"Was kostet ein Energieausweis?","a":"Die Kosten hängen von Gebäudegröße, Unterlagen und Anbieter ab. Am besten mehrere Angebote von befugten Ausstellern einholen."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('oegk-krankentransport-rechnung-selbstbehalt','ÖGK Krankentransport: 87.000 Rechnungen für Selbstbehalt verschickt','Die Österreichische Gesundheitskasse verschickt ab Mitte Oktober rund 87.000 Rechnungen für geplante Krankentransporte aus dem zweiten Quartal 2026. Was Betroffene wissen müssen.','Beim ÖGK Krankentransport werden jetzt erstmals in großem Umfang Selbstbehalte nachträglich verrechnet: Rund 87.000 Versicherte, die im zweiten Quartal 2026 einen geplanten Transport in Anspruch genommen haben, bekommen Post von der Österreichischen Gesundheitskasse. Das berichtete VIENNA.AT am 13. Oktober. Betroffen sind vor allem Menschen, die regelmäßig zu Therapien gebracht werden.

## Warum der ÖGK Krankentransport jetzt Geld kostet

Seit Juli 2025 gilt für bestimmte geplante Krankentransporte ein Selbstbehalt. Er wird nicht sofort bei der Fahrt kassiert, sondern im Nachhinein eingehoben. Die nun versendeten Rechnungen betreffen Fahrten aus dem Zeitraum April bis Juni 2026. Zugestellt wird in Etappen: zuerst elektronisch, danach per Brief. Laut Bericht erhalten nur rund fünf Prozent der Betroffenen die Rechnung auf elektronischem Weg, der Großteil kommt also klassisch mit der Post.

Die Höhe des Selbstbehalts orientiert sich an der Rezeptgebühr und hängt davon ab, ob bei der Fahrt eine Sanitäterin oder ein Sanitäter an Bord war. Pro Kalenderjahr werden höchstens 28 Fahrten verrechnet. Als Rechenbeispiel nennt der Bericht 151 Euro für zehn kostenpflichtige Fahrten mit Sanitäter.

## Wer vom Selbstbehalt befreit ist

Nicht jede Fahrt ist betroffen. Ausgenommen sind:

- medizinisch notwendige, zeitkritische Transporte, also etwa Notfälle
- Kinder
- Personen, die generell von der Rezeptgebühr befreit sind

Wer eine Rezeptgebührenbefreiung hat, sollte daher die Rechnung genau prüfen. Wurde die Befreiung nicht berücksichtigt, empfiehlt sich eine rasche Rückmeldung bei der ÖGK, am besten schriftlich und mit Kopie des Befreiungsbescheids. Auch wer unsicher ist, ob eine Fahrt als zeitkritisch eingestuft wurde, kann bei der Kasse nachfragen.

## Fristen und Ratenzahlung beim ÖGK Krankentransport

Für die Bezahlung gilt eine Frist von 30 Tagen. Wer nicht zahlt, bekommt zunächst eine Zahlungserinnerung. Bei offenen Beträgen über 151 Euro ist laut ÖGK eine Ratenzahlung möglich. Gerade Menschen mit vielen Therapiefahrten, etwa zur Dialyse oder zur Strahlentherapie, können so die Belastung strecken. Ein entsprechender Antrag sollte innerhalb der Zahlungsfrist gestellt werden.

Der Bericht weist auch darauf hin, dass möglicherweise Versicherte in Vorarlberg betroffen sind. Grundsätzlich gilt die Regelung aber für ÖGK-Versicherte in ganz Österreich. Wer bei einem anderen Träger versichert ist, etwa bei der BVAEB oder der SVS, sollte sich direkt dort nach den geltenden Regeln erkundigen.

## Was Betroffene jetzt tun können

Praktisch empfiehlt sich folgender Ablauf:

1. Rechnung auf Zeitraum, Zahl der Fahrten und Art des Transports prüfen.
2. Abgleichen, ob eine Befreiung von der Rezeptgebühr vorliegt.
3. Bei Unklarheiten die ÖGK kontaktieren, Belege aufheben.
4. Bei höheren Beträgen rechtzeitig um Ratenzahlung ansuchen.

Die Regelung ist politisch umstritten. Hilfsorganisationen kritisieren seit Längerem, dass Selbstbehalte gerade chronisch kranke und pflegebedürftige Menschen treffen. Die Kasse wiederum steht unter erheblichem finanziellen Druck und sucht nach Einsparungen. Für Versicherte ist vor allem wichtig, die Fristen einzuhalten und mögliche Befreiungen geltend zu machen. Wer gesundheitliche Fragen zu seiner Therapie hat, wendet sich an die behandelnde Ärztin oder den behandelnden Arzt.','gesundheit','Medizin',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/oegk-krankentransport-rechnung-selbstbehalt.webp','VIENNA.AT','https://www.vienna.at/oegk-sends-out-87000-invoices-who-has-to-pay-now/10539395','published','2026-10-13T07:14:00.000Z','2026-10-22T00:17:07.879Z','ÖGK Krankentransport: Rechnungen für Selbstbehalt','ÖGK Krankentransport: Rund 87.000 Versicherte erhalten Rechnungen für geplante Fahrten. Wer zahlt, wer befreit ist und welche Fristen gelten – jetzt lesen.','ÖGK Krankentransport','["ÖGK Krankentransport","Krankentransport Selbstbehalt","ÖGK Rechnung","Rezeptgebühr","krankentransport selbstbehalt ögk rechnung oktober 2026","wer zahlt krankentransport österreich","ögk ratenzahlung selbstbehalt","rezeptgebührenbefreiung krankentransport"]','ÖGK Krankentransport: Krankentransportwagen vor dem Eingang eines österreichischen Spitals','Photorealistic editorial photo of a white patient transport van parked at the side entrance of an Austrian regional hospital in the morning, empty wheelchair ramp lowered, autumn trees, soft overcast light, no text, no logos, no readable signs, no recognizable people','[{"q":"Wie hoch ist der Selbstbehalt beim ÖGK Krankentransport?","a":"Er richtet sich nach der Rezeptgebühr und danach, ob ein Sanitäter an Bord war. Laut Bericht ergeben zehn Fahrten mit Sanitäter rund 151 Euro."},{"q":"Wer muss für Krankentransporte nichts zahlen?","a":"Befreit sind zeitkritische, medizinisch notwendige Transporte, Kinder sowie Personen mit Rezeptgebührenbefreiung."},{"q":"Kann ich die Rechnung in Raten zahlen?","a":"Ja, bei offenen Beträgen über 151 Euro ist laut ÖGK eine Ratenzahlung möglich. Die Zahlungsfrist beträgt 30 Tage."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('grippeimpfung-2026-verspaetung-impfstoff','Grippeimpfung 2026: Teil des Impfstoffs kommt später','Bei der Grippeimpfung 2026 verzögert sich die Lieferung von rund 868.000 Dosen. Für Kinder und ältere Menschen ist Impfstoff aber bereits verfügbar.','Bei der Grippeimpfung 2026 kommt es zu Lieferverzögerungen: Rund 868.000 Dosen des Impfstoffs Influvac treffen später als geplant in Österreich ein. Das Gesundheitsministerium führt das laut einem Bericht von News.at vom 8. Oktober auf Produktionsprobleme und unzuverlässige internationale Lieferketten zurück. Ein rechtzeitiger Schutz sei dennoch möglich, sofern es zu keinen weiteren Verzögerungen kommt.

## Grippeimpfung 2026: Diese Impfstoffe sind schon da

Insgesamt hat Österreich für die Saison 2026/27 knapp 1,7 Millionen kostenlose Dosen bestellt, rund zwölf Prozent mehr als im Vorjahr. Etwa 259.000 Dosen sind für Kinder und Jugendliche zwischen zwei und 18 Jahren vorgesehen, rund 538.000 für ältere Menschen.

Bereits verfügbar sind laut Bericht:

- der Nasenspray-Impfstoff für Kinder und Jugendliche von zwei bis 18 Jahren
- Impfstoff für ältere Menschen
- Impfstoff für bestimmte Risikogruppen

Später geliefert wird der Impfstoff für Babys ab sechs Monaten, für Schwangere und für Personen, die mit Neugeborenen im Haushalt leben. Er soll in den Kalenderwochen 43 und 44 verfügbar sein, also zwischen 19. Oktober und 1. November. Alle restlichen Mengen werden bis Mitte November erwartet.

## Wann die Grippeimpfung sinnvoll ist

Empfohlen wird die Impfung ab Mitte Oktober beziehungsweise im November. Sie ist aber auch später in der Saison noch sinnvoll. Das Ministerium betont, dass der genaue Beginn der Grippesaison nicht vorhersehbar ist. Wer zu einer Risikogruppe gehört, chronisch krank ist oder unsicher ist, ob die Impfung passt, sollte das mit der Hausärztin oder dem Hausarzt besprechen.

Die Impfung ist im Rahmen des öffentlichen Impfprogramms für alle Menschen ab sechs Monaten kostenlos.

## Für wen die Impfung besonders wichtig ist

Nach dem österreichischen Impfplan profitieren von der Grippeimpfung vor allem Menschen, bei denen eine Influenza schwer verlaufen kann. Dazu zählen ältere Menschen, Personen mit chronischen Erkrankungen etwa von Herz, Lunge oder Stoffwechsel, Schwangere und kleine Kinder. Ebenfalls empfohlen wird sie Menschen, die beruflich oder privat viel Kontakt mit gefährdeten Personen haben, etwa im Gesundheitswesen, in der Pflege oder in Haushalten mit Säuglingen. Wer selbst geimpft ist, schützt damit auch sein Umfeld.

Wichtig zu wissen: Die Grippeimpfung schützt nicht vor gewöhnlichen Erkältungen, die von anderen Viren ausgelöst werden. Sie senkt aber das Risiko einer echten Influenza und vor allem von schweren Verläufen. Da sich die Grippeviren laufend verändern, wird der Impfstoff jedes Jahr angepasst. Eine jährliche Impfung ist daher nötig.

## Wo es die Grippeimpfung gibt

Geimpft wird bei teilnehmenden Allgemeinmedizinerinnen und Kinderärzten, bei betrieblichen Impfaktionen und in Pflegeheimen. Je nach Bundesland bieten auch Bezirkshauptmannschaften oder Magistrate Termine an. In Wien impfen zusätzlich die Gesundheitszentren der ÖGK sowie der Impfservice der Stadt. Eine vorherige Terminbuchung wird empfohlen. Für Fragen nennt der Bericht die Hotline 05 0766-501510.

## Niedrige Durchimpfungsrate

Die Impfbereitschaft ist in Österreich traditionell gering. In der Saison 2025/26 waren laut Bericht nur etwa 13 Prozent der Bevölkerung gegen Grippe geimpft, bei den über 65-Jährigen rund 24 Prozent. Langfristiges Ziel sind 75 Prozent bei älteren Menschen und Risikogruppen. Eine Studie der MedUni Wien hatte im Jänner geschätzt, dass die saisonale Grippe in Österreich jedes Jahr 350.000 bis 400.000 Infektionen und rund 1.300 Todesfälle verursacht.

Wer Grippesymptome wie plötzliches hohes Fieber, Gliederschmerzen und starkes Krankheitsgefühl bemerkt, sollte zu Hause bleiben und telefonisch bei der Ärztin oder dem Arzt bzw. bei der Gesundheitshotline 1450 abklären, wie es weitergeht.','gesundheit','Medizin',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/grippeimpfung-2026-verspaetung-impfstoff.webp','News.at','https://www.news.at/gesundheit/grippeimpfung-2026-impfstoff-verspaetung-wer-jetzt-impfen','published','2026-10-08T08:22:00.000Z','2026-10-22T00:17:07.880Z','Grippeimpfung 2026: Teil des Impfstoffs verspätet','Grippeimpfung 2026: Rund 868.000 Dosen kommen verspätet. Wer jetzt schon geimpft werden kann, wann der Rest kommt und wo es die Impfung gibt – hier lesen.','Grippeimpfung 2026','["Grippeimpfung 2026","Grippeimpfung Österreich","Influenza Impfung","Grippeimpfung gratis","grippeimpfung 2026 verspätung impfstoff","grippeimpfung wien wo impfen","grippeimpfung kinder nasenspray","öffentliches impfprogramm influenza"]','Grippeimpfung 2026: Impfstoffpackungen im Kühlschrank einer Arztpraxis in Österreich','Photorealistic editorial close-up of a medical refrigerator shelf in an Austrian general practice with neatly arranged unlabeled vaccine boxes and syringes, cool clinical light, shallow depth of field, no text, no logos, no readable signs','[{"q":"Ist die Grippeimpfung 2026 kostenlos?","a":"Ja, im Rahmen des öffentlichen Impfprogramms ist sie für alle ab sechs Monaten gratis."},{"q":"Wann kommt der Impfstoff für Babys und Schwangere?","a":"Laut Ministerium in den Kalenderwochen 43 und 44, also zwischen 19. Oktober und 1. November. Die Restmengen folgen bis Mitte November."},{"q":"Ist eine Impfung im Dezember noch sinnvoll?","a":"Ja, die Impfung ist auch später in der Saison noch sinnvoll. Den passenden Zeitpunkt bespricht man am besten mit der Ärztin oder dem Arzt."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('keuchhusten-impfung-auffrischung-zehn-jahre','Keuchhusten-Impfung: Auffrischung wieder alle zehn Jahre','Der aktualisierte Impfplan bringt eine Änderung bei der Keuchhusten-Impfung: Erwachsene unter 60 sollen wieder alle zehn Jahre auffrischen, ab 60 bleibt es bei fünf Jahren.','Bei der Keuchhusten-Impfung gibt es eine Änderung im österreichischen Impfplan: Für Erwachsene unter 60 Jahren wird die Auffrischung wieder alle zehn Jahre empfohlen. Das Gesundheitsministerium hat den Impfplan kürzlich aktualisiert, wie die APA am 26. September berichtete. Vor zwei Jahren war das Intervall wegen eines starken Anstiegs der Fälle auf fünf Jahre verkürzt worden.

## Keuchhusten-Impfung: Was sich im Impfplan ändert

Die wichtigsten Punkte im Überblick:

- Erwachsene unter 60 Jahren: Auffrischung wieder alle zehn Jahre
- Erwachsene ab 60 Jahren: weiterhin alle fünf Jahre
- Kinder: Die Keuchhusten-Impfung bleibt im kostenlosen Kinderimpfprogramm

In der Praxis wird gegen Keuchhusten meist mit einem Kombinationsimpfstoff geimpft, der auch vor Diphtherie und Tetanus schützt, bei Bedarf zusätzlich vor Kinderlähmung. Welche Impfung im Einzelfall fällig ist, lässt sich am besten mit dem Impfpass bei der Hausärztin oder dem Hausarzt klären.

## Warum das Intervall wieder länger wird

Hintergrund der Änderung ist die Entwicklung der Fallzahlen. Im Vorjahr wurden in Österreich 1.913 Keuchhustenfälle registriert. Das entspricht laut Bericht etwa dem Niveau vor der Pandemie. Im Jahr 2024 waren es dagegen 15.470 Fälle gewesen, ein außergewöhnlich hoher Wert, der damals zur Verkürzung der Auffrischungsintervalle geführt hatte.

Keuchhusten, medizinisch Pertussis, ist eine bakterielle Infektion der Atemwege. Typisch sind lang anhaltende, krampfartige Hustenanfälle. Für Erwachsene ist die Krankheit oft langwierig und belastend. Besonders gefährlich ist sie für Säuglinge, die noch nicht ausreichend geschützt sind. Deshalb spielt die Impfung von Erwachsenen im Umfeld von Babys eine wichtige Rolle.

## Keuchhusten-Impfung in Schwangerschaft und Familie

Der österreichische Impfplan sieht seit Jahren vor, dass Schwangere im letzten Drittel der Schwangerschaft gegen Keuchhusten geimpft werden, um das Neugeborene über mütterliche Antikörper zu schützen. Auch Eltern, Großeltern und andere enge Kontaktpersonen sollten ihren Impfstatus überprüfen lassen. Konkrete Empfehlungen für die eigene Situation gibt die Frauenärztin, der Hausarzt oder die Kinderärztin.

## Keuchhusten-Impfung: Impfstatus prüfen lassen

Viele Erwachsene wissen nicht, wann sie zuletzt gegen Keuchhusten geimpft wurden. Ein Blick in den Impfpass schafft Klarheit. Wer keinen Impfpass mehr findet, kann prüfen, ob Impfungen im elektronischen Impfpass erfasst sind. Dieser ist über ELGA bzw. die Gesundheitsportale abrufbar, enthält aber vor allem neuere Impfungen. Fehlen Unterlagen, entscheidet die Ärztin oder der Arzt, wie die Grundimmunisierung oder Auffrischung nachgeholt wird.

Für Erwachsene ist die Auffrischung in der Regel kostenpflichtig, es gibt aber in manchen Bundesländern und bei bestimmten Aktionen vergünstigte Angebote. Auskunft geben die Gesundheitsabteilungen der Länder, in Wien etwa der Impfservice der Stadt.

Die Rückkehr zum Zehn-Jahres-Intervall für jüngere Erwachsene bedeutet nicht, dass Keuchhusten verschwunden ist. Die Erkrankung tritt immer wieder in Wellen auf. Fachleute raten daher, die Auffrischung nicht zu vergessen, besonders für Menschen mit Kontakt zu Säuglingen und für ältere Personen.

## Weitere Inhalte des Impfplans

Der aktualisierte Impfplan enthält auch die Empfehlungen zur Covid-19-Impfung für die Saison 2026/27. Hier gibt es laut Bericht keine größeren Änderungen. Die Impfung bleibt kostenlos.

Wer längere Zeit hustet, Fieber hat oder Atemnot bemerkt, sollte ärztlich abklären lassen, was dahintersteckt. Außerhalb der Ordinationszeiten hilft die Gesundheitshotline 1450 bei der Einschätzung, wohin man sich wenden kann.','gesundheit','Medizin',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/keuchhusten-impfung-auffrischung-zehn-jahre.webp','VIENNA.AT / APA','https://www.vienna.at/keuchhusten-impfung-wieder-alle-zehn-statt-fuenf-jahre/10496000','published','2026-09-26T06:47:00.000Z','2026-10-22T00:17:07.880Z','Keuchhusten-Impfung: Auffrischung wieder alle 10 Jahre','Keuchhusten-Impfung: Der neue Impfplan verlängert das Intervall für Erwachsene unter 60 wieder auf zehn Jahre. Was gilt, für wen – jetzt nachlesen.','Keuchhusten-Impfung','["Keuchhusten-Impfung","Impfplan Österreich","Pertussis Auffrischung","Keuchhusten","keuchhusten impfung auffrischung erwachsene","impfplan österreich 2026 neu","keuchhusten fälle österreich","pertussis impfung ab 60"]','Keuchhusten-Impfung: Impfpass und Stethoskop auf dem Schreibtisch einer Wiener Arztpraxis','Photorealistic editorial still life of an open paper vaccination booklet next to a stethoscope on a wooden desk in a Viennese doctor''s office, morning sunlight through tall old window, no text, no logos, no readable signs, no people','[{"q":"Wie oft muss man die Keuchhusten-Impfung auffrischen?","a":"Laut aktuellem Impfplan alle zehn Jahre bis 60, ab 60 alle fünf Jahre."},{"q":"Ist die Keuchhusten-Impfung für Kinder gratis?","a":"Ja, sie ist Teil des kostenlosen Kinderimpfprogramms."},{"q":"Sollen Schwangere gegen Keuchhusten geimpft werden?","a":"Der Impfplan empfiehlt die Impfung im letzten Drittel der Schwangerschaft. Details bespricht man mit der Frauenärztin oder dem Frauenarzt."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('covid-impfung-herbst-2026-empfehlung','Covid-Impfung Herbst 2026: Experten erwarten frühere Welle','Die Covid-Impfung bleibt in der Saison 2026/27 kostenlos. Das Ministerium rechnet heuer mit einer früheren Welle und empfiehlt Risikogruppen die Auffrischung.','Die Covid-Impfung Herbst 2026 bleibt in Österreich kostenlos, und das Gesundheitsministerium rechnet heuer mit einer früheren Infektionswelle. „Wir erwarten die Welle heuer früher“, sagte Maria Paulke-Korinek vom Ministerium laut einem APA-Bericht vom 26. September. An den Empfehlungen selbst ändert sich gegenüber dem Vorjahr wenig.

## Covid-Impfung Herbst 2026: Für wen sie empfohlen wird

Laut der aktuellen Impfempfehlung des Ministeriums wird die Auffrischung ab dem vollendeten zwölften Lebensjahr empfohlen, um das Risiko eines schweren Verlaufs zu senken. Die Empfehlung ist nach Priorität gestaffelt:

1. Personen mit erhöhtem Risiko für einen schweren Verlauf sowie alle Menschen ab 60 Jahren
2. Personal im Gesundheitswesen
3. alle übrigen Personen ab zwölf Jahren, die ihr Risiko senken möchten

Kostenlos ist die Impfung laut Bericht in der Saison 2026/27 für Kinder ab sechs Monaten sowie für Jugendliche und Erwachsene. Ob und wann eine Impfung im Einzelfall sinnvoll ist, klärt man am besten mit der Hausärztin oder dem Hausarzt, besonders bei Vorerkrankungen.

## Zeitpunkt und Abstände

Bevorzugt wird eine einmalige Impfung im Spätsommer oder Herbst, möglichst bevor die Infektionszahlen saisonal steigen. Zur letzten Infektion oder Impfung sollte laut Empfehlung ein Abstand von mindestens sechs Monaten liegen, bei Personen ohne besondere Indikation etwa zwölf Monate. Für immungeschwächte Menschen gelten eigene, kürzere Abstände, die ärztlich festgelegt werden.

Im Herbst 2026 kommen an die Varianten LP.8.1 und XFG angepasste Impfstoffe zum Einsatz. Laut Ministerium können beide gleichwertig verwendet werden, weil die Varianten immunologisch sehr eng verwandt sind. Für Kinder steht ein eigener angepasster Impfstoff zur Verfügung. Welches Präparat verwendet wird, entscheidet die impfende Stelle.

## Covid-Impfung Herbst 2026 und Grippeimpfung kombinieren

Viele Menschen fragen sich, ob sie Covid- und Grippeimpfung gleichzeitig bekommen können. Grundsätzlich ist eine Kombination in der Praxis üblich, die konkrete Planung erfolgt aber mit der Ärztin oder dem Arzt. Die Grippeimpfung ist in Österreich ebenfalls für alle ab sechs Monaten kostenlos.

## Was die Impfung leisten kann

Die Auffrischung soll vor allem schwere Verläufe, Spitalsaufenthalte und Komplikationen verhindern. Einen vollständigen Schutz vor einer Ansteckung bietet sie nicht. Deshalb bleiben auch einfache Maßnahmen sinnvoll: bei Krankheitssymptomen zu Hause bleiben, beim Besuch von Risikopersonen besonders vorsichtig sein, in Innenräumen regelmäßig lüften und auf Händehygiene achten.

Gerade ältere Menschen und chronisch Kranke sollten die Impfung rechtzeitig planen. Pflegeheime organisieren häufig eigene Impftermine für Bewohnerinnen und Bewohner. Angehörige können dort nachfragen, wann geimpft wird, und den Termin mit der Grippeimpfung abstimmen lassen.

## Wo man sich impfen lassen kann

Geimpft wird in vielen Arztpraxen, in Apotheken mit entsprechendem Angebot je nach Bundesland, bei Impfstellen der Länder und in Wien unter anderem über den städtischen Impfservice. Da die Angebote je nach Bundesland unterschiedlich organisiert sind, lohnt ein Blick auf die Website des eigenen Landes oder ein Anruf bei 1450.

Wer Symptome wie Fieber, Husten oder Atembeschwerden hat, sollte zu Hause bleiben und telefonisch mit der Ordination oder der Gesundheitshotline 1450 klären, ob ein Test oder eine Untersuchung nötig ist.','gesundheit','Medizin',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/covid-impfung-herbst-2026-empfehlung.webp','Tiroler Tageszeitung / APA','https://www.tt.com/artikel/30943134/neuer-impfplan-keuchhusten-auffrischung-wieder-alle-zehn-jahre','published','2026-09-27T09:05:00.000Z','2026-10-22T00:17:07.880Z','Covid-Impfung Herbst 2026: Empfehlung und Ablauf','Covid-Impfung Herbst 2026: Für wen die Auffrischung empfohlen ist, welche Abstände gelten und warum eine frühere Welle erwartet wird – hier lesen.','Covid-Impfung Herbst 2026','["Covid-Impfung Herbst 2026","Covid Impfung Österreich","Corona Auffrischung","Covid Impfempfehlung","covid impfung herbst 2026 wer soll impfen","covid auffrischung ab 60","covid impfung abstand infektion","covid welle früher 2026"]','Covid-Impfung Herbst 2026: leerer Impfraum in einem Gesundheitszentrum in Tirol','Photorealistic editorial photo of an empty modern vaccination room in a Tyrolean health center, treatment chair, gloves and cotton pads on a tray, mountains visible through window in late afternoon light, no text, no logos, no readable signs, no people','[{"q":"Wer soll sich im Herbst 2026 gegen Covid impfen lassen?","a":"Vorrangig Menschen ab 60, Personen mit erhöhtem Risiko und Gesundheitspersonal. Empfohlen ist die Auffrischung ab zwölf Jahren für alle, die ihr Risiko senken wollen."},{"q":"Ist die Covid-Impfung 2026/27 gratis?","a":"Ja, laut Ministerium bleibt sie in der Saison 2026/27 kostenlos."},{"q":"Welcher Abstand zur letzten Infektion gilt?","a":"Mindestens sechs Monate, ohne besondere Indikation etwa zwölf Monate. Ausnahmen legt die Ärztin oder der Arzt fest."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('oegk-sparplaene-wahlarzt-kostenerstattung','ÖGK Sparpläne: Debatte über Ende der Wahlarzt-Kostenerstattung','Ein Papier der Dienstgeberseite in der ÖGK schlägt vor, die Kostenerstattung für Wahlärzte zu streichen. Gesundheitsministerin und Arbeitnehmervertreter lehnen das ab.','Die ÖGK Sparpläne sorgen für heftige politische Diskussionen: Ein Papier der Dienstgeberseite in der Österreichischen Gesundheitskasse schlägt unter anderem vor, die Kostenerstattung für Wahlärztinnen und Wahlärzte abzuschaffen. Das berichtete ORF.at am 1. Oktober. Veröffentlicht wurde das Papier von den Grünen.

## Was die ÖGK Sparpläne vorsehen

Zwei Vorschläge stehen im Mittelpunkt:

- das Ende der Kostenerstattung für Behandlungen bei Wahlärztinnen und Wahlärzten
- eine gestaffelte Kostenbeteiligung bei Arztbesuchen

ÖGK-Obmann Peter McDonald, Vertreter der Dienstgeberseite, bestätigte die Überlegungen und sprach sich für „völlig neue Ansätze“ aus. Die Ergebnisse sollen mit den Sozialpartnern diskutiert werden. Beschlossen ist damit noch nichts.

## Breite Ablehnung

Gesundheitsministerin Korinna Schumann (SPÖ) lehnt die Vorschläge ab. Neue finanzielle Hürden für Patientinnen und Patienten dürfe es nicht geben. Auch Andreas Huss, Obmann auf Arbeitnehmerseite, stellte klar, dass es Leistungskürzungen mit ihm nicht geben werde. Kritik kam außerdem von NEOS, Grünen und FPÖ, die vor sozialer Ungerechtigkeit und zusätzlichen Belastungen für Versicherte warnten.

## Hintergrund: Defizit der Gesundheitskasse

Die ÖGK steht finanziell unter Druck. Im November 2025 hatte sie für 2026 ein Defizit von rund 460 Millionen Euro prognostiziert, bis 2029 sogar knapp 800 Millionen Euro. Als Gründe nannte der Dachverband unter anderem die alternde Bevölkerung, teure neue Medikamente und ein schwächeres Wirtschaftswachstum.

Gleichzeitig spielen Wahlärzte eine immer größere Rolle in der Versorgung. Gesundheitsministerin Schumann hatte im März angegeben, dass im Vorjahr Honorare von 766 Millionen Euro bei der ÖGK zur Rückerstattung eingereicht worden seien. Sie selbst hatte damals mehr Preistransparenz bei Wahlärzten und eine stärkere Einbindung in die öffentliche Versorgung gefordert.

## Wie es weitergehen könnte

Die Selbstverwaltung der ÖGK ist paritätisch organisiert: Arbeitnehmer- und Arbeitgebervertreter teilen sich die Führung. Größere Änderungen bei Leistungen brauchen daher breite Zustimmung, viele davon zudem gesetzliche Änderungen im Parlament. Dass die Vorschläge in der vorliegenden Form umgesetzt werden, gilt angesichts der breiten Ablehnung als offen. Die Debatte zeigt aber, wie groß der finanzielle Druck im System ist und dass über die künftige Rolle der Wahlärzte intensiv gestritten wird.

Im Raum stehen auch andere Ansätze: mehr Kassenstellen, bessere Bedingungen für Vertragsärztinnen, der Ausbau von Primärversorgungseinheiten und eine stärkere Steuerung der Patientenwege, etwa über die Gesundheitshotline 1450. Gesundheitsministerin Schumann hatte im Frühjahr außerdem angeregt, Wahlärzte zu verpflichten, einen Teil ihrer Zeit für Kassenpatienten zu reservieren.

## Was die ÖGK Sparpläne für Patienten bedeuten würden

Derzeit gilt: Wer zu einer Wahlärztin oder einem Wahlarzt geht, zahlt die Rechnung zunächst selbst. Die Kasse erstattet 80 Prozent jenes Betrags, den sie einer Vertragsärztin bzw. einem Vertragsarzt für dieselbe Leistung zahlen würde. Weil Wahlarzthonorare meist deutlich höher sind, bleibt ein Großteil der Kosten ohnehin bei den Patienten. Fiele die Erstattung weg, müssten Betroffene die gesamte Rechnung tragen.

Viele Menschen weichen zu Wahlärzten aus, weil sie bei Kassenärzten lange auf einen Termin warten. Kritiker befürchten daher, dass ein Ende der Erstattung vor allem Menschen mit geringerem Einkommen treffen würde.

Für Versicherte ändert sich vorerst nichts. Rechnungen von Wahlärzten können weiterhin zur Kostenerstattung eingereicht werden, auf Wunsch übernimmt das die Ordination online. Wie die Diskussion weitergeht, hängt nun von den Verhandlungen mit den Sozialpartnern und der Politik ab.','gesundheit','Medizin',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/oegk-sparplaene-wahlarzt-kostenerstattung.webp','ORF.at','https://orf.at/stories/3443794/','published','2026-10-01T14:12:00.000Z','2026-10-22T00:17:07.881Z','ÖGK Sparpläne: Kritik an Aus für Wahlarzt-Erstattung','ÖGK Sparpläne: Ein Papier schlägt das Ende der Wahlarzt-Kostenerstattung und Selbstbehalte vor. Wer was fordert und was das für Patienten heißt – lesen.','ÖGK Sparpläne','["ÖGK Sparpläne","Wahlarzt Kostenerstattung","ÖGK Defizit","Selbstbehalt Arztbesuch","ögk sparpläne wahlarzt kostenerstattung abschaffen","kostenbeteiligung arztbesuch österreich","ögk mcdonald huss schumann","wahlarzt rückerstattung 80 prozent"]','ÖGK Sparpläne: Wartezimmer einer Wahlarztpraxis in einem Wiener Altbau','Photorealistic editorial photo of a quiet waiting room of a private doctor''s practice in a Viennese Altbau, upholstered chairs, potted plant, herringbone parquet floor, warm afternoon light, no text, no logos, no readable signs, no people','[{"q":"Wird die Wahlarzt-Kostenerstattung abgeschafft?","a":"Nein, derzeit nicht. Es handelt sich um einen Vorschlag der Dienstgeberseite, den Ministerin und Arbeitnehmervertreter ablehnen."},{"q":"Wie viel erstattet die ÖGK beim Wahlarzt?","a":"80 Prozent des Kassentarifs, also des Betrags, den die Kasse einem Vertragsarzt für die gleiche Leistung zahlen würde."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('wahlarzt-kostenrueckerstattung-oegk-ablauf','Wahlarzt Kostenrückerstattung: So bekommen Sie Geld von der ÖGK','Wer zur Wahlärztin oder zum Wahlarzt geht, zahlt zuerst selbst. Ein Teil kommt von der Kasse zurück. So funktioniert die Rückerstattung in der Praxis.','Die Wahlarzt Kostenrückerstattung ist für viele Menschen in Österreich ein wichtiges Thema, denn immer mehr Patientinnen und Patienten weichen wegen langer Wartezeiten auf Wahlärzte aus. Das Prinzip ist einfach: Man zahlt die Rechnung zunächst selbst und bekommt einen Teil von der Krankenkasse zurück. Wie viel das ist und wie man vorgeht, erklärt dieser Überblick.

## Kassenarzt, Wahlarzt, Privatarzt: der Unterschied

Kassenärztinnen und Kassenärzte haben einen Vertrag mit der Krankenkasse und rechnen direkt mit ihr ab. Mit der e-card zahlt man dort in der Regel nichts. Wahlärzte haben keinen solchen Vertrag. Sie legen ihre Honorare selbst fest, ihre Rechnungen können aber bei der Kasse eingereicht werden. Reine Privatärzte schließlich rechnen ausschließlich privat ab, eine Erstattung durch die Kasse gibt es dann nicht oder nur eingeschränkt. Vor dem Termin lohnt es sich daher, in der Ordination nachzufragen.

## Wie viel die Wahlarzt Kostenrückerstattung bringt

Die Kasse ersetzt 80 Prozent jenes Betrags, den sie einer Vertragsärztin oder einem Vertragsarzt für dieselbe Leistung bezahlen würde. Entscheidend ist also nicht die Höhe der Wahlarztrechnung, sondern der Kassentarif. Da Wahlarzthonorare meist deutlich über den Kassentarifen liegen, bekommt man oft nur einen kleineren Teil der tatsächlichen Kosten zurück. Wie hoch der Betrag im Einzelfall ist, hängt von der Leistung, dem Fachgebiet und dem Versicherungsträger ab.

## Rechnung einreichen: Schritt für Schritt

1. Rechnung und Zahlungsbestätigung aufbewahren. Die Rechnung sollte Diagnose oder Leistungsbeschreibung, Datum und Honorar enthalten.
2. Einreichen lassen oder selbst einreichen. Wahlärzte sind seit Juli 2024 grundsätzlich verpflichtet, die Rechnung auf Wunsch elektronisch an die Kasse zu übermitteln. Fragen Sie in der Ordination danach.
3. Alternativ selbst einreichen: online über das Portal meineSV, per App, per Post oder in einem Kundenservice der Kasse.
4. Kontonummer bekanntgeben, falls die Kasse sie noch nicht hat.
5. Bescheid bzw. Abrechnung abwarten und prüfen.

Rechnungen sollten möglichst zeitnah eingereicht werden. Für die Kostenerstattung gelten Fristen, die je nach Träger unterschiedlich sein können. Aktuelle Informationen gibt es bei der ÖGK, der BVAEB oder der SVS.

## Wahlarzt Kostenrückerstattung bei Rezepten und Überweisungen

Rezepte von Wahlärzten können in vielen Fällen auf Kassenkosten eingelöst werden. Bei bestimmten Medikamenten ist allerdings eine chefärztliche Bewilligung nötig. Überweisungen zu Labor oder Röntgen müssen unter Umständen von der Kasse bestätigt werden, damit die Untersuchung auf e-card möglich ist. Auch hier hilft eine kurze Nachfrage bei der Kasse vorab.

Tipp: Vor einem Wahlarzttermin kann man bei der eigenen Kasse nachfragen, welcher Betrag für eine bestimmte Leistung voraussichtlich erstattet wird. So lassen sich die tatsächlichen Kosten besser abschätzen.

## Aktuelle Debatte

Die Wahlarzt-Erstattung steht politisch unter Druck. Im Oktober wurde ein Papier der Dienstgeberseite in der ÖGK bekannt, das ihr Ende vorschlägt. Gesundheitsministerin und Arbeitnehmervertreter lehnen das ab. Derzeit gilt die Erstattung unverändert weiter.

Wer gesundheitliche Beschwerden hat und nicht weiß, ob ein Termin beim Hausarzt, Facharzt oder in der Ambulanz sinnvoll ist, kann sich telefonisch bei 1450 beraten lassen.','gesundheit','Medizin','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/wahlarzt-kostenrueckerstattung-oegk-ablauf.webp',NULL,NULL,'published','2026-10-03T05:38:00.000Z','2026-10-22T00:17:07.881Z','Wahlarzt Kostenrückerstattung: Ablauf bei der ÖGK','Wahlarzt Kostenrückerstattung: Wie viel die Kasse zahlt, wie Sie die Rechnung einreichen und welche Fristen gelten. Schritt für Schritt erklärt.','Wahlarzt Kostenrückerstattung','["Wahlarzt Kostenrückerstattung","Wahlarzt Rechnung einreichen","ÖGK Rückerstattung","Wahlarzt","wahlarzt kostenrückerstattung ögk wie viel","wahlarzt rechnung online einreichen","wahlarzt oder kassenarzt unterschied","meine sv wahlarzt"]','Wahlarzt Kostenrückerstattung: Arztrechnung und Smartphone auf einem Küchentisch in Wien','Photorealistic editorial flat lay of a paper medical invoice, a payment card terminal receipt and a smartphone on a kitchen table in a Vienna apartment, soft morning daylight, documents blurred and unreadable, no text, no logos, no readable signs','[{"q":"Wie viel bekomme ich beim Wahlarzt zurück?","a":"80 Prozent des Kassentarifs für die gleiche Leistung. Weil Wahlarzthonorare meist höher sind, ist das oft deutlich weniger als die Rechnung."},{"q":"Wie reiche ich eine Wahlarztrechnung ein?","a":"Am einfachsten über die Ordination, die die Rechnung auf Wunsch elektronisch übermittelt, oder selbst über meineSV, per App oder per Post."},{"q":"Wie lange dauert die Rückerstattung?","a":"Das ist je nach Träger und Aufkommen unterschiedlich und kann einige Wochen dauern."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('gesundheitshotline-1450-wann-anrufen','Gesundheitshotline 1450: Wann anrufen und was passiert','Unter 1450 bekommen Menschen in ganz Österreich rund um die Uhr telefonische Gesundheitsberatung. Wann der Anruf hilft und wann sofort 144 die richtige Nummer ist.','Die Gesundheitshotline 1450 ist in ganz Österreich rund um die Uhr erreichbar und hilft, wenn man bei gesundheitlichen Beschwerden nicht weiß, was zu tun ist. Diplomiertes Pflegepersonal stellt am Telefon strukturierte Fragen und empfiehlt dann, ob man zu Hause bleiben kann, eine Ordination aufsuchen sollte oder rasch ins Spital muss. Die Nummer wird ohne Vorwahl gewählt.

## Wann die Gesundheitshotline 1450 sinnvoll ist

Typische Situationen für einen Anruf:

- Fieber, Erbrechen oder Durchfall in der Nacht oder am Wochenende
- Unsicherheit, ob ein Symptom ärztlich abgeklärt werden muss
- Beschwerden bei Kindern, wenn die Kinderarztpraxis geschlossen ist
- Fragen, welche Ordination, Apotheke oder Ambulanz gerade offen ist
- Verdacht auf eine ansteckende Erkrankung

Der Vorteil: Viele Menschen, die sonst in eine Spitalsambulanz fahren würden, können nach der Beratung zu Hause bleiben oder am nächsten Tag zur Hausärztin gehen. Das entlastet die Notaufnahmen und erspart lange Wartezeiten.

## Wann sofort 144 gewählt werden muss

1450 ersetzt nicht den Notruf. Bei lebensbedrohlichen Situationen gilt immer die Rettung unter 144. Dazu zählen etwa:

- starke Brustschmerzen oder Atemnot
- plötzliche Lähmungen, Sprachstörungen oder ein hängender Mundwinkel
- Bewusstlosigkeit oder schwere Verletzungen
- starke Blutungen

Im Zweifel lieber 144 wählen. Die Leitstelle entscheidet dann, welche Hilfe nötig ist.

## So läuft ein Anruf bei der Gesundheitshotline 1450 ab

1. Nach dem Wählen meldet sich eine Fachkraft, meist diplomiertes Gesundheits- und Krankenpflegepersonal.
2. Sie fragt nach Alter, Beschwerden, Dauer und Vorerkrankungen.
3. Mithilfe eines standardisierten Abfrageschemas wird die Dringlichkeit eingeschätzt.
4. Am Ende gibt es eine Empfehlung: Selbstbehandlung zu Hause, Termin bei der Ärztin, Besuch einer Ambulanz oder Verständigung der Rettung.

Es hilft, wichtige Infos bereitzuhaben: e-card, Medikamentenliste, gemessene Temperatur. Bei Kindern sollte das Körpergewicht bekannt sein.

## Unterschiede zwischen den Bundesländern

Organisiert wird 1450 von den Ländern gemeinsam mit Sozialversicherung und Bund. Daher unterscheiden sich die Zusatzangebote: In manchen Bundesländern vermittelt 1450 auch ärztliche Hausbesuche oder Videokonsultationen, in anderen Termine in Erstversorgungsambulanzen. Bund und Länder arbeiten an einem einheitlichen Basisangebot. Wer wissen will, was in Wien, Niederösterreich, Tirol oder der Steiermark konkret angeboten wird, findet Infos auf den Gesundheitsseiten des jeweiligen Landes.

## Gesundheitshotline 1450 für Angehörige und Pflegende

Auch Angehörige können für eine andere Person anrufen, etwa für ein krankes Kind, einen älteren Elternteil oder eine pflegebedürftige Person. Wichtig ist, möglichst genau zu beschreiben, welche Beschwerden seit wann bestehen und ob sich der Zustand verändert hat. Bei Sprachbarrieren kann eine Person mit Deutschkenntnissen beim Gespräch unterstützen, in manchen Bundesländern gibt es zusätzliche Sprachangebote.

Der Anruf kostet nur den üblichen Telefontarif. Die Beratung ersetzt keine Diagnose, sie dient der Orientierung. Die Fachkräfte verschreiben keine Medikamente und geben keine Dosierungsanweisungen. Wer nach dem Anruf weiter unsicher ist oder sich der Zustand verschlechtert, kann jederzeit erneut anrufen oder ärztliche Hilfe suchen.','gesundheit','Medizin',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/gesundheitshotline-1450-wann-anrufen.webp',NULL,NULL,'published','2026-09-29T17:26:00.000Z','2026-10-22T00:17:07.881Z','Gesundheitshotline 1450: Wann anrufen, wie es abläuft','Gesundheitshotline 1450: Wann der Anruf sinnvoll ist, wie die Beratung abläuft und wann Sie besser 144 wählen. Der Überblick – jetzt lesen.','Gesundheitshotline 1450','["Gesundheitshotline 1450","1450 anrufen","Gesundheitsberatung Telefon","1450 oder 144","gesundheitshotline 1450 wann anrufen","1450 wien nachts arzt","telefonische gesundheitsberatung österreich","1450 kosten anruf"]','Gesundheitshotline 1450: Person greift nachts zum Telefon, Fieberthermometer am Tisch','Photorealistic editorial photo of a hand holding a smartphone in a dimly lit living room at night, a thermometer and a glass of water on the coffee table, warm lamp light, screen blank and unreadable, no text, no logos, no readable signs, face not visible','[{"q":"Ist die Gesundheitshotline 1450 rund um die Uhr erreichbar?","a":"Ja, 1450 ist österreichweit 24 Stunden täglich ohne Vorwahl erreichbar."},{"q":"Was kostet ein Anruf bei 1450?","a":"Es fällt nur der normale Telefontarif an, die Beratung selbst ist kostenlos."},{"q":"Wann wähle ich 144 statt 1450?","a":"Bei lebensbedrohlichen Situationen wie Brustschmerzen, Atemnot, Lähmungen oder Bewusstlosigkeit immer sofort 144."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('facharzt-termin-wartezeit-tipps','Facharzt Termin: Was gegen lange Wartezeiten hilft','Monate auf einen Kassentermin warten? Viele kennen das. Mit diesen Wegen lässt sich ein Facharzt Termin oft schneller finden – ohne gleich zum Wahlarzt zu gehen.','Einen Facharzt Termin auf Kasse zu bekommen, dauert in Österreich oft Wochen, manchmal Monate. Besonders in Fächern wie Dermatologie, Augenheilkunde, Kinder- und Jugendpsychiatrie oder bei bildgebenden Untersuchungen klagen Patientinnen und Patienten über lange Wartezeiten. Es gibt jedoch einige Wege, die Suche zu verkürzen.

## Erst zur Hausärztin: der richtige Einstieg

Die Hausärztin oder der Hausarzt ist die erste Anlaufstelle. Viele Beschwerden lassen sich dort bereits abklären oder behandeln, ohne dass ein Facharzt nötig ist. Ist eine Überweisung sinnvoll, kann die Hausärztin die Dringlichkeit vermerken und häufig auch konkrete Kolleginnen oder Kollegen empfehlen, die kurzfristig Termine vergeben. Bei medizinisch dringenden Fällen gibt es zwischen Ordinationen oft eigene Wege.

## Facharzt Termin: Tipps für die Suche

- Mehrere Ordinationen anfragen, nicht nur die nächstgelegene.
- Nach einer Warteliste für kurzfristig frei werdende Termine fragen.
- Online-Terminbuchung nutzen, wo die Praxis das anbietet, und regelmäßig nachsehen.
- Flexibel sein: Termine am frühen Morgen oder in einem Nachbarbezirk sind oft schneller verfügbar.
- Ambulatorien der Krankenkasse und Gruppenpraxen einbeziehen.
- Vereinbarte Termine, die man nicht wahrnehmen kann, rechtzeitig absagen. Das hilft allen.

## Primärversorgungseinheiten nutzen

In den vergangenen Jahren sind in ganz Österreich zahlreiche Primärversorgungszentren und -netzwerke entstanden, auch mit EU-Mitteln gefördert. Dort arbeiten mehrere Allgemeinmedizinerinnen gemeinsam mit Pflege, Physiotherapie, Sozialarbeit oder Diätologie. Die Öffnungszeiten sind meist länger, und viele Fragen können im Team gelöst werden, ohne dass ein Facharztbesuch nötig ist. In Wien, Niederösterreich, Oberösterreich, der Steiermark und anderen Bundesländern gibt es inzwischen auch Primärversorgungseinheiten für Kinder.

## Wenn es schnell gehen muss

Bei akuten Beschwerden ist der Facharzt Termin nicht der richtige Weg. Dann helfen:

- die Gesundheitshotline 1450 zur Einschätzung
- Erstversorgungsambulanzen an vielen Spitälern
- bei Notfällen die Rettung unter 144

Spitalsambulanzen sind für Notfälle und spezielle Fälle gedacht. Wer dort mit leichteren Beschwerden erscheint, muss mit langen Wartezeiten rechnen.

## Facharzt Termin beim Wahlarzt als Alternative

Wer nicht warten möchte, kann eine Wahlärztin oder einen Wahlarzt aufsuchen. Die Rechnung zahlt man zunächst selbst, die Kasse erstattet 80 Prozent des Kassentarifs. Da die Honorare höher sind, bleibt ein Teil der Kosten beim Patienten. Ob sich das lohnt, ist eine persönliche Abwägung. Vor dem Termin kann man bei der Kasse nachfragen, wie viel für die geplante Leistung voraussichtlich zurückkommt. Manche Wahlärzte bieten zudem eigene Tarife für Kontrolltermine an. Wichtig: Befunde und Rezepte vom Wahlarzt werden in der Regel auch bei späteren Kassenärzten anerkannt, sodass eine Behandlung später beim Kassenarzt fortgesetzt werden kann.

Gerade bei chronischen Erkrankungen lohnt es sich, Kontrolltermine frühzeitig zu vereinbaren, idealerweise gleich beim aktuellen Besuch. So entstehen keine Versorgungslücken, wenn der Kalender der Ordination wieder voll ist.

Hilfreich ist außerdem, zum Termin gut vorbereitet zu erscheinen: Überweisung, Vorbefunde, Medikamentenliste und eine kurze Notiz zu Beschwerden und Fragen sparen Zeit und verhindern Folgetermine.

Wer den Eindruck hat, dass eine notwendige Behandlung unzumutbar lange verzögert wird, kann sich an die Krankenkasse oder an die Patientenanwaltschaft des jeweiligen Bundeslandes wenden. Diese beraten kostenlos und vermitteln bei Problemen. Bei gesundheitlichen Fragen bleibt die behandelnde Ärztin oder der Arzt die wichtigste Ansprechperson.','gesundheit','Medizin','niederoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/facharzt-termin-wartezeit-tipps.webp',NULL,NULL,'published','2026-10-17T06:09:00.000Z','2026-10-22T00:17:07.881Z','Facharzt Termin: Tipps gegen lange Wartezeiten','Facharzt Termin schneller bekommen: Welche Wege es gibt, was Überweisung und Dringlichkeit bringen und welche Alternativen helfen – lesen.','Facharzt Termin','["Facharzt Termin","Wartezeit Facharzt","Kassenarzt Termin","Primärversorgung","facharzt termin schneller bekommen österreich","wartezeit mrt kassenpatient","primärversorgungszentrum vorteile","dringliche überweisung facharzt"]','Facharzt Termin: Empfang eines Primärversorgungszentrums in Niederösterreich','Photorealistic editorial photo of the bright reception area of a modern primary care center in a Lower Austrian small town, wooden counter, plants, large windows with vineyard hills in the distance, midday light, no text, no logos, no readable signs, no recognizable people','[{"q":"Wie bekomme ich schneller einen Facharzt Termin auf Kasse?","a":"Mehrere Ordinationen anfragen, auf Wartelisten setzen lassen, Online-Buchung nutzen und die Hausärztin um eine Einschätzung der Dringlichkeit bitten."},{"q":"Was mache ich, wenn es dringend ist?","a":"Bei akuten Beschwerden 1450 anrufen oder eine Erstversorgungsambulanz aufsuchen, im Notfall 144 wählen."},{"q":"Wo kann ich mich über lange Wartezeiten beschweren?","a":"Bei der Krankenkasse oder der Patientenanwaltschaft des Bundeslandes, die kostenlos berät."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pflegegeld-beantragen-ablauf','Pflegegeld beantragen: Ablauf, Begutachtung und Tipps','Rund 506.000 Menschen beziehen in Österreich Pflegegeld. Wer den Antrag stellt, sollte die Begutachtung gut vorbereiten. So läuft das Verfahren ab.','Wer Pflegegeld beantragen möchte, muss den Antrag beim zuständigen Pensionsversicherungsträger stellen, bei den meisten Menschen ist das die Pensionsversicherungsanstalt. Das Pflegegeld ist ein Beitrag zu den pflegebedingten Mehraufwendungen und wird unabhängig von Einkommen und Vermögen gewährt. Im März 2026 bezogen in Österreich rund 506.000 Menschen diese Leistung.

## Wer Pflegegeld beantragen kann

Anspruch besteht, wenn wegen einer körperlichen, geistigen oder psychischen Behinderung oder einer Sinnesbehinderung voraussichtlich mindestens sechs Monate lang ein ständiger Betreuungs- und Hilfsbedarf von mehr als 65 Stunden im Monat besteht. Zusätzlich muss der gewöhnliche Aufenthalt in Österreich liegen. Das Alter spielt keine Rolle: Auch Kinder mit Behinderung können Pflegegeld erhalten.

## Wo und wie der Antrag gestellt wird

Zuständig ist jener Träger, von dem man eine Pension bezieht, also meist die PVA, die SVS oder die BVAEB. Wer keine Pension bezieht, stellt den Antrag in der Regel ebenfalls bei der PVA. Der Antrag ist formlos möglich, einfacher geht es aber mit dem Formular, das online, bei Gemeinden und bei Sozialberatungsstellen erhältlich ist. Auch eine Online-Antragstellung ist möglich. Angehörige können den Antrag für die betroffene Person einbringen.

## Die Begutachtung beim Pflegegeld

Nach dem Antrag kommt eine Ärztin, ein Arzt oder eine diplomierte Pflegefachkraft zur Begutachtung, meist nach Hause. Dabei wird erhoben, bei welchen Tätigkeiten Hilfe nötig ist, etwa beim Waschen, Anziehen, Essen, bei der Mobilität oder bei der Einnahme von Medikamenten. Auch Hilfe im Haushalt wie Einkaufen oder Reinigen wird berücksichtigt.

So bereiten Sie sich vor:

1. Ein Pflegetagebuch über mindestens zwei Wochen führen, in dem alle Hilfestellungen mit Zeitaufwand notiert sind.
2. Aktuelle Befunde, Arztbriefe und Medikamentenliste bereitlegen.
3. Eine vertraute Person zur Begutachtung dazuholen.
4. Ehrlich schildern, was nicht mehr geht, statt aus Scham Probleme herunterzuspielen.

## Bescheid und Einspruch

Über den Antrag entscheidet der Träger mit Bescheid. Das Pflegegeld gebührt ab dem Monat nach der Antragstellung. Wer mit der Einstufung nicht einverstanden ist, kann innerhalb von drei Monaten ab Zustellung Klage beim zuständigen Arbeits- und Sozialgericht einbringen. Das Verfahren ist für die klagende Person grundsätzlich kostenlos. Beratung bieten Arbeiterkammer, Sozialberatungsstellen und Behindertenorganisationen.

Bis zur Entscheidung vergehen meist einige Wochen bis wenige Monate. Wer in dieser Zeit dringend Unterstützung braucht, sollte sich parallel an mobile Dienste, das Sozialamt der Gemeinde oder Hilfsorganisationen wie Hilfswerk, Volkshilfe, Caritas oder Rotes Kreuz wenden. Diese beraten auch, welche weiteren Leistungen in Frage kommen.

Verschlechtert sich der Zustand später, kann jederzeit ein Antrag auf Erhöhung gestellt werden.

Wichtig für Angehörige: Neben dem Pflegegeld gibt es weitere Unterstützungen, etwa die Zuwendung zur Ersatzpflege, wenn die Hauptpflegeperson verhindert ist, oder die Möglichkeit von Pflegekarenz und Pflegeteilzeit. Informationen dazu gibt das Sozialministeriumservice.

## Pflegegeld wird 2027 angepasst

Das Pflegegeld wird jährlich an die Inflation angepasst. Sozialministerin Korinna Schumann hat im Mai bestätigt, dass die Valorisierung auch 2027 erfolgt, dafür sind rund 120 Millionen Euro budgetiert. Die genauen Beträge der sieben Stufen veröffentlicht das Sozialministerium jeweils für das neue Jahr.

Bei Fragen zur medizinischen Versorgung der pflegebedürftigen Person ist die Hausärztin oder der Hausarzt die erste Anlaufstelle.','gesundheit','Pflege','oberoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/pflegegeld-beantragen-ablauf.webp',NULL,NULL,'published','2026-09-23T08:41:00.000Z','2026-10-22T00:17:07.881Z','Pflegegeld beantragen: Ablauf und Begutachtung','Pflegegeld beantragen: Wo der Antrag gestellt wird, wie die Begutachtung abläuft und wie Sie sich gut vorbereiten. Schritt für Schritt erklärt.','Pflegegeld beantragen','["Pflegegeld beantragen","Pflegegeld Antrag","Pflegegeld Begutachtung","Pflegegeld Österreich","pflegegeld beantragen pva ablauf","pflegegeld begutachtung vorbereiten","pflegetagebuch pflegegeld","pflegegeld 2027 valorisierung"]','Pflegegeld beantragen: Angehörige füllen gemeinsam ein Antragsformular am Küchentisch aus','Photorealistic editorial photo of an elderly person''s hands and a younger person''s hands filling out a paper form together at a farmhouse kitchen table in Upper Austria, reading glasses and coffee cup, soft window light, form unreadable, no text, no logos, no readable signs, faces not visible','[{"q":"Wo kann ich Pflegegeld beantragen?","a":"Beim Pensionsversicherungsträger, meist der PVA. Wer eine Pension von SVS oder BVAEB bezieht, stellt den Antrag dort."},{"q":"Ab wann wird Pflegegeld ausbezahlt?","a":"Ab dem Monat, der auf die Antragstellung folgt, sofern der Anspruch besteht."},{"q":"Was kann ich gegen den Bescheid tun?","a":"Innerhalb von drei Monaten Klage beim Arbeits- und Sozialgericht einbringen. Das Verfahren ist grundsätzlich kostenlos."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pflegegeld-stufen-stunden-uebersicht','Pflegegeld Stufen: Welche Stunden für welche Stufe zählen','Das Pflegegeld kennt sieben Stufen. Entscheidend ist der monatliche Pflegebedarf in Stunden. Ein Überblick über die Kriterien und typische Fragen.','Die Pflegegeld Stufen reichen in Österreich von Stufe 1 bis Stufe 7. Welche Stufe zuerkannt wird, hängt davon ab, wie viele Stunden Betreuung und Hilfe eine Person im Monat benötigt, und bei den höheren Stufen zusätzlich von der Art des Pflegebedarfs. Das Einkommen spielt keine Rolle.

## Pflegegeld Stufen und Stunden im Überblick

Die gesetzlichen Kriterien:

- Stufe 1: mehr als 65 Stunden Pflegebedarf pro Monat
- Stufe 2: mehr als 95 Stunden
- Stufe 3: mehr als 120 Stunden
- Stufe 4: mehr als 160 Stunden
- Stufe 5: mehr als 180 Stunden und ein außergewöhnlicher Pflegeaufwand
- Stufe 6: mehr als 180 Stunden und zeitlich nicht koordinierbare Betreuungsmaßnahmen rund um die Uhr oder die dauernde Anwesenheit einer Pflegeperson wegen Eigen- oder Fremdgefährdung
- Stufe 7: mehr als 180 Stunden und keine zielgerichteten Bewegungen der Arme und Beine mit funktioneller Umsetzung möglich oder ein gleichzuachtender Zustand

Die genauen monatlichen Beträge werden jedes Jahr valorisiert und auf den Seiten des Sozialministeriums veröffentlicht. Auch 2027 wird das Pflegegeld laut Sozialministerium an die Inflation angepasst.

## Wie die Stunden berechnet werden

Für viele Verrichtungen sind Richtwerte oder Mindestwerte festgelegt, etwa für das tägliche Waschen, An- und Auskleiden, die Zubereitung und Einnahme von Mahlzeiten oder die Mobilitätshilfe. Für Hilfsverrichtungen wie Einkaufen, Wäschepflege oder Reinigung der Wohnung werden pauschale Werte angesetzt. Die Gutachterin oder der Gutachter addiert diese Zeiten. Deshalb ist es wichtig, bei der Begutachtung alle Hilfen vollständig zu nennen.

## Erschwerniszuschläge bei Demenz und Kindern

Bei Menschen mit schweren geistigen oder psychischen Beeinträchtigungen, insbesondere bei Demenz, wird ein pauschaler Erschwerniszuschlag zum Pflegebedarf hinzugerechnet. Das trägt dem Umstand Rechnung, dass Beaufsichtigung, Motivation und Anleitung viel Zeit kosten. Auch für schwer behinderte Kinder und Jugendliche gibt es eigene Erschwerniszuschläge. Diese können den Ausschlag für eine höhere Pflegegeld Stufe geben.

## Pflegegeld Stufen erhöhen lassen

Verschlechtert sich der Gesundheitszustand, kann jederzeit ein Antrag auf Erhöhung gestellt werden. Dann folgt eine neue Begutachtung. Hilfreich sind:

1. ein aktuelles Pflegetagebuch
2. neue Befunde und Arztbriefe
3. Hinweise der Hauskrankenpflege oder mobiler Dienste zum gestiegenen Aufwand

Ein häufiger Fehler bei der Begutachtung: Betroffene schildern einen guten Tag und verschweigen, wie viel Unterstützung an schlechten Tagen nötig ist. Ein über mehrere Wochen geführtes Pflegetagebuch zeigt realistisch, wie viel Zeit Angehörige oder Pflegekräfte tatsächlich aufwenden. Wer nach dem Bescheid den Eindruck hat, dass die Stufe zu niedrig ist, kann innerhalb von drei Monaten Klage beim Arbeits- und Sozialgericht einbringen.

Bei Kindern wird zudem nur jener Pflegebedarf berücksichtigt, der über den eines gleichaltrigen gesunden Kindes hinausgeht.

## Warum die Stufe so wichtig ist

An der Pflegegeld Stufe hängen weitere Leistungen. So ist etwa für die Förderung einer 24-Stunden-Betreuung in der Regel mindestens Stufe 3 erforderlich. Auch bei Pflegeheimen, mobilen Diensten oder Zuwendungen für pflegende Angehörige spielt die Einstufung eine Rolle. Die Details regeln Bund und Länder unterschiedlich, daher lohnt eine Beratung beim Sozialministeriumservice, beim Land oder bei Hilfsorganisationen.

Bei Fragen zum Gesundheitszustand, zu Therapien oder Hilfsmitteln ist die Hausärztin oder der Hausarzt die richtige Ansprechperson.','gesundheit','Pflege',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/pflegegeld-stufen-stunden-uebersicht.webp',NULL,NULL,'published','2026-10-06T12:53:00.000Z','2026-10-22T00:17:07.882Z','Pflegegeld Stufen: Stunden und Kriterien im Überblick','Pflegegeld Stufen 1 bis 7: Wie viele Pflegestunden pro Monat nötig sind, was Erschwerniszuschläge bringen und wann eine Erhöhung möglich ist – jetzt lesen.','Pflegegeld Stufen','["Pflegegeld Stufen","Pflegestufe","Pflegegeld Stunden","Pflegegeld Erhöhung","pflegegeld stufen stunden tabelle","pflegestufe 3 voraussetzungen","erschwerniszuschlag demenz pflegegeld","pflegegeld erhöhung antrag"]','Pflegegeld Stufen: Rollator und Lehnstuhl in einer Wohnung eines pflegebedürftigen Menschen','Photorealistic editorial photo of a walker and a comfortable armchair next to a window in a modest Austrian apartment, knitted blanket, house plants, late afternoon golden light, no text, no logos, no readable signs, no people','[{"q":"Ab wie vielen Stunden gibt es Pflegegeld Stufe 1?","a":"Ab einem Pflegebedarf von mehr als 65 Stunden pro Monat, der voraussichtlich mindestens sechs Monate dauert."},{"q":"Was ist für Pflegestufe 3 nötig?","a":"Ein Pflegebedarf von mehr als 120 Stunden im Monat."},{"q":"Gibt es bei Demenz mehr Pflegegeld?","a":"Bei schweren geistigen oder psychischen Beeinträchtigungen wird ein pauschaler Erschwerniszuschlag zum Pflegebedarf addiert."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('24-stunden-betreuung-foerderung-voraussetzungen','24-Stunden-Betreuung: Förderung, Voraussetzungen und Ablauf','Für viele Familien ist die 24-Stunden-Betreuung die Alternative zum Pflegeheim. Welche Voraussetzungen für die Förderung gelten und worauf Angehörige achten sollten.','Die 24-Stunden-Betreuung ermöglicht es pflegebedürftigen Menschen, in den eigenen vier Wänden zu bleiben, obwohl sie rund um die Uhr Unterstützung brauchen. In Österreich arbeiten dafür meist selbstständige Personenbetreuerinnen und -betreuer, häufig aus Nachbarländern, die im Wechsel von einigen Wochen im Haushalt leben. Bund und Länder fördern dieses Modell unter bestimmten Bedingungen.

## Voraussetzungen für die Förderung der 24-Stunden-Betreuung

Die Förderung wird über das Sozialministeriumservice abgewickelt. Grundvoraussetzungen sind:

- ein Bedarf an Betreuung rund um die Uhr
- Anspruch auf Pflegegeld in der Regel ab Stufe 3; bei Demenz kann unter Umständen auch eine niedrigere Stufe genügen
- ein Betreuungsverhältnis, das den gesetzlichen Vorgaben entspricht, also mit selbstständigen oder angestellten Betreuungskräften
- ein Einkommen der betreuten Person unter einer festgelegten Grenze, die sich bei unterhaltsberechtigten Angehörigen erhöht
- Nachweise zur Qualifikation der Betreuungskraft, etwa eine theoretische Ausbildung oder eine mehrmonatige fachgerechte Betreuung

Die Höhe des monatlichen Zuschusses hängt davon ab, ob die Betreuungskräfte selbstständig oder angestellt sind. Hilfsorganisationen kritisieren seit Langem, dass Förderung und Einkommensgrenze nicht ausreichend an die Teuerung angepasst wurden. Die aktuellen Beträge sollten daher immer direkt beim Sozialministeriumservice erfragt werden. Manche Bundesländer gewähren zusätzliche Zuschüsse.

## Agentur oder private Vermittlung?

Die meisten Familien arbeiten mit einer Vermittlungsagentur. Diese sucht Betreuungskräfte, organisiert die Wechsel und hilft bei Formalitäten. Bei der Auswahl lohnt ein genauer Blick:

1. Ist die Agentur im Gewerberegister eingetragen und nennt sie transparente Kosten?
2. Gibt es einen schriftlichen Vertrag mit klaren Kündigungsfristen?
3. Wie werden Ersatzkräfte bei Krankheit oder Ausfall organisiert?
4. Gibt es Qualitätszertifikate oder Pflegevisiten durch diplomiertes Personal?

Das Sozialministerium hat ein Qualitätszertifikat für Vermittlungsagenturen eingeführt, an dem man sich orientieren kann.

## Was die 24-Stunden-Betreuung leisten darf

Personenbetreuerinnen übernehmen Haushalt, Begleitung, Unterstützung bei der Körperpflege, beim Essen und bei der Mobilität. Medizinische und pflegerische Tätigkeiten wie das Verabreichen von Injektionen oder das Wechseln von Verbänden dürfen sie nur nach Anordnung und Anleitung durch Ärztinnen oder diplomiertes Pflegepersonal übernehmen. Daher ist oft eine Kombination mit Hauskrankenpflege sinnvoll.

Die Betreuungskraft lebt im selben Haushalt und braucht ein eigenes Zimmer sowie geregelte Ruhezeiten. Für die Familie bedeutet das, dass eine fremde Person zum Alltag dazugehört. Ein offenes Gespräch über Erwartungen, Essgewohnheiten, Freizeit und Sprache hilft, Konflikte zu vermeiden. Auch Angehörige sollten erreichbar bleiben und regelmäßig vorbeischauen.

## Kosten der 24-Stunden-Betreuung realistisch planen

Zu den laufenden Kosten zählen das Honorar der Betreuungskräfte, die Vermittlungsgebühr der Agentur, Fahrtkosten für die Wechsel sowie Kost und Logis im Haushalt. Selbstständige Betreuerinnen sind selbst sozialversichert, dennoch sollte man klären, wer welche Abgaben trägt. Förderung und Pflegegeld decken in der Regel nur einen Teil der Ausgaben ab. Ein schriftlicher Kostenplan hilft, böse Überraschungen zu vermeiden, und sollte vor Vertragsabschluss mit der Agentur durchgegangen werden.

## Beratung vor dem Start

Vor dem Entschluss für eine 24-Stunden-Betreuung lohnt eine unabhängige Beratung, etwa bei Pflegeberatungsstellen der Länder, bei Hilfsorganisationen wie Caritas, Hilfswerk, Volkshilfe oder Rotes Kreuz oder beim Sozialministeriumservice. Dort erfährt man auch, ob mobile Dienste, Tageszentren oder ein Pflegeheim die passendere Lösung sind. Gesundheitliche Fragen zur betreuten Person klärt die Hausärztin oder der Hausarzt.','gesundheit','Pflege','burgenland','ratgeber','Presseinfo Redaktion','/assets/img/artikel/24-stunden-betreuung-foerderung-voraussetzungen.webp',NULL,NULL,'published','2026-09-24T13:17:00.000Z','2026-10-22T00:17:07.883Z','24-Stunden-Betreuung: Förderung und Voraussetzungen','24-Stunden-Betreuung zu Hause: Welche Voraussetzungen für die Förderung gelten, wie Agentur und Vertrag funktionieren und worauf Sie achten sollten.','24-Stunden-Betreuung','["24-Stunden-Betreuung","24h Betreuung Förderung","Personenbetreuung","24 Stunden Pflege zu Hause","24-stunden-betreuung förderung voraussetzungen","24h betreuung agentur auswählen","personenbetreuung selbstständig gewerbe","24-stunden-betreuung pflegestufe 3"]','24-Stunden-Betreuung: Betreuerin unterstützt älteren Menschen zu Hause im Burgenland','Photorealistic editorial photo of a cozy living room in a Burgenland single-family house, a caregiver''s hands helping an elderly person''s hand onto a walker, autumn light through lace curtains, faces not visible, no text, no logos, no readable signs','[{"q":"Ab welcher Pflegestufe gibt es Förderung für die 24-Stunden-Betreuung?","a":"In der Regel ab Pflegegeldstufe 3, bei Demenz unter Umständen schon früher. Weitere Voraussetzungen betreffen Einkommen und Qualifikation der Betreuungskraft."},{"q":"Wo beantrage ich die Förderung?","a":"Beim Sozialministeriumservice. Manche Bundesländer zahlen zusätzliche Zuschüsse."},{"q":"Dürfen Personenbetreuer medizinische Tätigkeiten übernehmen?","a":"Nur nach ärztlicher oder pflegerischer Anordnung und Anleitung. Oft ist zusätzlich Hauskrankenpflege sinnvoll."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pflegeheim-kosten-wer-zahlt','Pflegeheim Kosten: Wer zahlt und was vom Einkommen bleibt','Ein Pflegeheimplatz kostet viel Geld. Wer zahlt, was vom eigenen Einkommen bleibt und warum das Vermögen seit 2018 geschützt ist – ein Überblick.','Die Pflegeheim Kosten sind für viele Familien eine große Sorge, wenn ein Angehöriger nicht mehr zu Hause betreut werden kann. In Österreich übernimmt in der Regel die öffentliche Hand den Großteil, sofern Einkommen und Pflegegeld der betroffenen Person nicht reichen. Die Details regeln die Bundesländer, die Grundprinzipien sind aber ähnlich.

## Pflegeheim Kosten: So wird finanziert

Zur Finanzierung eines Platzes in einem öffentlichen oder vertraglich gebundenen Heim wird zunächst das Einkommen der Bewohnerin oder des Bewohners herangezogen. Üblich ist:

- ein Großteil der Pension, meist 80 Prozent; die Sonderzahlungen sowie ein Teil der Pension bleiben als Taschengeld
- das Pflegegeld bis auf einen kleinen Betrag, der als Taschengeld verbleibt
- weitere Einkünfte wie etwa Mieterträge

Reicht das nicht aus, übernimmt das Land bzw. der Sozialhilfeträger die Differenz. Die genauen Regeln, etwa zur Höhe des Taschengelds, unterscheiden sich je nach Bundesland.

## Pflegeregress: Vermögen bleibt geschützt

Seit 1. Jänner 2018 ist der sogenannte Pflegeregress abgeschafft. Das bedeutet: Für die Kosten eines Pflegeheimplatzes darf nicht mehr auf das Vermögen der pflegebedürftigen Person zugegriffen werden, also etwa auf Ersparnisse, eine Eigentumswohnung oder ein Haus. Auch Kinder und andere Angehörige werden nicht zur Kasse gebeten. Das Einkommen wird aber weiterhin herangezogen.

Das Verbot gilt für stationäre Pflegeeinrichtungen. Für andere Leistungen, etwa betreutes Wohnen oder mobile Dienste, können Länder eigene Kostenbeiträge vorsehen. Wer unsicher ist, sollte sich bei der Sozialabteilung des Landes oder der Gemeinde beraten lassen.

Neben öffentlichen Häusern gibt es private und gemeinnützige Heime. Viele haben Verträge mit dem Land, dann gelten dieselben Finanzierungsregeln. Bei rein privaten Einrichtungen ohne Vertrag muss man die Kosten unter Umständen selbst tragen. Vor der Entscheidung sollte daher klar sein, ob das Heim einen Vertrag mit dem Land hat.

## Einen Pflegeheimplatz finden

1. Beratung bei der Pflegeberatung des Landes, beim Sozialzentrum oder in Wien beim Fonds Soziales Wien.
2. Antrag auf einen Platz stellen, meist mit ärztlichen Unterlagen und Pflegegeldbescheid.
3. Heime besichtigen und nach Wartezeiten fragen.
4. Übergangslösungen wie Kurzzeitpflege oder mobile Dienste einplanen.

In vielen Regionen gibt es Wartelisten. Wer früh plant, hat mehr Auswahl.

## Pflegeheim Kosten und Alternativen

Nicht immer ist ein Heim die einzige Lösung. Mobile Pflege, Tageszentren, betreutes Wohnen oder eine 24-Stunden-Betreuung können je nach Pflegebedarf in Frage kommen. Die Kosten dieser Modelle unterscheiden sich stark, ebenso die Förderungen. Hilfsorganisationen wie Caritas, Hilfswerk, Volkshilfe oder Rotes Kreuz bieten kostenlose Erstberatung an.

Ein Hinweis zu Wartezeiten: In Ballungsräumen wie Wien, Graz oder Linz, aber auch in ländlichen Regionen gibt es teils Wartelisten für Heimplätze. Wer nach einem Spitalsaufenthalt nicht mehr nach Hause kann, sollte frühzeitig mit dem Entlassungsmanagement oder der Sozialarbeit im Spital sprechen. Diese helfen bei der Suche nach einer Übergangslösung und beim Antrag.

Zu den Pflegeheim Kosten gehören neben dem Grundtarif oft Zusatzleistungen wie Friseur, Fußpflege oder Telefon, die aus dem Taschengeld bezahlt werden. Es lohnt sich, beim Heim nachzufragen, was im Tagsatz enthalten ist.

## Gespräch in der Familie

Der Umzug in ein Pflegeheim ist für alle Beteiligten ein großer Schritt. Wenn möglich, sollte die betroffene Person in die Entscheidung eingebunden sein. Vorsorgevollmacht und Erwachsenenvertretung regeln, wer im Bedarfsfall entscheiden darf. Medizinische Fragen klärt die Hausärztin oder der Hausarzt.','gesundheit','Pflege','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/pflegeheim-kosten-wer-zahlt.webp',NULL,NULL,'published','2026-10-09T11:36:00.000Z','2026-10-22T00:17:07.883Z','Pflegeheim Kosten: Wer zahlt, was bleibt','Pflegeheim Kosten in Österreich: Wie Pension und Pflegegeld herangezogen werden, was seit dem Ende des Pflegeregresses gilt und wie man einen Platz findet.','Pflegeheim Kosten','["Pflegeheim Kosten","Pflegeregress","Pflegeheim Österreich","Pflegeheimplatz","pflegeheim kosten wer zahlt österreich","pflegeheim pension 80 prozent","pflegeregress abgeschafft vermögen","pflegeheimplatz wien antrag"]','Pflegeheim Kosten: Aufenthaltsraum eines modernen Pflegeheims in Wien','Photorealistic editorial photo of a bright common room in a modern Viennese nursing home, empty armchairs around a round table with a vase of autumn flowers, large windows overlooking a courtyard garden, midday light, no text, no logos, no readable signs, no people','[{"q":"Wer zahlt die Pflegeheim Kosten in Österreich?","a":"Zuerst werden Pension und Pflegegeld bis auf ein Taschengeld herangezogen. Den Rest übernimmt in der Regel das Land bzw. der Sozialhilfeträger."},{"q":"Muss ich für das Pflegeheim mein Haus verkaufen?","a":"Nein. Seit der Abschaffung des Pflegeregresses 2018 darf auf das Vermögen für Pflegeheimkosten nicht mehr zugegriffen werden."},{"q":"Müssen Kinder für das Pflegeheim der Eltern zahlen?","a":"Nein, Angehörige werden für die Kosten eines Pflegeheimplatzes nicht herangezogen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pflegende-angehoerige-entlastung-tipps','Pflegende Angehörige: Entlastung, Ersatzpflege und Beratung','Rund die Hälfte der Pflegebedürftigen wird von Angehörigen betreut. Viele sind selbst über 60. Welche Entlastungsangebote es gibt und wie man sie bekommt.','Pflegende Angehörige sind die tragende Säule der Pflege in Österreich. Rund die Hälfte der Pflegebedürftigen wird nach Angaben der großen Hilfsorganisationen zu Hause von Familienmitgliedern betreut, viele davon sind selbst über 60 Jahre alt. Die Belastung ist hoch, körperlich wie seelisch. Es gibt aber eine Reihe von Unterstützungsangeboten, die oft zu wenig bekannt sind.

## Finanzielle Hilfen für pflegende Angehörige

Wichtige Leistungen auf Bundesebene sind:

- die Zuwendung zur Ersatzpflege, wenn die Hauptpflegeperson wegen Urlaub, Krankheit oder anderer Gründe verhindert ist
- der Angehörigenbonus für Personen, die einen nahen Angehörigen mit höherem Pflegebedarf überwiegend zu Hause pflegen; die Voraussetzungen sind beim Sozialministeriumservice nachzulesen
- die kostenlose Weiter- oder Selbstversicherung in der Pensionsversicherung für pflegende Angehörige ab einer bestimmten Pflegegeldstufe
- die beitragsfreie Mitversicherung in der Krankenversicherung unter bestimmten Bedingungen

Die Anträge laufen über das Sozialministeriumservice bzw. die Pensionsversicherung. Da sich Beträge und Grenzen ändern können, empfiehlt sich ein Blick auf die aktuellen Bedingungen.

## Pflegekarenz und Pflegeteilzeit

Berufstätige können für die Pflege eines nahen Angehörigen eine Pflegekarenz oder Pflegeteilzeit vereinbaren. Während dieser Zeit gibt es ein Pflegekarenzgeld, das sich am bisherigen Einkommen orientiert. Voraussetzung ist eine Vereinbarung mit dem Arbeitgeber; unter bestimmten Bedingungen besteht ein Rechtsanspruch für einen begrenzten Zeitraum. Die Arbeiterkammer berät zu den Details.

## Entlastung im Alltag für pflegende Angehörige

Neben Geld zählt vor allem Zeit. Hilfreich sind:

1. Mobile Dienste wie Heimhilfe und Hauskrankenpflege, die einzelne Aufgaben übernehmen.
2. Tageszentren, in denen Pflegebedürftige tagsüber betreut werden.
3. Kurzzeitpflege in Heimen, etwa während eines Urlaubs der Angehörigen.
4. Besuchsdienste und Selbsthilfegruppen.

Die Angebote unterscheiden sich je nach Bundesland und Gemeinde. In Wien koordiniert der Fonds Soziales Wien viele Leistungen, in den anderen Ländern sind es Sozialabteilungen, Sozialsprengel oder Gesundheits- und Sozialsprengel.

## Das kostenlose Angehörigengespräch

Im Rahmen der Qualitätssicherung in der häuslichen Pflege können pflegende Angehörige ein kostenloses Gespräch mit einer Psychologin oder einem Psychologen in Anspruch nehmen. Auch Hausbesuche durch diplomierte Pflegefachkräfte zur Beratung sind möglich. Diese Angebote werden über das Sozialministeriumservice organisiert.

Ein praktischer Tipp: Viele Gemeinden und Länder bieten Pflegeberatung direkt vor Ort an, teilweise auch als Hausbesuch. In der Steiermark etwa gibt es regionale Pflegedrehscheiben, in anderen Bundesländern Pflegeberatungsstellen oder Sozialsprengel. Dort erfährt man, welche Angebote in der Nähe verfügbar sind, und bekommt Unterstützung bei Anträgen. Wer die Pflege gemeinsam mit Geschwistern oder anderen Angehörigen organisiert, sollte Aufgaben klar verteilen und regelmäßig besprechen, wer was übernimmt.

## Auf sich selbst achten

Wer pflegt, vergisst oft die eigene Gesundheit. Warnzeichen für Überlastung sind Schlafstörungen, Gereiztheit, Rückzug oder körperliche Beschwerden. Dann ist es wichtig, Hilfe anzunehmen. Die Hausärztin oder der Hausarzt ist auch für pflegende Angehörige eine wichtige Anlaufstelle. In seelischen Krisen ist die Telefonseelsorge unter 142 rund um die Uhr kostenlos erreichbar.

Hilfsorganisationen fordern seit Jahren mehr Unterstützung und weniger Bürokratie für pflegende Angehörige. Am Tag der Pflegenden im Mai haben Caritas, Diakonie, Hilfswerk, Rotes Kreuz und Volkshilfe diese Forderungen vor dem Parlament bekräftigt.','gesundheit','Pflege','steiermark','ratgeber','Presseinfo Redaktion','/assets/img/artikel/pflegende-angehoerige-entlastung-tipps.webp',NULL,NULL,'published','2026-10-04T07:52:00.000Z','2026-10-22T00:17:07.883Z','Pflegende Angehörige: Entlastung und Unterstützung','Pflegende Angehörige: Welche Entlastung es gibt – von Ersatzpflege über Pflegekarenz bis Tageszentrum – und wo Sie kostenlos Beratung bekommen.','Pflegende Angehörige','["Pflegende Angehörige","Ersatzpflege","Pflegekarenz","Angehörigenbonus","pflegende angehörige entlastung österreich","zuwendung ersatzpflege antrag","pflegekarenz pflegeteilzeit dauer","angehörigengespräch kostenlos"]','Pflegende Angehörige: Person macht eine Pause im Garten in der Steiermark','Photorealistic editorial photo of a middle-aged person sitting on a garden bench in a Styrian village in autumn, holding a cup of tea and looking at vineyard hills, seen from behind, golden late afternoon light, no text, no logos, no readable signs, face not visible','[{"q":"Was ist die Zuwendung zur Ersatzpflege?","a":"Ein Zuschuss für die Kosten einer Ersatzpflege, wenn die Hauptpflegeperson etwa wegen Urlaub oder Krankheit verhindert ist. Beantragt wird sie beim Sozialministeriumservice."},{"q":"Wie lange kann man Pflegekarenz nehmen?","a":"Pflegekarenz und Pflegeteilzeit sind zeitlich begrenzt. Details und Ansprüche erklärt die Arbeiterkammer."},{"q":"Wo bekommen pflegende Angehörige psychische Unterstützung?","a":"Über das kostenlose Angehörigengespräch des Sozialministeriumservice, bei Selbsthilfegruppen und in Krisen bei der Telefonseelsorge 142."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('hauskrankenpflege-mobile-dienste-antrag','Hauskrankenpflege: Mobile Dienste beantragen und Kosten','Mobile Dienste ermöglichen vielen älteren Menschen ein Leben zu Hause. Was Hauskrankenpflege und Heimhilfe leisten und wie die Kosten berechnet werden.','Die Hauskrankenpflege ist für viele ältere und kranke Menschen die Voraussetzung dafür, weiter zu Hause leben zu können. Diplomierte Pflegekräfte kommen in die Wohnung, versorgen Wunden, unterstützen bei der Körperpflege oder kontrollieren die Medikamenteneinnahme. Ergänzt wird das Angebot durch Heimhilfen und andere mobile Dienste.

## Medizinische Hauskrankenpflege auf Kasse

Zu unterscheiden ist zwischen zwei Formen:

- Die medizinische Hauskrankenpflege wird ärztlich verordnet und von der Krankenkasse bezahlt. Sie ersetzt oder verkürzt einen Spitalsaufenthalt, etwa zur Wundversorgung nach einer Operation oder für Infusionen. Sie ist in der Regel zeitlich begrenzt.
- Die allgemeine Hauskrankenpflege und die Heimhilfe sind Teil der sozialen Dienste der Länder. Sie unterstützen dauerhaft im Alltag und bei der Pflege.

Für die medizinische Hauskrankenpflege ist eine Verordnung der Hausärztin oder des Hausarztes bzw. des Spitals bei der Entlassung nötig. Diese wird bei der Kasse eingereicht.

Heimhilfen unterstützen bei alltäglichen Dingen: Körperpflege, An- und Auskleiden, Zubereitung einfacher Mahlzeiten, Einkäufe und leichte Haushaltstätigkeiten. Daneben gibt es weitere Angebote wie Essen auf Rädern, Besuchsdienste, Notruftelefone, Reinigungsdienste oder mobile Therapie. Welche Kombination sinnvoll ist, wird meist bei einem Erstgespräch festgelegt.

## Hauskrankenpflege beantragen: so geht es

1. Kontakt mit der zuständigen Stelle aufnehmen: in Wien der Fonds Soziales Wien, in Tirol die Sozial- und Gesundheitssprengel, in anderen Bundesländern Sozialabteilungen, Gemeinden oder Hilfsorganisationen.
2. Erstgespräch und Bedarfserhebung, oft bei einem Hausbesuch.
3. Pflegeplan mit Häufigkeit und Dauer der Einsätze.
4. Laufende Anpassung, wenn sich der Bedarf ändert.

Anbieter sind Organisationen wie Hilfswerk, Volkshilfe, Caritas, Rotes Kreuz, Diakonie, Johanniter oder regionale Vereine.

## Was mobile Dienste kosten

Die Kosten für allgemeine Hauskrankenpflege und Heimhilfe sind gefördert. Pflegebedürftige zahlen einen Kostenbeitrag pro Stunde, der sich in den meisten Bundesländern am Einkommen und an der Pflegegeldstufe orientiert. Die Höchst- und Mindestbeiträge legen die Länder fest. Das Pflegegeld ist dafür gedacht, solche Leistungen mitzufinanzieren. Aktuelle Tarife nennen die Anbieter oder die Sozialabteilung des Landes.

## Hauskrankenpflege nach dem Spital

Besonders wichtig ist die Hauskrankenpflege nach einer Entlassung aus dem Krankenhaus. Viele Spitäler haben ein Entlassungsmanagement, das schon vor der Heimkehr Kontakt mit mobilen Diensten aufnimmt. Angehörige sollten früh nachfragen, welche Unterstützung geplant ist, welche Hilfsmittel wie Pflegebett oder Toilettenstuhl nötig sind und wer die ärztliche Verordnung ausstellt. So lassen sich Lücken in den ersten Tagen zu Hause vermeiden.

## Grenzen der Hauskrankenpflege

Mobile Dienste kommen zu vereinbarten Zeiten und für eine begrenzte Dauer. Wer rund um die Uhr Hilfe benötigt, braucht zusätzlich Unterstützung durch Angehörige, eine 24-Stunden-Betreuung oder einen Platz im Pflegeheim. Hilfsorganisationen weisen seit Längerem darauf hin, dass ein Ausbau der Hauskrankenpflege viele vermeidbare Spitalsaufenthalte und Transporte verhindern könnte.

Für das Erstgespräch hilfreich sind Pflegegeldbescheid, Medikamentenliste, aktuelle Befunde und Kontaktdaten der Hausärztin. Bei Verschlechterung des Gesundheitszustands ist die Ärztin oder der Arzt bzw. außerhalb der Ordinationszeiten die Gesundheitshotline 1450 die richtige Anlaufstelle.','gesundheit','Pflege','tirol','ratgeber','Presseinfo Redaktion','/assets/img/artikel/hauskrankenpflege-mobile-dienste-antrag.webp',NULL,NULL,'published','2026-10-14T05:21:00.000Z','2026-10-22T00:17:07.884Z','Hauskrankenpflege: Mobile Dienste und Kosten','Hauskrankenpflege und mobile Dienste: Was Heimhilfe und Pflege zu Hause leisten, wer sie verordnet, was sie kostet und wie Sie sie beantragen – hier lesen.','Hauskrankenpflege','["Hauskrankenpflege","mobile Pflege","Heimhilfe","medizinische Hauskrankenpflege","hauskrankenpflege beantragen österreich","mobile dienste kosten einkommen","medizinische hauskrankenpflege kasse verordnung","heimhilfe tirol sozialsprengel"]','Hauskrankenpflege: Auto eines mobilen Pflegedienstes vor einem Haus in Tirol','Photorealistic editorial photo of a small white compact car of a mobile care service parked in front of a traditional Tyrolean house with wooden balconies in the early morning, mountains in background, frosty grass, no text, no logos, no readable signs, no people','[{"q":"Zahlt die Krankenkasse die Hauskrankenpflege?","a":"Die ärztlich verordnete medizinische Hauskrankenpflege zahlt die Kasse, meist zeitlich begrenzt. Allgemeine Hauskrankenpflege und Heimhilfe sind Sozialleistungen der Länder mit Kostenbeitrag."},{"q":"Wie viel kostet Heimhilfe pro Stunde?","a":"Das hängt vom Bundesland, vom Einkommen und von der Pflegegeldstufe ab. Die aktuellen Tarife nennen Anbieter und Sozialabteilungen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('demenz-zu-hause-pflegen-tipps','Demenz zu Hause pflegen: Alltag, Hilfe und Anlaufstellen','Die meisten Menschen mit Demenz werden zu Hause betreut. Wie Angehörige den Alltag gestalten, wo es Diagnose und Beratung gibt und welche Hilfen entlasten.','Demenz zu Hause zu pflegen, ist für Angehörige eine große Aufgabe, die viel Geduld und Wissen erfordert. In Österreich leben nach Schätzungen weit über hunderttausend Menschen mit einer Form der Demenz, die meisten davon in ihrem gewohnten Umfeld. Wer früh Unterstützung sucht, kann die Lebensqualität für alle Beteiligten deutlich verbessern.

## Erste Anzeichen und Diagnose

Vergesslichkeit allein ist noch kein Zeichen für Demenz. Auffällig wird es, wenn Gedächtnisprobleme den Alltag beeinträchtigen, die Orientierung nachlässt oder sich die Persönlichkeit verändert. Dann sollte die Hausärztin oder der Hausarzt eine erste Abklärung vornehmen und gegebenenfalls an eine Fachärztin für Neurologie oder Psychiatrie bzw. eine Gedächtnisambulanz überweisen. Eine genaue Diagnose ist wichtig, weil manche Ursachen von Gedächtnisstörungen behandelbar sind.

## Demenz zu Hause: den Alltag strukturieren

Menschen mit Demenz profitieren von festen Abläufen und einer vertrauten Umgebung. Bewährt haben sich:

- ein gleichbleibender Tagesrhythmus mit festen Zeiten für Mahlzeiten und Ruhe
- einfache, klare Sätze und Geduld bei Wiederholungen
- gut sichtbare Uhren, Kalender und Beschriftungen an Schränken
- Sicherheit in der Wohnung: Stolperfallen entfernen, Herd absichern, gute Beleuchtung
- Beschäftigungen, die an frühere Hobbys anknüpfen, etwa Musik, Gartenarbeit oder Fotoalben

Streit über Fakten bringt meist wenig. Hilfreicher ist es, auf die Gefühle hinter einer Aussage einzugehen.

## Unterstützung für Angehörige

Die Pflege von Menschen mit Demenz ist oft besonders belastend, weil Unruhe, nächtliches Umherwandern oder Misstrauen hinzukommen können. Folgende Angebote helfen:

1. Demenzberatungsstellen und Angehörigenschulungen, angeboten von Ländern, Hilfsorganisationen und Vereinen wie Alzheimer Austria.
2. Tageszentren mit speziellen Demenzgruppen.
3. Mobile Dienste, die auch zur Entlastung stundenweise kommen.
4. Selbsthilfegruppen, in denen sich Angehörige austauschen.

Auch das Pflegegeld berücksichtigt Demenz: Bei schweren geistigen oder psychischen Beeinträchtigungen wird ein Erschwerniszuschlag zum Pflegebedarf hinzugerechnet. Ein Antrag auf Pflegegeld oder auf Erhöhung lohnt sich daher oft.

Für Angehörige ist es wichtig, sich selbst Pausen zu gönnen. Schon wenige Stunden pro Woche, in denen jemand anderer die Betreuung übernimmt, können viel bewirken. Manche Hilfsorganisationen bieten speziell geschulte Besuchsdienste für Menschen mit Demenz an. In Kärnten, wie in anderen Bundesländern, gibt es zudem Demenzservicestellen, die Beratung, Gedächtnistraining und Angehörigengruppen anbieten.

## Rechtliches rechtzeitig regeln

Solange die betroffene Person noch entscheidungsfähig ist, sollte eine Vorsorgevollmacht errichtet werden. Sie legt fest, wer später in finanziellen, medizinischen oder rechtlichen Fragen entscheiden darf. Ohne Vorsorge kann eine gerichtliche Erwachsenenvertretung nötig werden. Notariate, Rechtsanwälte und Erwachsenenschutzvereine beraten dazu.

## Demenz zu Hause und wann es nicht mehr geht

Irgendwann kann die Pflege zu Hause an Grenzen stoßen, etwa wenn rund um die Uhr Aufsicht nötig ist. Dann kommen eine 24-Stunden-Betreuung oder ein Pflegeheim mit Demenzschwerpunkt in Frage. Diese Entscheidung ist kein Versagen, sondern oft der richtige Schritt für alle.

Zu Medikamenten und Therapien berät ausschließlich die behandelnde Ärztin oder der Arzt. Wer als Angehöriger selbst an seine Grenzen kommt, findet bei der Telefonseelsorge unter 142 rund um die Uhr ein offenes Ohr.','gesundheit','Pflege','kaernten','ratgeber','Presseinfo Redaktion','/assets/img/artikel/demenz-zu-hause-pflegen-tipps.webp',NULL,NULL,'published','2026-09-30T09:04:00.000Z','2026-10-22T00:17:07.884Z','Demenz zu Hause pflegen: Tipps und Anlaufstellen','Demenz zu Hause pflegen: Wie Angehörige den Alltag strukturieren, welche Unterstützung es gibt und wo Sie Beratung und Diagnose bekommen. Jetzt lesen.','Demenz zu Hause','["Demenz zu Hause","Demenz Pflege","Demenz Angehörige","Demenzberatung","demenz zu hause pflegen tipps","demenz diagnose wo abklären","demenz pflegegeld erschwerniszuschlag","demenz tageszentrum kärnten"]','Demenz zu Hause: Fotoalbum und Lesebrille als Erinnerungshilfe im Alltag','Photorealistic editorial photo of an old family photo album open on a wooden table next to a pair of reading glasses and a cup of tea, Carinthian lake visible through a window in soft autumn light, photos blurred, no text, no logos, no readable signs, no people','[{"q":"Wo wird Demenz diagnostiziert?","a":"Erste Anlaufstelle ist die Hausärztin oder der Hausarzt, die an Neurologie, Psychiatrie oder eine Gedächtnisambulanz überweisen."},{"q":"Gibt es bei Demenz mehr Pflegegeld?","a":"Bei schweren geistigen Beeinträchtigungen wird ein Erschwerniszuschlag zum Pflegebedarf hinzugerechnet, was zu einer höheren Stufe führen kann."},{"q":"Wo bekommen Angehörige von Menschen mit Demenz Beratung?","a":"Bei Demenzberatungsstellen der Länder, Hilfsorganisationen, Vereinen wie Alzheimer Austria und in Selbsthilfegruppen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pflegekarenz-pflegeteilzeit-ueberblick','Pflegekarenz und Pflegeteilzeit: Ansprüche und Pflegekarenzgeld','Wer einen Angehörigen pflegen will, kann beruflich kürzertreten. Wie Pflegekarenz und Pflegeteilzeit funktionieren und wer Pflegekarenzgeld bekommt.','Die Pflegekarenz gibt Arbeitnehmerinnen und Arbeitnehmern die Möglichkeit, sich für eine begrenzte Zeit ganz oder teilweise von der Arbeit freistellen zu lassen, um einen nahen Angehörigen zu pflegen oder die Pflege neu zu organisieren. Während dieser Zeit besteht Anspruch auf Pflegekarenzgeld. Die Regelungen sind vor allem dann hilfreich, wenn eine Pflegesituation plötzlich eintritt, etwa nach einem Schlaganfall oder einer schweren Erkrankung.

## Pflegekarenz oder Pflegeteilzeit?

Bei der Pflegekarenz wird die Arbeit für eine bestimmte Dauer ganz unterbrochen. Bei der Pflegeteilzeit wird die Arbeitszeit reduziert, wobei eine Mindeststundenzahl bestehen bleiben muss. Beide Formen sind zeitlich begrenzt; die genaue Höchstdauer und die Möglichkeit, sie bei einer Verschlechterung des Zustands erneut in Anspruch zu nehmen, sind gesetzlich geregelt. Aktuelle Informationen bietet das Sozialministeriumservice.

## Voraussetzungen für die Pflegekarenz

Wichtige Bedingungen sind:

- Die zu pflegende Person ist ein naher Angehöriger, etwa Elternteil, Kind, Ehepartner oder Lebensgefährtin.
- Die Person bezieht Pflegegeld, in der Regel ab Stufe 3. Bei Demenz oder bei minderjährigen Angehörigen genügen niedrigere Stufen.
- Das Arbeitsverhältnis besteht bereits eine gewisse Zeit.
- Es gibt eine schriftliche Vereinbarung mit dem Arbeitgeber.

In Betrieben ab einer bestimmten Größe besteht unter Umständen ein Rechtsanspruch auf Pflegekarenz bzw. Pflegeteilzeit für einen Teil der Zeit. Andernfalls ist man auf die Zustimmung des Arbeitgebers angewiesen.

## Pflegekarenzgeld beantragen

Das Pflegekarenzgeld wird beim Sozialministeriumservice beantragt, idealerweise gleich zu Beginn der Karenz. Es orientiert sich am bisherigen Einkommen, ähnlich wie das Arbeitslosengeld, und wird bei Pflegeteilzeit anteilig ausbezahlt. Während der Pflegekarenz besteht Kranken- und Pensionsversicherungsschutz. Außerdem gilt ein Kündigungs- und Entlassungsschutz.

So gehen Sie vor:

1. Mit dem Arbeitgeber Beginn, Dauer und Ausmaß vereinbaren und schriftlich festhalten.
2. Pflegegeldbescheid der angehörigen Person bereithalten oder Antrag auf Pflegegeld stellen.
3. Antrag auf Pflegekarenzgeld beim Sozialministeriumservice einbringen.
4. Zeit nutzen, um die weitere Betreuung zu organisieren, etwa mobile Dienste, 24-Stunden-Betreuung oder Heimplatz.

## Pflegekarenz: Tipps für das Gespräch mit dem Arbeitgeber

Viele Arbeitgeber zeigen Verständnis, wenn eine Pflegesituation plötzlich eintritt. Hilfreich ist es, offen über den Bedarf zu sprechen und einen Vorschlag mitzubringen: Wie lange soll die Karenz dauern, wäre eine Teilzeit möglich, wie können Aufgaben übergeben werden? Eine schriftliche Vereinbarung schafft Klarheit für beide Seiten. Bei Unsicherheiten kann der Betriebsrat unterstützen. Auch nach der Pflegekarenz besteht Anspruch, an den früheren Arbeitsplatz bzw. auf eine gleichwertige Stelle zurückzukehren.

Für die Begleitung sterbender Angehöriger oder schwerst erkrankter Kinder gibt es die Familienhospizkarenz. Hier gelten eigene Regeln und längere Fristen. Zusätzlich gibt es einen Härteausgleich für Familien in finanzieller Notlage.

## Pflegekarenz gut planen

Pflegekarenz ist keine Dauerlösung, sondern eine Überbrückung. Sie eignet sich, um die Pflege zu organisieren, Anträge zu stellen und Unterstützung aufzubauen. Beratung zu arbeitsrechtlichen Fragen geben die Arbeiterkammer und die Gewerkschaften. Fragen zur Gesundheit und Pflege des Angehörigen beantworten die behandelnden Ärztinnen und Ärzte sowie Pflegeberatungsstellen.','gesundheit','Pflege','vorarlberg','ratgeber','Presseinfo Redaktion','/assets/img/artikel/pflegekarenz-pflegeteilzeit-ueberblick.webp',NULL,NULL,'published','2026-10-19T15:44:00.000Z','2026-10-22T00:17:07.884Z','Pflegekarenz: Ansprüche und Pflegekarenzgeld','Pflegekarenz und Pflegeteilzeit: Wer Anspruch hat, wie lange sie dauern, wie das Pflegekarenzgeld berechnet wird und wie Sie es beantragen – jetzt lesen.','Pflegekarenz','["Pflegekarenz","Pflegeteilzeit","Pflegekarenzgeld","Familienhospizkarenz","pflegekarenz anspruch arbeitgeber","pflegekarenzgeld beantragen sozialministeriumservice","pflegeteilzeit wie lange","pflegekarenz voraussetzungen pflegestufe"]','Pflegekarenz: Homeoffice-Schreibtisch und Rollstuhl im Hintergrund eines Hauses in Vorarlberg','Photorealistic editorial photo of a closed laptop and a stack of folders on a home office desk beside a window, an empty wheelchair visible in the softly blurred background hallway, modern Vorarlberg wooden house interior, evening light, no text, no logos, no readable signs, no people','[{"q":"Wer hat Anspruch auf Pflegekarenzgeld?","a":"Arbeitnehmer, die mit dem Arbeitgeber Pflegekarenz oder Pflegeteilzeit vereinbaren, um einen nahen Angehörigen mit Pflegegeld zu pflegen."},{"q":"Wo beantrage ich Pflegekarenzgeld?","a":"Beim Sozialministeriumservice, am besten gleich zu Beginn der Karenz."},{"q":"Bin ich während der Pflegekarenz versichert?","a":"Ja, es besteht Kranken- und Pensionsversicherungsschutz sowie ein Kündigungsschutz."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('psychiatrie-home-treatment-tirol-verlaengert','Psychiatrie Home-Treatment in Tirol: Programm bis 2028 verlängert','Land Tirol und Sozialversicherung finanzieren das Home-Treatment für psychisch kranke Kinder und Jugendliche bis Ende 2028. Die Zahl der Plätze steigt.','Das Home-Treatment Tirol für Kinder und Jugendliche mit psychiatrischem Behandlungsbedarf wird fortgesetzt: Land Tirol und Sozialversicherung finanzieren das Programm bis Dezember 2028. Das berichtete MeinBezirk am 15. Oktober. Die Landes-Zielsteuerungskommission hat eine dritte Projektphase von Jänner 2027 bis Dezember 2028 beschlossen.

## Home-Treatment Tirol: mehr Plätze und Personal

Für die neue Phase sind insgesamt rund zwei Millionen Euro vorgesehen, etwa 965.000 Euro für 2027 und mehr als 970.000 Euro für 2028. Die Zahl der Behandlungsplätze steigt von zehn auf zwölf. Das Personal ist abgesichert, zusätzlich kommt eine Ärztin bzw. ein Arzt in Ausbildung dazu.

## So funktioniert die Behandlung zu Hause

Beim Home-Treatment kommen multiprofessionelle Teams zu den jungen Patientinnen und Patienten nach Hause. Die Familie wird in die Therapie eingebunden. Statt eines Aufenthalts auf einer Station findet die Behandlung im gewohnten Umfeld statt. Gesundheitslandesrätin Cornelia Hagele betonte, dass nicht für jede psychiatrische Erkrankung ein Spitalsaufenthalt die beste Therapie sei.

Seit dem Start im November 2023 wurden 95 Kinder und Jugendliche in diesem Modell behandelt. Eine Behandlung dauert im Durchschnitt rund 88 Tage.

## Warum Behandlung im Alltag helfen kann

Fachleute sehen in solchen Modellen mehrere Vorteile. Kinder und Jugendliche bleiben in ihrer Familie und oft auch in ihrer Schule. Was in der Therapie erarbeitet wird, kann direkt im Alltag geübt werden. Eltern und Geschwister lernen, wie sie unterstützen können. Gleichzeitig werden stationäre Betten für jene frei, die eine Aufnahme dringend brauchen. Die Kinder- und Jugendpsychiatrie ist in Österreich seit Jahren ein Engpassfach mit langen Wartezeiten.

Welche Form der Behandlung im Einzelfall passt, entscheiden Fachärztinnen und Fachärzte gemeinsam mit den Familien. Home-Treatment ist nicht für jede Situation geeignet, etwa wenn eine akute Gefährdung besteht.

Auch in anderen Bundesländern werden ähnliche Modelle erprobt oder diskutiert. Der Bedarf an kinder- und jugendpsychiatrischer Versorgung ist in Österreich seit der Pandemie deutlich gestiegen. Fachgesellschaften fordern seit Längerem mehr Kassenstellen, mehr stationäre Plätze und mehr ambulante Angebote. Home-Treatment gilt dabei als ein Baustein, um die Versorgung flexibler zu gestalten.

## Weitere Gesundheitsthemen in Tirol

Im selben Zusammenhang wies das Land auf das Brustkrebs-Früherkennungsprogramm hin. In Tirol erkranken jährlich rund 590 Frauen an Brustkrebs, etwa 110 sterben daran. Nur gut die Hälfte der eingeladenen Frauen nutzt das kostenlose Screening, für das es in Tirol 21 Standorte gibt. Frauen zwischen 45 und 74 Jahren erhalten alle zwei Jahre eine Einladung oder Erinnerung.

## Home-Treatment Tirol und andere Hilfsangebote

Eltern, die sich Sorgen um die psychische Gesundheit ihres Kindes machen, sollten zunächst mit der Kinderärztin, dem Hausarzt oder der Schulpsychologie sprechen. Diese können an Fachstellen weitervermitteln. Für Kinder und Jugendliche gibt es zudem die kostenlose Beratung von Rat auf Draht unter 147, rund um die Uhr und anonym. Erwachsene finden bei der Telefonseelsorge unter 142 Unterstützung. In akuten Notfällen ist die Rettung unter 144 zu verständigen.','gesundheit','Psyche','tirol','news','Presseinfo Redaktion','/assets/img/artikel/psychiatrie-home-treatment-tirol-verlaengert.webp','MeinBezirk Tirol','https://www.meinbezirk.at/tirol/c-gesundheit/tirol-sichert-psychiatrische-hilfe-im-zuhause-ausbau-bis-2028_a8957148','published','2026-10-15T12:28:00.000Z','2026-10-22T00:17:07.884Z','Home-Treatment Tirol: Psychiatrie zu Hause bis 2028','Home-Treatment Tirol: Kinder und Jugendliche mit psychiatrischem Bedarf werden weiter zu Hause behandelt. Plätze, Kosten und Ergebnisse im Überblick.','Home-Treatment Tirol','["Home-Treatment Tirol","Kinderpsychiatrie Tirol","psychiatrische Behandlung zu Hause","Jugendpsychiatrie","home treatment kinder jugendliche psychiatrie tirol","psychiatrie zu hause behandlung familie","landes-zielsteuerungskommission tirol","psychische gesundheit kinder tirol"]','Home-Treatment Tirol: Jugendzimmer als Ort der psychiatrischen Behandlung zu Hause','Photorealistic editorial photo of a teenager''s bedroom in a Tyrolean apartment with a desk, books and a guitar, two empty chairs facing each other as if for a conversation, Innsbruck mountains through the window, soft afternoon light, no text, no logos, no readable signs, no people','[{"q":"Was ist Home-Treatment in der Kinderpsychiatrie?","a":"Multiprofessionelle Teams behandeln Kinder und Jugendliche zu Hause und binden die Familie ein, statt einer stationären Aufnahme."},{"q":"Wie lange läuft das Programm in Tirol?","a":"Die dritte Projektphase läuft von Jänner 2027 bis Dezember 2028."},{"q":"Wo finden Kinder und Jugendliche rasch Hilfe?","a":"Bei Rat auf Draht unter 147, rund um die Uhr und anonym. Im Notfall gilt die Rettung 144."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('psychische-gesundheit-kaernten-welttag','Psychische Gesundheit in Kärnten: Jeder Dritte betroffen','Fast jeder dritte Mensch in Österreich erkrankt im Lauf des Lebens psychisch. In Kärnten zeigt ein Pilotprojekt, wie Betroffene zurück in den Alltag finden.','Die psychische Gesundheit in Kärnten stand rund um den Welttag der psychischen Gesundheit im Mittelpunkt: Laut einem Bericht von ORF Kärnten vom 8. Oktober erkrankt fast jeder dritte Mensch in Österreich mindestens einmal im Leben an einer psychischen Erkrankung. Am häufigsten sind Angststörungen und Depressionen, gefolgt von Suchterkrankungen und Essstörungen.

## Psychische Gesundheit in Kärnten: Zahlen und Folgen

Psychische Erkrankungen sind für zwölf Prozent der Krankenstandstage verantwortlich und gelten als häufigster Grund für Frühpensionierungen. Gesundheitsreferentin Beate Prettner (SPÖ) betonte, dass statistisch jede dritte Person im Leben in eine psychische Krise gerät. Mit Öffentlichkeitsarbeit wolle man die Stigmatisierung abbauen, damit Betroffene früher Hilfe suchen.

In Kärnten gibt es laut Bericht unter anderem:

- einen rund um die Uhr erreichbaren Akutdienst
- spezialisierte Teams
- zwei kürzlich sanierte Krankenhäuser mit psychiatrischen Angeboten
- ambulante Therapiezentren
- Tageszentren

Weil die Fallzahlen steigen, sei ein Ausbau nötig. Die angespannte Finanzlage mache das allerdings schwierig.

## Pilotprojekt in Feldkirchen

Als Beispiel für neue Wege nennt der Bericht den Perspektivenraum Feldkirchen, ein Pilot-Tageszentrum des Vereins Autark. Dort gibt es 20 Plätze, an denen Betroffene in Bereichen wie Holzarbeit, Küche, kreatives Arbeiten oder Hauswirtschaft tätig sind. Dazu kommen Einzel- und Gruppentherapie. Ziel ist es, Tagesstruktur zu geben und Schritt für Schritt Stabilität aufzubauen.

Autark betreibt außerdem eine Trainingswohnung in Krumpendorf, in der zwei Klientinnen und Klienten selbstständiges Wohnen üben. Das Pilotprojekt soll künftig in die reguläre Landesfinanzierung übernommen werden.

Ähnliche Projekte zur beruflichen und sozialen Rehabilitation gibt es auch in anderen Bundesländern. Sie setzen dort an, wo eine akute Behandlung abgeschlossen ist, Betroffene aber noch nicht in den Arbeitsalltag zurückkehren können. Eine geregelte Tagesstruktur, sinnvolle Tätigkeiten und der Kontakt zu anderen Menschen gelten dabei als wichtige Faktoren für die Genesung.

## Warum frühe Hilfe wichtig ist

Fachleute betonen seit Jahren, dass psychische Erkrankungen gut behandelbar sind, je früher, desto besser. Viele Menschen warten jedoch lange, bevor sie sich Hilfe holen, oft aus Scham oder aus Sorge vor Vorurteilen. Gesprächsangebote, Aufklärung in Schulen und Betrieben und niedrigschwellige Anlaufstellen sollen das ändern.

## Was jeder selbst tun kann

Neben professioneller Hilfe tragen auch alltägliche Faktoren zur seelischen Stabilität bei: ausreichend Schlaf, regelmäßige Bewegung, soziale Kontakte und Pausen von Bildschirm und Arbeit. Sie ersetzen keine Behandlung, können aber vorbeugen und den Heilungsprozess unterstützen. Wichtig ist auch, auf Menschen im eigenen Umfeld zu achten. Wer bemerkt, dass sich ein Freund oder Familienmitglied zurückzieht oder stark verändert, kann behutsam das Gespräch suchen und Unterstützung anbieten, ohne zu drängen.

## Anlaufstellen für psychische Gesundheit in Kärnten und Österreich

Wer sich belastet fühlt, kann sich zunächst an die Hausärztin oder den Hausarzt wenden. Weitere Anlaufstellen sind psychosoziale Beratungsstellen, klinisch-psychologische Behandlung, die seit 2026 auch auf Kassenkosten möglich ist, sowie Psychotherapie. In Krisen helfen rund um die Uhr und kostenlos:

- Telefonseelsorge: 142
- Rat auf Draht für Kinder und Jugendliche: 147
- Gesundheitshotline: 1450

Bei akuter Gefahr ist sofort die Rettung unter 144 zu rufen. Niemand muss eine Krise allein bewältigen.','gesundheit','Psyche','kaernten','news','Presseinfo Redaktion','/assets/img/artikel/psychische-gesundheit-kaernten-welttag.webp','ORF Kärnten','https://kaernten.orf.at/stories/3374398/','published','2026-10-08T15:33:00.000Z','2026-10-22T00:17:07.884Z','Psychische Gesundheit Kärnten: jeder Dritte betroffen','Psychische Gesundheit in Kärnten: Fast jeder Dritte erkrankt im Leben psychisch. Welche Angebote es gibt und welches Pilotprojekt neue Wege geht – lesen.','Psychische Gesundheit in Kärnten','["Psychische Gesundheit Kärnten","Welttag psychische Gesundheit","psychische Erkrankung","Tageszentrum Psyche","psychische gesundheit kärnten angebote","psychische erkrankung krankenstand frühpension","perspektivenraum feldkirchen autark","depression angststörung häufigkeit österreich"]','Psychische Gesundheit Kärnten: Holzwerkstatt in einem Tageszentrum für Betroffene','Photorealistic editorial photo of a bright carpentry workshop in a Carinthian day center, wooden workbench with hand tools and half-finished birdhouses, sawdust in sunlight from tall windows, no text, no logos, no readable signs, no people','[{"q":"Wie häufig sind psychische Erkrankungen in Österreich?","a":"Fast jeder Dritte erkrankt im Lauf des Lebens mindestens einmal psychisch, am häufigsten an Angststörungen oder Depressionen."},{"q":"Wo bekomme ich in einer psychischen Krise sofort Hilfe?","a":"Bei der Telefonseelsorge unter 142, für junge Menschen bei Rat auf Draht unter 147, im Notfall bei der Rettung 144."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('depression-kosten-oesterreich-studie','Depression in Österreich: Studie schätzt 40 Milliarden Euro Schaden','Depressionen könnten Österreich bis 2050 rund 40 Milliarden Euro kosten, schätzt eine Studie unter Beteiligung der WU Wien. Fachleute fordern rascheren Zugang zur Therapie.','Depression in Österreich verursacht nicht nur großes persönliches Leid, sondern auch enorme wirtschaftliche Kosten. Eine Studie unter Leitung von Klaus Prettner von der Wirtschaftsuniversität Wien, veröffentlicht im Fachjournal Nature Medicine, schätzt den Schaden für Österreich im Zeitraum 2025 bis 2050 auf rund 40 Milliarden Euro. Darüber berichtete RELATUS MED am 11. Oktober, dem Tag nach dem Welttag der psychischen Gesundheit.

## Depression in Österreich: Woher die Kosten kommen

Weltweit beziffert die Studie die Kosten durch Depressionen bis 2050 auf etwa 10,7 Billionen Euro, das entspricht rund 0,46 Prozent der jährlichen globalen Wirtschaftsleistung. Den Großteil machen nicht Behandlungskosten aus, sondern Verluste durch geringere Beschäftigung und Produktivität. Menschen mit Depressionen fallen häufiger und länger aus oder scheiden früher aus dem Erwerbsleben aus.

Die Forschenden empfehlen daher:

- eine bessere Versorgung insgesamt
- die Integration psychischer Gesundheit in die Primärversorgung
- den Ausbau von Therapieangeboten
- eine möglichst frühe Behandlung

Nach Angaben der Weltgesundheitsorganisation lebte 2023 fast jeder siebte Mensch weltweit mit einer psychischen Erkrankung.

## Forderungen zum Welttag

Der Österreichische Bundesverband für Psychotherapie (ÖBVP) fordert einen leistbaren und zeitnahen Zugang zur Psychotherapie und will Betroffene stärker in die Gestaltung der Versorgung einbinden. Der Gesundheitssprecher der Grünen, Ralph Schallmeiner, verlangt eine verbindliche Zusage für das Programm „Gesund aus der Krise“ für Kinder und Jugendliche über Juni 2027 hinaus.

Der Gewerkschaftsbund wies darauf hin, dass die Krankenstandstage insgesamt leicht gesunken seien, die psychisch bedingten Ausfälle aber seit Jahren steigen. Er fordert bessere Arbeitsbedingungen.

Die Ergebnisse bestätigen, was Fachleute seit Längerem betonen: Investitionen in psychische Gesundheit rechnen sich nicht nur menschlich, sondern auch volkswirtschaftlich. Je früher eine Depression erkannt und behandelt wird, desto geringer sind in der Regel die Folgen für Betroffene, Familien und Arbeitgeber.

## Maßnahmen in Wien

Die Stadt Wien fördert laut Bericht heuer 600 Workshops der Initiative „Mental Health Days“ an Schulen der Sekundarstufe. 227 Schulen erhalten zusätzliches Personal wie Sozialarbeiterinnen oder Schulpsychologen. Eine Studie der Stadt zeigt zudem, dass der Anteil der LGBTIQ-Personen, die regelmäßig Diskriminierung im öffentlichen Raum erleben, von 28 Prozent im Jahr 2015 auf 38 Prozent im Jahr 2025 gestiegen ist.

Für Betroffene ist seit Jahresbeginn ein zusätzlicher Weg dazugekommen: Die klinisch-psychologische Behandlung ist seit 2026 eine Kassenleistung. Die ÖGK hat dafür gemeinsam mit SVS und BVAEB einen bundesweiten Vertrag mit dem Berufsverband Österreichischer Psychologinnen und Psychologen abgeschlossen. Laut ÖGK stehen jährlich rund 120.700 Behandlungseinheiten zur Verfügung, die nach Bevölkerungszahl auf die Bundesländer verteilt werden.

## Depression erkennen und Hilfe holen

Anhaltende gedrückte Stimmung, Interessenverlust, Antriebslosigkeit, Schlafprobleme oder das Gefühl der Wertlosigkeit über mehrere Wochen können Hinweise auf eine Depression sein. Depressionen sind gut behandelbar. Erste Anlaufstelle ist die Hausärztin oder der Hausarzt, die an Fachärzte für Psychiatrie, an klinische Psychologinnen oder an Psychotherapeuten weitervermitteln können.

In Krisen helfen die Telefonseelsorge unter 142 und für junge Menschen Rat auf Draht unter 147, beide rund um die Uhr, kostenlos und anonym. Bei akuter Gefahr ist die Rettung unter 144 zu verständigen.','gesundheit','Psyche','wien','news','Presseinfo Redaktion','/assets/img/artikel/depression-kosten-oesterreich-studie.webp','RELATUS MED','https://www.medmedia.at/relatus-pharm/forderungen-nach-ausbau-der-psychischen-versorgung/','published','2026-10-11T10:16:00.000Z','2026-10-22T00:17:07.885Z','Depression Österreich: 40 Mrd. Euro Schaden bis 2050','Depression in Österreich: Eine Studie schätzt den wirtschaftlichen Schaden bis 2050 auf rund 40 Milliarden Euro. Was Experten fordern und wo es Hilfe gibt.','Depression in Österreich','["Depression Österreich","Depression Kosten","Welttag psychische Gesundheit","Psychotherapie Zugang","depression österreich studie wirtschaftlicher schaden","mental health days wien schulen","gesund aus der krise verlängerung","psychische krankenstände steigen"]','Depression Österreich: verlassener Büroarbeitsplatz in Wien in der Abenddämmerung','Photorealistic editorial photo of an empty office desk with a closed laptop and a cold cup of coffee in a Vienna high-rise office at dusk, city lights of Donaustadt visible through glass facade, melancholic mood, no text, no logos, no readable signs, no people','[{"q":"Wie viel kosten Depressionen Österreich?","a":"Eine Studie in Nature Medicine schätzt den wirtschaftlichen Schaden für Österreich von 2025 bis 2050 auf rund 40 Milliarden Euro."},{"q":"Wo bekomme ich Hilfe bei Depressionen?","a":"Erste Anlaufstelle ist die Hausärztin oder der Hausarzt. In Krisen hilft die Telefonseelsorge 142 rund um die Uhr."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('psychiatrische-reha-oberndorf-ausbau','Psychiatrische Reha in Salzburg: Oberndorf erhält 35 neue Betten','Die Rehaklinik Oberndorf bei Salzburg baut ihre Kapazitäten für psychische Rehabilitation um 35 Betten aus. Auch im Montafon wird erweitert.','Die psychiatrische Reha in Österreich wird ausgebaut: Die Rehaklinik Oberndorf bei Salzburg erhält 35 zusätzliche Betten, einen neuen Therapiebereich und weitere Infrastruktur. Das berichtete MeinBezirk am 6. Oktober. Betreiber ist die Vitrea-Gruppe, die im Auftrag der Kostenträger ihre Kapazitäten für psychische und psychosomatische Rehabilitation erweitert.

## Psychiatrische Reha: Investitionen in Salzburg und Vorarlberg

In Oberndorf werden laut Bericht 12,6 Millionen Euro investiert. In der Rehaklinik Montafon in Vorarlberg fließen 1,4 Millionen Euro in eine stationäre Erweiterung. Beide Projekte sind Teil einer größeren Investitionsoffensive der Gruppe an Standorten in Österreich und anderen deutschsprachigen Ländern.

## Hoher Bedarf an Rehabilitation

Der Ausbau wird mit dem steigenden Bedarf begründet. Laut Bericht leben in Österreich rund 2,1 Millionen Menschen mit einer psychischen Erkrankung. Nach Angaben der OECD ist die österreichische Bevölkerung stärker betroffen als der EU-Durchschnitt. Unter Verweis auf Daten von WIFO und Pensionsversicherung nennt der Betreiber weitere Zahlen:

- Bei den 25- bis 44-Jährigen sind psychische Erkrankungen die häufigste Ursache für Langzeitkrankenstände, mit rund 1,97 Millionen Fehltagen pro Jahr.
- 46,9 Prozent der neu zuerkannten Berufsunfähigkeits- und Invaliditätspensionen sind psychisch bedingt.
- Die Gesamtkosten werden auf 4,3 Prozent der Wirtschaftsleistung geschätzt.

Christian Breitfuß, Regional-COO von Vitrea Österreich, sagte, psychische Erkrankungen seien für immer mehr Menschen eine langfristige gesundheitliche Einschränkung.

Für Patientinnen und Patienten aus Salzburg und Oberösterreich bedeutet der Ausbau in Oberndorf mehr Plätze in Wohnortnähe. Wann die zusätzlichen Betten in Betrieb gehen, hängt vom Baufortschritt ab. Zuweisungen erfolgen weiterhin über die Sozialversicherung.

## Was eine psychiatrische Reha bietet

Eine stationäre psychiatrische oder psychosomatische Rehabilitation dauert in der Regel mehrere Wochen. Sie kombiniert Einzel- und Gruppentherapie, Bewegung, kreative Therapien, Entspannungsverfahren und sozialarbeiterische Beratung. Ziel ist es, die Belastbarkeit zu stärken, Rückfällen vorzubeugen und die Rückkehr in Alltag und Beruf zu erleichtern. Daneben gibt es zunehmend ambulante Angebote, bei denen Betroffene zu Hause wohnen.

Fachleute betonen, dass Rehabilitation vor allem dann wirkt, wenn sie gut in die weitere Behandlung eingebettet ist. Nach der Reha sollte daher eine ambulante Nachbetreuung geplant werden, etwa durch Psychotherapie, klinisch-psychologische Behandlung oder fachärztliche Kontrollen. Auch eine schrittweise Rückkehr an den Arbeitsplatz kann sinnvoll sein. In Österreich gibt es dafür seit einigen Jahren das Modell der Wiedereingliederungsteilzeit, das mit Arbeitgeber und Krankenkasse vereinbart wird.

## Psychiatrische Reha beantragen

Der Antrag wird meist von der behandelnden Ärztin oder dem Arzt gemeinsam mit der Patientin bzw. dem Patienten gestellt und beim zuständigen Sozialversicherungsträger eingereicht, für Erwerbstätige häufig bei der Pensionsversicherung. Nach Prüfung wird ein Platz zugewiesen. Wartezeiten sind möglich. Ein ausführlicher ärztlicher Befund beschleunigt das Verfahren.

Wer sich in einer akuten Krise befindet, sollte nicht auf einen Reha-Platz warten. Hilfe gibt es bei der Hausärztin oder dem Hausarzt, in psychiatrischen Ambulanzen, bei der Telefonseelsorge unter 142 und bei Rat auf Draht unter 147 für junge Menschen. Bei akuter Gefahr ist die Rettung unter 144 zu verständigen.','gesundheit','Psyche','salzburg','news','Presseinfo Redaktion','/assets/img/artikel/psychiatrische-reha-oberndorf-ausbau.webp','MeinBezirk Flachgau','https://www.meinbezirk.at/flachgau/c-wirtschaft/ausbau-der-kapazitaeten-fuer-psychiatrische-reha_a8938878','published','2026-10-06T16:49:00.000Z','2026-10-22T00:17:07.885Z','Psychiatrische Reha Salzburg: 35 neue Betten','Psychiatrische Reha in Oberndorf: Die Klinik bei Salzburg erhält 35 zusätzliche Betten. Hintergründe, Zahlen und Antrag im Überblick – jetzt lesen.','Psychiatrische Reha','["Psychiatrische Reha","Reha Oberndorf","psychische Rehabilitation","Reha Antrag PVA","psychiatrische reha salzburg oberndorf","psychosomatische reha antrag pensionsversicherung","reha montafon erweiterung","psychische erkrankung invaliditätspension"]','Psychiatrische Reha: Garten einer Rehaklinik im Salzburger Flachgau im Herbst','Photorealistic editorial photo of a calm rehabilitation clinic garden near the Salzach river in Flachgau, wooden benches, walking path, autumn foliage, morning mist over meadows, no text, no logos, no readable signs, no people','[{"q":"Wie lange dauert eine psychiatrische Reha?","a":"Eine stationäre Rehabilitation dauert in der Regel mehrere Wochen. Daneben gibt es ambulante Angebote."},{"q":"Wer beantragt eine psychiatrische Reha?","a":"Meist die behandelnde Ärztin oder der Arzt gemeinsam mit dem Patienten, eingereicht beim zuständigen Sozialversicherungsträger."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('psychotherapie-auf-kasse-kassenplatz-finden','Psychotherapie auf Kasse: So finden Sie einen Kassenplatz','Ein Kassenplatz für Psychotherapie ist begehrt, Wartezeiten sind oft lang. Wie die Suche abläuft, was der Kostenzuschuss bringt und welche Alternativen es gibt.','Psychotherapie auf Kasse bedeutet, dass die Krankenkasse die Kosten der Behandlung vollständig übernimmt. Solche Kassenplätze gibt es in Österreich, sie sind aber begrenzt und je nach Bundesland unterschiedlich organisiert. Wer weiß, wie das System funktioniert, findet leichter einen Weg zur passenden Unterstützung.

## Wie Psychotherapie auf Kasse funktioniert

Die Krankenkassen stellen ein bestimmtes Kontingent an vollfinanzierten Therapiestunden zur Verfügung. Vergeben werden diese entweder über Psychotherapeutinnen und Psychotherapeuten mit Kassenvertrag oder über Vereine und Versorgungseinrichtungen, mit denen die Kasse Verträge hat. In manchen Bundesländern gibt es zentrale Clearing- oder Koordinationsstellen, die Anfragen sammeln und Plätze vermitteln. Welche Struktur im eigenen Bundesland gilt, erfährt man bei der ÖGK, der BVAEB oder der SVS.

Vor Beginn einer Therapie ist in der Regel eine ärztliche Untersuchung nötig, spätestens vor der zweiten Sitzung. Dafür reicht meist ein Besuch bei der Hausärztin oder dem Hausarzt. Ab einer bestimmten Stundenzahl muss die Therapeutin oder der Therapeut eine Bewilligung bei der Kasse beantragen.

## Einen Kassenplatz finden: Schritt für Schritt

1. Mit der Hausärztin oder dem Hausarzt sprechen, die Beschwerden schildern und die ärztliche Untersuchung durchführen lassen.
2. Bei der eigenen Krankenkasse nachfragen, welche Stellen Kassenplätze vergeben.
3. Mehrere Therapeutinnen und Einrichtungen gleichzeitig kontaktieren und sich auf Wartelisten setzen lassen.
4. Im Erstgespräch klären, ob ein Kassenplatz frei ist oder wann einer frei wird.
5. Die Bewilligung wird von der Therapeutin bei der Kasse beantragt.

Die Wartezeiten können je nach Region und Fachrichtung von einigen Wochen bis zu vielen Monaten reichen. Es lohnt sich daher, früh mit der Suche zu beginnen.

## Kostenzuschuss bei Wahltherapeuten

Ist kein Kassenplatz verfügbar, kann man eine Psychotherapeutin ohne Kassenvertrag wählen. Die Kasse zahlt dann einen Kostenzuschuss pro Sitzung, den Rest trägt man selbst. Voraussetzung ist ebenfalls die ärztliche Untersuchung und ab einer bestimmten Stundenzahl eine Bewilligung. Die Höhe des Zuschusses legt die jeweilige Kasse fest. Viele Therapeuten bieten für Menschen mit geringem Einkommen Sozialtarife an. Danach zu fragen, ist üblich.

## Alternativen zur Psychotherapie auf Kasse

Während der Wartezeit oder ergänzend gibt es weitere Möglichkeiten:

- klinisch-psychologische Behandlung, die seit 2026 ebenfalls als Kassenleistung angeboten wird
- psychosoziale Beratungsstellen von Ländern, Gemeinden und Hilfsorganisationen, oft kostenlos
- psychiatrische Ambulanzen und Fachärzte für Psychiatrie mit Kassenvertrag
- Psychotherapie-Ambulanzen von Ausbildungseinrichtungen, die oft günstiger sind
- für Kinder und Jugendliche das Programm „Gesund aus der Krise“

Psychotherapie ist eine anerkannte Behandlungsmethode bei psychischen Erkrankungen wie Depressionen, Angststörungen, Traumafolgen oder Essstörungen. Es gibt in Österreich zahlreiche anerkannte Methoden, etwa verhaltenstherapeutische, psychodynamische, systemische oder humanistische Ansätze. Wichtig ist, dass die Chemie zwischen Klientin und Therapeut stimmt. Ein Erstgespräch hilft, das herauszufinden.

## Hilfe in der Krise

Wer sich in einer akuten seelischen Krise befindet, sollte nicht auf einen Therapieplatz warten. Rund um die Uhr, kostenlos und anonym erreichbar ist die Telefonseelsorge unter 142. Kinder und Jugendliche finden bei Rat auf Draht unter 147 Unterstützung. Bei akuter Gefahr ist sofort die Rettung unter 144 zu verständigen.','gesundheit','Psyche','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/psychotherapie-auf-kasse-kassenplatz-finden.webp',NULL,NULL,'published','2026-09-25T07:31:00.000Z','2026-10-22T00:17:07.886Z','Psychotherapie auf Kasse: Kassenplatz finden','Psychotherapie auf Kasse: Wie Sie einen Kassenplatz finden, was der Kostenzuschuss bringt und welche Alternativen es gibt. Schritt für Schritt.','Psychotherapie auf Kasse','["Psychotherapie auf Kasse","Kassenplatz Psychotherapie","Psychotherapie Kostenzuschuss","Psychotherapie Österreich","psychotherapie auf kasse wien wartezeit","kassenplatz psychotherapie finden ögk","psychotherapie kostenzuschuss wahltherapeut","psychotherapie bewilligung krankenkasse"]','Psychotherapie auf Kasse: ruhiger Therapieraum mit zwei Sesseln in einem Wiener Altbau','Photorealistic editorial photo of a calm psychotherapy room in a Viennese Gründerzeit building, two armchairs facing each other, a box of tissues on a small side table, tall window with soft overcast light, herringbone parquet, no text, no logos, no readable signs, no people','[{"q":"Wie bekomme ich Psychotherapie auf Kasse?","a":"Nach einer ärztlichen Untersuchung bei der Krankenkasse nachfragen, welche Stellen Kassenplätze vergeben, und sich bei mehreren Therapeuten auf Wartelisten setzen lassen."},{"q":"Was zahlt die Kasse beim Wahltherapeuten?","a":"Einen Kostenzuschuss pro Sitzung, dessen Höhe die jeweilige Kasse festlegt. Den Rest zahlt man selbst."},{"q":"Was tun, wenn es mir jetzt schlecht geht?","a":"Die Telefonseelsorge ist unter 142 rund um die Uhr erreichbar, für junge Menschen Rat auf Draht unter 147. Bei akuter Gefahr 144 wählen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('klinisch-psychologische-behandlung-kasse','Klinisch-psychologische Behandlung: Seit 2026 auf Kasse','Seit 2026 übernehmen die Krankenkassen die klinisch-psychologische Behandlung. Wie man zu einem Platz kommt und was sie von Psychotherapie unterscheidet.','Die klinisch-psychologische Behandlung ist seit 2026 eine Leistung der gesetzlichen Krankenversicherung in Österreich. Damit gibt es neben Psychotherapie und psychiatrischer Behandlung einen weiteren Weg, um bei psychischen Erkrankungen auf Kassenkosten Hilfe zu bekommen. Bis dahin hatten die Kassen nur die Diagnostik bezahlt, für die Behandlung selbst gab es höchstens Zuschüsse.

## Klinisch-psychologische Behandlung: was neu ist

Die ÖGK hat gemeinsam mit der SVS und der BVAEB einen österreichweiten Vertrag mit dem Berufsverband Österreichischer Psychologinnen und Psychologen (BÖP) abgeschlossen. Laut ÖGK stehen rund 120.700 Behandlungseinheiten pro Jahr zur Verfügung, die nach Einwohnerzahl auf die Bundesländer verteilt werden. Für die Versicherten sind diese Behandlungsplätze kostenfrei, es muss also nichts vorgestreckt werden. Die Finanzierung durch den Bund ist nach Angaben der ÖGK vorerst bis 2028 gesichert.

## So kommen Sie zu einem Platz

Die Anmeldung erfolgt über eine zentrale Servicestelle des Berufsverbands. Diese vermittelt an qualifizierte klinische Psychologinnen und Psychologen in Wohnortnähe. Praktisch empfiehlt sich:

1. Mit der Hausärztin oder dem Hausarzt über die Beschwerden sprechen.
2. Bei der Servicestelle des BÖP oder bei der eigenen Krankenkasse über die Anmeldung informieren.
3. Unterlagen wie Befunde bereithalten.
4. Nach der Vermittlung einen Termin für das Erstgespräch vereinbaren.

Da die Zahl der Plätze begrenzt ist, kann es auch hier Wartezeiten geben. Bereits kurz nach dem Start gab es zahlreiche Anmeldungen.

## Unterschied zur Psychotherapie

Klinische Psychologinnen und Psychologen haben ein Psychologiestudium und eine zusätzliche postgraduelle Ausbildung absolviert. Sie sind auf Diagnostik spezialisiert und behandeln mit wissenschaftlich fundierten psychologischen Methoden, oft strukturiert und zeitlich überschaubar. Psychotherapeutinnen und Psychotherapeuten haben eine eigene Ausbildung in einer anerkannten Methode, die Behandlung kann je nach Ansatz auch länger dauern. Beide Berufsgruppen verschreiben keine Medikamente, das ist Ärztinnen und Ärzten vorbehalten.

Welche Form im Einzelfall passt, hängt von den Beschwerden und persönlichen Vorlieben ab. Oft ergänzen sich die Angebote.

## Wobei klinisch-psychologische Behandlung hilft

Typische Einsatzbereiche sind:

- Depressionen und Angststörungen
- Belastungsreaktionen nach schwierigen Lebensereignissen
- Schlafstörungen und Erschöpfungszustände
- psychische Begleiterscheinungen körperlicher Erkrankungen, etwa chronischer Schmerzen
- Probleme mit Konzentration und Gedächtnis

Wie viele Einheiten im Einzelfall bewilligt werden, hängt von der Diagnose und dem Behandlungsverlauf ab. Die Behandlung beginnt in der Regel mit einer genauen Abklärung, auf deren Basis gemeinsam Ziele festgelegt werden. Typische Elemente sind Gespräche, Übungen für den Alltag, Entspannungsverfahren und der Aufbau hilfreicher Gewohnheiten. Zwischen den Terminen werden oft kleine Aufgaben vereinbart, die das Gelernte festigen.

## Klinisch-psychologische Behandlung und andere Hilfen

Die neue Kassenleistung ersetzt nicht die akute Krisenhilfe. In seelischen Notlagen sind die Telefonseelsorge unter 142 sowie Rat auf Draht für junge Menschen unter 147 rund um die Uhr erreichbar. Bei akuter Gefahr gilt immer die Rettung unter 144. Für Kinder und Jugendliche gibt es zusätzlich das Programm „Gesund aus der Krise“, über das kostenlose psychologische und psychotherapeutische Unterstützung vermittelt wird.

Wer unsicher ist, welcher Weg der richtige ist, kann sich auch an psychosoziale Beratungsstellen im eigenen Bundesland wenden. Dort wird gemeinsam überlegt, welche Unterstützung am besten passt.','gesundheit','Psyche','oberoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/klinisch-psychologische-behandlung-kasse.webp',NULL,NULL,'published','2026-10-12T08:57:00.000Z','2026-10-22T00:17:07.886Z','Klinisch-psychologische Behandlung auf Kasse','Klinisch-psychologische Behandlung ist seit 2026 Kassenleistung. Wie Sie einen Platz bekommen, wie sie sich von Psychotherapie unterscheidet – hier lesen.','Klinisch-psychologische Behandlung','["Klinisch-psychologische Behandlung","Psychologe auf Kasse","Kassenleistung Psychologie","klinische Psychologin","klinisch-psychologische behandlung kasse anmeldung","psychologe oder psychotherapeut unterschied","böp servicestelle behandlung","psychologische behandlung kostenlos österreich"]','Klinisch-psychologische Behandlung: Behandlungsraum einer psychologischen Praxis in Linz','Photorealistic editorial photo of a modern psychology practice in Linz, a desk with a notepad and pen, two chairs, a large plant, view of the Danube through window on a misty morning, no text, no logos, no readable signs, no people','[{"q":"Ist klinisch-psychologische Behandlung jetzt gratis?","a":"Ja, seit 2026 gibt es kostenfreie Behandlungsplätze auf Kassenkosten, vermittelt über eine Servicestelle des Berufsverbands."},{"q":"Was ist der Unterschied zwischen Psychologe und Psychotherapeut?","a":"Klinische Psychologen haben ein Psychologiestudium mit Zusatzausbildung, Psychotherapeuten eine eigene Ausbildung in einer anerkannten Methode. Medikamente verschreiben beide nicht."},{"q":"Wie viele Behandlungseinheiten gibt es?","a":"Laut ÖGK rund 120.700 Einheiten pro Jahr, verteilt nach Bevölkerungszahl."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('psychische-krise-hilfe-anlaufstellen','Psychische Krise: Wo es in Österreich sofort Hilfe gibt','In einer seelischen Krise zählt schnelle Hilfe. Welche Nummern und Stellen in Österreich rund um die Uhr erreichbar sind und wie Angehörige unterstützen können.','Eine psychische Krise kann jeden treffen: nach einem Verlust, bei Überforderung im Beruf, in einer Trennung, bei Schulden oder ohne erkennbaren Anlass. Wichtig ist zu wissen, dass es in Österreich rund um die Uhr Hilfe gibt, kostenlos und auf Wunsch anonym. Niemand muss eine solche Situation allein durchstehen.

## Psychische Krise: Diese Nummern helfen sofort

- Telefonseelsorge: 142, rund um die Uhr, kostenlos, anonym; zusätzlich gibt es Online-Beratung per Chat und Mail
- Rat auf Draht für Kinder, Jugendliche und Bezugspersonen: 147, rund um die Uhr, kostenlos, anonym
- Gesundheitshotline: 1450 für die Einschätzung, welche medizinische Hilfe nötig ist
- Rettung: 144 bei akuter Gefahr für das eigene Leben oder das anderer
- Polizei: 133 in akuten Gefahrensituationen

Zusätzlich gibt es in den Bundesländern Kriseninterventionszentren und psychosoziale Notdienste. In Wien etwa bieten das Kriseninterventionszentrum und der Psychosoziale Notdienst Unterstützung, in anderen Ländern übernehmen ähnliche Einrichtungen diese Aufgabe. Die Kontaktdaten finden sich auf den Gesundheitsseiten der Länder.

## Warnzeichen erkennen

Anzeichen für eine ernste Krise können sein:

- anhaltende Hoffnungslosigkeit oder das Gefühl, dass nichts mehr Sinn hat
- starker sozialer Rückzug
- Schlaflosigkeit über längere Zeit
- Verlust des Interesses an allem, was früher wichtig war
- vermehrter Konsum von Alkohol oder anderen Substanzen
- Äußerungen, nicht mehr leben zu wollen

Wer solche Gedanken bei sich selbst bemerkt, sollte sofort mit jemandem sprechen, etwa mit der Telefonseelsorge unter 142. Gedanken an den Tod sind in schweren Krisen nicht ungewöhnlich, und sie sind ein klares Signal, Hilfe anzunehmen.

## Angehörigen in einer psychischen Krise beistehen

Wer sich um einen Menschen sorgt, kann viel bewirken:

1. Das Gespräch suchen, ruhig nachfragen und zuhören, ohne zu bewerten.
2. Sorgen offen ansprechen. Das direkte Nachfragen nach Suizidgedanken erhöht das Risiko nicht, sondern kann entlasten.
3. Gemeinsam nach Hilfe suchen, etwa einen Termin bei der Hausärztin vereinbaren oder gemeinsam bei einer Krisenstelle anrufen.
4. Bei akuter Gefahr die Person nicht allein lassen und die Rettung unter 144 rufen.
5. Auch auf sich selbst achten: Angehörige können sich ebenfalls an die Telefonseelsorge oder Beratungsstellen wenden.

## Nach der akuten Krise

Ist die akute Situation überstanden, ist eine weitere Begleitung wichtig. Möglichkeiten sind Gespräche bei der Hausärztin oder dem Hausarzt, fachärztliche Behandlung in der Psychiatrie, klinisch-psychologische Behandlung, die seit 2026 auf Kassenkosten möglich ist, sowie Psychotherapie. Psychosoziale Beratungsstellen helfen bei der Suche nach dem passenden Angebot.

Hilfreich ist es außerdem, sich vorab einen persönlichen Krisenplan zu überlegen, am besten gemeinsam mit einer Ärztin, einem Therapeuten oder einer Vertrauensperson. Darin steht, welche Warnzeichen man bei sich kennt, was in schwierigen Momenten guttut, wen man anrufen kann und welche Notrufnummern gelten. Ein solcher Plan auf einem Zettel oder im Handy kann in einer akuten Situation Orientierung geben.

## Psychische Krise: kein Zeichen von Schwäche

Viele Menschen zögern, Hilfe zu suchen, weil sie sich schämen oder glauben, sie müssten allein zurechtkommen. Fachleute betonen, dass seelische Krisen behandelbar sind und dass es Stärke zeigt, Unterstützung anzunehmen. Die Telefonseelsorge ist unter 142 jederzeit erreichbar, auch nachts und an Feiertagen.','gesundheit','Psyche',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/psychische-krise-hilfe-anlaufstellen.webp',NULL,NULL,'published','2026-10-10T06:03:00.000Z','2026-10-22T00:17:07.886Z','Psychische Krise: Sofort-Hilfe in Österreich','Psychische Krise: Welche Notrufe und Anlaufstellen in Österreich rund um die Uhr helfen und wie Sie Angehörige unterstützen können. Hier im Überblick.','Psychische Krise','["Psychische Krise","Telefonseelsorge 142","Krisenintervention","Rat auf Draht 147","psychische krise hilfe österreich sofort","krisenintervention wien kontakt","angehörige in der krise unterstützen","psychosozialer notdienst"]','Psychische Krise: zwei Teetassen am Balkon als Symbol für ein unterstützendes Gespräch','Photorealistic editorial photo of two cups of tea on a small balcony table at dawn, a blanket over a chair, view over rooftops of an Austrian town, hopeful soft sunrise light, no text, no logos, no readable signs, no people','[{"q":"Wen kann ich in einer psychischen Krise sofort anrufen?","a":"Die Telefonseelsorge unter 142, rund um die Uhr, kostenlos und anonym. Junge Menschen erreichen Rat auf Draht unter 147."},{"q":"Wann muss ich die Rettung rufen?","a":"Bei akuter Gefahr für das eigene Leben oder das anderer sofort 144 wählen."},{"q":"Wie kann ich einem Angehörigen in der Krise helfen?","a":"Zuhören, Sorgen offen ansprechen, gemeinsam Hilfe suchen und bei akuter Gefahr die Person nicht allein lassen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('ernaehrungsempfehlungen-oesterreich-ueberblick','Ernährungsempfehlungen Österreich: So isst man ausgewogen','Mehr Pflanzliches, Vollkorn und Wasser, weniger Zucker, Salz und Wurst: Die österreichischen Ernährungsempfehlungen im Überblick und wie man sie im Alltag umsetzt.','Die Ernährungsempfehlungen Österreich werden von Gesundheitsministerium und AGES herausgegeben und geben Orientierung, wie eine ausgewogene Ernährung im Alltag aussehen kann. Sie beruhen auf dem aktuellen wissenschaftlichen Stand und berücksichtigen zunehmend auch Fragen der Nachhaltigkeit. Im Kern geht es nicht um Verbote, sondern um ein gutes Verhältnis der Lebensmittelgruppen.

## Ernährungsempfehlungen Österreich: die Grundprinzipien

Zusammengefasst gilt:

- reichlich Gemüse, Hülsenfrüchte und Obst
- Getreideprodukte bevorzugt als Vollkorn
- täglich Milch und Milchprodukte in moderaten Mengen
- Fisch ein- bis zweimal pro Woche
- Fleisch und Wurst in kleinen Mengen und nicht täglich
- hochwertige pflanzliche Öle statt viel tierischem Fett
- sparsam mit Zucker, Salz und stark verarbeiteten Produkten
- als Getränk vor allem Wasser und ungesüßte Tees

Die Empfehlungen sind bewusst pflanzenbetont. Eine abwechslungsreiche Ernährung mit viel Gemüse, Obst und Vollkorn liefert Ballaststoffe, Vitamine und Mineralstoffe und wird mit einem geringeren Risiko für zahlreiche Erkrankungen in Verbindung gebracht.

## Obst und Gemüse: bunt und regelmäßig

Als Faustregel gelten mehrere Portionen Gemüse und Obst pro Tag, wobei Gemüse überwiegen sollte. Eine Portion entspricht ungefähr einer Handvoll. Saisonale und regionale Produkte sind oft günstiger und geschmackvoll: Im Herbst etwa Kürbis, Kraut, Rote Rüben, Äpfel und Birnen. Auch tiefgekühltes Gemüse ohne Zusätze ist eine gute Wahl.

## Vollkorn und Hülsenfrüchte

Vollkornbrot, Haferflocken, Naturreis oder Vollkornnudeln sättigen länger als Weißmehlprodukte. Hülsenfrüchte wie Linsen, Bohnen oder Kichererbsen liefern pflanzliches Eiweiß und Ballaststoffe. Sie können Fleisch in vielen Gerichten teilweise ersetzen, etwa im Chili, im Eintopf oder als Aufstrich.

## Ernährungsempfehlungen im Alltag umsetzen

Praktische Tipps:

1. Beim Einkauf eine Liste schreiben und mit Gemüse beginnen.
2. Den Teller zur Hälfte mit Gemüse oder Salat füllen.
3. Wasserkaraffe sichtbar auf den Tisch stellen.
4. Fertigprodukte gezielt auswählen und auf Zucker- und Salzgehalt achten.
5. Öfter selbst kochen, auch einfache Gerichte zählen.
6. Einmal pro Woche fleischlos kochen und Neues ausprobieren.

Ein Schnitzel am Sonntag oder ein Stück Kuchen beim Familienfest passen ebenfalls in eine ausgewogene Ernährung. Entscheidend ist, was man überwiegend isst. Auch Bewegung gehört dazu: Die österreichischen Bewegungsempfehlungen raten Erwachsenen zu regelmäßiger körperlicher Aktivität über die Woche verteilt.

Auch beim Essen außer Haus lassen sich die Empfehlungen umsetzen: In vielen Kantinen und Gasthäusern gibt es Salatbuffets und vegetarische Tagesgerichte. Statt Pommes kann man oft Erdäpfel oder Gemüse als Beilage wählen. Wer mittags deftig isst, kann am Abend leichter essen.

## Besondere Situationen

In Schwangerschaft und Stillzeit, für Kinder, ältere Menschen, Sportlerinnen oder Menschen mit Erkrankungen wie Diabetes, Nierenerkrankungen oder Nahrungsmittelunverträglichkeiten können besondere Empfehlungen gelten. Hier sollte die Ernährung mit der Ärztin, dem Arzt oder einer Diätologin abgestimmt werden. Diätologinnen arbeiten in Spitälern, in Primärversorgungseinheiten und in eigenen Praxen. Von Nahrungsergänzungsmitteln ohne ärztliche Abklärung raten Fachleute in der Regel ab, da eine ausgewogene Ernährung den Bedarf der meisten gesunden Menschen deckt.','gesundheit','Ernährung',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/ernaehrungsempfehlungen-oesterreich-ueberblick.webp',NULL,NULL,'published','2026-09-22T10:48:00.000Z','2026-10-22T00:17:07.886Z','Ernährungsempfehlungen Österreich im Überblick','Ernährungsempfehlungen Österreich: Was die offiziellen Empfehlungen zu Obst, Gemüse, Vollkorn, Fleisch und Getränken sagen und wie Sie sie umsetzen.','Ernährungsempfehlungen Österreich','["Ernährungsempfehlungen Österreich","ausgewogene Ernährung","Ernährungspyramide","AGES Ernährung","ernährungsempfehlungen österreich ages neu","gesund essen alltag tipps","pflanzenbetonte ernährung empfehlung","wie viel obst und gemüse am tag"]','Ernährungsempfehlungen Österreich: Gemüse, Obst, Vollkornbrot und Hülsenfrüchte auf einem Markttisch','Photorealistic editorial overhead photo of a rustic wooden table at an Austrian farmers market stall with autumn vegetables, pumpkins, red beets, apples, whole grain bread and lentils in bowls, soft morning light, no text, no logos, no readable signs, no people','[{"q":"Wie viel Obst und Gemüse soll man pro Tag essen?","a":"Mehrere Portionen täglich, wobei Gemüse überwiegen sollte. Eine Portion entspricht etwa einer Handvoll."},{"q":"Wie oft darf man laut Empfehlung Fleisch essen?","a":"Die Empfehlungen raten zu kleinen Mengen Fleisch und Wurst und nicht täglich. Fisch ein- bis zweimal pro Woche."},{"q":"Wer gibt die Ernährungsempfehlungen in Österreich heraus?","a":"Das Gesundheitsministerium gemeinsam mit der AGES."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('salz-reduzieren-tipps-alltag','Salz reduzieren: Tipps für weniger Salz im Alltag','Die meisten Menschen essen deutlich mehr Salz als empfohlen. Ein großer Teil steckt in Brot, Wurst, Käse und Fertigprodukten. So gelingt es, Salz zu reduzieren.','Salz reduzieren ist eine der einfachsten Möglichkeiten, die eigene Ernährung zu verbessern. Die Weltgesundheitsorganisation empfiehlt Erwachsenen, nicht mehr als fünf Gramm Salz pro Tag zu sich zu nehmen, das entspricht etwa einem Teelöffel. Tatsächlich liegt der durchschnittliche Konsum in Österreich wie in vielen europäischen Ländern deutlich darüber. Ein hoher Salzkonsum wird mit erhöhtem Blutdruck in Verbindung gebracht, der wiederum ein Risikofaktor für Herz-Kreislauf-Erkrankungen ist.

## Wo verstecktes Salz steckt

Der größte Teil des Salzes kommt nicht aus dem Salzstreuer, sondern aus verarbeiteten Lebensmitteln. Besonders salzreich sind häufig:

- Brot und Gebäck, weil sie täglich und in größeren Mengen gegessen werden
- Wurst, Schinken und Speck
- Käse, vor allem Hartkäse und Schmelzkäse
- Fertiggerichte, Tiefkühlpizza und Instantsuppen
- Knabbergebäck, Chips und gesalzene Nüsse
- Saucen, Suppenwürze und Würzmischungen

Die Nährwerttabelle auf der Verpackung zeigt den Salzgehalt pro 100 Gramm. Ein Vergleich ähnlicher Produkte lohnt sich, die Unterschiede können groß sein.

## Salz reduzieren beim Kochen

1. Erst am Ende abschmecken, nicht schon zu Beginn großzügig salzen.
2. Mit frischen oder getrockneten Kräutern würzen, etwa Petersilie, Schnittlauch, Liebstöckel, Majoran oder Thymian.
3. Gewürze wie Pfeffer, Paprika, Kümmel, Muskat oder Knoblauch einsetzen.
4. Säure nutzen: Ein Spritzer Zitrone oder Essig hebt den Geschmack.
5. Suppenwürfel und Würzpasten sparsam verwenden oder selbst Gemüsefond kochen.
6. Den Salzstreuer vom Esstisch nehmen.

Der Geschmackssinn passt sich an. Wer Salz schrittweise reduziert, empfindet nach einigen Wochen weniger gesalzene Speisen als normal und stark gesalzene als zu intensiv. Es hilft, nicht alles auf einmal umzustellen, sondern bei einzelnen Gerichten zu beginnen.

## Salz reduzieren beim Einkauf

- Frische, unverarbeitete Lebensmittel bevorzugen.
- Bei Brot, Wurst und Käse auf salzärmere Varianten achten.
- Statt Chips ungesalzene Nüsse oder Gemüsesticks wählen.
- Bei Konserven wie Bohnen oder Mais den Inhalt abspülen.

Auch beim Essen außer Haus lässt sich Salz sparen: Saucen und Dressings separat bestellen, bei Suppen und Eintöpfen vorsichtig nachwürzen und bei Jausenplatten nicht zu viel Wurst und Käse wählen. Wer regelmäßig in der Kantine isst, kann dort anregen, dass weniger gesalzen und mehr mit Kräutern gewürzt wird.

Wichtig ist auch die Wahl des Salzes: Jodiertes Speisesalz trägt in Österreich zur Versorgung mit Jod bei. Wenn man Salz verwendet, dann idealerweise jodiertes, aber eben in kleinen Mengen.

## Was die Lebensmittelbranche tut

In Österreich wird seit Jahren daran gearbeitet, den Salz-, Zucker- und Fettgehalt in verarbeiteten Lebensmitteln schrittweise zu senken, etwa über freiwillige Vereinbarungen mit der Branche und im Bäckereihandwerk. Fachleute fordern, diesen Weg weiterzugehen, weil Änderungen bei häufig gegessenen Produkten wie Brot viele Menschen gleichzeitig erreichen.

## Bei Bluthochdruck ärztlich beraten lassen

Wer erhöhten Blutdruck hat oder an Herz- oder Nierenerkrankungen leidet, sollte die Ernährung mit der Ärztin oder dem Arzt besprechen. Auch Diätologinnen können individuell beraten. Bei bestimmten Erkrankungen gelten eigene Empfehlungen, die nicht für alle passen. Den Blutdruck regelmäßig messen zu lassen, etwa im Rahmen der kostenlosen Vorsorgeuntersuchung, ist für Erwachsene sinnvoll.','gesundheit','Ernährung','salzburg','ratgeber','Presseinfo Redaktion','/assets/img/artikel/salz-reduzieren-tipps-alltag.webp',NULL,NULL,'published','2026-10-02T16:15:00.000Z','2026-10-22T00:17:07.886Z','Salz reduzieren: Tipps für weniger Salz im Alltag','Salz reduzieren im Alltag: Wo verstecktes Salz steckt, wie Sie beim Kochen und Einkaufen sparen und warum es sich lohnt. Praktische Tipps – jetzt lesen.','Salz reduzieren','["Salz reduzieren","weniger Salz","verstecktes Salz","Salzkonsum Österreich","salz reduzieren tipps kochen","wie viel salz pro tag who","salz in brot wurst käse","kräuter statt salz würzen"]','Salz reduzieren: frische Kräuter und Zitrone statt Salz auf einem Schneidbrett','Photorealistic editorial close-up of fresh herbs, a lemon and a small wooden bowl of coarse salt on a cutting board in a Salzburg farmhouse kitchen, a pot steaming in the blurred background, warm evening light, no text, no logos, no readable signs, no people','[{"q":"Wie viel Salz pro Tag ist empfohlen?","a":"Die WHO empfiehlt Erwachsenen höchstens fünf Gramm Salz pro Tag, etwa einen Teelöffel."},{"q":"Wo steckt das meiste Salz?","a":"In verarbeiteten Lebensmitteln wie Brot, Wurst, Käse, Fertiggerichten und Knabbergebäck."},{"q":"Wie gewöhne ich mich an weniger Salz?","a":"Schrittweise reduzieren und mit Kräutern, Gewürzen und Säure würzen. Der Geschmack passt sich nach einigen Wochen an."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('zucker-reduzieren-versteckter-zucker','Zucker reduzieren: Versteckten Zucker erkennen und meiden','Zucker steckt in vielen Produkten, in denen man ihn nicht erwartet. Wie man versteckten Zucker auf dem Etikett erkennt und den Konsum Schritt für Schritt senkt.','Zucker reduzieren ist für viele Menschen ein guter Vorsatz, doch im Alltag schwerer umzusetzen als gedacht. Ein großer Teil des Zuckers steckt nämlich nicht in Kuchen und Süßigkeiten, sondern in Getränken, Frühstücksflocken, Joghurts, Saucen und Fertigprodukten. Die Weltgesundheitsorganisation empfiehlt, den Anteil an freiem Zucker auf weniger als zehn Prozent der täglichen Energiezufuhr zu begrenzen, idealerweise auf unter fünf Prozent.

Als freier Zucker gilt jeder Zucker, der Lebensmitteln zugesetzt wird, sowie der natürlich vorkommende Zucker in Honig, Sirupen und Fruchtsäften. Nicht dazu zählt der Zucker in ganzen Früchten oder in Milch. Ein Apfel ist also anders zu bewerten als ein Glas Apfelsaft, weil das ganze Obst zusätzlich Ballaststoffe liefert und besser sättigt.

## Versteckter Zucker: die häufigsten Quellen

- gesüßte Getränke wie Limonaden, Eistee, Energydrinks und Fruchtsaftgetränke
- Fruchtjoghurts, Puddings und Milchmischgetränke
- Frühstücksflocken und Müslimischungen
- Ketchup, Salatdressings und Fertigsaucen
- Müsliriegel und vermeintlich gesunde Snacks
- Backwaren und Fertigdesserts

Gerade Getränke spielen eine große Rolle, weil sie kaum sättigen und schnell große Mengen Zucker liefern.

## Zucker auf dem Etikett erkennen

In der Nährwerttabelle findet sich die Angabe „davon Zucker“ pro 100 Gramm. Sie umfasst allerdings auch natürlich enthaltenen Zucker. Mehr verrät die Zutatenliste: Je weiter vorne Zucker steht, desto mehr ist enthalten. Zucker versteckt sich dort unter vielen Namen, etwa Glukose, Fruktose, Saccharose, Dextrose, Maltodextrin, Glukosesirup, Fruchtsüße, Invertzucker oder Gerstenmalzextrakt.

## Zucker reduzieren: Tipps für den Alltag

1. Durst mit Wasser, Mineralwasser oder ungesüßtem Tee löschen. Ein Spritzer Zitrone oder ein paar Minzblätter sorgen für Geschmack.
2. Naturjoghurt mit frischem Obst statt Fruchtjoghurt wählen.
3. Müsli aus Haferflocken, Nüssen und Obst selbst mischen.
4. Im Kaffee und Tee den Zucker schrittweise verringern.
5. Bei Rezepten für Kuchen den Zucker um ein Viertel reduzieren, das fällt oft kaum auf.
6. Süßes bewusst genießen, statt nebenbei zu naschen.

Hilfreich ist es, nicht auf alles gleichzeitig zu verzichten, sondern mit den größten Zuckerquellen zu beginnen. Für viele Menschen sind das die Getränke. Wer täglich ein bis zwei Gläser Limonade durch Wasser ersetzt, spart bereits eine beträchtliche Menge Zucker. Nach einigen Wochen empfinden viele stark gesüßte Produkte als zu süß, weil sich der Geschmack anpasst.

## Kinder und Zucker

Kinder gewöhnen sich früh an süßen Geschmack. Eltern können helfen, indem sie Wasser als Standardgetränk etablieren, Süßes nicht als Belohnung einsetzen und Obst als Snack anbieten. Eine Umfrage von SIPCAN unter Volksschulen zeigte Anfang 2026, dass zwar an allen Schulen Leitungswasser verfügbar ist, ein Drittel aber zusätzlich gesüßten Sirup oder verdünntes Saftkonzentrat ausgibt.

## Wann ärztlicher Rat wichtig ist

Menschen mit Diabetes, Übergewicht oder anderen Stoffwechselerkrankungen sollten ihre Ernährung mit der Ärztin oder dem Arzt bzw. einer Diätologin abstimmen. Süßstoffe und Zuckerersatzstoffe sind kein Freibrief und sollten ebenfalls maßvoll eingesetzt werden. Die kostenlose Vorsorgeuntersuchung bietet eine gute Gelegenheit, Blutzucker und andere Werte überprüfen zu lassen.','gesundheit','Ernährung','steiermark','ratgeber','Presseinfo Redaktion','/assets/img/artikel/zucker-reduzieren-versteckter-zucker.webp',NULL,NULL,'published','2026-10-07T14:39:00.000Z','2026-10-22T00:17:07.887Z','Zucker reduzieren: versteckten Zucker erkennen','Zucker reduzieren: Wo versteckter Zucker steckt, wie Sie ihn auf dem Etikett erkennen und welche Alternativen im Alltag helfen. Praktische Tipps – lesen.','Zucker reduzieren','["Zucker reduzieren","versteckter Zucker","Zucker Etikett","Softdrinks Zucker","zucker reduzieren tipps alltag","wie viel zucker pro tag empfehlung","zucker andere namen zutatenliste","zuckerfrei frühstück kinder"]','Zucker reduzieren: Wasser mit Minze neben Saft und Würfelzucker auf der Küchenablage','Photorealistic editorial still life of several glasses on a kitchen counter in a Graz apartment: one with tap water and mint, one with cloudy apple juice, sugar cubes scattered beside, natural afternoon window light, no text, no logos, no readable signs, no people','[{"q":"Wie viel Zucker pro Tag ist empfohlen?","a":"Die WHO empfiehlt, freien Zucker auf weniger als zehn Prozent der täglichen Energiezufuhr zu begrenzen, idealerweise unter fünf Prozent."},{"q":"Wie erkenne ich versteckten Zucker?","a":"In der Zutatenliste unter Namen wie Glukosesirup, Dextrose, Maltodextrin oder Fruchtsüße. Je weiter vorne, desto mehr ist enthalten."},{"q":"Ist Obst wegen des Zuckers ungesund?","a":"Nein. Der Zucker in ganzen Früchten zählt nicht als freier Zucker, Obst liefert zudem Ballaststoffe und Vitamine."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('ernaehrung-im-alter-tipps','Ernährung im Alter: Worauf es ab 65 ankommt','Mit dem Alter verändern sich Appetit, Durstgefühl und Bedarf. Warum Mangelernährung oft unbemerkt bleibt und wie eine ausgewogene Ernährung im Alter gelingt.','Die Ernährung im Alter verdient besondere Aufmerksamkeit, denn mit den Jahren verändern sich Körper und Bedürfnisse. Der Energiebedarf sinkt oft, weil man sich weniger bewegt, der Bedarf an Nährstoffen wie Eiweiß, Vitaminen und Mineralstoffen bleibt aber gleich oder steigt sogar. Gleichzeitig lassen Appetit und Durstgefühl häufig nach. Das kann dazu führen, dass ältere Menschen zu wenig essen und trinken, ohne es selbst zu bemerken.

## Mangelernährung im Alter erkennen

Mangelernährung ist bei älteren Menschen, besonders bei Pflegebedürftigen, keine Seltenheit. Warnzeichen sind:

- ungewollter Gewichtsverlust, etwa wenn Kleidung plötzlich weiter wird
- nachlassende Kraft und Schwierigkeiten beim Aufstehen oder Gehen
- Müdigkeit und Antriebslosigkeit
- häufige Infekte oder schlecht heilende Wunden
- Probleme beim Kauen oder Schlucken

Wer solche Anzeichen bemerkt, sollte mit der Hausärztin oder dem Hausarzt sprechen. Ursachen können Zahnprobleme, Erkrankungen, Medikamente, Einsamkeit oder Depressionen sein.

## Ernährung im Alter: die wichtigsten Bausteine

Eiweiß ist im Alter besonders wichtig, um Muskelmasse und Kraft zu erhalten. Gute Quellen sind Milchprodukte wie Topfen und Joghurt, Eier, Fisch, mageres Fleisch, Hülsenfrüchte und Vollkornprodukte. Ideal ist es, eiweißreiche Lebensmittel über den Tag zu verteilen.

Auch Gemüse, Obst und Vollkorn sind wichtig: Sie liefern Ballaststoffe, die der Verdauung guttun, sowie Vitamine und Mineralstoffe. Bei Kauproblemen helfen weich gekochtes Gemüse, Suppen, Aufläufe oder Smoothies.

## Genug trinken

Das Durstgefühl lässt im Alter oft nach. Zu wenig Flüssigkeit kann zu Verwirrtheit, Schwindel, Verstopfung oder Kreislaufproblemen führen. Hilfreich sind:

1. Getränke sichtbar bereitstellen, etwa eine Karaffe Wasser auf dem Tisch.
2. Feste Trinkzeiten einplanen, zum Beispiel zu jeder Mahlzeit und am Nachmittag.
3. Abwechslung bieten: Wasser, Kräutertee, verdünnte Säfte, Suppen.
4. Bei Bedarf ein Trinkprotokoll führen.

Bei Herz- oder Nierenerkrankungen kann eine bestimmte Trinkmenge ärztlich vorgegeben sein. Diese Vorgaben haben Vorrang.

Bei Menschen mit Demenz kann das Essen zusätzlich erschwert sein, weil sie vergessen zu essen oder Besteck nicht mehr sicher verwenden. Fingerfood, also mundgerechte Stücke, die man mit der Hand essen kann, sowie kräftige Farben am Teller können helfen. Wichtig ist, Mahlzeiten in Ruhe und ohne Zeitdruck anzubieten.

## Gemeinsam essen statt allein

Essen ist auch ein soziales Erlebnis. Wer allein lebt, kocht oft nicht mehr für sich selbst. Gemeinsame Mahlzeiten mit Familie, Nachbarn oder in Seniorentreffs fördern den Appetit. Für Menschen, die nicht mehr selbst kochen können, bieten Hilfsorganisationen und Gemeinden in vielen Regionen Essen auf Rädern an, in Niederösterreich ebenso wie in den anderen Bundesländern.

## Ernährung im Alter: Unterstützung holen

Bei Gewichtsverlust, Schluckbeschwerden oder chronischen Erkrankungen ist ärztlicher Rat wichtig. Diätologinnen können einen individuellen Ernährungsplan erstellen. Nahrungsergänzungsmittel oder spezielle Trinknahrung sollten nur nach ärztlicher Abklärung eingesetzt werden. Regelmäßige Zahnkontrollen und gut sitzende Prothesen tragen ebenfalls dazu bei, dass Essen wieder Freude macht. Bewegung, etwa tägliche Spaziergänge oder Seniorenturnen, unterstützt den Appetit und den Erhalt der Muskelkraft.','gesundheit','Ernährung','niederoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/ernaehrung-im-alter-tipps.webp',NULL,NULL,'published','2026-10-16T09:58:00.000Z','2026-10-22T00:17:07.887Z','Ernährung im Alter: Worauf es ab 65 ankommt','Ernährung im Alter: Warum Eiweiß, Flüssigkeit und Appetit ab 65 wichtiger werden und wie Angehörige unterstützen können. Praktische Tipps – jetzt lesen.','Ernährung im Alter','["Ernährung im Alter","Mangelernährung Senioren","Trinken im Alter","Eiweiß Senioren","ernährung im alter tipps angehörige","mangelernährung erkennen ältere menschen","zu wenig trinken senioren folgen","essen auf rädern niederösterreich"]','Ernährung im Alter: gedeckter Mittagstisch mit Gemüsesuppe und Wasser in Niederösterreich','Photorealistic editorial photo of a set lunch table for two in a Lower Austrian village kitchen, bowls of vegetable soup, whole grain bread, a jug of water, checkered tablecloth, wine hills visible through window, warm midday light, no text, no logos, no readable signs, no people','[{"q":"Warum ist Eiweiß im Alter so wichtig?","a":"Es hilft, Muskelmasse und Kraft zu erhalten. Gute Quellen sind Milchprodukte, Eier, Fisch, Hülsenfrüchte und mageres Fleisch."},{"q":"Woran erkenne ich Mangelernährung bei älteren Menschen?","a":"An ungewolltem Gewichtsverlust, Kraftverlust, Müdigkeit, häufigen Infekten oder Problemen beim Kauen. Dann ärztlich abklären lassen."},{"q":"Wie viel sollen ältere Menschen trinken?","a":"Regelmäßig über den Tag verteilt. Bei Herz- oder Nierenerkrankungen gilt die ärztlich vorgegebene Trinkmenge."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('gesunde-jause-kinder-schule','Gesunde Jause für Kinder: Ideen für Schule und Kindergarten','Die Jause gibt Kindern Energie für den Schultag. Mit einfachen Zutaten gelingt eine gesunde Jause, die schmeckt und lange satt hält – Ideen für die Jausenbox.','Eine gesunde Jause liefert Kindern Energie für den Vormittag in Schule oder Kindergarten und hilft, konzentriert zu bleiben. Sie muss weder kompliziert noch teuer sein. Wichtig ist eine gute Mischung aus Vollkorn, Gemüse oder Obst und einer Eiweißquelle, dazu ein ungesüßtes Getränk.

## Was in eine gesunde Jause gehört

Eine ausgewogene Jausenbox besteht idealerweise aus:

- einem Getreideprodukt, bevorzugt Vollkorn: Vollkornbrot, Weckerl, Knäckebrot oder Haferflocken
- Gemüse oder Obst: Karotten- oder Gurkensticks, Paprikastreifen, Cocktailtomaten, Apfelspalten, Weintrauben
- einer Eiweißquelle: Käse, Topfenaufstrich, Ei, Hummus oder Joghurt
- einem Getränk: Leitungswasser oder ungesüßter Tee

Obst und Gemüse in mundgerechten Stücken werden eher gegessen als ganze Früchte. Auch die Optik zählt: Bunte Boxen mit kleinen Fächern machen Lust aufs Essen.

## Ideen für die gesunde Jause

1. Vollkornbrot mit Kräutertopfen und Gurkenscheiben
2. Weckerl mit Käse, Salatblatt und Paprika
3. Linsen- oder Kichererbsenaufstrich mit Karottensticks
4. Naturjoghurt mit Haferflocken und Beeren in einem dichten Becher
5. Vollkorn-Wrap mit Frischkäse und Gemüsestreifen
6. Hartgekochtes Ei, Cocktailtomaten und ein Stück Brot

Wer am Abend etwas mehr Gemüse schneidet, hat am Morgen schon die Basis für die Box.

## Getränke: Wasser zuerst

Das beste Getränk für Kinder ist Leitungswasser, das in Österreich fast überall in hervorragender Qualität verfügbar ist. Gesüßte Getränke, Fruchtsaftgetränke oder Sirup liefern viel Zucker und sollten die Ausnahme bleiben. Eine Umfrage der Initiative SIPCAN unter Volksschulen ergab Anfang 2026, dass zwar alle Schulen Leitungswasser anbieten, ein Drittel aber zusätzlich gesüßten Sirup oder verdünntes Saftkonzentrat ausschenkt.

## Gesunde Jause und Mittagessen in der Schule

Immer mehr Kinder essen in der Schule oder im Hort zu Mittag. Laut der SIPCAN-Umfrage bieten 81 Prozent der befragten Volksschulen mit eigenem Mittagstisch täglich ein Mittagessen an, meist geliefert von externen Caterern. Viele Schulen setzen auf vegetarische, regionale und saisonale Gerichte. Nur ein Teil der Schulen konnte allerdings eine Zertifizierung für kindgerechtes Essen bestätigen. Eltern können beim Elternverein oder der Schulleitung nachfragen, wie die Verpflegung organisiert ist.

Ein Stück Kuchen beim Geburtstag oder ein Keks gehören zum Kinderalltag. In der täglichen Jause haben Schokoriegel, Milchschnitten oder süße Teilchen aber besser keinen Stammplatz. Kinder, die von klein auf an weniger süße Speisen gewöhnt sind, empfinden diese als normal.

Auch das Frühstück spielt eine Rolle. Kinder, die zu Hause schon etwas gegessen haben, kommen leichter durch den Vormittag. Wer morgens keinen Appetit hat, kann mit einem Glas Milch, einem Joghurt oder etwas Obst starten und die Jause in der Pause etwas größer gestalten.

Praktisch ist außerdem eine wiederverwendbare Jausenbox und Trinkflasche. Das spart Verpackung und hält die Lebensmittel frisch. Brot, das nicht durchweichen soll, bleibt mit einem Salatblatt zwischen Aufstrich und Belag knackig.

## Kinder einbeziehen

Kinder essen lieber, was sie mit ausgesucht oder zubereitet haben. Gemeinsames Einkaufen, das Schneiden von Gemüse oder das Bestreichen des Brots am Vorabend machen die Jause zum eigenen Projekt. Bei Nahrungsmittelallergien, Unverträglichkeiten oder auffälligem Essverhalten beraten Kinderärztin oder Kinderarzt sowie Diätologinnen.','gesundheit','Ernährung','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/gesunde-jause-kinder-schule.webp',NULL,NULL,'published','2026-09-28T05:12:00.000Z','2026-10-22T00:17:07.887Z','Gesunde Jause für Kinder: Ideen für die Schule','Gesunde Jause für Kinder: Einfache Ideen für Schule und Kindergarten, was in die Jausenbox gehört und welche Getränke sich eignen. Praktische Tipps.','Gesunde Jause','["Gesunde Jause","Jause Schule","Jausenbox Kinder","Schulessen","gesunde jause kinder schule ideen","jausenbox volksschule tipps","getränke für kinder wasser","schulessen österreich qualität"]','Gesunde Jause: Jausenbox mit Vollkornbrot, Gemüsesticks und Apfel auf einem Schultisch','Photorealistic editorial overhead photo of an open children''s lunchbox with whole grain bread sandwich, carrot and cucumber sticks, apple slices and cherry tomatoes, a reusable water bottle beside it on a school desk in a Vienna classroom, morning light, no text, no logos, no readable signs, no people','[{"q":"Was gehört in eine gesunde Jause?","a":"Ein Vollkornprodukt, Gemüse oder Obst, eine Eiweißquelle wie Käse oder Topfen und Wasser oder ungesüßter Tee."},{"q":"Was ist das beste Getränk für Kinder in der Schule?","a":"Leitungswasser. Gesüßte Getränke und Sirup sollten die Ausnahme bleiben."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('ballaststoffe-vollkorn-huelsenfruechte','Ballaststoffe: Warum Vollkorn und Hülsenfrüchte wichtig sind','Die meisten Menschen essen zu wenig Ballaststoffe. Dabei sättigen sie lange und tun der Verdauung gut. Wie Vollkorn, Gemüse und Hülsenfrüchte mehr Platz am Teller bekommen.','Ballaststoffe sind Bestandteile pflanzlicher Lebensmittel, die der Körper nicht vollständig verdauen kann. Gerade deshalb sind sie wertvoll: Sie sorgen für ein längeres Sättigungsgefühl, unterstützen eine regelmäßige Verdauung und dienen den Darmbakterien als Nahrung. Fachgesellschaften empfehlen Erwachsenen mindestens 30 Gramm Ballaststoffe pro Tag. Erhebungen zeigen, dass viele Menschen in Österreich und Deutschland deutlich darunter liegen.

## Wo viele Ballaststoffe stecken

Besonders ballaststoffreich sind:

- Vollkornprodukte wie Vollkornbrot, Haferflocken, Vollkornnudeln und Naturreis
- Hülsenfrüchte wie Linsen, Bohnen, Erbsen und Kichererbsen
- Gemüse, etwa Kohlsorten, Karotten, Fenchel, Pastinaken oder Brokkoli
- Obst, vor allem mit Schale, sowie Beeren
- Nüsse und Samen wie Leinsamen, Chiasamen oder Walnüsse

Weißmehlprodukte, Fleisch, Fisch und Milchprodukte enthalten dagegen kaum oder keine Ballaststoffe.

Nicht jedes dunkle Brot ist ein Vollkornbrot. Manche Gebäcke werden mit Malz oder Zuckerkulör gefärbt. Ein Blick auf die Zutatenliste hilft: Vollkornmehl oder Vollkornschrot sollte an erster Stelle stehen. Auch die Bezeichnung „Vollkorn“ ist geregelt und gibt Orientierung. Beim Bäcker kann man gezielt nachfragen.

## Mehr Ballaststoffe im Alltag

1. Zum Frühstück Haferflocken mit Obst und Nüssen statt Weißgebäck.
2. Beim Brot schrittweise auf Vollkorn umsteigen.
3. Nudeln und Reis teilweise oder ganz durch Vollkornvarianten ersetzen.
4. Einmal pro Woche ein Gericht mit Hülsenfrüchten einplanen, etwa Linseneintopf, Bohnensalat oder Chili.
5. Zu jeder Hauptmahlzeit eine Portion Gemüse oder Salat.
6. Als Snack Obst, Gemüsesticks oder eine Handvoll Nüsse.

## Langsam steigern und viel trinken

Wer bisher wenig Ballaststoffe gegessen hat, sollte die Menge schrittweise erhöhen. Ein plötzlicher Umstieg kann zu Blähungen oder Völlegefühl führen. Der Darm gewöhnt sich aber an die Umstellung. Wichtig ist, ausreichend zu trinken, damit die Ballaststoffe gut aufquellen können. Bei Hülsenfrüchten helfen gründliches Einweichen und Kochen sowie Gewürze wie Kümmel, Fenchel oder Bohnenkraut, sie bekömmlicher zu machen.

## Hülsenfrüchte: günstig und vielseitig

Hülsenfrüchte sind nicht nur ballaststoffreich, sondern auch eine gute Quelle für pflanzliches Eiweiß. Getrocknet sind sie lange haltbar und günstig, aus der Dose oder dem Glas schnell verfügbar. In Österreich werden zunehmend auch heimische Linsen, Kichererbsen und Bohnen angebaut, etwa im Weinviertel oder im Burgenland. Klassiker der österreichischen Küche wie das Linsengericht oder der Bohnensalat mit Kürbiskernöl zeigen, wie gut sie in die regionale Küche passen.

Ein einfacher Rechenweg zeigt, wie man auf die empfohlene Menge kommt: Einige Scheiben Vollkornbrot, eine Portion Haferflocken am Morgen, zwei bis drei Portionen Gemüse und Obst sowie ein Gericht mit Hülsenfrüchten tragen zusammen bereits einen großen Teil bei. Es geht also nicht um besondere Produkte, sondern um eine kluge Auswahl alltäglicher Lebensmittel.

## Ballaststoffe bei Erkrankungen

Bei bestimmten Erkrankungen des Darms, etwa entzündlichen Darmerkrankungen, oder nach Operationen können andere Empfehlungen gelten. Wer anhaltende Verdauungsbeschwerden, Blut im Stuhl oder ungewollten Gewichtsverlust bemerkt, sollte das ärztlich abklären lassen. Die Darmkrebsvorsorge ist ab einem bestimmten Alter Teil der empfohlenen Vorsorgeuntersuchungen. Individuelle Ernährungsberatung bieten Diätologinnen.','gesundheit','Ernährung','burgenland','ratgeber','Presseinfo Redaktion','/assets/img/artikel/ballaststoffe-vollkorn-huelsenfruechte.webp',NULL,NULL,'published','2026-10-18T07:26:00.000Z','2026-10-22T00:17:07.887Z','Ballaststoffe: Vollkorn und Hülsenfrüchte im Alltag','Ballaststoffe im Alltag: Warum sie wichtig sind, welche Lebensmittel viel davon liefern und wie Sie mehr Vollkorn und Hülsenfrüchte essen. Tipps – lesen.','Ballaststoffe','["Ballaststoffe","Vollkorn","Hülsenfrüchte","ballaststoffreiche Ernährung","ballaststoffe lebensmittel liste","wie viel ballaststoffe am tag","hülsenfrüchte rezepte einfach","vollkornbrot erkennen"]','Ballaststoffe: Gläser mit Linsen, Kichererbsen und Haferflocken neben Vollkornbrot','Photorealistic editorial photo of glass jars filled with lentils, chickpeas, white beans and oats on a wooden shelf in a Burgenland country pantry, a loaf of whole grain bread in front, soft side light, no text, no logos, no readable signs, no people','[{"q":"Wie viel Ballaststoffe soll man pro Tag essen?","a":"Fachgesellschaften empfehlen Erwachsenen mindestens 30 Gramm pro Tag."},{"q":"Welche Lebensmittel haben viele Ballaststoffe?","a":"Vollkornprodukte, Hülsenfrüchte, Gemüse, Obst mit Schale sowie Nüsse und Samen."},{"q":"Warum bekomme ich von Ballaststoffen Blähungen?","a":"Meist wurde die Menge zu schnell erhöht. Schrittweise steigern und ausreichend trinken hilft dem Darm, sich anzupassen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('wasser-trinken-wie-viel-pro-tag','Wasser trinken: Wie viel pro Tag sinnvoll ist','Wasser ist das wichtigste Getränk. Wie viel man täglich trinken sollte, welche Getränke zählen und woran man erkennt, dass der Körper mehr Flüssigkeit braucht.','Wasser trinken ist lebenswichtig: Der menschliche Körper besteht zu einem großen Teil aus Wasser, das er für Kreislauf, Temperaturregulation, Verdauung und viele andere Funktionen braucht. Täglich verliert man Flüssigkeit über Atmung, Haut, Harn und Stuhl. Diese Verluste müssen über Getränke und Nahrung ausgeglichen werden.

## Wasser trinken: die richtige Menge

Als Orientierung gilt für gesunde Erwachsene eine Trinkmenge von etwa 1,5 Litern pro Tag. Ein weiterer Teil des Flüssigkeitsbedarfs wird über die Nahrung gedeckt, etwa über Obst, Gemüse und Suppen. Mehr Flüssigkeit braucht man:

- bei Hitze und in trockener Heizungsluft
- bei körperlicher Arbeit und Sport
- bei Fieber, Erbrechen oder Durchfall
- in der Stillzeit

Bei bestimmten Erkrankungen, etwa Herz- oder Nierenschwäche, kann die Trinkmenge ärztlich begrenzt sein. Diese Vorgaben sind unbedingt einzuhalten.

## Welche Getränke sich eignen

Am besten geeignet sind Leitungswasser, Mineralwasser und ungesüßte Kräuter- oder Früchtetees. Österreichisches Leitungswasser hat in der Regel eine sehr hohe Qualität und wird laufend kontrolliert. Es ist zudem günstig und ohne Verpackung verfügbar. Fruchtsäfte im Verhältnis von etwa einem Teil Saft zu zwei bis drei Teilen Wasser gespritzt sind eine Abwechslung.

Kaffee und schwarzer Tee dürfen in üblichen Mengen zur Trinkmenge gezählt werden. Limonaden, Eistee und Energydrinks enthalten dagegen oft viel Zucker und sind als Durstlöscher ungeeignet. Alkohol zählt nicht zur Flüssigkeitszufuhr.

## Woran man Flüssigkeitsmangel erkennt

Anzeichen dafür, dass der Körper mehr Flüssigkeit braucht, können sein:

1. Durst und trockener Mund
2. dunkler, konzentrierter Harn
3. Kopfschmerzen und Konzentrationsschwierigkeiten
4. Müdigkeit und Schwindel
5. Verstopfung

Bei älteren Menschen ist das Durstgefühl oft schwächer. Bei ihnen kann Flüssigkeitsmangel auch zu Verwirrtheit führen. Angehörige sollten daher darauf achten, dass regelmäßig getrunken wird. Bei Säuglingen und Kleinkindern mit Durchfall oder Erbrechen ist rasch ärztlicher Rat einzuholen, da sie schnell austrocknen können.

## Wasser trinken im Alltag: Tipps

- Eine Wasserflasche ins Büro, in die Schule oder auf Ausflüge mitnehmen.
- Zu jeder Mahlzeit ein Glas Wasser trinken.
- Eine Karaffe sichtbar auf den Tisch oder Schreibtisch stellen.
- Geschmack mit Zitrone, Gurke, Minze oder Beeren variieren.
- Erinnerungen am Handy setzen, wenn man oft aufs Trinken vergisst.

In vielen österreichischen Städten, etwa in Linz, Wien oder Innsbruck, gibt es öffentliche Trinkbrunnen, an denen man im Sommer die Flasche kostenlos nachfüllen kann.

Für Kinder gelten altersabhängige Richtwerte. Sie sollten über den Tag verteilt regelmäßig trinken, vor allem beim Spielen und Sport. Eine eigene Trinkflasche im Schulrucksack und Wasser als selbstverständliches Getränk bei den Mahlzeiten helfen dabei. Auch im Winter ist ausreichendes Trinken wichtig, weil trockene Heizungsluft dem Körper Flüssigkeit entzieht.

## Zu viel trinken?

Gesunde Menschen scheiden überschüssige Flüssigkeit in der Regel problemlos aus. Extrem große Mengen in kurzer Zeit können jedoch gefährlich sein. Wer ungewöhnlich starken Durst hat, sehr viel trinkt oder häufig Harn lassen muss, sollte das ärztlich abklären lassen, da etwa ein erhöhter Blutzucker dahinterstecken kann. Bei Unsicherheit hilft die Gesundheitshotline 1450 weiter.','gesundheit','Ernährung','oberoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/wasser-trinken-wie-viel-pro-tag.webp',NULL,NULL,'published','2026-10-20T13:07:00.000Z','2026-10-22T00:17:07.888Z','Wasser trinken: Wie viel pro Tag sinnvoll ist','Wasser trinken: Wie viel Flüssigkeit Erwachsene pro Tag brauchen, welche Getränke sich eignen und woran Sie Flüssigkeitsmangel erkennen – hier lesen.','Wasser trinken','["Wasser trinken","Trinkmenge pro Tag","Leitungswasser Österreich","Flüssigkeitsbedarf","wasser trinken wie viel pro tag","flüssigkeitsmangel anzeichen","leitungswasser qualität österreich","kaffee zählt zur trinkmenge"]','Wasser trinken: Karaffe mit Leitungswasser und Glas auf einem Schreibtisch in Linz','Photorealistic editorial photo of a glass carafe of tap water and a filled glass on a sunny office desk in Linz, droplets on the glass, Danube riverfront blurred in background window, bright midday light, no text, no logos, no readable signs, no people','[{"q":"Wie viel Wasser soll man am Tag trinken?","a":"Gesunde Erwachsene sollten etwa 1,5 Liter pro Tag trinken, bei Hitze, Sport oder Fieber mehr."},{"q":"Zählt Kaffee zur Trinkmenge?","a":"Ja, Kaffee und Tee in üblichen Mengen dürfen mitgezählt werden. Alkohol zählt nicht."},{"q":"Woran erkenne ich, dass ich zu wenig trinke?","a":"An Durst, dunklem Harn, Kopfschmerzen, Müdigkeit oder Verstopfung."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('binnenmarkt-notfall-resilienzgesetz-regierungsvorlage','Binnenmarkt-Notfall- und Resilienzgesetz: Was die BNRG-Vorlage regelt','Mit dem Binnenmarkt-Notfall- und Resilienzgesetz (BNRG) will die Regierung die Versorgung mit krisenrelevanten Waren absichern. Die Vorlage liegt nun dem Nationalrat vor.','Das Binnenmarkt-Notfall- und Resilienzgesetz, kurz BNRG, ist im Nationalrat angekommen: Die Regierungsvorlage mit der Nummer 648 der Beilagen wurde in der 101. Sitzung des Nationalrates am 14. Oktober 2026 als eingelangt mitgeteilt. Das Resilienzgesetz soll sicherstellen, dass Österreich bei einem Notfall im EU-Binnenmarkt rascher und abgestimmter reagieren kann – vor allem dann, wenn bestimmte Waren knapp werden.

## Worum es beim Resilienzgesetz geht

Ausgangspunkt sind die Erfahrungen aus der COVID-19-Pandemie. Damals kam es zu Störungen in den Lieferketten, und mehrere Mitgliedstaaten setzten nationale Beschränkungen, die den freien Warenverkehr behinderten. Die EU hat daraufhin einen Rechtsrahmen für Binnenmarkt-Notfälle geschaffen. Dazu gehören die Verordnung (EU) 2024/2747, die als Rahmenverordnung dient, die Verordnung (EU) 2024/2748 und die Richtlinie (EU) 2024/2749.

Das österreichische BNRG setzt laut den Erläuterungen die Richtlinie in nationales Recht um und enthält die nötigen innerstaatlichen Anpassungen an die Verordnung (EU) 2024/2748. Der Ministerrat hatte den Entwurf bereits am 7. Oktober 2026 auf der Tagesordnung, danach wurde er dem Parlament zugeleitet.

## Zuständige Behörde und Kernpunkte der Vorlage

Eine zentrale Rolle soll das Bundesamt für Eich- und Vermessungswesen (BEV) übernehmen. Es ist als Marktüberwachungsbehörde vorgesehen, entscheidet über Ausnahmegenehmigungen und erkennt Genehmigungen anderer Mitgliedstaaten an. Mit der Vollziehung des Gesetzes ist das Bundesministerium für Wirtschaft, Energie und Tourismus betraut.

Die wichtigsten Punkte der Regierungsvorlage im Überblick:

- **Vorrang für krisenrelevante Waren:** Konformitätsbewertungsstellen sollen die Prüfung solcher Produkte im Notfall priorisieren.
- **Ausnahmegenehmigungen:** Unter bestimmten Voraussetzungen sollen Waren ohne das übliche Verfahren mit einer notifizierten Stelle in Verkehr gebracht werden dürfen – befristet, auf das Bundesgebiet beschränkt und mit Kennzeichnungspflicht.
- **Konformitätsvermutung:** Stimmen Produkte mit bestimmten Normen oder gemeinsamen Spezifikationen überein, gilt eine Vermutung der Konformität.
- **Marktüberwachung:** Die Kontrolle krisenrelevanter Waren soll vorrangig erfolgen, Behörden sollen einander unterstützen.
- **Verordnungsermächtigungen:** Unter anderem zu Kennzeichnung, Informationspflichten und Höchstpreisen.

## Höchstpreise nur mit Zustimmung des Hauptausschusses

Besonders heikel ist die Möglichkeit, im Krisenfall Höchstpreise per Verordnung festzulegen. Die Vorlage sieht dafür eine Absicherung vor: Für eine solche Verordnung ist die Zustimmung des Hauptausschusses des Nationalrates notwendig. Damit bleibt das Parlament in eine der eingriffsintensivsten Maßnahmen eingebunden.

Für Verstöße gegen Kennzeichnungs-, Informations- und Meldepflichten enthält das Gesetz Strafbestimmungen. Die konkrete Strafhöhe orientiert sich laut Erläuterungen an vergleichbaren Regelungen. Zudem soll die Marktüberwachungsbehörde Beschwerde gegen Straferkenntnisse erheben können.

## Wie es mit dem BNRG im Nationalrat weitergeht

Regierungsvorlagen werden nach dem Einlangen in der Regel einem Fachausschuss zugewiesen, der sie berät und dem Plenum einen Bericht vorlegt. Erst danach stimmt der Nationalrat ab, anschließend befasst sich der Bundesrat damit. Für Unternehmen, die krisenrelevante Produkte herstellen oder vertreiben, lohnt es sich, die parlamentarischen Beratungen zu verfolgen. Die Unterlagen zur Vorlage sind auf der Website des Parlaments öffentlich abrufbar.

Fachleute sehen in dem Gesetz vor allem ein Instrument für den Ernstfall: Im Normalbetrieb ändert sich für Konsumentinnen und Konsumenten wenig. Erst wenn auf EU-Ebene ein Binnenmarkt-Notfall festgestellt wird, greifen die besonderen Befugnisse. Wann das Gesetz in Kraft treten soll, regelt ein eigener Paragraf; der genaue Zeitplan hängt vom Abschluss des parlamentarischen Verfahrens ab.','politik','Parlament',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/binnenmarkt-notfall-resilienzgesetz-regierungsvorlage.webp','Parlament Österreich','https://www.parlament.gv.at/dokument/XXVIII/NRSITZ/101/fname_1782994.pdf','published','2026-10-15T07:12:00.000Z','2026-10-22T00:17:07.889Z','Resilienzgesetz BNRG: Regierungsvorlage im Nationalrat','Resilienzgesetz BNRG: Was die Regierungsvorlage 648 d.B. für krisenrelevante Waren, Behörden und Höchstpreise vorsieht. Jetzt den Überblick lesen.','Resilienzgesetz','["Resilienzgesetz","BNRG","Binnenmarkt-Notfall- und Resilienzgesetz","648 d.B.","Regierungsvorlage Nationalrat","Binnenmarkt Notfall Österreich","krisenrelevante Waren Versorgung","IMERA Umsetzung Österreich","BEV Marktüberwachung"]','Lager mit krisenrelevanten Waren als Symbolbild zum Resilienzgesetz BNRG in Österreich','Photorealistic editorial photo of a large logistics warehouse in Lower Austria with stacked pallets of medical supplies and protective equipment, forklift in soft focus, cool morning light through high windows, wide angle, no text, no logos, no readable signs, no identifiable people','[{"q":"Was ist das Resilienzgesetz BNRG?","a":"Das Binnenmarkt-Notfall- und Resilienzgesetz soll die Versorgung mit krisenrelevanten Waren bei einem Notfall im EU-Binnenmarkt sichern. Es setzt die Richtlinie (EU) 2024/2749 um."},{"q":"Welche Behörde ist für das BNRG zuständig?","a":"Als Marktüberwachungsbehörde ist das Bundesamt für Eich- und Vermessungswesen vorgesehen. Vollzogen wird das Gesetz vom Wirtschaftsministerium."},{"q":"Kann die Regierung mit dem BNRG Höchstpreise festlegen?","a":"Die Vorlage enthält eine Verordnungsermächtigung für Höchstpreise im Krisenfall. Dafür ist aber die Zustimmung des Hauptausschusses des Nationalrates nötig."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('andreas-babler-rueckzug-spoe-marterbauer-vizekanzler','Andreas Babler: Rückzug von der SPÖ-Spitze, Marterbauer folgt','Nach einer langen Krisensitzung kündigt SPÖ-Chef Andreas Babler seinen schrittweisen Rückzug an. Ab Jänner soll Finanzminister Markus Marterbauer Vizekanzler werden.','Andreas Babler zieht sich schrittweise von der Spitze der SPÖ zurück. Das hat der Parteichef am Sonntag, dem 4. Oktober 2026, nach einer rund vierstündigen Aussprache zwischen den Landesparteivorsitzenden und der Bundespartei angekündigt. Vizekanzler bleibt Babler demnach mindestens bis Jahresende, ab Jänner soll Finanzminister Markus Marterbauer dieses Amt übernehmen.

## Was der Rückzug von Andreas Babler konkret bedeutet

Der Wechsel ist als Übergang angelegt. Bis Jahresende sollen Babler zwei bekannte Gesichter der Partei zur Seite stehen: Klubobmann Philip Kucher und SPÖ-Frauenvorsitzende Eva-Maria Holzleitner. Danach sollen die beiden die Führung ohne ihn weitertragen. Babler selbst betonte, sein Schritt sei freiwillig, und sagte sinngemäß, die anhaltende Debatte über seine Person müsse enden.

Offen gelassen wurde, ob Babler weiterhin der Bundesregierung angehören wird. Medienberichten zufolge könnte er als Minister im Kabinett bleiben, falls Marterbauer das wünscht. Ob Marterbauer neben dem Amt des Vizekanzlers auch den Parteivorsitz übernimmt, war zunächst offiziell nicht geklärt.

## Reaktionen aus Wien und den Ländern

Wiens Bürgermeister und SPÖ-Landesparteichef Michael Ludwig hatte vor der Sitzung eine einvernehmliche Lösung erwartet. Eine neuerliche Mitgliederbefragung über die Parteispitze lehnte er ab. Auch andere Landesorganisationen drängten auf eine rasche Klärung, um die Partei aus den Schlagzeilen zu bringen.

Wenige Tage nach der Ankündigung meldete sich auch Medienmanager Gerhard Zeiler zu Wort, der immer wieder als möglicher Kandidat für den Parteivorsitz genannt worden war. In einem Video wünschte er Marterbauer viel Erfolg, falls dieser die SPÖ übernimmt, und stellte eigene Ambitionen vorerst zurück.

## Andreas Babler und die Koalition

Für die Dreierkoalition aus ÖVP, SPÖ und NEOS bringt der Wechsel Unsicherheit. Die FPÖ forderte umgehend Neuwahlen. Aus der ÖVP kamen gemischte Signale: Vorarlbergs Landeshauptmann Markus Wallner bezeichnete Neuwahlen als nicht ausgeschlossen, auch wenn er nicht darauf hoffe. Bundeskanzler Christian Stocker stellte sich wenig später klar hinter die Fortsetzung der Zusammenarbeit.

Inhaltlich steht die Regierung vor einem dichten Herbstprogramm. Zu den angekündigten Vorhaben zählen unter anderem eine Reform der Sozialhilfe, Maßnahmen für den Wirtschaftsstandort und das sogenannte Zukunftsdepot. Für die SPÖ wird entscheidend sein, wie reibungslos der Übergang an der Spitze gelingt und ob die Partei in den Verhandlungen geschlossen auftritt.

## Wie geht es in der SPÖ weiter?

Der Fahrplan sieht vor, dass die neue Konstellation mit Jahresbeginn 2027 greift. Formal muss ein neuer Parteivorsitz von den zuständigen Parteigremien und einem Parteitag bestätigt werden. Wann und in welcher Form das geschieht, war Anfang Oktober noch nicht festgelegt.

Babler war im Sommer 2023 nach einem parteiinternen Wettstreit an die Spitze der SPÖ gekommen. Mit dem Eintritt in die Bundesregierung wurde er Vizekanzler. Die Debatte über seine Führung hatte die Partei in den Wochen vor der Krisensitzung zunehmend belastet. Mit dem angekündigten Übergang will die SPÖ nun Stabilität signalisieren – sowohl nach innen als auch gegenüber den Koalitionspartnern.

Marterbauer ist seit März 2025 Finanzminister und gilt als Ökonom mit langjähriger Erfahrung, zuvor war er Chefökonom der Arbeiterkammer Wien. ','politik','Innenpolitik',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/andreas-babler-rueckzug-spoe-marterbauer-vizekanzler.webp','Salzburg24','https://www.salzburg24.at/news/oesterreich/adieu-andi-babler-bekommt-duo-als-aufpasser-soll-im-jaenner-fix-gehen-art-340150','published','2026-10-04T17:48:00.000Z','2026-10-22T00:17:07.889Z','Andreas Babler: Rückzug, Marterbauer wird Vizekanzler','Andreas Babler zieht sich schrittweise von der SPÖ-Spitze zurück. Was bis Jahresende gilt und wer ab Jänner Vizekanzler werden soll – jetzt lesen.','Andreas Babler','["Andreas Babler","Babler Rücktritt","SPÖ Vorsitz","Marterbauer Vizekanzler","SPÖ Krise 2026","Babler Nachfolger","Vizekanzler Österreich 2027","Kucher Holzleitner SPÖ"]','Leerer Sitzungsraum am Abend als Symbolbild zum Rückzug von Andreas Babler','Photorealistic editorial photo of an empty modern party meeting room in Vienna at night, long table with water glasses and scattered papers, chairs pushed back, warm lamp light, rainy window reflections, no text, no logos, no readable signs, no people','[{"q":"Wer wird nach Andreas Babler Vizekanzler?","a":"Laut der Einigung vom 4. Oktober 2026 soll Finanzminister Markus Marterbauer ab Jänner 2027 Vizekanzler werden."},{"q":"Bleibt Andreas Babler bis Jahresende im Amt?","a":"Ja, Babler soll bis Jahresende Vizekanzler bleiben. Ihm stehen Klubobmann Philip Kucher und Eva-Maria Holzleitner zur Seite."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('neuwahl-oesterreich-stocker-schliesst-aus','Neuwahl Österreich: Stocker schließt vorgezogene Wahl aus','Nach dem angekündigten Rückzug von SPÖ-Chef Babler schließt Bundeskanzler Christian Stocker eine Neuwahl aus. Die Koalition soll ihr Herbstprogramm abarbeiten.','Eine Neuwahl steht für Bundeskanzler Christian Stocker (ÖVP) nicht zur Debatte. Am 5. Oktober 2026, einen Tag nach dem angekündigten schrittweisen Rückzug von SPÖ-Chef Andreas Babler, betonte der Kanzler, die Koalition arbeite und funktioniere. Von der SPÖ forderte er volle Konzentration auf das Regierungsprogramm.

## Neuwahl kein Thema: Stocker setzt auf den Herbst der Ergebnisse

Stocker verwies auf die Vorhaben, die bis Jahresende umgesetzt werden sollen. Bereits beim ersten Ministerrat nach der Sommerpause im September hatte er einen „Herbst der Ergebnisse“ angekündigt. Genannt wurden nun unter anderem Maßnahmen für den Wirtschaftsstandort, die Reform der Sozialhilfe, das sogenannte Zukunftsdepot und ein Verbot des politischen Islam.

Den SPÖ-internen Wechsel wollte der Kanzler nicht kommentieren. Babler bleibe für ihn weiterhin Ansprechpartner, solange er Vizekanzler sei. Laut der SPÖ-Einigung soll das bis Jahresende der Fall sein, danach soll Finanzminister Markus Marterbauer übernehmen.

## Reaktionen von NEOS und ÖVP-Ländern

NEOS-Chefin und Außenministerin Beate Meinl-Reisinger bezeichnete Personalentscheidungen als Angelegenheit der SPÖ. Kritisch sah sie allerdings lange Übergangsphasen: Reformen müssten trotz der Veränderungen zügig abgeschlossen werden.

Die ÖVP-Landeshauptleute berieten sich per Videokonferenz. Oberösterreichs Landeshauptmann Thomas Stelzer stellte die Stabilität der Regierung in den Vordergrund. Vorarlbergs Landeshauptmann Markus Wallner warnte davor, dass die Debatte dem Land schade. Die FPÖ hatte zuvor Neuwahlen gefordert.

## Wie eine Neuwahl in Österreich ablaufen würde

Die Gesetzgebungsperiode des Nationalrates dauert fünf Jahre. Nach der Wahl im Herbst 2024 wäre der reguläre Wahltermin daher erst 2029. Eine vorgezogene Wahl ist auf zwei Wegen möglich:

1. **Selbstauflösung:** Der Nationalrat beschließt mit einfacher Mehrheit ein Gesetz über seine vorzeitige Auflösung. Das ist in der Praxis der übliche Weg.
2. **Auflösung durch den Bundespräsidenten:** Auf Vorschlag der Bundesregierung kann der Bundespräsident den Nationalrat auflösen, allerdings nur einmal aus demselben Anlass.

In beiden Fällen bleibt der bisherige Nationalrat bis zum Zusammentritt des neuen im Amt. Zwischen dem Auflösungsbeschluss und dem Wahltag liegen erfahrungsgemäß mehrere Monate, da die Wahlbehörden Fristen für Wahlvorschläge, Wählerverzeichnisse und Wahlkarten einhalten müssen.

## Was die Neuwahl-Debatte für Bürgerinnen und Bürger bedeutet

Für die Bevölkerung ändert sich vorerst nichts: Die Regierung bleibt im Amt, laufende Gesetzesvorhaben werden weiter verhandelt. Entscheidend wird sein, ob die Koalition die angekündigten Projekte tatsächlich beschließt. Zu den großen Themen der kommenden Monate gehören auch das Doppelbudget 2027/2028 und die Reformpartnerschaft zwischen Bund, Ländern und Gemeinden.

Politikbeobachter verweisen darauf, dass Übergangsphasen in Regierungsparteien immer ein Risiko für die Zusammenarbeit darstellen. Ob die Dreierkoalition gestärkt oder geschwächt aus der Situation hervorgeht, wird sich spätestens beim Wechsel an der SPÖ-Spitze im Jänner zeigen.

## Neuwahl und Koalition: Worauf jetzt zu achten ist

Ein wichtiger Gradmesser für die Stabilität der Regierung sind die wöchentlichen Ministerräte und die Plenarsitzungen des Nationalrates. Wenn dort Gesetze wie die Sozialhilfereform oder Teile der Reformpartnerschaft beschlossen werden, spricht das gegen eine baldige Neuwahl. Umgekehrt würden lange Verzögerungen oder offene Konflikte zwischen den Partnern die Debatte neu anfachen. Auch Umfragen spielen erfahrungsgemäß eine Rolle, wenn Parteien über einen vorgezogenen Wahltermin nachdenken. Für Wahlberechtigte gilt: Sollte es doch zu einer Neuwahl kommen, werden Termin und Fristen rechtzeitig amtlich kundgemacht, und Wahlkarten können wie gewohnt beantragt werden.','politik','Innenpolitik',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/neuwahl-oesterreich-stocker-schliesst-aus.webp','Salzburg24','https://www.salzburg24.at/news/oesterreich/bundeskanzler-christian-stocker-erteilt-neuwahlen-absage-koalition-will-nach-babler-aus-weiterarbeiten-art-340283','published','2026-10-05T13:21:00.000Z','2026-10-22T00:17:07.889Z','Neuwahl Österreich: Stocker schließt Wahl aus','Neuwahl Österreich: Kanzler Stocker erteilt vorgezogenen Wahlen eine Absage. Was das für die Koalition heißt und wie eine Neuwahl ablaufen würde.','Neuwahl','["Neuwahl","Neuwahl Österreich","Stocker Neuwahl","Koalition ÖVP SPÖ NEOS","Nationalratswahl vorgezogen","Herbst der Ergebnisse","Auflösung Nationalrat","nächste Nationalratswahl Österreich"]','Herbstlicher Platz im Regierungsviertel Wien als Symbolbild zur Neuwahl-Debatte','Photorealistic editorial photo of the Ballhausplatz area in Vienna seen from a low angle on an overcast autumn afternoon, baroque facade partially in frame, fallen leaves on cobblestones, shallow depth of field, no text, no logos, no readable signs, no identifiable people','[{"q":"Wann ist die nächste reguläre Nationalratswahl?","a":"Die Gesetzgebungsperiode dauert fünf Jahre. Nach der Wahl 2024 wäre die nächste reguläre Nationalratswahl 2029."},{"q":"Wie kommt es in Österreich zu einer Neuwahl?","a":"Meist beschließt der Nationalrat mit einfacher Mehrheit seine vorzeitige Auflösung. Alternativ kann der Bundespräsident ihn auf Vorschlag der Regierung auflösen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('budgetdefizit-oesterreich-2027-prognose','Budgetdefizit Österreich: Regierung erwartet 3,6 Prozent für 2027','Das Finanzministerium rechnet für 2027 mit einem gesamtstaatlichen Defizit von 3,6 Prozent des BIP. Unter die EU-Grenze von drei Prozent soll es bis Ende 2028 gehen.','Das Budgetdefizit Österreich soll im kommenden Jahr sinken, bleibt aber über der EU-Grenze. Laut einer Mitteilung des Finanzministeriums vom 14. Oktober 2026 wird für 2027 ein gesamtstaatliches Defizit von 3,6 Prozent des Bruttoinlandsprodukts erwartet. Für heuer wurde an die EU ein Wert von 4,1 Prozent gemeldet.

## Budgetdefizit Österreich: Die wichtigsten Zahlen

Die Prognose ist Teil der regelmäßigen Berichterstattung im EU-Defizitverfahren, das gegen Österreich läuft. Der Bericht wurde im Ministerrat beschlossen und nach Brüssel übermittelt. Die Eckdaten:

- **Defizit 2026:** 4,1 Prozent des BIP (an die EU notifiziert)
- **Defizit 2027:** 3,6 Prozent des BIP
- **Schuldenquote 2027:** 83,2 Prozent des BIP
- **Ziel:** Defizit bis Ende 2028 unter die Referenzgrenze von 3 Prozent

Gegenüber früheren Annahmen wurde die Defizitprognose für 2027 um 0,1 Prozentpunkte nach oben korrigiert. Als Gründe nennt das Ministerium die hohen Zinskosten und die schwache Lage am Arbeitsmarkt. Die Schuldenquote fällt dagegen niedriger aus als noch im Juni angenommen. Das liegt vor allem daran, dass Statistik Austria das Bruttoinlandsprodukt für 2025 nach oben revidiert hat – bei gleicher Schuldenhöhe sinkt damit der Anteil am BIP.

## Was Finanzminister und Staatssekretäre sagen

Finanzminister Markus Marterbauer (SPÖ) betonte, dass die im Doppelbudget 2027/2028 vorgesehenen Konsolidierungsmaßnahmen strikt eingehalten werden müssen. Neue Maßnahmen seien nur möglich, wenn sie durch Umschichtungen oder eine Gegenfinanzierung gedeckt sind.

Finanzstaatssekretärin Barbara Eibinger-Miedl (ÖVP) nannte als Ziel, das Defizit durch Budgetdisziplin und Strukturreformen bis 2028 auf drei Prozent zu senken. Die geopolitische Unsicherheit erschwere diesen Weg. Deregulierungsstaatssekretär Sepp Schellhorn (NEOS) sah Bund, Länder und Gemeinden gemeinsam in der Verantwortung: Strukturen, die den Staat teuer und kompliziert machen, müssten reformiert werden.

## Das EU-Defizitverfahren kurz erklärt

Die EU-Fiskalregeln sehen vor, dass das gesamtstaatliche Defizit drei Prozent des BIP nicht übersteigen soll. Liegt ein Land deutlich darüber, kann ein Verfahren wegen eines übermäßigen Defizits eingeleitet werden. Der betroffene Staat muss dann einen Anpassungspfad einhalten und halbjährlich berichten, wie er sein Defizit abbaut.

Wichtig: Gemeint ist das Defizit des Gesamtstaats. Neben dem Bund zählen auch Länder, Gemeinden und Sozialversicherungen dazu. Deshalb spielen auch die Finanzen der Bundesländer und Kommunen eine Rolle für die Frage, ob Österreich das Verfahren verlassen kann.

## Budgetdefizit und Alltag: Was das für Haushalte bedeutet

Unmittelbare neue Belastungen enthält die aktuelle Prognose nicht. Sie bestätigt aber den Kurs, den die Regierung mit dem Doppelbudget eingeschlagen hat: Sparen auf der Ausgabenseite und wenig Spielraum für neue Leistungen. Für Bürgerinnen und Bürger heißt das, dass zusätzliche Förderungen oder Entlastungen nur kommen dürften, wenn an anderer Stelle eingespart wird.

Ob der Pfad hält, hängt stark von der Konjunktur ab. Ein schwächeres Wachstum oder steigende Arbeitslosigkeit würden die Einnahmen drücken und die Ausgaben erhöhen. Die nächste Überprüfung im Rahmen des Defizitverfahrens folgt im kommenden Frühjahr.

Für Gemeinden und Länder bedeutet der Konsolidierungskurs ebenfalls wenig Spielraum. Sie müssen ihre eigenen Haushalte so planen, dass der Gesamtstaat den vereinbarten Pfad einhält. Der innerösterreichische Stabilitätspakt legt dafür fest, welchen Beitrag die einzelnen Ebenen leisten sollen.','politik','Innenpolitik',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/budgetdefizit-oesterreich-2027-prognose.webp','Bundesministerium für Finanzen','https://www.bmf.gv.at/presse/pressemeldungen/2026/oktober-2026/ued-verfahren.html','published','2026-10-14T11:05:00.000Z','2026-10-22T00:17:07.889Z','Budgetdefizit Österreich: 3,6 Prozent für 2027','Budgetdefizit Österreich: Laut Finanzministerium sinkt das Defizit 2027 auf 3,6 Prozent des BIP. Was das für das EU-Defizitverfahren heißt – hier lesen.','Budgetdefizit Österreich','["Budgetdefizit Österreich","Defizit 2027","Defizitverfahren Österreich","Schuldenquote Österreich","Marterbauer Budget","Doppelbudget 2027 2028","Maastricht Defizit 3 Prozent","Staatsschulden Österreich 2027"]','Taschenrechner und Euromünzen als Symbolbild zum Budgetdefizit Österreich 2027','Photorealistic editorial still life of a calculator, printed budget charts and euro coins on a wooden desk in a Viennese office, autumn daylight from a tall window, close-up top-down angle, no text, no logos, no readable signs, no people','[{"q":"Wie hoch ist das Budgetdefizit Österreich 2027?","a":"Das Finanzministerium erwartet für 2027 ein gesamtstaatliches Defizit von 3,6 Prozent des BIP, nach 4,1 Prozent im Jahr 2026."},{"q":"Wann soll Österreich das EU-Defizitverfahren verlassen?","a":"Ziel der Regierung ist, das Defizit bis Ende 2028 unter drei Prozent des BIP zu senken. Dann könnte das Verfahren beendet werden."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pilnacek-u-ausschuss-stocker-sobotka-befragung','Pilnacek-U-Ausschuss: Stocker und Sobotka als Auskunftspersonen','Der Pilnacek-U-Ausschuss steuert auf seinen Höhepunkt zu: Bundeskanzler Christian Stocker und Ex-Nationalratspräsident Wolfgang Sobotka sollen befragt werden.','Der Pilnacek-U-Ausschuss geht in eine entscheidende Woche. Am Mittwoch, dem 21. Oktober 2026, ist Bundeskanzler Christian Stocker (ÖVP) als Auskunftsperson geladen, am Donnerstag soll der frühere Innenminister und Nationalratspräsident Wolfgang Sobotka (ÖVP) befragt werden. Zwei weitere prominente Ladungen fallen dagegen aus.

## Pilnacek-U-Ausschuss: Wer kommt, wer abgesagt hat

Laut Berichten haben Ex-Bundeskanzler Karl Nehammer und die frühere Ministerin Karoline Edtstadler (beide ÖVP) ihr Erscheinen abgesagt. Damit gilt eine Verlängerung der Befragungen als möglich. Ob der Ausschuss tatsächlich verlängert wird, war vorerst offen. FPÖ-Fraktionsführer Christian Hafenecker kündigte eine Entscheidung für Donnerstag an.

Die FPÖ hat den Untersuchungsausschuss verlangt. Bei der Befragung von Stocker interessiert sie vor allem dessen frühere Zeit als Generalsekretär der ÖVP. Sobotka gilt in der Causa als zentrale Figur: Pilnacek soll auf einer heimlich angefertigten Tonaufnahme angebliche Interventionen angesprochen haben. Sobotka hat entsprechende Vorwürfe in der Vergangenheit zurückgewiesen.

## Was untersucht wird

Gegenstand des Ausschusses ist die Frage, ob es politische Einflussnahme auf Ermittlungen gegeben hat – insbesondere rund um die Ermittlungen nach dem Tod des früheren Justiz-Sektionschefs Christian Pilnacek im Herbst 2023. Zuvor waren bereits unter anderem Justizministerin Anna Sporrer und ihre Vorgängerin Alma Zadić als Auskunftspersonen geladen.

## Wie ein U-Ausschuss im Nationalrat funktioniert

Untersuchungsausschüsse sind ein zentrales Kontrollinstrument des Parlaments. Seit der Reform 2015 ist die Einsetzung ein Minderheitenrecht: Ein Viertel der Abgeordneten kann einen Ausschuss verlangen. Wichtige Regeln im Überblick:

- **Auskunftspersonen** sind verpflichtet zu erscheinen und wahrheitsgemäß auszusagen. Eine falsche Aussage kann strafrechtliche Folgen haben.
- **Verfahrensrichterin oder Verfahrensrichter** führt die Erstbefragung durch und achtet auf die Einhaltung der Verfahrensregeln.
- **Verfahrensanwältin oder Verfahrensanwalt** wahrt die Grund- und Persönlichkeitsrechte der Befragten.
- **Aktenvorlage:** Ministerien und Behörden müssen dem Ausschuss relevante Unterlagen vorlegen.

Ein Ausschuss endet mit einem Bericht, in dem auch die Fraktionen ihre Sicht festhalten können. Strafrechtliche Urteile fällt er nicht – er klärt politische Verantwortung.

## Befragungen im Pilnacek-U-Ausschuss live verfolgen

Die Befragungen finden im Parlament in Wien statt. Medienvertreterinnen und Medienvertreter können vor Ort berichten, Bild- und Tonaufnahmen während der Befragung sind jedoch nicht erlaubt. Die Parlamentskorrespondenz veröffentlicht laufend Zusammenfassungen. Wörtliche Protokolle der Befragungen werden später auf der Website des Parlaments veröffentlicht.

Mit den Befragungen von Kanzler und Ex-Nationalratspräsident erreicht der Ausschuss einen politischen Höhepunkt. Für die Koalition kommt der Termin zu einem heiklen Zeitpunkt, da sie nach dem angekündigten Führungswechsel in der SPÖ ohnehin unter Beobachtung steht.

## Pilnacek-U-Ausschuss: Wie es weitergeht

Nach den Befragungen im Oktober hängt der weitere Fahrplan davon ab, ob der Ausschuss verlängert wird. Ein Untersuchungsausschuss hat eine gesetzlich begrenzte Dauer, die auf Verlangen der Minderheit einmal verlängert werden kann. Ist die Beweisaufnahme abgeschlossen, erstellt die Verfahrensrichterin oder der Verfahrensrichter einen Entwurf für den Bericht. Die Fraktionen können anschließend eigene Stellungnahmen abgeben, die gemeinsam mit dem Bericht im Nationalrat behandelt werden. Erst dann ist die parlamentarische Aufarbeitung der Causa formal beendet. Strafrechtliche Ermittlungen laufen davon unabhängig bei den zuständigen Staatsanwaltschaften.','politik','Parlament',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/pilnacek-u-ausschuss-stocker-sobotka-befragung.webp','ORF.at','https://orf.at/stories/3445427/','published','2026-10-18T08:34:00.000Z','2026-10-22T00:17:07.890Z','Pilnacek-U-Ausschuss: Stocker und Sobotka geladen','Pilnacek-U-Ausschuss: Kanzler Stocker und Wolfgang Sobotka werden befragt, Nehammer und Edtstadler sagten ab. Was die Woche bringt – jetzt lesen.','Pilnacek-U-Ausschuss','["Pilnacek-U-Ausschuss","U-Ausschuss Pilnacek","Stocker Befragung","Sobotka U-Ausschuss","Untersuchungsausschuss Nationalrat","Pilnacek Ermittlungen","Hafenecker U-Ausschuss Verlängerung","Auskunftsperson U-Ausschuss"]','Leerer Ausschusssaal mit Mikrofonen als Symbolbild zum Pilnacek-U-Ausschuss','Photorealistic editorial photo of an empty parliamentary committee hearing room with a witness table, microphones and folders, modern wood paneling, cool neutral light, view from the back of the room, no text, no logos, no readable signs, no people','[{"q":"Wann wird Kanzler Stocker im Pilnacek-U-Ausschuss befragt?","a":"Bundeskanzler Christian Stocker war für Mittwoch, den 21. Oktober 2026, als Auskunftsperson geladen."},{"q":"Muss man vor einem U-Ausschuss aussagen?","a":"Ja, geladene Auskunftspersonen müssen erscheinen und wahrheitsgemäß aussagen. Bestimmte Aussageverweigerungsrechte gibt es etwa bei Gefahr der Selbstbelastung."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('bundesrat-parlamentswoche-oktober-2026','Bundesrat: Das steht in der Parlamentswoche bis 23. Oktober an','Der Bundesrat berät am Donnerstag über neue Gesetze, daneben tagen U-Ausschuss und mehrere Fachausschüsse. Am Freitag schließt das Parlament früher.','Der Bundesrat steht im Mittelpunkt der Parlamentswoche von 19. bis 23. Oktober 2026. Die Länderkammer behandelt am Donnerstag mehrere Gesetze, die der Nationalrat zuletzt beschlossen hat. Daneben setzen der Pilnacek-Untersuchungsausschuss und zahlreiche Fachausschüsse ihre Arbeit fort.

## Bundesrat am Donnerstag: Gesetze und Aktuelle Stunde

Die Sitzung des Bundesrates beginnt am Donnerstag, dem 22. Oktober, um 9 Uhr mit einer Aktuellen Stunde mit Sozialministerin Korinna Schumann. Auf der Tagesordnung stehen anschließend unter anderem:

- Regelungen im Strafvollzug, die die Abschiebung ausländischer Strafgefangener betreffen
- Bestimmungen zur Verhinderung von Geldwäsche
- eine Novelle der Gewerbeordnung

Der Bundesrat kann gegen Gesetzesbeschlüsse des Nationalrates Einspruch erheben. In den meisten Fällen hat dieser nur aufschiebende Wirkung: Der Nationalrat kann mit einem Beharrungsbeschluss das Gesetz trotzdem in Kraft setzen.

## Ausschüsse und Termine von Montag bis Mittwoch

Bereits am Montag ging es im Bundesratssaal um die Reformpartnerschaft zwischen Bund, Ländern und Gemeinden. Dazu war ein Austausch mit mehreren Ministerinnen, Ministern und Staatssekretären angesetzt. Am Abend lud der Zweite Nationalratspräsident Peter Haubner ins Palais Epstein zur Präsentation einer deutschsprachigen Ausgabe eines Buches mit Briefen von Holocaust-Überlebenden aus dem Archiv von Yad Vashem.

Am Dienstag tagten der Gleichbehandlungsausschuss und der Rechnungshofausschuss. Letzterer befasste sich mit vier Berichten des Rechnungshofes, darunter zu Liegenschaften der AUVA und zur ambulanten ärztlichen Versorgung.

Am Mittwoch setzte der Pilnacek-Untersuchungsausschuss seine Befragungen fort, unter anderem mit Bundeskanzler Christian Stocker als Auskunftsperson. Im EU-Unterausschuss standen EU-Vorhaben zu Reisebuchungen und zum Bahnverkehr auf dem Programm, Infrastrukturminister Peter Hanke stand den Abgeordneten zur Verfügung.

## Landesverteidigung, Petitionen und Kultur

Neben dem Bundesrat tagt am Donnerstag auch der Landesverteidigungsausschuss. Mit Verteidigungsministerin Klaudia Tanner geht es um das Verteidigungsbudget und Beschaffungen, darunter Kampfdrohnen und Jets des Herstellers Leonardo. Parallel befragt der Pilnacek-U-Ausschuss den früheren Nationalratspräsidenten Wolfgang Sobotka.

Der Petitionsausschuss hält eine gemeinsame Anhörung zu fünf Bürgeranliegen ab. Außerdem sind Sitzungen des Verfassungsausschusses und des Kulturausschusses angesetzt, deren Tagesordnungen zunächst noch nicht feststanden.

## Bundesrat-Präsidentin in Budapest, Parlament vor dem Nationalfeiertag

Am Freitag nimmt Bundesratspräsidentin Christine Schwarz-Fuchs an den Feierlichkeiten zum 70. Jahrestag des Ungarischen Volksaufstands von 1956 in Budapest teil. Das Parlamentsgebäude an der Ringstraße schließt am Freitag bereits um 12 Uhr. Grund sind die Vorbereitungen für den Tag der offenen Tür am Nationalfeiertag, dem 26. Oktober.

Wer die Arbeit von Nationalrat und Bundesrat verfolgen möchte, findet Tagesordnungen, Livestreams der Plenarsitzungen und Zusammenfassungen der Parlamentskorrespondenz auf der Website des Parlaments. Ausschusssitzungen sind in der Regel nicht öffentlich, die Ergebnisse werden aber anschließend veröffentlicht.

## Bundesrat kurz erklärt

Der Bundesrat ist die Länderkammer des österreichischen Parlaments. Seine Mitglieder werden nicht direkt gewählt, sondern von den Landtagen entsandt. Wie viele Mandate ein Bundesland stellt, richtet sich nach der Einwohnerzahl. Den Vorsitz übernimmt halbjährlich wechselnd ein Mitglied aus einem anderen Bundesland. Bei Verfassungsgesetzen, die die Zuständigkeiten der Länder einschränken, hat der Bundesrat ein echtes Vetorecht.','politik','Parlament',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/bundesrat-parlamentswoche-oktober-2026.webp','Parlament Österreich','https://www.parlament.gv.at/aktuelles/pk/woche','published','2026-10-19T05:46:00.000Z','2026-10-22T00:17:07.890Z','Bundesrat: Sitzung und Termine der Parlamentswoche','Bundesrat, U-Ausschuss, Rechnungshof: Diese Termine stehen im Parlament bis 23. Oktober 2026 an. Hier alle Sitzungen der Woche im Überblick lesen.','Bundesrat','["Bundesrat","Bundesrat Sitzung Oktober 2026","Parlamentswoche","Parlament Wien Termine","Rechnungshofausschuss","Landesverteidigungsausschuss Drohnen","Nationalfeiertag Parlament offen","Bundesrat Aktuelle Stunde"]','Leerer Sitzungssaal des Bundesrat aus der Besuchergalerie gesehen','Photorealistic editorial photo of a semicircular legislative chamber with rows of red upholstered seats seen from the visitor gallery, soft daylight through a glass ceiling, empty chamber before a session, no text, no logos, no readable signs, no people','[{"q":"Wann tagt der Bundesrat im Oktober 2026?","a":"Die Sitzung des Bundesrates fand am Donnerstag, dem 22. Oktober 2026, ab 9 Uhr statt, eröffnet mit einer Aktuellen Stunde."},{"q":"Kann der Bundesrat Gesetze verhindern?","a":"Meist nicht endgültig. Ein Einspruch hat in der Regel nur aufschiebende Wirkung, der Nationalrat kann mit einem Beharrungsbeschluss das Gesetz dennoch beschließen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('gemeindepaket-reformpartnerschaft-gemeinden','Gemeindepaket: Was die Reformpartnerschaft für Gemeinden ändert','Bund und Gemeindebund haben ein Gemeindepaket vorgestellt: mehr Kooperation, schnellere Verfahren, digitale Amtswege und weniger Bürokratie in den Kommunen.','Mit einem Gemeindepaket will die Bundesregierung die Verwaltung in Österreichs Kommunen vereinfachen. Vorgestellt wurde es am 1. Oktober 2026 im Rahmen der Reformpartnerschaft zwischen Bund, Ländern und Gemeinden, konkret in der Arbeitsgruppe Verfassung und Verwaltung. Beteiligt waren die Staatssekretäre Alexander Pröll, Jörg Leichtfried und Sepp Schellhorn sowie Gemeindebund-Präsident Johannes Pressl.

## Gemeindepaket: Kooperation statt Zwangsfusion

Ein zentraler Grundsatz des Pakets lautet „Kooperation statt Zwangsfusion“. Statt Gemeinden zusammenzulegen, soll die Zusammenarbeit zwischen ihnen leichter werden. Als Beispiel wird genannt, dass Wasserverbände künftig einfacher fusionieren können. Viele kleinere Gemeinden arbeiten schon heute in Verbänden zusammen, etwa bei Abwasser, Müll oder Schulen.

## Schnellere Verfahren und gemeinsame Sachverständige

Für Bürgerinnen und Bürger besonders spürbar könnte eine Verfahrensänderung sein: In Gemeindeangelegenheiten soll eine interne Instanz entfallen. Das betrifft zum Beispiel Baubewilligungen, bei denen bisher in vielen Fällen zunächst der Gemeinderat oder ein anderes Gemeindeorgan über eine Berufung entscheiden musste, bevor ein Gericht angerufen werden konnte.

Zudem soll ein gemeinsamer Pool an Amtssachverständigen entstehen, auf den Behörden verschiedener Ebenen zugreifen können. Das soll Genehmigungsverfahren beschleunigen, die heute oft an fehlenden Gutachterinnen und Gutachtern hängen.

## Digitale Verwaltung und Künstliche Intelligenz

Ein großer Teil des Gemeindepakets betrifft die Digitalisierung:

- **KI-Initiative:** Ein Bundesprogramm mit gemeinsamer Infrastruktur, Regeln und Schulungen nach dem Shared-Service-Prinzip.
- **Datenplattform für Gemeinden:** Einheitliche Schnittstellen und bessere Daten, unterstützt vom Bund.
- **Ausbau von dadeX:** Eine zentrale Infrastruktur für den Datenaustausch, damit das Once-Only-Prinzip umgesetzt werden kann – Bürgerinnen und Bürger sollen Daten nur einmal angeben müssen.
- **Antragslose Verfahren:** Behörden sollen vorhandene Daten automatisch teilen, Gemeinden etwa Gebühren automatisiert vorschreiben können.
- **Workshops „Digital Überall“:** Ab Dezember 2026 kostenlos für die Bevölkerung, bis zu 3.000 Termine bis Ende 2027 – unter anderem zu Online-Amtswegen, Sicherheit im Netz, Faktenchecks und KI.

## Weniger Papier, einfachere Wahlen

Das Paket sieht auch Deregulierung vor. Vorgaben zu Papier, Amtstafel und Barzahlung sollen reduziert werden, Kundmachungen sollen digital möglich werden. Bei Volksbegehren sollen Gemeinden künftig keine unnötigen Amtsstunden während der Eintragungszeiträume mehr abhalten müssen – die Unterstützung ist ohnehin bereits online mit ID Austria möglich.

## Was das Gemeindepaket für Bürgerinnen und Bürger bringt

Viele Punkte des Gemeindepakets sind Absichtserklärungen, die noch in Gesetze gegossen werden müssen. Manche betreffen Bundesrecht, andere fallen in die Zuständigkeit der Länder, etwa das Baurecht oder die Gemeindeordnungen. Wann sich im Alltag tatsächlich etwas ändert, hängt daher vom Tempo der Umsetzung in Bund und Ländern ab.

Für Gemeinden ist das Paket auch eine Antwort auf knappe Kassen. Wenn Verwaltung effizienter wird und Kommunen Aufgaben gemeinsam erledigen, sollen Kosten sinken. Ob das reicht, um die angespannte Finanzlage vieler Gemeinden zu entschärfen, bleibt eine offene Frage.

Der Gemeindebund begrüßte die Stoßrichtung des Pakets, weil sie die Eigenständigkeit der Gemeinden betont. Die Umsetzung soll schrittweise erfolgen, erste Gesetzesentwürfe werden im Laufe des kommenden Jahres erwartet. Bürgerinnen und Bürger erfahren über ihre Gemeindeämter, ab wann sich Abläufe ändern.','politik','Gemeinden',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/gemeindepaket-reformpartnerschaft-gemeinden.webp','Bundeskanzleramt','https://www.bundeskanzleramt.gv.at/bundeskanzleramt/nachrichten-der-bundesregierung/2026/09/gemeindepaket-im-rahmen-der-reformpartnerschaft-auf-den-weg-gebracht.html','published','2026-10-01T12:12:00.000Z','2026-10-22T00:17:07.890Z','Gemeindepaket: Was sich für Gemeinden ändert','Gemeindepaket der Reformpartnerschaft: Kooperation statt Zwangsfusion, schnellere Verfahren und digitale Ämter. Die zehn Punkte im Überblick – jetzt lesen.','Gemeindepaket','["Gemeindepaket","Reformpartnerschaft","Gemeinden Reform 2026","Kooperation statt Zwangsfusion","Gemeindebund Pressl","digitale Verwaltung Gemeinde","Bauverfahren Instanzenzug Gemeinde","Digital Überall Workshops"]','Gemeindeamt mit Laptop und Formularen als Symbolbild zum Gemeindepaket','Photorealistic editorial photo of a small Austrian municipal office in a rural town hall, laptop and tablet on a counter next to paper forms, morning sun through old windows, vaulted ceiling, no text, no logos, no readable signs, no people','[{"q":"Was ist das Gemeindepaket der Reformpartnerschaft?","a":"Ein Maßnahmenbündel von Bund und Gemeindebund für einfachere Verwaltung: mehr Kooperation zwischen Gemeinden, schnellere Verfahren, Digitalisierung und weniger Bürokratie."},{"q":"Werden Gemeinden zwangsweise zusammengelegt?","a":"Nein, das Paket setzt ausdrücklich auf Kooperation statt Zwangsfusion. Die Zusammenarbeit zwischen Gemeinden soll erleichtert werden."},{"q":"Wann starten die Workshops „Digital Überall“?","a":"Die kostenlosen Workshops sollen ab Dezember 2026 angeboten werden, bis Ende 2027 sind bis zu 3.000 Termine geplant."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('gemeindefinanzen-burgenland-buergermeister-entlastung','Gemeindefinanzen Burgenland: Bürgermeister fordern rasche Entlastung','ÖVP-Bürgermeister aus dem Burgenland warnen vor einer Schieflage der Gemeindefinanzen und fordern vom Land ein Darlehensprogramm sowie transparente Förderregeln.','Die Gemeindefinanzen Burgenland geraten laut ÖVP-Bürgermeistern zunehmend unter Druck. Bei einem Pressetermin in Eisenstadt forderten am 19. Oktober 2026 rund 20 Ortschefinnen und Ortschefs eine rasche Entlastung der burgenländischen Gemeinden durch das Land.

## Gemeindefinanzen Burgenland: Die Zahlen hinter der Warnung

Die Bürgermeister stützen sich auf die mittelfristige Finanzplanung. Demnach soll der Saldo der laufenden Gebarung der Gemeinden von plus 71,3 Millionen Euro im Jahr 2025 auf minus 22 Millionen Euro im Jahr 2030 sinken. Der Saldo der laufenden Gebarung zeigt, ob eine Gemeinde ihre laufenden Ausgaben – etwa für Personal, Kinderbetreuung oder Sozialleistungen – aus den laufenden Einnahmen decken kann. Ist er negativ, fehlt Geld für Investitionen, und Schulden steigen.

Gemeindebund-Präsident Markus Ulram warnte, die Gemeinden würden zunehmend ihre finanzielle Handlungsfähigkeit verlieren, wenn jetzt nicht gegengesteuert werde.

## Forderung nach Darlehensprogramm und fairer Förderung

Eisenstadts Bürgermeister Thomas Steiner schlug ein Darlehensprogramm des Landes im Umfang von 100 Millionen Euro vor, bei dem das Land die Zinsen übernehmen soll. Ollersdorfs Bürgermeister Bernd Strobl verlangte eine transparentere Vergabe von Förderungen und die Gleichbehandlung aller Gemeinden.

Der Gemeindebund will einen Antrag im Landtag einbringen, der vier Punkte umfasst:

1. eine Deckelung der Abzüge von den Ertragsanteilen der Gemeinden
2. transparente Regeln für Projektbedarfszuweisungen
3. die sofortige Auszahlung bereits fälliger Fördermittel
4. eine stärkere Unterstützung bei Investitionen

Zusätzlich wird die Wiedereinführung der Güterwegförderung gefordert, die für ländliche Gemeinden mit vielen Wirtschaftswegen wichtig ist.

## Was das Land Burgenland entgegnet

Das Land verweist auf eine Förderoffensive für Klimaschutz und Energieeffizienz mit einem Volumen von mehr als vier Millionen Euro. Rund 20 Gemeinden hätten bereits Genehmigungen erhalten, die Investitionen von etwa 5,5 Millionen Euro auslösen sollen.

## Warum Gemeindefinanzen in ganz Österreich ein Thema sind

Die Lage im Burgenland ist kein Einzelfall. Österreichweit klagen Gemeinden über steigende Ausgaben bei Kinderbetreuung, Pflege, Gesundheit und Personal, während die Einnahmen nicht im selben Ausmaß wachsen. Gemeinden finanzieren sich vor allem über Ertragsanteile an den gemeinschaftlichen Bundesabgaben, über eigene Abgaben wie die Kommunalsteuer und die Grundsteuer sowie über Gebühren.

Gleichzeitig fließen über Umlagen Mittel an die Länder zurück, etwa für Sozialhilfe oder Krankenanstalten. Genau diese Abzüge stehen im Burgenland nun in der Kritik. Für die Bevölkerung kann eine angespannte Finanzlage bedeuten, dass Projekte wie Straßensanierungen, neue Kindergärten oder Sportanlagen verschoben werden.

Auf Bundesebene wird die Finanzierung der Gemeinden im Rahmen der Reformpartnerschaft verhandelt. Auch das Finanzministerium betont, dass Bund, Länder und Gemeinden gemeinsam zur Budgetkonsolidierung beitragen müssen. Wie sich das Land Burgenland zu den konkreten Forderungen positioniert, dürfte sich spätestens bei der Behandlung des Antrags im Landtag zeigen.

Wer wissen will, wie es um die Finanzen der eigenen Gemeinde steht, kann den Voranschlag und den Rechnungsabschluss einsehen. Beide werden vom Gemeinderat beschlossen und sind öffentlich zugänglich, viele Gemeinden veröffentlichen sie auch online. Zusätzlich bietet das Portal offenerhaushalt.at vergleichbare Finanzdaten zu österreichischen Gemeinden.','politik','Gemeinden','burgenland','news','Presseinfo Redaktion','/assets/img/artikel/gemeindefinanzen-burgenland-buergermeister-entlastung.webp','MeinBezirk.at','https://www.meinbezirk.at/burgenland/c-politik/oevp-gemeinden-alarmieren-vor-finanzsituation_a8958315','published','2026-10-19T14:23:00.000Z','2026-10-22T00:17:07.890Z','Gemeindefinanzen Burgenland: Bürgermeister schlagen Alarm','Gemeindefinanzen Burgenland: 20 Bürgermeister fordern Entlastung, ein Darlehensprogramm und transparente Förderungen. Die Forderungen im Überblick lesen.','Gemeindefinanzen Burgenland','["Gemeindefinanzen Burgenland","Gemeinden Burgenland Finanzen","Ertragsanteile Gemeinden","Bedarfszuweisungen Burgenland","Gemeindebund Burgenland","Eisenstadt Steiner Darlehen","Güterwegförderung","Gemeindebudget 2027"]','Burgenländisches Dorf mit Kirche als Symbolbild zu den Gemeindefinanzen Burgenland','Photorealistic editorial photo of a small village in Burgenland with a church tower, vineyards and a narrow rural road in golden late afternoon autumn light, aerial drone perspective, no text, no logos, no readable signs, no identifiable people','[{"q":"Wie steht es um die Gemeindefinanzen im Burgenland?","a":"Laut mittelfristiger Planung soll der Saldo der laufenden Gebarung der Gemeinden von plus 71,3 Millionen Euro 2025 auf minus 22 Millionen Euro 2030 sinken."},{"q":"Was fordern die Bürgermeister vom Land?","a":"Unter anderem ein zinsfreies Darlehensprogramm über 100 Millionen Euro, gedeckelte Abzüge von den Ertragsanteilen und transparente Bedarfszuweisungen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('ukrainer-in-oesterreich-schutzstatus-wehrfaehige-maenner','Ukrainer in Österreich: Kein automatischer Schutz für wehrfähige Männer','Österreich setzt einen EU-Beschluss um: Wehrfähige Männer aus der Ukraine, die neu einreisen, erhalten nicht mehr automatisch vorübergehenden Schutz.','Für Ukrainer in Österreich ändern sich die Regeln beim vorübergehenden Schutz. Der Ministerrat hat am 30. September 2026 eine Änderung der Vertriebenen-Verordnung beschlossen: Wehrfähige Männer aus der Ukraine erhalten künftig nicht mehr automatisch einen Schutzstatus. Österreich setzt damit einen Beschluss auf EU-Ebene um.

## Wen die neue Regel für Ukrainer in Österreich betrifft

Die Änderung gilt nur für Männer, die neu in die Europäische Union einreisen. Erfasst sind Anträge, die seit Anfang August gestellt wurden. Wer bereits vorübergehenden Schutz in Österreich hat, verliert diesen nicht. Für Frauen, Kinder, ältere Menschen und andere Vertriebene aus der Ukraine bleibt der Schutz bestehen.

Neu einreisende wehrfähige Männer müssen künftig nachweisen, dass sie ihren Wehrdienst erfüllt haben oder sich diesem nicht illegal entzogen haben. Gelingt das nicht, bleibt ihnen nur ein regulärer Asylantrag, bei dem auch subsidiärer Schutz geprüft wird. Wird ein solcher Antrag negativ entschieden, droht die Abschiebung.

## Europa: Vorübergehender Schutz bis März 2028 verlängert

Der vorübergehende Schutz für Vertriebene aus der Ukraine beruht auf einer EU-Richtlinie, die nach dem russischen Angriff im Februar 2022 erstmals aktiviert wurde. Sie ermöglicht es, Geflüchteten rasch Aufenthalt, Zugang zum Arbeitsmarkt und Grundversorgung zu gewähren, ohne dass jeder Einzelfall in einem Asylverfahren geprüft werden muss.

Für die übrigen ukrainischen Vertriebenen wurde dieser Schutz auf EU-Ebene bis 4. März 2028 verlängert. Die Mitgliedstaaten setzen die Vorgaben national um, in Österreich über die Vertriebenen-Verordnung. Nicht alle Staaten ziehen gleich: Ungarn gewährt Männern, die sich dem Wehrdienst entziehen, laut Berichten weiterhin Schutz.

## Zahlen: Wie viele Ukrainer in Österreich leben

In Österreich sind rund 94.100 ukrainische Staatsangehörige registriert. Ein großer Teil von ihnen lebt in Wien, viele weitere in den übrigen Bundesländern. Zahlreiche Vertriebene sind inzwischen berufstätig, Kinder und Jugendliche besuchen Schulen und Kindergärten.

## Was Betroffene jetzt beachten sollten

Für Ukrainerinnen und Ukrainer, die bereits einen Ausweis für Vertriebene besitzen, ändert sich durch die Verordnung nichts. Wichtig bleibt, den Ausweis rechtzeitig zu verlängern und Änderungen beim Wohnsitz zu melden. Informationen zu Registrierung und Verlängerung stellt das Bundesamt für Fremdenwesen und Asyl bereit.

Neu ankommende Männer im wehrfähigen Alter sollten vor der Einreise prüfen, welche Nachweise sie benötigen. Beratung bieten unter anderem Hilfsorganisationen und Rechtsberatungsstellen. Die Regierung begründet den Schritt mit der gemeinsamen europäischen Linie; Kritik kommt von Organisationen, die vor zusätzlichen Asylverfahren und Unsicherheit für Betroffene warnen.

## Ukrainer in Österreich: Rechte mit Vertriebenen-Ausweis

Wer den Status als Vertriebener hat, darf sich in Österreich aufhalten und hat Zugang zum Arbeitsmarkt, ohne dass eine eigene Beschäftigungsbewilligung nötig ist. Zudem besteht Anspruch auf Leistungen der Grundversorgung, solange keine ausreichenden eigenen Mittel vorhanden sind. Kinder unterliegen der Schulpflicht. Seit einiger Zeit gibt es außerdem die Möglichkeit, unter bestimmten Voraussetzungen in eine Rot-Weiß-Rot-Karte plus zu wechseln, die einen längerfristigen Aufenthalt ermöglicht. Die genauen Bedingungen dafür sollten Betroffene bei den zuständigen Behörden oder Beratungsstellen erfragen.','politik','Europa',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/ukrainer-in-oesterreich-schutzstatus-wehrfaehige-maenner.webp','ORF.at','https://orf.at/stories/3443689/','published','2026-09-30T12:37:00.000Z','2026-10-22T00:17:07.891Z','Ukrainer in Österreich: Neue Regeln beim Schutzstatus','Ukrainer in Österreich: Neu einreisende wehrfähige Männer erhalten keinen automatischen Schutzstatus mehr. Wer betroffen ist und wer nicht – hier lesen.','Ukrainer in Österreich','["Ukrainer in Österreich","Vertriebenenverordnung","Schutzstatus Ukraine","vorübergehender Schutz Ukraine 2028","wehrfähige Männer Ukraine","EU Beschluss Ukrainer","Ministerrat 30. September","Vertriebene Ukraine Österreich"]','Koffer am Bahnsteig als Symbolbild zum Schutzstatus für Ukrainer in Österreich','Photorealistic editorial photo of a quiet Vienna railway station platform at dusk with suitcases and a backpack resting on a bench, departure area lights glowing, long perspective of tracks, no text, no logos, no readable signs, no identifiable people','[{"q":"Verlieren Ukrainer in Österreich ihren Schutzstatus?","a":"Nein, wer bereits vorübergehenden Schutz hat, behält ihn. Die neue Regel betrifft nur wehrfähige Männer, die neu in die EU einreisen."},{"q":"Wie lange gilt der Schutz für Vertriebene aus der Ukraine?","a":"Der vorübergehende Schutz wurde auf EU-Ebene bis 4. März 2028 verlängert."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('klima-sozialplan-oesterreich-eu-einreichung','Klima-Sozialplan: Regierung beschließt Einreichung bei der EU','Der Ministerrat hat die Einreichung des Klima-Sozialplans 2026–2032 beschlossen. Mit EU-Mitteln sollen einkommensschwache Haushalte bei Sanierung und Mobilität unterstützt werden.','Der Klima-Sozialplan Österreichs ist auf dem Weg nach Brüssel. Der Ministerrat hat am 21. Oktober 2026 die Vorlage und Umsetzung des Klima-Sozialplans für die Jahre 2026 bis 2032 beschlossen. Der Plan regelt, wie Österreich Mittel aus dem EU-Klima-Sozialfonds einsetzt.

## Wozu der Klima-Sozialplan dient

Hintergrund ist das neue EU-Emissionshandelssystem für Gebäude und Straßenverkehr, kurz ETS2. Es soll den CO2-Ausstoß beim Heizen mit fossilen Brennstoffen und beim Tanken bepreisen. Damit das nicht vor allem Menschen mit geringem Einkommen trifft, hat die EU einen Klima-Sozialfonds eingerichtet. Rechtsgrundlage ist die Verordnung (EU) 2023/955.

Jeder Mitgliedstaat muss einen Klima-Sozialplan vorlegen, um an die Mittel zu kommen. Darin muss er Maßnahmen für besonders betroffene Gruppen festlegen: benachteiligte Haushalte, energiearme Haushalte, von Mobilitätsarmut betroffene Menschen sowie benachteiligte Kleinstunternehmen.

## Wie viel Geld der Klima-Sozialplan bringt

Laut Finanzministerium stehen Österreich aus dem Klima-Sozialfonds bis zu 577,8 Millionen Euro zur Verfügung. Hinzu kommt ein nationaler Kofinanzierungsanteil von mindestens 25 Prozent der geschätzten Gesamtkosten. Insgesamt ergibt das rund 770,4 Millionen Euro, die bis 2032 eingesetzt werden können.

## Geplante Maßnahmen: Sanierung, Heizung, Mobilität

Ein technischer Entwurf vom August 2026 sieht sieben Investitionsmaßnahmen vor:

- **Gebäude (vier Maßnahmen):** thermische Sanierung und Heizungstausch für vulnerable und einkommensschwache Haushalte, sowohl in Einfamilien- als auch in Mehrparteienhäusern, dazu eine gezielte Energieberatung.
- **Verkehr (drei Maßnahmen):** emissionsfreie Fahrzeuge für benachteiligte Regionen und für Kleinstunternehmen sowie Rad- und Fußwege in benachteiligten Gebieten.

Zum Entwurf gab es zwei öffentliche Konsultationen, im Sommer 2025 und im Sommer 2026. Die Stellungnahmen aus der zweiten Runde wurden laut Ministerium ausgewertet.

## Was der Klima-Sozialplan für Haushalte bedeutet

Für Mieterinnen, Mieter und Eigentümer mit geringem Einkommen könnten sich in den kommenden Jahren neue Förderschienen ergeben, etwa für den Umstieg von Öl- oder Gasheizungen. Welche Programme konkret kommen, wie hoch die Zuschüsse sind und wo man sie beantragt, ist aber erst nach der Genehmigung durch die EU-Kommission und der Ausgestaltung der einzelnen Förderungen klar. Bis dahin gelten die bestehenden Förderungen von Bund und Ländern.

Für Gemeinden in strukturschwachen Regionen ist vor allem der Verkehrsteil interessant: Investitionen in Rad- und Fußwege sowie emissionsfreie Mobilität könnten dort mitfinanziert werden. Wer eine Sanierung oder einen Heizungstausch plant, sollte die Entwicklung beobachten und sich bei den Energieberatungsstellen des jeweiligen Bundeslandes informieren.

Der Klima-Sozialplan ist Teil einer breiteren Klimapolitik auf EU-Ebene. Die EU-Kommission prüft die eingereichten Pläne und kann Änderungen verlangen, bevor Gelder fließen.

## Klima-Sozialplan und ETS2: Der Zeitplan

Der Emissionshandel für Gebäude und Verkehr soll auf EU-Ebene in den kommenden Jahren starten. Damit die Unterstützung rechtzeitig greift, sollen Mittel aus dem Klima-Sozialfonds bereits vorab fließen können. Österreich hat in Teilbereichen schon Erfahrung mit CO2-Bepreisung: Seit 2022 gilt die nationale CO2-Bepreisung, deren Einnahmen teilweise über den Klimabonus zurückgegeben wurden, bevor dieser im Zuge der Budgetkonsolidierung abgeschafft wurde. Mit dem ETS2 wird die Bepreisung künftig europaweit einheitlich geregelt.','politik','Europa',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/klima-sozialplan-oesterreich-eu-einreichung.webp','Bundeskanzleramt – 67. Ministerrat','https://www.bundeskanzleramt.gv.at/medien/ministerraete/ministerraete-seit-maerz-2025/67-mr-21-okt.html','published','2026-10-21T10:16:00.000Z','2026-10-22T00:17:07.891Z','Klima-Sozialplan: Regierung reicht Plan bei EU ein','Klima-Sozialplan 2026–2032: Rund 770 Millionen Euro für Sanierung, Heizungstausch und Mobilität. Was der Plan vorsieht und wer profitiert – jetzt lesen.','Klima-Sozialplan','["Klima-Sozialplan","Klima-Sozialfonds","KSP Österreich","ETS2 Österreich","Heizungstausch einkommensschwache Haushalte","Energiearmut Förderung","Ministerrat 21. Oktober","Sanierung Förderung EU"]','Mehrparteienhaus mit Dämmung als Symbolbild zum Klima-Sozialplan Österreich','Photorealistic editorial photo of an older Austrian multi-family apartment building in Graz under renovation with scaffolding and fresh insulation panels, heat pump unit in the courtyard, crisp autumn morning light, three-quarter street-level view, no text, no logos, no readable signs, no identifiable people','[{"q":"Was ist der Klima-Sozialplan?","a":"Der Plan legt fest, wie Österreich Mittel aus dem EU-Klima-Sozialfonds verwendet, um einkommensschwache Haushalte und Kleinstunternehmen bei steigenden CO2-Kosten zu unterstützen."},{"q":"Wie viel Geld steht im Klima-Sozialplan zur Verfügung?","a":"Bis zu 577,8 Millionen Euro kommen von der EU, mit nationaler Kofinanzierung sind es rund 770,4 Millionen Euro bis 2032."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('wahlkarte-beantragen-fristen-ablauf','Wahlkarte beantragen: Fristen, Ablauf und Briefwahl erklärt','Wer am Wahltag nicht ins eigene Wahllokal kann, braucht eine Wahlkarte. So funktioniert der Antrag – und diese Fristen sollten Sie kennen.','Eine Wahlkarte beantragen sollten alle, die am Wahltag nicht in ihrem zuständigen Wahllokal wählen können – etwa wegen einer Reise, eines Krankenhausaufenthalts oder weil sie lieber per Brief wählen. Mit der Wahlkarte kann man bei bundesweiten Wahlen per Briefwahl abstimmen oder in einem anderen Wahllokal wählen. Der Ablauf ist einfach, die Fristen sind aber streng.

## Wo man eine Wahlkarte beantragen kann

Zuständig ist immer die Gemeinde, in deren Wählerverzeichnis man eingetragen ist – in Wien ist das der Magistrat, in den anderen Bundesländern das Gemeindeamt. Es gibt drei Wege:

- **Online:** über die Website der Gemeinde oder über oesterreich.gv.at, am einfachsten mit ID Austria. Ohne ID Austria muss in der Regel die Passnummer oder ein anderes Ausweisdokument angegeben werden.
- **Schriftlich:** per Post oder E-Mail mit Angabe von Name, Geburtsdatum, Adresse und Identitätsnachweis.
- **Persönlich:** direkt im Gemeindeamt oder Wahlreferat, mit amtlichem Lichtbildausweis.

Telefonisch ist ein Antrag nicht möglich. Für eine andere Person kann man nur mit schriftlicher Vollmacht persönlich beantragen und abholen.

## Fristen: Bis wann man die Wahlkarte beantragen muss

Bei Nationalratswahlen, Bundespräsidentenwahlen und EU-Wahlen gilt grundsätzlich:

1. Schriftliche und Online-Anträge müssen spätestens am vierten Tag vor dem Wahltag bei der Gemeinde einlangen, das ist meist der Mittwoch vor dem Wahlsonntag.
2. Persönlich kann man die Wahlkarte bis zum zweiten Tag vor dem Wahltag, also dem Freitag, bis 12 Uhr beantragen.

Bei Landtags- und Gemeinderatswahlen regeln die Bundesländer die Fristen selbst, sie können abweichen. Die genauen Termine stehen in der amtlichen Wahlinformation, die vor jeder Wahl an alle Haushalte geht. Tipp: Möglichst früh beantragen, denn die Zustellung per Post dauert einige Tage.

## Briefwahl: So wird die Stimme gültig

Die Wahlkarte kommt meist eingeschrieben per Post. Darin liegen der amtliche Stimmzettel und ein Wahlkuvert. Wichtig für eine gültige Stimme:

- Stimmzettel ausfüllen und in das kleine Wahlkuvert legen, dieses zukleben.
- Das Wahlkuvert in die Wahlkarte legen und die Wahlkarte verschließen.
- Die eidesstattliche Erklärung auf der Wahlkarte **eigenhändig unterschreiben** – ohne Unterschrift ist die Stimme ungültig.
- Die Wahlkarte rechtzeitig abschicken. Sie muss spätestens am Wahltag um 17 Uhr bei der zuständigen Bezirkswahlbehörde einlangen. Das Porto übernimmt der Staat.

Alternativ kann die ausgefüllte Wahlkarte auch persönlich abgegeben werden. Wo das möglich ist, steht auf der Wahlkarte und in den Informationen der Gemeinde.

## Wahlkarte verloren oder nicht angekommen?

Eine verlorene oder nicht zugestellte Wahlkarte wird grundsätzlich nicht ersetzt. Deshalb lohnt es sich, die Sendung nach Möglichkeit zu verfolgen und bei Verzögerungen rasch bei der Gemeinde nachzufragen. Wer mit Wahlkarte doch ins Wahllokal geht, muss sie unbeschädigt mitbringen – mit einer Wahlkarte kann man in jedem geöffneten Wahllokal wählen, das Wahlkarten annimmt.

## Besondere Fälle: Krankheit und Ausland

Wer bettlägerig ist, kann zusätzlich den Besuch einer sogenannten fliegenden Wahlkommission beantragen. Auslandsösterreicherinnen und Auslandsösterreicher, die in der Wählerevidenz eingetragen sind, können sich die Wahlkarte automatisch für mehrere Jahre zuschicken lassen. Für die Rücksendung aus dem Ausland sollte man mehr Zeit einplanen.

Die Wahlkarte beantragen ist damit in wenigen Minuten erledigt – entscheidend ist nur, die Fristen im Blick zu behalten und die Unterschrift nicht zu vergessen.','politik','Innenpolitik',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/wahlkarte-beantragen-fristen-ablauf.webp',NULL,NULL,'published','2026-09-23T06:14:00.000Z','2026-10-22T00:17:07.891Z','Wahlkarte beantragen: Fristen und Ablauf','Wahlkarte beantragen leicht gemacht: online, schriftlich oder persönlich. Alle Fristen, nötige Daten und Tipps zur Briefwahl – jetzt nachlesen.','Wahlkarte beantragen','["Wahlkarte beantragen","Wahlkarte online beantragen","Briefwahl Österreich","Wahlkarte Frist","Wahlkarte ID Austria","Wahlkarte Wien beantragen","Wahlkarte abgeben Wahltag","Briefwahl Unterschrift ungültig"]','Hand wirft Kuvert in Briefkasten als Symbolbild zum Thema Wahlkarte beantragen','Photorealistic editorial close-up of a hand dropping a sealed beige envelope into a yellow Austrian street mailbox on a sunny autumn morning in a Vienna residential street, shallow depth of field, no text, no logos, no readable signs, face not visible','[{"q":"Bis wann kann man eine Wahlkarte beantragen?","a":"Bei bundesweiten Wahlen schriftlich oder online bis zum vierten Tag vor der Wahl, persönlich bis zum zweiten Tag vor der Wahl um 12 Uhr."},{"q":"Kostet die Briefwahl etwas?","a":"Nein, die Wahlkarte ist kostenlos und das Porto für die Rücksendung im Inland wird übernommen."},{"q":"Warum ist meine Briefwahlstimme ungültig?","a":"Häufigster Grund ist eine fehlende Unterschrift auf der eidesstattlichen Erklärung. Auch zu spät eingelangte oder beschädigte Wahlkarten werden nicht gezählt."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('volksbegehren-unterschreiben-online-gemeindeamt','Volksbegehren unterschreiben: Online oder am Gemeindeamt','Ein Volksbegehren kann man online oder in jeder Gemeinde unterstützen. Ab 100.000 Unterschriften muss der Nationalrat das Anliegen behandeln.','Ein Volksbegehren unterschreiben ist in Österreich ein direkter Weg, ein politisches Anliegen in den Nationalrat zu bringen. Möglich ist das bequem online oder persönlich in jeder Gemeinde. Wer die Regeln kennt, vermeidet doppelte Wege und ungültige Unterschriften.

## Wer ein Volksbegehren unterschreiben darf

Unterschreiben dürfen alle österreichischen Staatsbürgerinnen und Staatsbürger, die spätestens am letzten Tag der Eintragungswoche das 16. Lebensjahr vollendet haben und in der Wählerevidenz einer Gemeinde eingetragen sind. Auch Auslandsösterreicherinnen und Auslandsösterreicher mit Eintrag in der Wählerevidenz sind berechtigt. Jede Person darf ein bestimmtes Volksbegehren nur einmal unterstützen.

## Die zwei Phasen eines Volksbegehrens

Ein Volksbegehren durchläuft zwei Stufen:

1. **Einleitungsverfahren:** Die Initiatorinnen und Initiatoren sammeln Unterstützungserklärungen. Nötig sind Unterschriften von einem Promille der Wohnbevölkerung. Dann kann beim Innenministerium die Einleitung beantragt werden.
2. **Eintragungsverfahren:** Das Innenministerium legt eine Eintragungswoche fest, die acht Tage dauert. In dieser Zeit können alle Berechtigten unterschreiben.

Wichtig: Wer bereits eine Unterstützungserklärung abgegeben hat, wird automatisch mitgezählt und muss in der Eintragungswoche nicht noch einmal unterschreiben.

## Volksbegehren online unterschreiben

Am schnellsten geht es online über das Zentrale Wählerregister des Innenministeriums oder über oesterreich.gv.at. Dafür braucht man die ID Austria. So funktioniert es:

- Liste der aktuellen Volksbegehren aufrufen und das gewünschte auswählen.
- Mit ID Austria anmelden und die Identität bestätigen.
- Unterstützung abgeben – fertig. Eine Bestätigung erscheint sofort.

Online-Unterschriften sind rund um die Uhr möglich, sowohl in der Phase der Unterstützungserklärungen als auch während der Eintragungswoche.

## Volksbegehren am Gemeindeamt unterschreiben

Ohne ID Austria kann man in jeder Gemeinde Österreichs unterschreiben – nicht nur in der eigenen Wohngemeinde. In Wien ist das in den Magistratischen Bezirksämtern möglich. Mitzubringen ist ein amtlicher Lichtbildausweis. Unterstützungserklärungen kann man während der Öffnungszeiten der Gemeinde abgeben, in der Eintragungswoche gelten eigene Eintragungszeiten, die die Gemeinden kundmachen.

## Was nach dem Volksbegehren passiert

Erreicht ein Volksbegehren 100.000 Unterschriften oder ein Sechstel der Stimmberechtigten in drei Bundesländern, muss der Nationalrat es behandeln. Das Anliegen wird einem Ausschuss zugewiesen, die Initiatorinnen und Initiatoren haben dort ein Recht auf Anhörung. Ein Volksbegehren ist allerdings nicht bindend: Der Nationalrat muss darüber beraten, aber kein Gesetz beschließen.

Eine Übersicht über alle laufenden Volksbegehren, deren Text und die Eintragungszeiträume veröffentlicht das Innenministerium. Im Juni 2026 lief etwa eine Eintragungswoche für fünf Volksbegehren, darunter Anliegen zum Karfreitag als Feiertag und zur Transparenz im Parlament. Wer regelmäßig nachsieht, verpasst keine Frist.

Volksbegehren unterschreiben kostet nichts und dauert online nur wenige Minuten. Bevor man unterschreibt, lohnt es sich, den Text des Begehrens genau zu lesen – unterstützt wird immer der konkrete Gesetzesvorschlag oder das formulierte Anliegen.

Wer ein Volksbegehren selbst starten möchte, muss einen Bevollmächtigten benennen, einen Kostenbeitrag an das Innenministerium leisten und den Text des Anliegens genau formulieren. Erreicht das Begehren später mindestens 100.000 Unterschriften, wird ein Teil der Kosten pauschal ersetzt. Viele Initiativen nutzen zudem die Möglichkeit, über soziale Medien und Informationsstände auf ihr Anliegen aufmerksam zu machen.','politik','Parlament',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/volksbegehren-unterschreiben-online-gemeindeamt.webp',NULL,NULL,'published','2026-09-24T08:27:00.000Z','2026-10-22T00:17:07.892Z','Volksbegehren unterschreiben: So geht es','Volksbegehren unterschreiben: Wer darf, wie es online mit ID Austria klappt und ab wann der Nationalrat es behandeln muss. Jetzt lesen.','Volksbegehren unterschreiben','["Volksbegehren unterschreiben","Volksbegehren online unterschreiben","Volksbegehren ID Austria","Eintragungswoche Volksbegehren","Unterstützungserklärung Volksbegehren","Volksbegehren 100.000 Unterschriften","Volksbegehren Gemeindeamt","aktuelle Volksbegehren Österreich"]','Smartphone mit Identitätsbestätigung als Symbolbild zum Thema Volksbegehren unterschreiben','Photorealistic editorial photo of a person''s hands holding a smartphone with a blurred identity confirmation screen at a kitchen table in a Salzburg apartment, coffee cup and reading glasses nearby, soft morning light, no text, no logos, no readable signs, no face visible','[{"q":"Kann man ein Volksbegehren online unterschreiben?","a":"Ja, mit ID Austria über das Zentrale Wählerregister oder oesterreich.gv.at. Das ist rund um die Uhr möglich."},{"q":"Ab wie vielen Unterschriften muss der Nationalrat ein Volksbegehren behandeln?","a":"Ab 100.000 Unterschriften oder einem Sechstel der Stimmberechtigten in drei Bundesländern."},{"q":"Muss ich in der Eintragungswoche nochmals unterschreiben?","a":"Nein, wer bereits eine Unterstützungserklärung abgegeben hat, wird automatisch mitgezählt."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('politik-wien-gemeinderat-landtag-erklaert','Politik Wien: Wie Gemeinderat und Landtag zusammenarbeiten','Wien ist Stadt und Bundesland zugleich. Deshalb tagen dieselben 100 Abgeordneten einmal als Gemeinderat und einmal als Landtag – ein Überblick.','Politik Wien folgt einer Besonderheit, die es in Österreich nur einmal gibt: Wien ist gleichzeitig Gemeinde und Bundesland. Deshalb erfüllen dieselben Gremien eine Doppelrolle. Wer verstehen will, wer in Wien was entscheidet, sollte diese Struktur kennen.

## Politik Wien: Ein Gremium, zwei Rollen

Die Wienerinnen und Wiener wählen alle fünf Jahre 100 Abgeordnete. Diese bilden den Wiener Gemeinderat und zugleich den Wiener Landtag. Je nachdem, welche Aufgabe gerade behandelt wird, tagen sie in der einen oder der anderen Funktion:

- **Als Gemeinderat** beschließen sie Angelegenheiten der Gemeinde, etwa das Budget der Stadt, Flächenwidmungen, Förderungen, Tarife und Gebühren sowie Verträge.
- **Als Landtag** beschließen sie Landesgesetze, zum Beispiel die Bauordnung, Regelungen zu Kindergärten oder das Wiener Mindestsicherungsgesetz, und kontrollieren die Landesregierung.

Die Sitzungen finden im Rathaus statt. In der Regel tagt der Gemeinderat häufiger als der Landtag, weil viele Alltagsthemen Gemeindeangelegenheiten sind.

## Wer in Wien wählen darf

Bei der Wahl zum Gemeinderat und Landtag sind österreichische Staatsbürgerinnen und Staatsbürger ab 16 Jahren mit Hauptwohnsitz in Wien wahlberechtigt. Da der Gemeinderat zugleich Landtag ist, dürfen EU-Bürgerinnen und EU-Bürger hier nicht mitwählen. Sie können aber an den Wahlen der Bezirksvertretungen teilnehmen. Die letzte Wien-Wahl fand im April 2025 statt, danach bildeten SPÖ und NEOS eine Koalition.

## Ausschüsse, Fragestunde und Aktuelle Stunde

Ein großer Teil der Arbeit passiert in den Gemeinderatsausschüssen, die nach Themen gegliedert sind – etwa Finanzen, Wohnen, Bildung oder Klima. Dort werden Geschäftsstücke vorbereitet, bevor sie im Plenum beschlossen werden.

In den Sitzungen gibt es feste Kontrollinstrumente:

1. **Fragestunde:** Abgeordnete stellen Mitgliedern der Stadtregierung mündliche Fragen.
2. **Aktuelle Stunde:** Eine Fraktion bringt ein aktuelles Thema zur Debatte.
3. **Anträge und Anfragen:** Auch Oppositionsparteien können Anträge einbringen und schriftliche Anfragen stellen.

Zusätzlich gibt es Untersuchungskommissionen, die Missstände in der Verwaltung prüfen können, sowie den Stadtrechnungshof als Kontrollorgan.

## Sitzungen in Wien live verfolgen

Die Sitzungen von Gemeinderat und Landtag sind öffentlich. Interessierte können auf der Galerie im Rathaus zuhören, die Sitzungen werden außerdem im Internet live übertragen. Wörtliche Protokolle und Tagesordnungen veröffentlicht die Stadt auf wien.gv.at. Wer ein bestimmtes Thema sucht, findet dort auch Beschlüsse früherer Sitzungen.

## Politik Wien und die Bezirke

Unterhalb der Stadtebene gibt es 23 Bezirke mit eigenen Bezirksvertretungen und Bezirksvorstehungen. Sie entscheiden über bestimmte Budgets und lokale Angelegenheiten, etwa die Gestaltung von Parks, Gehsteigen oder Schulgebäuden im Bezirk. Für die großen Linien – Budget, Verkehr, Wohnbau – sind aber Gemeinderat, Landtag und Stadtregierung zuständig.

Die Doppelrolle macht Wien effizient, weil keine zwei getrennten Parlamente nötig sind. Gleichzeitig ist sie für viele Bürgerinnen und Bürger schwer zu durchschauen. Ein Blick auf die Tagesordnung zeigt aber rasch, ob gerade über ein Landesgesetz oder eine Gemeindeangelegenheit beraten wird.

Ein weiteres Instrument der Politik Wien ist die Volksbefragung. Der Gemeinderat kann die Bevölkerung zu Gemeindeangelegenheiten befragen, und auch ein bestimmter Anteil der Wahlberechtigten kann eine Befragung verlangen. Das Ergebnis ist rechtlich nicht bindend, hat aber politisches Gewicht. Die Stadt nutzte dieses Instrument in der Vergangenheit etwa zu Fragen der Parkraumbewirtschaftung oder zur Stadtplanung.','politik','Gemeinden','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/politik-wien-gemeinderat-landtag-erklaert.webp',NULL,NULL,'published','2026-09-25T07:41:00.000Z','2026-10-22T00:17:07.892Z','Politik Wien: Gemeinderat und Landtag erklärt','Politik Wien einfach erklärt: Warum der Gemeinderat zugleich Landtag ist, wer was beschließt und wie Sie Sitzungen verfolgen können. Jetzt lesen.','Politik Wien','["Politik Wien","Wiener Gemeinderat","Wiener Landtag","Gemeinderat Wien Sitzung","Wien Gemeinde und Bundesland","Wiener Stadtverfassung","Gemeinderat Wien Mitglieder","Wien Wahl 2025"]','Wiener Rathaus zur blauen Stunde als Symbolbild zum Thema Politik Wien','Photorealistic editorial photo of the Vienna City Hall neo-gothic facade at blue hour with warm illuminated windows, Rathauspark trees in autumn colors in foreground, wide angle from the park, no text, no logos, no readable signs, no identifiable people','[{"q":"Wie viele Mitglieder hat der Wiener Gemeinderat?","a":"Der Wiener Gemeinderat hat 100 Mitglieder, die zugleich den Wiener Landtag bilden."},{"q":"Dürfen EU-Bürger in Wien wählen?","a":"EU-Bürgerinnen und EU-Bürger dürfen in Wien nur die Bezirksvertretung wählen, nicht aber Gemeinderat und Landtag."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('buergermeister-wien-stadtregierung-aufgaben','Bürgermeister Wien: Aufgaben, Wahl und Rolle der Stadtregierung','Der Bürgermeister von Wien ist auch Landeshauptmann. Was er entscheidet, wie er gewählt wird und was amtsführende und nicht amtsführende Stadträte unterscheidet.','Der Bürgermeister Wien hat eine Doppelfunktion: Er ist Oberhaupt der Stadt und zugleich Landeshauptmann des Bundeslandes Wien. Seit 2018 übt Michael Ludwig (SPÖ) dieses Amt aus. Wer wissen will, wie die Stadtregierung funktioniert, muss die Rollen von Bürgermeister, Stadtsenat und Magistrat auseinanderhalten.

## Wie der Bürgermeister Wien gewählt wird

Anders als in mehreren anderen Bundesländern wird der Wiener Bürgermeister nicht direkt von der Bevölkerung gewählt. Die Wienerinnen und Wiener wählen den Gemeinderat, und dieser wählt den Bürgermeister. In der Praxis stellt die stärkste Partei oder Koalition den Bürgermeister. Nach der Wahl im April 2025 wurde Ludwig mit den Stimmen der Koalition aus SPÖ und NEOS wiedergewählt.

## Aufgaben des Bürgermeisters

Zu den wichtigsten Aufgaben zählen:

- **Leitung des Magistrats:** Der Bürgermeister ist Vorstand des Magistrats, also der gesamten Stadtverwaltung mit ihren Magistratsabteilungen.
- **Vorsitz im Stadtsenat:** Er leitet die Sitzungen der Stadtregierung.
- **Landeshauptmann:** Als Landeshauptmann vertritt er Wien gegenüber dem Bund und nimmt an der Landeshauptleutekonferenz teil. Zudem ist er für die mittelbare Bundesverwaltung in Wien verantwortlich.
- **Repräsentation:** Er vertritt die Stadt nach außen, etwa bei Partnerstädten und internationalen Organisationen.

## Stadtregierung Wien: Der Stadtsenat

Die Stadtregierung heißt in Wien Stadtsenat, als Landesregierung Wiener Landesregierung. Ihr gehören der Bürgermeister und die Stadträtinnen und Stadträte an. Eine Besonderheit ist die Unterscheidung zwischen zwei Arten von Stadträten:

1. **Amtsführende Stadträte** leiten eine Geschäftsgruppe, etwa Finanzen, Wohnen, Bildung oder Gesundheit. Sie haben ein eigenes Ressort und politische Verantwortung für die zugehörigen Magistratsabteilungen.
2. **Nicht amtsführende Stadträte** sitzen im Stadtsenat, haben aber kein Ressort. Sie stammen meist von Oppositionsparteien, weil die Sitze im Stadtsenat nach Stärke der Parteien im Gemeinderat vergeben werden.

Aus dem Kreis der Stadträte werden auch Vizebürgermeisterinnen und Vizebürgermeister gewählt.

## Was der Magistrat für Bürgerinnen und Bürger erledigt

Der Magistrat ist die Verwaltung, mit der Wienerinnen und Wiener im Alltag zu tun haben. Er stellt Meldezettel und Reisepässe aus, genehmigt Bauvorhaben, betreibt Kindergärten, kümmert sich um Parkraum und Müllabfuhr und vollzieht viele Bundesgesetze. Ansprechpartner vor Ort sind die Magistratischen Bezirksämter, die in den einzelnen Bezirken Amtswege anbieten.

## Bürgermeister Wien kontaktieren

Anliegen an die Stadtregierung können über das Büro des Bürgermeisters oder die Büros der zuständigen Stadträte eingebracht werden. Für konkrete Probleme – etwa Schäden auf der Straße oder Fragen zu Amtswegen – ist meist der direkte Weg zur zuständigen Magistratsabteilung oder zum Bürgerdienst der Stadt schneller. Auch der Wiener Stadtrechnungshof und die Volksanwaltschaft nehmen Beschwerden über die Verwaltung entgegen.

Das Amt des Bürgermeisters Wien ist damit eines der mächtigsten in der österreichischen Landespolitik. Seine Gestaltungsmacht hängt aber stark von der Mehrheit im Gemeinderat und der Zusammenarbeit innerhalb der Stadtregierung ab.

Die Zusammensetzung der Stadtregierung ändert sich in der Regel nach jeder Wahl. Koalitionsvereinbarungen legen fest, welche Partei welche Geschäftsgruppe übernimmt und welche Vorhaben in der Legislaturperiode umgesetzt werden sollen. Das Regierungsübereinkommen von SPÖ und NEOS ist auf der Website der Stadt öffentlich einsehbar.','politik','Gemeinden','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/buergermeister-wien-stadtregierung-aufgaben.webp',NULL,NULL,'published','2026-09-28T09:08:00.000Z','2026-10-22T00:17:07.892Z','Bürgermeister Wien: Aufgaben und Stadtregierung','Bürgermeister Wien ist zugleich Landeshauptmann. Wie er gewählt wird, was Stadtsenat und Stadträte tun und wer wofür zuständig ist – hier erklärt.','Bürgermeister Wien','["Bürgermeister Wien","Stadtregierung Wien","Stadtsenat Wien","amtsführende Stadträte","Landeshauptmann Wien","Michael Ludwig","Magistrat Wien Aufgaben","Vizebürgermeister Wien"]','Historischer Sitzungssaal als Symbolbild zu Bürgermeister Wien und Stadtregierung','Photorealistic editorial photo of an ornate historic meeting hall interior in a Viennese city hall with wooden panels, chandeliers and a long conference table, late afternoon golden light, symmetrical composition, no text, no logos, no readable signs, no people','[{"q":"Wird der Bürgermeister von Wien direkt gewählt?","a":"Nein, der Wiener Bürgermeister wird vom Gemeinderat gewählt, nicht direkt von der Bevölkerung."},{"q":"Was sind nicht amtsführende Stadträte?","a":"Sie gehören dem Stadtsenat an, leiten aber kein Ressort. Meist kommen sie aus Oppositionsparteien."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('nationalrat-gesetz-entstehung-ablauf','Nationalrat: Wie ein Gesetz in Österreich entsteht','Vom Entwurf bis zum Bundesgesetzblatt: Ein Gesetz durchläuft in Österreich mehrere Stationen. Der Nationalrat spielt dabei die zentrale Rolle.','Der Nationalrat ist das zentrale Gesetzgebungsorgan des Bundes. Seine 183 Abgeordneten beschließen Bundesgesetze, das Budget und Staatsverträge. Doch bis ein Gesetz im Bundesgesetzblatt steht, durchläuft es mehrere Schritte – vom ersten Entwurf bis zur Unterschrift des Bundespräsidenten.

## Wie ein Gesetz in den Nationalrat kommt

Gesetzesvorschläge können auf vier Wegen eingebracht werden:

- **Regierungsvorlage:** Der häufigste Weg. Ein Ministerium erarbeitet einen Entwurf, die Bundesregierung beschließt ihn einstimmig im Ministerrat und leitet ihn dem Nationalrat zu.
- **Initiativantrag:** Mindestens fünf Abgeordnete können selbst einen Gesetzesantrag einbringen.
- **Antrag des Bundesrates:** Auch die Länderkammer oder ein Drittel ihrer Mitglieder kann Gesetze vorschlagen.
- **Volksbegehren:** Ein Volksbegehren mit mindestens 100.000 Unterschriften muss behandelt werden.

## Begutachtung: Die Öffentlichkeit kann mitreden

Vor einer Regierungsvorlage steht meist ein Begutachtungsverfahren. Der Entwurf wird auf der Website des Parlaments veröffentlicht, und Interessenvertretungen, Länder, Gemeinden, aber auch Bürgerinnen und Bürger können Stellungnahmen abgeben. Die Ministerien sollen diese bei der Überarbeitung berücksichtigen. Initiativanträge durchlaufen keine verpflichtende Begutachtung, was immer wieder kritisiert wird.

## Ausschuss und drei Lesungen im Nationalrat

Im Nationalrat wird ein Gesetzesvorschlag meist zunächst einem Fachausschuss zugewiesen. Dort wird beraten, Expertinnen und Experten können angehört, Änderungen eingebracht werden. Der Ausschuss erstattet dann einen Bericht an das Plenum.

Im Plenum folgen formal drei Lesungen:

1. **Erste Lesung:** Eine allgemeine Debatte, die oft entfällt, weil der Vorschlag direkt dem Ausschuss zugewiesen wird.
2. **Zweite Lesung:** Die eigentliche Debatte über den Ausschussbericht, mit Abänderungsanträgen und Abstimmungen über einzelne Teile.
3. **Dritte Lesung:** Die Schlussabstimmung über das gesamte Gesetz.

Für ein einfaches Gesetz reicht die Mehrheit der abgegebenen Stimmen bei Anwesenheit von mindestens einem Drittel der Abgeordneten. Verfassungsgesetze brauchen eine Zweidrittelmehrheit bei Anwesenheit von mindestens der Hälfte der Abgeordneten.

## Bundesrat, Bundespräsident und Kundmachung

Nach dem Beschluss im Nationalrat geht das Gesetz an den Bundesrat. Dieser kann zustimmen, nichts unternehmen oder Einspruch erheben. Ein Einspruch hat meist nur aufschiebende Wirkung: Der Nationalrat kann mit einem Beharrungsbeschluss das Gesetz trotzdem durchsetzen.

Danach beurkundet der Bundespräsident das verfassungsmäßige Zustandekommen, der Bundeskanzler zeichnet gegen. Schließlich wird das Gesetz im Bundesgesetzblatt kundgemacht, das im Rechtsinformationssystem des Bundes (RIS) kostenlos abrufbar ist. In Kraft tritt es am Tag nach der Kundmachung, sofern kein anderer Zeitpunkt festgelegt ist.

## Nationalrat verfolgen: Gesetze im Blick behalten

Auf der Website des Parlaments lässt sich jedes Gesetzesvorhaben verfolgen – von der Begutachtung über die Ausschussberatung bis zum Beschluss. Ein aktuelles Beispiel ist das Binnenmarkt-Notfall- und Resilienzgesetz, das im Oktober 2026 als Regierungsvorlage im Nationalrat eingelangt ist. Wer Stellungnahmen abgeben möchte, sollte die Begutachtungsfristen beachten, die meist mehrere Wochen betragen.

Neben Gesetzen hat der Nationalrat weitere wichtige Aufgaben. Er kontrolliert die Bundesregierung, etwa mit schriftlichen und mündlichen Anfragen, Misstrauensanträgen oder Untersuchungsausschüssen. Zudem wirkt er an der EU-Politik mit: Der Hauptausschuss und der EU-Unterausschuss können Stellungnahmen beschließen, die Regierungsmitglieder bei Verhandlungen in Brüssel binden.','politik','Parlament',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/nationalrat-gesetz-entstehung-ablauf.webp',NULL,NULL,'published','2026-09-29T05:52:00.000Z','2026-10-22T00:17:07.892Z','Nationalrat: So entsteht ein Gesetz','Nationalrat erklärt: Von der Regierungsvorlage über Ausschuss und drei Lesungen bis zur Kundmachung im Bundesgesetzblatt. Jetzt lesen.','Nationalrat','["Nationalrat","Gesetz entsteht Österreich","Gesetzgebung Österreich","Regierungsvorlage","Initiativantrag","drei Lesungen Nationalrat","Begutachtung Gesetz","Bundesgesetzblatt Kundmachung"]','Gesetzestexte und Füllfeder als Symbolbild zur Gesetzgebung im Nationalrat','Photorealistic editorial still life of stacked bound legal documents and a fountain pen on a dark wooden desk in a historic library with tall bookshelves, warm side light, shallow depth of field, no text, no logos, no readable signs, no people','[{"q":"Wie viele Abgeordnete hat der Nationalrat?","a":"Der Nationalrat hat 183 Abgeordnete, die alle fünf Jahre gewählt werden."},{"q":"Wie lange dauert es, bis ein Gesetz beschlossen ist?","a":"Das ist sehr unterschiedlich. Mit Begutachtung, Ausschuss und Bundesrat dauert es meist mehrere Monate, dringende Gesetze können schneller beschlossen werden."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('eu-wahl-oesterreich-wahlrecht-ablauf','EU-Wahl in Österreich: Wahlrecht, Mandate und Ablauf','Alle fünf Jahre wählt Österreich seine Abgeordneten zum Europäischen Parlament. Wer wahlberechtigt ist und wie die Stimmen in Mandate umgerechnet werden.','Die EU-Wahl bestimmt, wer Österreich im Europäischen Parlament vertritt. Sie findet alle fünf Jahre statt, zuletzt im Juni 2024. Die nächste reguläre Europawahl ist 2029 vorgesehen. Viele Regeln ähneln der Nationalratswahl, es gibt aber wichtige Unterschiede – vor allem beim Wahlrecht von EU-Bürgerinnen und EU-Bürgern.

## Wer bei der EU-Wahl in Österreich wählen darf

Wahlberechtigt sind:

- österreichische Staatsbürgerinnen und Staatsbürger, die am Wahltag mindestens 16 Jahre alt sind, auch wenn sie im Ausland leben und in der Wählerevidenz eingetragen sind;
- Staatsangehörige anderer EU-Mitgliedstaaten mit Hauptwohnsitz in Österreich, die mindestens 16 Jahre alt sind und sich in die Europäische Wählerevidenz ihrer Gemeinde eintragen lassen.

EU-Bürgerinnen und EU-Bürger müssen sich entscheiden: Sie dürfen bei einer EU-Wahl nur einmal wählen, entweder in Österreich oder in ihrem Herkunftsland. Eine doppelte Stimmabgabe ist strafbar.

## So viele Abgeordnete stellt Österreich

Das Europäische Parlament hat derzeit 720 Mitglieder. Österreich stellt seit der Wahl 2024 insgesamt 20 Abgeordnete. Die Sitze werden nach Bevölkerungsgröße der Mitgliedstaaten verteilt, wobei kleinere Länder im Verhältnis mehr Sitze bekommen. Gewählt wird in Österreich in einem einzigen bundesweiten Wahlkreis.

Auf dem Stimmzettel kreuzt man eine Partei an. Zusätzlich kann man einer Kandidatin oder einem Kandidaten dieser Partei eine Vorzugsstimme geben, indem man den Namen oder die Reihungsnummer einträgt. Wer genügend Vorzugsstimmen erhält, kann auf der Liste nach vorne rücken. Die Hürde für den Einzug einer Partei liegt bei vier Prozent der gültigen Stimmen.

## Briefwahl und Wahlkarte bei der EU-Wahl

Auch bei der EU-Wahl kann man mit Wahlkarte per Brief wählen. Die Wahlkarte wird bei der Gemeinde beantragt, in der man im Wählerverzeichnis steht. Die Fristen entsprechen jenen der Nationalratswahl: Schriftliche und Online-Anträge spätestens am vierten Tag vor dem Wahltag, persönlich bis zum zweiten Tag vor dem Wahltag um 12 Uhr.

## EU-Wahl: Eintrag in die Europäische Wählerevidenz

EU-Bürgerinnen und EU-Bürger, die in Österreich wählen wollen, sollten den Eintrag in die Europäische Wählerevidenz rechtzeitig erledigen. Der Antrag erfolgt bei der Hauptwohnsitzgemeinde, in Wien beim Magistrat. Der Eintrag bleibt grundsätzlich bestehen, solange der Hauptwohnsitz in der Gemeinde gemeldet ist. Vor jeder Wahl gibt es einen Stichtag, bis zu dem die Eintragung erfolgt sein muss.

## Warum die EU-Wahl für Österreich wichtig ist

Viele Regeln, die den Alltag betreffen, entstehen auf europäischer Ebene – von Verbraucherschutz über Umweltstandards bis zu Binnenmarktregeln. Das Europäische Parlament beschließt EU-Gesetze gemeinsam mit dem Rat der EU, in dem die Regierungen der Mitgliedstaaten vertreten sind. Es wählt außerdem die Präsidentin oder den Präsidenten der EU-Kommission und stimmt dem EU-Budget zu.

Die Wahlbeteiligung bei EU-Wahlen war in Österreich lange niedriger als bei Nationalratswahlen, ist zuletzt aber gestiegen. Wer mitbestimmen will, wie europäische Regeln aussehen, hat mit der EU-Wahl die direkteste Möglichkeit dazu.

Wer am Wahltag im Ausland ist, kann die Wahlkarte auch an eine ausländische Adresse schicken lassen. Für die Rücksendung empfiehlt es sich, ausreichend Postlaufzeit einzuplanen oder die Wahlkarte bei einer österreichischen Vertretungsbehörde abzugeben, sofern diese das anbietet.','politik','Europa',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/eu-wahl-oesterreich-wahlrecht-ablauf.webp',NULL,NULL,'published','2026-09-30T06:19:00.000Z','2026-10-22T00:17:07.893Z','EU-Wahl Österreich: Wahlrecht und Ablauf','EU-Wahl in Österreich erklärt: Wer wählen darf, wie viele Abgeordnete Österreich stellt und wie EU-Bürger hier wählen können. Jetzt alle Fakten lesen.','EU-Wahl','["EU-Wahl","EU-Wahl Österreich","Europawahl Wahlrecht","Europäisches Parlament Österreich Abgeordnete","EU-Bürger wählen Österreich","Europawahl 2029","Vorzugsstimme EU-Wahl","Europäische Wählerevidenz"]','Parlamentsgebäude in Brüssel mit Fahnen als Symbolbild zur EU-Wahl in Österreich','Photorealistic editorial photo of a modern glass parliament building in Brussels at dusk with rows of European flags blurred by wind, reflection in a puddle on the plaza, cinematic low angle, no text, no logos, no readable signs, no identifiable people','[{"q":"Wie viele EU-Abgeordnete hat Österreich?","a":"Österreich stellt seit der Wahl 2024 insgesamt 20 Abgeordnete im Europäischen Parlament."},{"q":"Dürfen EU-Bürger in Österreich bei der EU-Wahl wählen?","a":"Ja, wenn sie ihren Hauptwohnsitz in Österreich haben und in der Europäischen Wählerevidenz eingetragen sind. Sie dürfen aber nur in einem Land wählen."},{"q":"Wann ist die nächste EU-Wahl?","a":"Die nächste reguläre Europawahl ist 2029 vorgesehen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('bezirksvertretung-wien-wahl-aufgaben','Bezirksvertretung Wien: Aufgaben, Wahl und Mitbestimmung','Jeder der 23 Wiener Bezirke hat ein eigenes Bezirksparlament. Was die Bezirksvertretung entscheidet und wie Bürgerinnen und Bürger mitreden können.','Die Bezirksvertretung Wien ist die politische Ebene, die dem Alltag der Wienerinnen und Wiener am nächsten ist. Jeder der 23 Bezirke hat ein eigenes Bezirksparlament, das über lokale Fragen mitentscheidet – vom neuen Zebrastreifen bis zur Umgestaltung eines Platzes. Hier können auch EU-Bürgerinnen und EU-Bürger wählen.

## Aufgaben der Bezirksvertretung Wien

Die Bezirksvertretungen verwalten ein eigenes Bezirksbudget, das ihnen die Stadt zuweist. Damit finanzieren sie unter anderem:

- die Instandhaltung von Pflichtschulgebäuden im Bezirk,
- kleinere Straßen-, Gehsteig- und Parkgestaltungen,
- Spielplätze, Grünflächen und Beleuchtung,
- lokale Kultur- und Jugendprojekte.

Darüber hinaus beraten die Bezirksvertretungen über Anliegen, die den Bezirk betreffen, und können Anträge an die Stadt richten. Bei vielen Vorhaben der Stadt, etwa Flächenwidmungen, werden sie angehört. Die endgültige Entscheidung liegt bei größeren Projekten aber meist beim Gemeinderat oder beim Magistrat.

## Bezirksvorsteherin und Bezirksvorsteher

An der Spitze des Bezirks steht die Bezirksvorsteherin oder der Bezirksvorsteher. Diese Person wird von der Bezirksvertretung gewählt und stammt in der Regel von der stimmenstärksten Partei im Bezirk. Sie vertritt den Bezirk nach außen, leitet die Sitzungen und ist erste Ansprechperson für Anliegen der Bevölkerung. Unterstützt wird sie von Stellvertreterinnen und Stellvertretern.

## Wer die Bezirksvertretung Wien wählt

Gewählt wird gemeinsam mit dem Gemeinderat alle fünf Jahre, zuletzt im April 2025. Wahlberechtigt sind österreichische Staatsbürgerinnen und Staatsbürger ab 16 Jahren mit Hauptwohnsitz im Bezirk. Anders als bei der Gemeinderatswahl dürfen auch Staatsangehörige anderer EU-Mitgliedstaaten mit Hauptwohnsitz in Wien teilnehmen. Für Wienerinnen und Wiener aus anderen EU-Ländern ist die Bezirksvertretungswahl damit die einzige Möglichkeit, auf kommunaler Ebene in Wien mitzuwählen.

## So bringen Sie Anliegen im Bezirk ein

Es gibt mehrere Wege, sich einzubringen:

1. **Sprechstunden:** Die Bezirksvorstehung bietet regelmäßig Sprechstunden an.
2. **Sitzungen besuchen:** Sitzungen der Bezirksvertretung sind grundsätzlich öffentlich. Termine stehen auf der Bezirksseite von wien.gv.at.
3. **Bürgerversammlung:** Zu wichtigen Bezirksthemen kann eine Bürgerversammlung einberufen werden, auch auf Verlangen einer bestimmten Zahl von Bezirksbewohnerinnen und -bewohnern.
4. **Petition:** Über die Petitionsplattform der Stadt Wien können Anliegen an den Petitionsausschuss des Gemeinderates gerichtet werden.
5. **Bezirksparteien und Kommissionen:** Viele Bezirke haben Ausschüsse oder Kommissionen, etwa für Verkehr oder Umwelt, die auch Anregungen aus der Bevölkerung aufgreifen.

## Bezirksvertretung Wien: Grenzen der Zuständigkeit

Nicht alles, was im Bezirk passiert, entscheidet der Bezirk. Große Verkehrsprojekte, U-Bahn-Bau, Wohnbauförderung oder das Parkpickerl werden von der Stadt geregelt. Dennoch hat die Bezirksvertretung Gewicht: Sie kennt die lokale Situation und ist für die Stadtpolitik ein wichtiger Gesprächspartner, wenn es um die Umsetzung vor Ort geht.

Die Größe der Bezirksvertretungen hängt von der Einwohnerzahl des Bezirks ab. Kleinere Innenbezirke haben weniger Mandate als große Flächenbezirke wie Favoriten, Floridsdorf oder Donaustadt. Die Sitzungen finden meist mehrmals im Jahr statt. Ein Blick auf die Tagesordnung lohnt sich, wenn im eigenen Grätzl größere Veränderungen geplant sind, etwa eine Begegnungszone, ein neuer Radweg oder die Umgestaltung eines Schulvorplatzes. Wer sich frühzeitig informiert, kann Einwände und Ideen noch einbringen, bevor Beschlüsse fallen.','politik','Gemeinden','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/bezirksvertretung-wien-wahl-aufgaben.webp',NULL,NULL,'published','2026-10-02T08:03:00.000Z','2026-10-22T00:17:07.893Z','Bezirksvertretung Wien: Aufgaben und Wahl','Bezirksvertretung Wien erklärt: Was die 23 Bezirke entscheiden, wer wählen darf und wie Sie Ihre Anliegen einbringen. Jetzt lesen.','Bezirksvertretung Wien','["Bezirksvertretung Wien","Bezirksvorsteher Wien","Bezirksvertretungswahl","Bezirksbudget Wien","EU-Bürger Wahlrecht Wien Bezirk","Bürgerversammlung Wien","Bezirksparlament Wien","Wiener Bezirke Mitbestimmung"]','Platz in einem Wiener Bezirk als Symbolbild zur Bezirksvertretung Wien','Photorealistic editorial photo of a lively Viennese neighborhood square in Ottakring with a small park, benches, young trees and a newly painted pedestrian crossing, morning autumn sun, eye-level street perspective, no text, no logos, no readable signs, no identifiable people','[{"q":"Wer darf die Bezirksvertretung in Wien wählen?","a":"Österreichische Staatsbürger ab 16 Jahren mit Hauptwohnsitz im Bezirk sowie EU-Bürger mit Hauptwohnsitz in Wien."},{"q":"Was entscheidet die Bezirksvertretung?","a":"Sie verwaltet ein eigenes Bezirksbudget, etwa für Schulgebäude, Parks, Spielplätze und kleinere Straßengestaltungen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('petition-buergerinitiative-nationalrat-einbringen','Petition an den Nationalrat: So bringen Sie ein Anliegen ein','Mit einer Petition oder Bürgerinitiative können Bürgerinnen und Bürger ein Anliegen direkt ins Parlament bringen. Was es dafür braucht und wie es weitergeht.','Eine Petition ist neben dem Volksbegehren das bekannteste Instrument, um ein Anliegen ins Parlament zu bringen. Im österreichischen Nationalrat gibt es dafür zwei Wege: die Petition, die von Abgeordneten eingebracht wird, und die Bürgerinitiative, die Bürgerinnen und Bürger mit eigenen Unterschriften starten. Beide landen im zuständigen Ausschuss.

## Petition: Mit Unterstützung von Abgeordneten

Eine Petition im engeren Sinn kann nur von einem Abgeordneten zum Nationalrat oder einem Mitglied des Bundesrates eingebracht werden. Bürgerinnen und Bürger, Vereine oder Gemeinden wenden sich also an eine Abgeordnete oder einen Abgeordneten, die das Anliegen überreichen. Eine bestimmte Zahl an Unterschriften ist dafür nicht vorgeschrieben. Viele Gemeinden nutzen diesen Weg, um auf lokale Probleme aufmerksam zu machen, etwa bei Verkehrsprojekten oder der Gesundheitsversorgung.

## Bürgerinitiative: 500 Unterschriften als Voraussetzung

Eine Bürgerinitiative kann direkt von Bürgerinnen und Bürgern eingebracht werden. Die wichtigsten Voraussetzungen:

- Das Anliegen muss eine Angelegenheit der Bundesgesetzgebung oder Bundesvollziehung betreffen.
- Mindestens 500 Personen müssen unterschreiben. Sie müssen das 16. Lebensjahr vollendet haben und zum Nationalrat wahlberechtigt sein.
- Eine Person übernimmt als Erstunterzeichnerin oder Erstunterzeichner die Verantwortung und ist Ansprechperson für das Parlament.

Die Unterschriften werden auf einem Unterschriftenblatt mit Name, Adresse, Geburtsdatum und Unterschrift gesammelt. Anschließend wird die Bürgerinitiative bei der Parlamentsdirektion eingereicht.

## Was im Petitionsausschuss passiert

Petitionen und Bürgerinitiativen werden im Ausschuss für Petitionen und Bürgerinitiativen behandelt. Dieser kann:

1. Stellungnahmen von Ministerien, Ländern oder Fachleuten einholen,
2. Anhörungen abhalten, bei denen auch die Initiatorinnen und Initiatoren zu Wort kommen,
3. das Anliegen einem Fachausschuss zuweisen,
4. einen Bericht an das Plenum des Nationalrates erstatten oder
5. die Behandlung abschließen, wenn er keinen weiteren Handlungsbedarf sieht.

Gerade die Anhörungen bieten eine Chance, das Thema öffentlich sichtbar zu machen. So hielt der Petitionsausschuss etwa am 22. Oktober 2026 eine gemeinsame Anhörung zu fünf Bürgeranliegen ab.

## Petition online unterstützen

Eingebrachte Petitionen und Bürgerinitiativen werden auf der Website des Parlaments veröffentlicht. Dort kann man sie nachträglich elektronisch unterstützen. Die Zahl der Unterstützungen ist zwar rechtlich nicht bindend, zeigt den Abgeordneten aber, wie groß das öffentliche Interesse ist. Man sieht dort auch, welche Stellungnahmen eingelangt sind und wie der Stand der Beratungen ist.

## Petition oder Volksbegehren: Was passt besser?

Eine Bürgerinitiative ist deutlich einfacher zu starten als ein Volksbegehren, weil nur 500 Unterschriften nötig sind. Dafür ist der politische Druck geringer. Ein Volksbegehren erfordert mehr Aufwand, wird aber im Plenum breiter diskutiert, wenn es 100.000 Unterschriften erreicht. Für lokale Anliegen, die Land oder Gemeinde betreffen, sind ohnehin die Petitionsrechte in den Bundesländern der richtige Weg – viele Landtage und auch der Wiener Gemeinderat haben eigene Petitionsverfahren.

Ein Tipp aus der Praxis: Je konkreter das Anliegen formuliert ist, desto eher wird es ernsthaft behandelt. Hilfreich sind eine klare Forderung, eine kurze Begründung mit Fakten und, wenn möglich, ein Vorschlag, welche gesetzliche Bestimmung geändert werden soll. Auch die Unterstützung durch Gemeinden, Vereine oder Fachleute kann einem Anliegen zusätzliches Gewicht verleihen.','politik','Parlament',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/petition-buergerinitiative-nationalrat-einbringen.webp',NULL,NULL,'published','2026-10-06T07:36:00.000Z','2026-10-22T00:17:07.893Z','Petition Nationalrat: Bürgerinitiative einbringen','Petition an den Nationalrat oder Bürgerinitiative starten: Voraussetzungen, 500 Unterschriften und Ablauf im Ausschuss. Jetzt lesen.','Petition','["Petition","Petition Nationalrat","Bürgerinitiative Nationalrat","Petitionsausschuss","Bürgerinitiative 500 Unterschriften","Anliegen Parlament einbringen","Petition online unterstützen Parlament","Ausschuss Fragen der Bürgerinnen und Bürger"]','Klemmbrett mit Unterschriftenlisten als Symbolbild für eine Petition an den Nationalrat','Photorealistic editorial photo of a clipboard with blank signature lists and a ballpoint pen on a wooden table at an outdoor market stand in Linz, blurred autumn street scene in background, natural daylight, no text, no logos, no readable signs, no identifiable people','[{"q":"Wie viele Unterschriften braucht eine Bürgerinitiative?","a":"Eine Bürgerinitiative an den Nationalrat braucht mindestens 500 Unterschriften von Wahlberechtigten ab 16 Jahren."},{"q":"Wer kann eine Petition an den Nationalrat einbringen?","a":"Eine Petition muss von einem Abgeordneten zum Nationalrat oder einem Mitglied des Bundesrates überreicht werden."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('eu-buerger-wahlrecht-gemeinderatswahl-oesterreich','EU-Bürger Wahlrecht: Wo sie in Österreich mitwählen dürfen','Rund jede zehnte Person in Österreich hat die Staatsbürgerschaft eines anderen EU-Landes. Bei welchen Wahlen sie mitbestimmen darf – und wo nicht.','Das EU-Bürger Wahlrecht in Österreich ist ein Ergebnis der europäischen Integration: Wer die Staatsbürgerschaft eines anderen EU-Mitgliedstaates besitzt und hier lebt, darf bei bestimmten Wahlen mitwählen. Allerdings gibt es klare Grenzen – und in Wien eine Besonderheit.

## EU-Bürger Wahlrecht: Gemeinderatswahlen

Bei Gemeinderatswahlen in den Bundesländern sind Unionsbürgerinnen und Unionsbürger wahlberechtigt, wenn sie ihren Hauptwohnsitz in der Gemeinde haben und die weiteren Voraussetzungen erfüllen, etwa das Mindestalter. Das gilt in Niederösterreich, Oberösterreich, Steiermark, Kärnten, Salzburg, Tirol, Vorarlberg und im Burgenland. Grundlage ist das EU-Recht, das allen Unionsbürgern das aktive und passive Wahlrecht bei Kommunalwahlen in ihrem Wohnsitzstaat garantiert.

In mehreren Bundesländern können EU-Bürgerinnen und EU-Bürger auch für den Gemeinderat kandidieren. Für bestimmte Ämter, etwa das Bürgermeisteramt, gelten in manchen Ländern Einschränkungen, die im jeweiligen Landesrecht geregelt sind.

## Die Wiener Ausnahme

In Wien ist der Gemeinderat zugleich Landtag. Weil EU-Bürgerinnen und EU-Bürger bei Landtagswahlen kein Wahlrecht haben, dürfen sie in Wien auch den Gemeinderat nicht wählen. Stattdessen sind sie bei den Wahlen zu den Bezirksvertretungen wahlberechtigt. Damit haben sie in Wien zumindest auf Bezirksebene ein kommunales Mitspracherecht.

Kein Wahlrecht haben Unionsbürgerinnen und Unionsbürger bei:

- Nationalratswahlen,
- Bundespräsidentenwahlen,
- Landtagswahlen,
- Volksabstimmungen und Volksbefragungen auf Bundesebene sowie Volksbegehren.

Für diese Wahlen ist die österreichische Staatsbürgerschaft Voraussetzung.

## EU-Wahl: Wählen in Österreich oder im Herkunftsland

Bei der Wahl zum Europäischen Parlament haben EU-Bürgerinnen und EU-Bürger mit Hauptwohnsitz in Österreich die Wahl: Sie können hier die österreichischen Listen wählen oder im Herkunftsland abstimmen. Dafür müssen sie sich in die Europäische Wählerevidenz ihrer Gemeinde eintragen lassen. Doppelt wählen ist verboten.

## So kommen EU-Bürger ins Wählerverzeichnis

Bei Gemeinderatswahlen werden EU-Bürgerinnen und EU-Bürger in der Regel automatisch in das Wählerverzeichnis aufgenommen, wenn sie mit Hauptwohnsitz gemeldet sind. Dennoch lohnt sich eine Kontrolle: Vor jeder Wahl liegt das Wählerverzeichnis zur Einsicht auf. Wer fehlt, kann innerhalb einer kurzen Frist einen Berichtigungsantrag stellen.

Für die EU-Wahl ist dagegen ein eigener Antrag auf Eintragung in die Europäische Wählerevidenz nötig. Er wird bei der Hauptwohnsitzgemeinde gestellt, oft auch online, und bleibt grundsätzlich bestehen, solange man dort gemeldet ist.

## Warum das EU-Bürger Wahlrecht immer wieder diskutiert wird

In Städten wie Wien, Salzburg oder Innsbruck lebt ein großer Teil der Bevölkerung ohne österreichische Staatsbürgerschaft, darunter viele EU-Bürgerinnen und EU-Bürger. Das führt regelmäßig zu Debatten über die Ausweitung des Wahlrechts. Eine Änderung beim Landtagswahlrecht wäre aber eine Frage der Bundesverfassung. Bis dahin gilt: Wer mitbestimmen will, sollte die bestehenden Möglichkeiten nutzen und rechtzeitig prüfen, ob er im Wählerverzeichnis steht.

Für Unionsbürgerinnen und Unionsbürger, die neu nach Österreich ziehen, gilt daher: Mit der Anmeldung des Hauptwohnsitzes ist der erste Schritt getan. Wer bei der nächsten Gemeinderatswahl oder Bezirksvertretungswahl mitbestimmen will, sollte die amtlichen Kundmachungen der Gemeinde verfolgen und rechtzeitig vor dem Stichtag prüfen, ob die Eintragung korrekt ist.','politik','Europa',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/eu-buerger-wahlrecht-gemeinderatswahl-oesterreich.webp',NULL,NULL,'published','2026-10-08T11:44:00.000Z','2026-10-22T00:17:07.893Z','EU-Bürger Wahlrecht in Österreich erklärt','EU-Bürger Wahlrecht in Österreich: Gemeinderatswahl, Bezirksvertretung Wien, EU-Wahl – wo Sie wählen dürfen und wie Sie sich eintragen. Hier nachlesen.','EU-Bürger Wahlrecht','["EU-Bürger Wahlrecht","EU-Bürger Gemeinderatswahl","Wahlrecht Unionsbürger Österreich","EU-Bürger wählen Wien","Europäische Wählerevidenz","Kommunalwahlrecht EU","Wählerverzeichnis EU-Bürger","Gemeinderatswahl Ausländer"]','Wahllokal in Tiroler Gemeinde als Symbolbild zum EU-Bürger Wahlrecht','Photorealistic editorial photo of a polling station in a Tyrolean village school gym with empty voting booths behind curtains and a ballot box on a table, mountains visible through windows, bright morning light, no text, no logos, no readable signs, no identifiable people','[{"q":"Dürfen EU-Bürger in Österreich bei der Gemeinderatswahl wählen?","a":"Ja, mit Hauptwohnsitz in der Gemeinde. In Wien dürfen sie allerdings nur die Bezirksvertretung wählen, nicht den Gemeinderat."},{"q":"Dürfen EU-Bürger bei der Nationalratswahl wählen?","a":"Nein, bei Nationalrats-, Bundespräsidenten- und Landtagswahlen ist die österreichische Staatsbürgerschaft Voraussetzung."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('bundesbudget-oesterreich-entstehung-erklaert','Bundesbudget Österreich: Wie der Staatshaushalt entsteht','Das Bundesbudget legt fest, wofür der Staat Geld ausgibt. Von der Planung im Finanzministerium bis zum Beschluss im Nationalrat – die Stationen im Überblick.','Das Bundesbudget ist das wichtigste Gesetz eines Jahres: Es legt fest, wie viel Geld der Bund einnimmt und wofür er es ausgibt. Für 2027 und 2028 hat die Bundesregierung ein Doppelbudget vorgelegt, das einen strikten Sparkurs vorsieht. Doch wie entsteht ein solches Budget eigentlich, und wer entscheidet darüber?

## Bundesbudget: Die Rechtsgrundlagen

Das Budget besteht aus zwei zentralen Gesetzen:

- **Bundesfinanzrahmengesetz:** Es legt für vier Jahre verbindliche Obergrenzen für die Ausgaben in den einzelnen Bereichen fest und wird jährlich fortgeschrieben.
- **Bundesfinanzgesetz:** Es enthält den detaillierten Voranschlag für ein Jahr, aufgeteilt in Untergliederungen wie Bildung, Soziales, Landesverteidigung oder Zinsen.

Bei einem Doppelbudget werden die Bundesfinanzgesetze für zwei Jahre gemeinsam beschlossen. Das gibt mehr Planungssicherheit, verringert aber die Flexibilität, wenn sich die wirtschaftliche Lage ändert.

## Von der Planung bis zur Budgetrede

Die Erstellung beginnt Monate vor dem Beschluss. Das Finanzministerium verhandelt mit den einzelnen Ministerien über deren Mittel. Grundlage sind Wirtschaftsprognosen, etwa von WIFO und IHS, sowie die Vorgaben der EU-Fiskalregeln. Ist der Entwurf fertig, beschließt ihn die Bundesregierung im Ministerrat und legt ihn dem Nationalrat vor.

Im Plenum präsentiert die Finanzministerin oder der Finanzminister das Budget in der Budgetrede. Sie erläutert die wichtigsten Schwerpunkte, die Einnahmen- und Ausgabenpläne sowie die erwartete Entwicklung von Defizit und Schulden.

## Budgetausschuss und Plenarberatungen

Nach der Budgetrede folgt eine Erste Lesung im Plenum. Anschließend berät der Budgetausschuss des Nationalrates intensiv über jede Untergliederung. Die zuständigen Ministerinnen und Minister stehen den Abgeordneten Rede und Antwort. Unterstützt werden die Abgeordneten vom Budgetdienst des Parlaments, der die Zahlen unabhängig analysiert und Berichte veröffentlicht.

Am Ende stehen mehrtägige Budgetberatungen im Plenum, bei denen jede Untergliederung einzeln debattiert und abgestimmt wird. Danach befasst sich der Bundesrat damit. Das Bundesfinanzgesetz tritt in der Regel mit 1. Jänner des Budgetjahres in Kraft.

Gibt es zum Jahreswechsel kein neues Budget, etwa nach einer Wahl, greift ein automatisches Budgetprovisorium. Dann gilt grundsätzlich das Budget des Vorjahres weiter, neue Vorhaben können kaum finanziert werden. Der Nationalrat kann auch ein eigenes Provisorium beschließen.

## Bundesbudget und EU-Regeln

Österreich muss sich an die EU-Fiskalregeln halten. Liegt das gesamtstaatliche Defizit über drei Prozent des BIP, droht ein Defizitverfahren, wie es derzeit läuft. Das Finanzministerium berichtet dann halbjährlich an die EU-Kommission. Laut der Mitteilung vom Oktober 2026 soll das Defizit von 4,1 Prozent im Jahr 2026 auf 3,6 Prozent im Jahr 2027 sinken.

## Bundesbudget selbst nachlesen

Alle Budgetunterlagen sind öffentlich zugänglich. Auf der Website des Finanzministeriums finden sich der Budgetbericht, die Teilhefte der Untergliederungen und übersichtliche Grafiken. Die Website des Parlaments bietet zusätzlich die Analysen des Budgetdienstes. Wer wissen will, wie viel etwa für Schulen oder Pensionen vorgesehen ist, findet dort die genauen Zahlen.

Neben dem Bundesbudget haben auch die Bundesländer und Gemeinden eigene Haushalte. Sie werden von Landtagen und Gemeinderäten beschlossen. Über den Finanzausgleich wird geregelt, wie die gemeinsamen Steuereinnahmen zwischen Bund, Ländern und Gemeinden aufgeteilt werden.','politik','Innenpolitik',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/bundesbudget-oesterreich-entstehung-erklaert.webp',NULL,NULL,'published','2026-10-09T05:22:00.000Z','2026-10-22T00:17:07.894Z','Bundesbudget Österreich: So entsteht der Haushalt','Bundesbudget Österreich erklärt: Finanzrahmen, Budgetrede, Budgetausschuss und Beschluss im Nationalrat Schritt für Schritt. Jetzt lesen.','Bundesbudget','["Bundesbudget","Bundesbudget Österreich","Budgetrede Nationalrat","Bundesfinanzgesetz","Bundesfinanzrahmen","Doppelbudget 2027 2028","Budgetdienst Parlament","Budgetausschuss Nationalrat"]','Budgetbericht und Laptop als Symbolbild zum Bundesbudget Österreich','Photorealistic editorial photo of a thick printed budget report binder and a laptop showing blurred bar charts on a desk in a modern Vienna ministry office, cool blue hour light through large windows, city lights outside, no text, no logos, no readable signs, no people','[{"q":"Wer beschließt das Bundesbudget?","a":"Das Bundesbudget wird vom Nationalrat als Bundesfinanzgesetz beschlossen, nachdem die Regierung es vorgelegt hat. Danach befasst sich der Bundesrat damit."},{"q":"Was ist ein Doppelbudget?","a":"Bei einem Doppelbudget werden die Budgets für zwei Jahre gemeinsam beschlossen, etwa für 2027 und 2028."},{"q":"Was passiert ohne beschlossenes Budget?","a":"Dann gilt ein automatisches Budgetprovisorium, bei dem grundsätzlich die Ansätze des Vorjahres weiterlaufen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('ministerrat-bundesregierung-entscheidungen','Ministerrat: Wie die Bundesregierung ihre Beschlüsse fasst','Jeden Mittwoch tritt in Wien die Bundesregierung zusammen. Was im Ministerrat beschlossen wird und warum dort alle zustimmen müssen.','Der Ministerrat ist das Gremium, in dem die Bundesregierung gemeinsam entscheidet. Er tritt in der Regel jeden Mittwoch im Bundeskanzleramt am Ballhausplatz zusammen. Wer verstehen will, wie Gesetze entstehen und warum Koalitionen um Kompromisse ringen, sollte die Regeln des Ministerrats kennen.

Dem Ministerrat gehören der Bundeskanzler, die Vizekanzlerin oder der Vizekanzler sowie alle Bundesministerinnen und Bundesminister an. Den Vorsitz führt der Bundeskanzler. Staatssekretärinnen und Staatssekretäre nehmen an den Sitzungen teil, haben aber kein Stimmrecht. Sie unterstützen die Ministerien, denen sie zugeordnet sind.

## Einstimmigkeit: Warum alle zustimmen müssen

Eine Besonderheit des österreichischen Systems: Beschlüsse im Ministerrat werden einstimmig gefasst. Jedes Regierungsmitglied hat damit faktisch ein Vetorecht. In einer Koalition, derzeit aus ÖVP, SPÖ und NEOS, bedeutet das, dass Vorhaben erst dann beschlossen werden, wenn sich alle Partner geeinigt haben. Oft werden Streitpunkte deshalb schon vor der Sitzung in Koordinierungsrunden ausverhandelt.

## Was im Ministerrat beschlossen wird

Typische Tagesordnungspunkte sind:

- **Regierungsvorlagen:** Gesetzesentwürfe, die anschließend dem Nationalrat zugeleitet werden, wie im Oktober 2026 das Binnenmarkt-Notfall- und Resilienzgesetz.
- **Verordnungen der Bundesregierung:** etwa Änderungen der Vertriebenen-Verordnung oder Preisregelungen.
- **Berichte:** zum Beispiel an die EU im Rahmen des Defizitverfahrens oder Rechnungshofberichte.
- **Personalentscheidungen:** Ernennungsvorschläge an den Bundespräsidenten und Bestellungen in Gremien.
- **Staatsverträge und internationale Einsätze:** etwa Verlängerungen von Auslandseinsätzen des Bundesheeres.

Die Ministerien bringen ihre Anliegen über sogenannte Ministerratsvorträge ein. Diese Dokumente erklären den Inhalt und schlagen einen Beschluss vor.

Muss eine Entscheidung rasch fallen und ist keine Sitzung angesetzt, etwa im Sommer, kann die Regierung einen Umlaufbeschluss fassen. Dabei stimmen die Regierungsmitglieder schriftlich zu. Auch hier gilt Einstimmigkeit. Umlaufbeschlüsse werden ebenso veröffentlicht wie reguläre Ministerratsbeschlüsse.

## Ministerrat: Beschlüsse selbst nachlesen

Das Bundeskanzleramt veröffentlicht nach jeder Sitzung die Tagesordnung, die Ministerratsvorträge und ein Beschlussprotokoll auf seiner Website. Dort lässt sich nachvollziehen, welche Gesetze und Berichte die Regierung auf den Weg gebracht hat. Nach den Sitzungen gibt es außerdem häufig ein Pressefoyer, bei dem Regierungsmitglieder Fragen von Journalistinnen und Journalisten beantworten.

## Was der Ministerrat nicht kann

Der Ministerrat beschließt keine Gesetze im eigentlichen Sinn. Er legt Entwürfe vor, entschieden wird im Nationalrat und Bundesrat. Auch das Budget muss vom Nationalrat beschlossen werden. Die Regierung ist dem Parlament gegenüber verantwortlich: Der Nationalrat kann einzelnen Ministerinnen und Ministern oder der gesamten Regierung mit einem Misstrauensantrag das Vertrauen entziehen. Dann muss der Bundespräsident die Betroffenen des Amtes entheben.

Für Bürgerinnen und Bürger ist der Ministerrat damit vor allem ein Frühindikator: Was mittwochs beschlossen wird, landet in den folgenden Wochen oft im Parlament und wird später Gesetz.

## Ministerrat und Koalitionsalltag

Gerade in einer Dreierkoalition zeigt sich die Bedeutung des Einstimmigkeitsprinzips. Bevor ein Thema auf die Tagesordnung kommt, verhandeln die Regierungskoordinatoren der Parteien die Details. Gelingt keine Einigung, wird ein Punkt vertagt oder gar nicht eingebracht. Das erklärt, warum manche angekündigten Vorhaben länger auf sich warten lassen. Zum Start der Herbstsaison im September 2026 kündigte die Regierung etwa einen „Herbst der Ergebnisse“ an, bei einzelnen Projekten wie der Bundesstaatsanwaltschaft gab es aber weiterhin unterschiedliche Positionen.','politik','Innenpolitik',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/ministerrat-bundesregierung-entscheidungen.webp',NULL,NULL,'published','2026-10-10T07:17:00.000Z','2026-10-22T00:17:07.894Z','Ministerrat: So entscheidet die Bundesregierung','Ministerrat erklärt: Warum die Bundesregierung einstimmig entscheiden muss, was Umlaufbeschlüsse sind und wo Sie Beschlüsse nachlesen. Jetzt lesen.','Ministerrat','["Ministerrat","Bundesregierung Österreich","Ministerrat Beschlüsse","Einstimmigkeit Bundesregierung","Umlaufbeschluss","Ministerratsvortrag","Regierungsvorlage Ministerrat","Ministerrat Mittwoch"]','Leerer Regierungstisch in historischem Saal als Symbolbild zum Ministerrat','Photorealistic editorial photo of a long empty government cabinet table with leather chairs, name-free placards and water carafes in a historic Viennese palace room with chandeliers, morning light, symmetrical wide view, no text, no logos, no readable signs, no people','[{"q":"Wann tagt der Ministerrat?","a":"Der Ministerrat tritt in der Regel jeden Mittwoch im Bundeskanzleramt in Wien zusammen."},{"q":"Muss der Ministerrat einstimmig entscheiden?","a":"Ja, Beschlüsse der Bundesregierung werden einstimmig gefasst. Jedes Regierungsmitglied muss zustimmen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('landeshauptmann-aufgaben-wahl-bundeslaender','Landeshauptmann: Aufgaben, Wahl und Macht in den Bundesländern','Neun Landeshauptleute regieren Österreichs Bundesländer. Wie sie ins Amt kommen und warum sie auch in der Bundespolitik viel Gewicht haben.','Der Landeshauptmann oder die Landeshauptfrau steht an der Spitze eines Bundeslandes. In Österreich gibt es neun solcher Ämter, in Wien übernimmt der Bürgermeister diese Funktion. Obwohl die Bundesländer weniger Gesetzgebungskompetenzen haben als etwa die deutschen Länder, gelten die Landeshauptleute als besonders einflussreich.

## Wie der Landeshauptmann gewählt wird

Die Bevölkerung wählt den Landtag, das Landesparlament. Der Landtag wählt anschließend die Landesregierung und den Landeshauptmann. In der Praxis stellt die stärkste Partei oder eine Koalition die Spitze. Eine Direktwahl des Landeshauptmanns gibt es in keinem Bundesland.

Früher galt in vielen Ländern das Proporzsystem: Alle Parteien ab einer bestimmten Stärke waren automatisch in der Landesregierung vertreten. Die meisten Bundesländer haben es inzwischen abgeschafft und setzen auf Koalitionsregierungen. In Niederösterreich und Oberösterreich ist der Proporz noch verankert, Regierungssitze werden dort nach Stärke der Parteien vergeben.

## Aufgaben des Landeshauptmanns

Zu den wichtigsten Aufgaben zählen:

- **Leitung der Landesregierung:** Der Landeshauptmann führt den Vorsitz und vertritt das Land nach außen.
- **Mittelbare Bundesverwaltung:** In vielen Bereichen vollziehen die Länder Bundesgesetze, etwa im Gewerberecht oder Teilen des Gesundheitswesens. Der Landeshauptmann ist dabei an Weisungen der Bundesministerien gebunden.
- **Landesgesetze vollziehen:** etwa Bauordnung, Raumordnung, Kinderbetreuung, Naturschutz oder Jugendschutz.
- **Landesbudget:** Die Landesregierung erstellt den Voranschlag, den der Landtag beschließt.

## Landeshauptleutekonferenz: Einfluss auf den Bund

Die Landeshauptleute treffen sich regelmäßig in der Landeshauptleutekonferenz. Der Vorsitz wechselt halbjährlich zwischen den Bundesländern. Das Gremium ist in der Verfassung nicht vorgesehen, hat aber großes politisches Gewicht. Bei Verhandlungen über den Finanzausgleich, über Gesundheit, Pflege oder Bildung treten die Länder dort gemeinsam gegenüber der Bundesregierung auf.

Auch in der Reformpartnerschaft zwischen Bund, Ländern und Gemeinden, die seit 2025 läuft, spielen die Landeshauptleute eine zentrale Rolle. Ohne ihre Zustimmung lassen sich viele Reformen nicht umsetzen, weil sie Zuständigkeiten der Länder betreffen.

## Landeshauptmann und Bundesrat

Die Länder wirken auch über den Bundesrat an der Bundesgesetzgebung mit. Dessen Mitglieder werden von den Landtagen entsandt. Zudem haben die Landeshauptleute oft eine starke Stellung in ihren Parteien und reden bei Personalentscheidungen auf Bundesebene mit – zuletzt etwa bei der Neuaufstellung der SPÖ-Spitze im Oktober 2026, bei der die Landesparteichefs mit der Bundespartei berieten.

Für viele Lebensbereiche ist das Land wichtiger als der Bund: Wohnbauförderung, Kindergärten, Spitäler, Raumordnung und Teile der Sozialleistungen werden auf Landesebene geregelt. Wer etwa eine Förderung beantragt oder ein Bauvorhaben plant, hat es meist mit Landesrecht zu tun. Die Website des jeweiligen Landes informiert über Zuständigkeiten, Landtagsbeschlüsse und Ansprechstellen.

## Landeshauptmann und Landtag: Kontrolle im Land

Wie auf Bundesebene ist die Landesregierung dem Parlament verantwortlich. Der Landtag kontrolliert sie mit Anfragen, Untersuchungskommissionen und dem Landesrechnungshof, den es in allen Bundesländern gibt. Landtagswahlen finden in der Regel alle fünf Jahre statt, in Oberösterreich alle sechs Jahre. Wer wissen will, welche Partei im eigenen Bundesland regiert und welche Gesetze zuletzt beschlossen wurden, findet die Informationen auf den Websites der Landtage. Dort sind auch Sitzungstermine und Livestreams abrufbar.','politik','Innenpolitik',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/landeshauptmann-aufgaben-wahl-bundeslaender.webp',NULL,NULL,'published','2026-10-12T08:48:00.000Z','2026-10-22T00:17:07.895Z','Landeshauptmann: Aufgaben und Wahl erklärt','Landeshauptmann erklärt: Wie er gewählt wird, was die Landesregierung entscheidet und welche Rolle die Landeshauptleutekonferenz spielt. Jetzt lesen.','Landeshauptmann','["Landeshauptmann","Landeshauptfrau","Landesregierung Aufgaben","Landeshauptleutekonferenz","Landtag Wahl Landeshauptmann","mittelbare Bundesverwaltung","Landespolitik Österreich","Proporz Landesregierung"]','Arkadenhof eines Landhauses als Symbolbild zu Aufgaben des Landeshauptmann','Photorealistic editorial photo of the historic Landhaus courtyard in Graz with Renaissance arcades, warm afternoon autumn light, view from a shaded corner of the arcade, no text, no logos, no readable signs, no identifiable people','[{"q":"Wird der Landeshauptmann direkt gewählt?","a":"Nein, der Landeshauptmann wird vom Landtag gewählt. Die Bevölkerung wählt den Landtag."},{"q":"Was ist die Landeshauptleutekonferenz?","a":"Ein regelmäßiges Treffen aller Landeshauptleute, bei dem die Länder ihre Positionen gegenüber dem Bund abstimmen. Der Vorsitz wechselt halbjährlich."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('id-austria-aktivieren-amtswege-online','ID Austria aktivieren: So erledigen Sie Amtswege online','Mit der ID Austria lassen sich viele Amtswege vom Sofa aus erledigen – von der Wahlkarte bis zum Volksbegehren. So kommen Sie zu Ihrem digitalen Ausweis.','Die ID Austria ist der digitale Ausweis für Amtswege in Österreich. Sie hat die frühere Handysignatur abgelöst und ermöglicht es, sich sicher online auszuweisen und Dokumente elektronisch zu unterschreiben. Für viele Bürgerservices, etwa das Unterschreiben von Volksbegehren oder das Beantragen einer Wahlkarte, ist sie inzwischen der einfachste Weg.

## Was man mit der ID Austria erledigen kann

Mit der ID Austria lassen sich unter anderem folgende Dinge online erledigen:

- Wahlkarte für Nationalrats-, Bundespräsidenten- oder EU-Wahlen beantragen
- Volksbegehren und Unterstützungserklärungen unterschreiben
- Meldebestätigungen und Strafregisterbescheinigungen abrufen
- Arbeitnehmerveranlagung über FinanzOnline einreichen
- Anträge bei Sozialversicherung, AMS oder Gemeinden stellen
- Dokumente rechtsgültig elektronisch unterschreiben

Zentrale Anlaufstellen sind das Portal oesterreich.gv.at und die App Digitales Amt. Auch viele Gemeinden und Länder binden die ID Austria in ihre Online-Services ein.

## ID Austria aktivieren: Die Registrierung

Für die Registrierung gibt es mehrere Möglichkeiten:

1. **Bei einer Behörde:** Registrierungsstellen sind etwa Passbehörden, viele Bezirkshauptmannschaften, Magistrate und Gemeindeämter sowie Finanzämter. Mitzubringen ist ein amtlicher Lichtbildausweis.
2. **Bei der Ausstellung eines Reisepasses oder Personalausweises:** Bei der Antragstellung kann die ID Austria gleich mit beantragt werden.
3. **Online:** Unter bestimmten Voraussetzungen, etwa mit einem bereits vorhandenen aktuellen Lichtbild in den Registern, kann der Prozess auch digital gestartet werden. Welche Variante möglich ist, zeigt die Website der ID Austria.

Nach der Registrierung erhält man Aktivierungsdaten, mit denen die ID Austria am Smartphone eingerichtet wird.

## ID Austria am Smartphone einrichten

Für die Nutzung braucht man in der Regel ein Smartphone mit der App Digitales Amt und eine Möglichkeit zur sicheren Freigabe, etwa per Fingerabdruck, Gesichtserkennung oder PIN. Alternativ können auch FIDO-Sicherheitsschlüssel verwendet werden, falls man kein Smartphone nutzen möchte. Bei der Anmeldung auf einer Website wird die Identität dann über die App bestätigt.

## Sicherheit: Darauf sollten Sie achten

Die ID Austria ist so viel wert wie ein Ausweis. Wichtig ist daher:

- Zugangsdaten und PIN niemals weitergeben, auch nicht am Telefon.
- Anmeldungen nur bestätigen, wenn man selbst gerade einen Vorgang gestartet hat.
- Bei Verlust des Smartphones die ID Austria umgehend sperren lassen.
- Vorsicht bei E-Mails oder SMS, die zur Eingabe von Daten auffordern – Behörden fordern das nicht auf diesem Weg.

## ID Austria und die Gemeinden

Mit der Reformpartnerschaft wollen Bund und Gemeinden die digitale Verwaltung weiter ausbauen. Das im Oktober 2026 vorgestellte Gemeindepaket sieht etwa vor, dass Daten nur noch einmal angegeben werden müssen und mehr Verfahren automatisiert ablaufen. Ab Dezember 2026 sind zudem kostenlose Workshops unter dem Titel „Digital Überall“ geplant, bei denen unter anderem der Umgang mit Online-Amtswegen erklärt wird. Wer sich mit der ID Austria noch unsicher fühlt, findet dort Unterstützung.

Wer die frühere Handysignatur verwendet hat, musste auf die ID Austria umsteigen. Für Menschen, die mit dem Smartphone wenig vertraut sind, ist es ratsam, die Registrierung gemeinsam mit einer Vertrauensperson zu erledigen. Viele Registrierungsstellen helfen auch direkt vor Ort bei der Einrichtung der App. Und wichtig: Alle Amtswege bleiben weiterhin auch persönlich oder schriftlich möglich – die ID Austria ist ein zusätzliches Angebot, keine Pflicht.','politik','Innenpolitik',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/id-austria-aktivieren-amtswege-online.webp',NULL,NULL,'published','2026-10-13T06:31:00.000Z','2026-10-22T00:17:07.895Z','ID Austria aktivieren: Amtswege online erledigen','ID Austria aktivieren in wenigen Schritten: Wo Sie die Registrierung erledigen, was Sie brauchen und welche Amtswege dann online gehen. Jetzt nachlesen.','ID Austria','["ID Austria","ID Austria aktivieren","ID Austria Registrierung","Amtswege online","oesterreich.gv.at","Digitales Amt App","Handysignatur Nachfolger","ID Austria Behörde"]','Smartphone in der Hand als Symbolbild zum Aktivieren der ID Austria','Photorealistic editorial photo of an older person''s hand holding a smartphone near a window in a cozy Carinthian living room, lake and mountains softly blurred outside, warm afternoon light, close-up, no text, no logos, no readable signs, no face visible','[{"q":"Wo kann ich die ID Austria aktivieren?","a":"Bei Registrierungsstellen wie Passbehörden, vielen Gemeindeämtern, Bezirkshauptmannschaften und Finanzämtern, mit einem amtlichen Lichtbildausweis."},{"q":"Brauche ich für die ID Austria ein Smartphone?","a":"Meist wird die App Digitales Amt genutzt. Alternativ können auch FIDO-Sicherheitsschlüssel verwendet werden."},{"q":"Was kostet die ID Austria?","a":"Die Registrierung und Nutzung der ID Austria sind für Bürgerinnen und Bürger grundsätzlich kostenlos."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('parlament-wien-besuchen-fuehrung-plenarsitzung','Parlament Wien besuchen: Führungen, Galerie und Demokratikum','Seit der Sanierung ist das Parlament an der Ringstraße offener als je zuvor. Wie Sie Führungen buchen, Sitzungen besuchen und was das Demokratikum bietet.','Das Parlament Wien an der Ringstraße ist nicht nur Arbeitsort von Nationalrat und Bundesrat, sondern auch ein Ort für Besucherinnen und Besucher. Nach der umfassenden Sanierung, die Anfang 2023 abgeschlossen wurde, hat sich das Haus bewusst geöffnet. Wer Demokratie aus der Nähe erleben will, hat mehrere Möglichkeiten.

## Parlament Wien: Führungen durch das Hohe Haus

Bei Führungen lernen Besucherinnen und Besucher die wichtigsten Räume kennen, darunter den Nationalratssitzungssaal, den Bundesratssaal und die prunkvolle Säulenhalle. Die Führungen erklären die Geschichte des Gebäudes, das von Theophil Hansen entworfen wurde, und die Arbeitsweise des Parlaments.

Termine, Sprachen und Anmeldung finden sich auf der Website des Parlaments. Für Gruppen und Schulklassen gibt es eigene Angebote, die rechtzeitig gebucht werden sollten. Da es sich um ein Arbeitsparlament handelt, können Führungen an Sitzungstagen eingeschränkt sein.

## Plenarsitzungen von der Galerie verfolgen

Die Sitzungen des Nationalrates und des Bundesrates sind öffentlich. Interessierte können sie von der Besuchergalerie aus verfolgen. Wichtig zu wissen:

- Plätze sind begrenzt, eine Anmeldung oder Zählkarte kann erforderlich sein.
- Beim Eingang gibt es eine Sicherheitskontrolle, ein amtlicher Lichtbildausweis ist mitzunehmen.
- Auf der Galerie gelten Verhaltensregeln: Zwischenrufe, Transparente oder Applaus sind nicht erlaubt.

Wer nicht vor Ort sein kann, verfolgt die Plenarsitzungen im Livestream auf der Website des Parlaments oder im Fernsehen. Ausschusssitzungen sind in der Regel nicht öffentlich, Untersuchungsausschüsse bilden mit eigener Medienöffentlichkeit eine Ausnahme.

## Demokratikum: Demokratie zum Mitmachen

Mit dem Demokratikum hat das Parlament ein Besucherzentrum eingerichtet, das spielerisch und interaktiv erklärt, wie Demokratie funktioniert. Es richtet sich an Erwachsene ebenso wie an Kinder und Jugendliche. Dort lässt sich etwa nachvollziehen, wie ein Gesetz entsteht oder wie Wahlen funktionieren. Ergänzend bietet die Demokratiewerkstatt Workshops für Schulklassen an.

Ein besonderer Termin ist der Nationalfeiertag am 26. Oktober. Dann öffnet das Parlament traditionell seine Türen für alle Interessierten, ohne Anmeldung. Abgeordnete und Mitarbeitende stehen für Gespräche zur Verfügung, es gibt Programmpunkte für Familien. Im Vorfeld kann das Haus für Vorbereitungen geschlossen sein, im Jahr 2026 etwa schon ab dem Mittag des 23. Oktober. Wegen des großen Andrangs empfiehlt es sich, früh zu kommen.

## Parlament Wien: Praktische Tipps für den Besuch

- **Anreise:** Das Parlament liegt am Dr.-Karl-Renner-Ring im 1. Bezirk. Öffentlich erreichbar ist es etwa mit der U-Bahn-Linie U2 und den Straßenbahnen am Ring.
- **Barrierefreiheit:** Das sanierte Gebäude ist weitgehend barrierefrei.
- **Café und Bibliothek:** Teile des Hauses, etwa das Besucherrestaurant, sind auch außerhalb von Führungen zugänglich. Die aktuellen Öffnungszeiten sind online abrufbar.

Ein Besuch im Parlament Wien lohnt sich besonders vor oder nach einer Plenarsitzung, wenn man Debatten aus der Nähe erlebt und die Abläufe besser versteht.

## Parlament Wien digital erkunden

Wer den Besuch vorbereiten oder das Haus von zu Hause aus kennenlernen möchte, findet auf der Parlamentswebsite virtuelle Rundgänge, Erklärvideos und Unterlagen für den Unterricht. Die Mediathek bietet Aufzeichnungen vergangener Plenarsitzungen. Auch die Parlamentskorrespondenz, die über alle Sitzungen und Ausschüsse berichtet, kann per Newsletter abonniert werden. Für Schulklassen lohnt sich eine Kombination aus Führung, Workshop in der Demokratiewerkstatt und einem Besuch der Galerie während einer Sitzung.','politik','Parlament','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/parlament-wien-besuchen-fuehrung-plenarsitzung.webp',NULL,NULL,'published','2026-10-15T13:39:00.000Z','2026-10-22T00:17:07.895Z','Parlament Wien besuchen: Führungen und Sitzungen','Parlament Wien besuchen: Führungen, Plenarsitzungen auf der Galerie, Demokratikum und Tag der offenen Tür. Alle Tipps für Ihren Besuch – jetzt lesen.','Parlament Wien','["Parlament Wien","Parlament Führung","Parlament besuchen","Demokratikum Parlament","Plenarsitzung Galerie","Tag der offenen Tür Parlament","Parlament Nationalfeiertag","Parlament Wien Schulklassen"]','Parlamentsgebäude an der Ringstraße als Symbolbild zum Besuch im Parlament Wien','Photorealistic editorial photo of the Austrian Parliament building on Vienna''s Ringstrasse with its classical columns and Pallas Athene fountain, seen from across the street on a crisp sunny autumn morning, tram tracks in foreground, no text, no logos, no readable signs, no identifiable people','[{"q":"Kann man Sitzungen im Parlament Wien besuchen?","a":"Ja, Plenarsitzungen von Nationalrat und Bundesrat sind öffentlich und können von der Galerie aus verfolgt werden. Ein Lichtbildausweis ist nötig."},{"q":"Wann ist der Tag der offenen Tür im Parlament?","a":"Traditionell am Nationalfeiertag, dem 26. Oktober. Eine Anmeldung ist dafür nicht notwendig."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('volksanwaltschaft-beschwerde-einbringen','Volksanwaltschaft: So bringen Sie eine Beschwerde ein','Wer sich von einer Behörde ungerecht behandelt fühlt, kann sich kostenlos an die Volksanwaltschaft wenden. Wann das sinnvoll ist und wie es funktioniert.','Die Volksanwaltschaft ist die Anlaufstelle für alle, die sich von einer österreichischen Behörde schlecht behandelt fühlen. Sie prüft Beschwerden über die öffentliche Verwaltung kostenlos und ohne Formalitäten. Als Hilfsorgan des Parlaments berichtet sie regelmäßig an Nationalrat, Bundesrat und Landtage.

## Wofür die Volksanwaltschaft zuständig ist

Die Volksanwaltschaft kontrolliert die gesamte öffentliche Verwaltung des Bundes. Außerdem ist sie für die Landes- und Gemeindeverwaltung zuständig, mit Ausnahme von Tirol und Vorarlberg, die eigene Landesvolksanwaltschaften eingerichtet haben. Typische Beschwerdefälle betreffen:

- lange Verfahrensdauern, etwa bei Pensions-, Asyl- oder Staatsbürgerschaftsverfahren,
- Probleme mit Sozialversicherung, AMS oder Finanzamt,
- Bauverfahren und Streitigkeiten mit der Gemeinde,
- Fragen der Pflege und der Unterbringung in Einrichtungen.

Nicht zuständig ist die Volksanwaltschaft für Streitigkeiten zwischen Privatpersonen und für die Rechtsprechung der unabhängigen Gerichte. Sie kann aber prüfen, ob ein Gerichtsverfahren unangemessen lange dauert.

## So bringen Sie eine Beschwerde ein

Eine Beschwerde ist formlos möglich:

1. **Online** über das Beschwerdeformular auf der Website der Volksanwaltschaft,
2. **per E-Mail oder Post**, mit Darstellung des Problems,
3. **telefonisch** über die kostenlose Servicenummer,
4. **persönlich** bei einem Sprechtag in Wien oder in den Bundesländern.

Hilfreich ist es, die wichtigsten Unterlagen beizulegen, etwa Bescheide, Schreiben der Behörde und eine kurze chronologische Darstellung. Die Beschwerde kostet nichts, ein Anwalt ist nicht nötig.

## Wie das Prüfverfahren abläuft

Nach Eingang prüft die Volksanwaltschaft, ob sie zuständig ist. Dann holt sie eine Stellungnahme der betroffenen Behörde ein und sichtet die Akten. Stellt sie einen Missstand fest, kann sie Empfehlungen aussprechen. Diese sind rechtlich nicht bindend, werden aber in den meisten Fällen befolgt, auch weil die Volksanwaltschaft darüber öffentlich berichtet. Die Beschwerdeführerin oder der Beschwerdeführer wird über das Ergebnis informiert.

Wichtig: Eine Beschwerde ersetzt keine Rechtsmittel. Wer gegen einen Bescheid vorgehen will, muss die Fristen für eine Beschwerde an das Verwaltungsgericht weiterhin selbst einhalten.

## Volksanwaltschaft und Menschenrechte

Seit 2012 hat die Volksanwaltschaft zusätzlich den Auftrag, Menschenrechte zu schützen. Gemeinsam mit Kommissionen besucht sie Einrichtungen, in denen Menschen in ihrer Freiheit eingeschränkt sind oder werden können, etwa Gefängnisse, Pflegeheime, psychiatrische Abteilungen und Polizeianhaltezentren. Die Besuche erfolgen oft unangekündigt.

## Wer die Volksanwaltschaft leitet

Die Volksanwaltschaft besteht aus drei Mitgliedern, die vom Nationalrat für sechs Jahre gewählt werden. Die drei mandatsstärksten Parteien haben das Recht, je ein Mitglied vorzuschlagen. Den Vorsitz übernehmen sie abwechselnd. Jedes Mitglied ist für bestimmte Verwaltungsbereiche zuständig.

Bevor man sich an die Volksanwaltschaft wendet, lohnt es sich, bei der zuständigen Stelle nachzufragen oder sich bei der vorgesetzten Behörde zu beschweren. Manche Probleme lassen sich so rasch lösen. Bleibt das ohne Erfolg, ist die Volksanwaltschaft der richtige nächste Schritt.

Bevor man sich an die Volksanwaltschaft wendet, lohnt es sich übrigens, bei der zuständigen Stelle nachzufragen oder sich bei der vorgesetzten Behörde zu beschweren. Manche Probleme lassen sich so rasch lösen. Bleibt das ohne Erfolg, ist die Volksanwaltschaft der richtige nächste Schritt. Ihre Jahresberichte, die im Nationalrat und in den Landtagen diskutiert werden, zeigen außerdem, in welchen Verwaltungsbereichen es besonders häufig Probleme gibt.','politik','Parlament',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/volksanwaltschaft-beschwerde-einbringen.webp',NULL,NULL,'published','2026-10-16T09:26:00.000Z','2026-10-22T00:17:07.895Z','Volksanwaltschaft: Beschwerde einfach einbringen','Volksanwaltschaft: Beschwerde kostenlos, formlos und ohne Anwalt einbringen. Wann sie hilft und wie das Verfahren abläuft – jetzt lesen.','Volksanwaltschaft','["Volksanwaltschaft","Volksanwaltschaft Beschwerde","Beschwerde Behörde Österreich","Missstand Verwaltung","Volksanwalt Sprechtag","Volksanwaltschaft kostenlos","Kontrolle Verwaltung Parlament","Volksanwaltschaft Wien"]','Mappe mit Behördenschreiben als Symbolbild zur Beschwerde bei der Volksanwaltschaft','Photorealistic editorial photo of a folder with official letters and a pair of reading glasses on a kitchen table in a Styrian farmhouse, steaming tea cup, soft overcast window light, close-up, no text, no logos, no readable signs, no people','[{"q":"Kostet eine Beschwerde bei der Volksanwaltschaft etwas?","a":"Nein, die Beschwerde ist kostenlos und formlos möglich. Ein Anwalt ist nicht erforderlich."},{"q":"Kann die Volksanwaltschaft einen Bescheid aufheben?","a":"Nein, sie kann Empfehlungen aussprechen, aber keine Bescheide aufheben. Rechtsmittelfristen müssen selbst eingehalten werden."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('eu-recht-oesterreich-verordnung-richtlinie','EU-Recht in Österreich: Verordnung und Richtlinie erklärt','Viele Regeln, die in Österreich gelten, stammen aus Brüssel. Warum manche sofort wirken, andere erst umgesetzt werden müssen – und wo das Parlament mitredet.','EU-Recht prägt den österreichischen Alltag stärker, als vielen bewusst ist: von der Produktsicherheit über den Datenschutz bis zu Regeln für Krisen im Binnenmarkt. Dabei gibt es zwei zentrale Rechtsformen, die sehr unterschiedlich wirken: die Verordnung und die Richtlinie. Wer sie unterscheiden kann, versteht politische Debatten über EU-Vorgaben deutlich besser.

## EU-Recht: Die Verordnung gilt unmittelbar

Eine EU-Verordnung gilt in allen Mitgliedstaaten direkt, sobald sie in Kraft tritt. Es braucht kein österreichisches Gesetz, damit sie anwendbar wird. Bekanntes Beispiel ist die Datenschutz-Grundverordnung. Österreich muss allerdings oft Begleitregelungen schaffen, etwa zu Zuständigkeiten von Behörden oder zu Strafen bei Verstößen.

## Die Richtlinie muss umgesetzt werden

Eine EU-Richtlinie legt Ziele fest, die alle Mitgliedstaaten erreichen müssen. Wie sie das tun, entscheiden die Staaten selbst. Dafür haben sie eine bestimmte Frist, meist zwei bis drei Jahre. In Österreich erfolgt die Umsetzung durch Bundes- oder Landesgesetze, je nachdem, wer nach der Verfassung zuständig ist.

Ein aktuelles Beispiel ist das Binnenmarkt-Notfall- und Resilienzgesetz, das im Oktober 2026 als Regierungsvorlage in den Nationalrat kam. Es dient der Umsetzung der Richtlinie (EU) 2024/2749 und passt das österreichische Recht zugleich an eine begleitende EU-Verordnung an. Das zeigt, wie Verordnungen und Richtlinien oft zusammenwirken.

Setzt ein Mitgliedstaat eine Richtlinie nicht rechtzeitig oder nicht korrekt um, kann die EU-Kommission ein Vertragsverletzungsverfahren einleiten. Der Ablauf:

1. **Aufforderungsschreiben:** Die Kommission fordert den Staat auf, sich zu äußern.
2. **Begründete Stellungnahme:** Bleibt das Problem bestehen, legt die Kommission ihre Sicht formell dar.
3. **Klage beim Europäischen Gerichtshof:** Als letzter Schritt, der im Extremfall zu finanziellen Sanktionen führen kann.

Österreich hat, wie andere Mitgliedstaaten auch, laufend mehrere solcher Verfahren offen. Viele werden beendet, sobald die Umsetzung nachgeholt ist.

## Wie Österreich bei EU-Recht mitredet

EU-Gesetze werden vom Europäischen Parlament und vom Rat der EU gemeinsam beschlossen. Im Rat sitzen die Fachministerinnen und Fachminister der Mitgliedstaaten, für Österreich also Mitglieder der Bundesregierung. Das österreichische Parlament hat dabei eigene Mitwirkungsrechte:

- **EU-Unterausschuss und Hauptausschuss:** Sie können Stellungnahmen beschließen, die Regierungsmitglieder bei Verhandlungen in Brüssel grundsätzlich binden.
- **Subsidiaritätsprüfung:** Nationalrat und Bundesrat können rügen, wenn die EU in Bereichen tätig wird, die besser national geregelt wären.
- **Information:** Die Regierung muss das Parlament über EU-Vorhaben laufend informieren.

## EU-Recht selbst nachschlagen

Alle EU-Rechtsakte sind im Portal EUR-Lex kostenlos und auf Deutsch abrufbar. Die österreichischen Umsetzungsgesetze finden sich im Rechtsinformationssystem des Bundes (RIS). Die Parlamentswebsite zeigt außerdem, welche EU-Vorhaben gerade im EU-Unterausschuss beraten werden – etwa im Oktober 2026 Vorhaben zu Reisebuchungen und zum Bahnverkehr.

## Warum EU-Recht oft Landessache ist

In Österreich verteilt die Bundesverfassung die Zuständigkeiten zwischen Bund und Ländern. Fällt eine EU-Richtlinie in einen Bereich der Länder, etwa Naturschutz, Raumordnung oder Teile des Baurechts, müssen alle neun Landtage eigene Umsetzungsgesetze beschließen. Das erklärt, warum die Umsetzung in Österreich manchmal länger dauert als in zentralistisch organisierten Staaten. Wenn auch nur ein Bundesland säumig ist, gilt Österreich gegenüber der EU als nicht vollständig umgesetzt.','politik','Europa',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/eu-recht-oesterreich-verordnung-richtlinie.webp',NULL,NULL,'published','2026-10-17T07:04:00.000Z','2026-10-22T00:17:07.896Z','EU-Recht Österreich: Verordnung vs. Richtlinie','EU-Recht in Österreich verständlich: Was Verordnung und Richtlinie unterscheidet, wie die Umsetzung abläuft und wer mitredet. Jetzt die Grundlagen lesen.','EU-Recht','["EU-Recht","EU-Verordnung","EU-Richtlinie","Richtlinie Umsetzung Österreich","Vertragsverletzungsverfahren","EU-Unterausschuss Nationalrat","Subsidiaritätsprüfung","EU-Gesetzgebung"]','Rechtsbibliothek mit Gesetzbüchern als Symbolbild zu EU-Recht in Österreich','Photorealistic editorial photo of a row of thick legal reference books in a university law library in Innsbruck, one book open on a reading table with a blurred page, warm reading lamp, mountain view through tall window at dusk, no text, no logos, no readable signs, no people','[{"q":"Was ist der Unterschied zwischen EU-Verordnung und EU-Richtlinie?","a":"Eine Verordnung gilt direkt in allen Mitgliedstaaten. Eine Richtlinie gibt Ziele vor, die jeder Staat mit eigenen Gesetzen umsetzen muss."},{"q":"Was passiert, wenn Österreich eine Richtlinie nicht umsetzt?","a":"Die EU-Kommission kann ein Vertragsverletzungsverfahren einleiten, das bis zu einer Klage beim Europäischen Gerichtshof führen kann."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('eu-foerderungen-gemeinden-oesterreich','EU-Förderungen für Gemeinden: Welche Programme es gibt','Vom Dorfplatz bis zum Radweg: Viele Gemeindeprojekte werden mit EU-Mitteln mitfinanziert. Welche Programme es gibt und wie der Weg zur Förderung aussieht.','EU-Förderungen sind für viele österreichische Gemeinden ein wichtiger Baustein, um Projekte zu finanzieren, die aus dem eigenen Budget nicht machbar wären. Gerade in Zeiten knapper Gemeindefinanzen lohnt sich ein Blick auf die Programme der Europäischen Union. Wichtig ist allerdings: EU-Mittel fließen fast nie direkt, sondern über Programme, die in Österreich von Bund und Ländern verwaltet werden.

## EU-Förderungen: Die wichtigsten Programme für Gemeinden

Für Kommunen sind vor allem diese Programme relevant:

- **LEADER:** Teil der Förderung für den ländlichen Raum. Lokale Aktionsgruppen in den Regionen entwickeln eigene Strategien und unterstützen Projekte, etwa zur Belebung von Ortskernen, im Tourismus oder bei sozialen Angeboten.
- **EFRE (Europäischer Fonds für regionale Entwicklung):** Fördert Innovation, Forschung, Klimaschutz und nachhaltige Stadtentwicklung, in Österreich vor allem über ein gemeinsames Programm von Bund und Ländern.
- **Interreg:** Unterstützt grenzüberschreitende Zusammenarbeit, etwa zwischen Gemeinden in Österreich und Nachbarregionen in Bayern, Tschechien, der Slowakei, Ungarn, Slowenien, Italien oder der Schweiz.
- **Europäischer Sozialfonds Plus (ESF+):** Fördert Beschäftigung, Bildung und soziale Inklusion, häufig über Träger, mit denen Gemeinden kooperieren.

## Neue Mittel aus dem Klima-Sozialfonds

Mit dem Klima-Sozialplan 2026–2032, dessen Einreichung die Bundesregierung im Oktober 2026 beschlossen hat, kommt ein weiterer Topf hinzu. Er ist vor allem für einkommensschwache Haushalte gedacht, sieht aber auch Investitionen in Rad- und Fußwege in benachteiligten Gebieten vor. Für Gemeinden in strukturschwachen Regionen könnte das interessant werden, sobald die konkreten Förderschienen feststehen.

## So kommen Gemeinden zu EU-Förderungen

Der Weg zur Förderung folgt meist einem ähnlichen Muster:

1. **Projektidee prüfen:** Passt das Vorhaben zu den Zielen eines Programms?
2. **Beratung einholen:** Erste Anlaufstellen sind die Förderabteilungen der Länder, Regionalmanagements und LEADER-Regionen.
3. **Partner suchen:** Viele Programme verlangen Kooperationen, etwa mit Nachbargemeinden, Vereinen oder Partnern jenseits der Grenze.
4. **Antrag stellen:** Mit Projektbeschreibung, Kostenplan und Nachweis der Kofinanzierung.
5. **Umsetzen und abrechnen:** EU-Mittel werden meist erst nach Nachweis der Ausgaben ausbezahlt.

## Worauf Gemeinden achten sollten

EU-Förderungen decken fast nie die vollen Kosten. Gemeinden müssen einen Eigenanteil aufbringen und oft in Vorleistung gehen. Hinzu kommt ein erheblicher Verwaltungsaufwand für Dokumentation und Abrechnung. Kleinere Gemeinden schließen sich daher häufig zusammen oder nutzen die Unterstützung der Regionalmanagements. Wer Vergabe- und Publizitätsvorschriften nicht einhält, riskiert Rückforderungen.

## EU-Förderungen sichtbar machen

Projekte, die mit EU-Mitteln gefördert werden, müssen das in der Regel öffentlich kenntlich machen. Eine Übersicht über geförderte Projekte in Österreich bieten die Websites der jeweiligen Programme. Für Bürgerinnen und Bürger lohnt ein Blick hinein: Oft zeigt sich, dass der neue Radweg, das sanierte Gemeindezentrum oder das regionale Bildungsangebot vor der Haustür auch mit europäischem Geld entstanden ist.

Ein guter Einstieg für Gemeinden ist das Gespräch mit dem Regionalmanagement des eigenen Bezirks oder der eigenen Region. Dort laufen Informationen zu offenen Ausschreibungen, Fristen und Fördersätzen zusammen. Auch der Gemeindebund und die Förderstellen der Länder bieten Informationsveranstaltungen an, bei denen erfolgreiche Projekte vorgestellt werden.','politik','Europa','steiermark','ratgeber','Presseinfo Redaktion','/assets/img/artikel/eu-foerderungen-gemeinden-oesterreich.webp',NULL,NULL,'published','2026-10-20T12:58:00.000Z','2026-10-22T00:17:07.896Z','EU-Förderungen für Gemeinden: Programme im Überblick','EU-Förderungen für Gemeinden: LEADER, EFRE, Interreg und Co. erklärt. Wer zuständig ist und wie Projekte zu Fördermitteln kommen – jetzt Überblick lesen.','EU-Förderungen','["EU-Förderungen","EU-Förderungen Gemeinden","LEADER Österreich","EFRE Österreich","Interreg Österreich","Regionalförderung EU","Klima-Sozialfonds Gemeinden","Förderstelle Land EU-Projekte"]','Neuer Radweg in ländlicher Steiermark als Symbolbild zu EU-Förderungen für Gemeinden','Photorealistic editorial photo of a newly built gravel cycling path along a stream through rolling green hills in rural Styria, wooden bridge, autumn foliage, soft late afternoon light, drone perspective, no text, no logos, no readable signs, no identifiable people','[{"q":"Welche EU-Förderungen gibt es für Gemeinden?","a":"Wichtig sind vor allem LEADER für den ländlichen Raum, EFRE für regionale Entwicklung, Interreg für grenzüberschreitende Projekte und der ESF+."},{"q":"Bekommen Gemeinden EU-Geld direkt aus Brüssel?","a":"Meist nicht. Die Mittel laufen über Programme, die in Österreich von Bund und Ländern verwaltet werden. Erste Anlaufstelle sind die Förderstellen der Länder."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('europa-gemeinderaete-oesterreich-initiative','Europa-Gemeinderäte: Wie Gemeinden die EU näherbringen','Mehr als tausend Kommunalpolitikerinnen und -politiker sind in Österreich als Europa-Gemeinderäte aktiv. Was hinter der Initiative steckt.','Europa-Gemeinderäte sind Kommunalpolitikerinnen und Kommunalpolitiker, die in ihrer Gemeinde als Ansprechpersonen für EU-Themen fungieren. Die Initiative gibt es in Österreich seit 2010, betreut wird sie heute vom Bundeskanzleramt gemeinsam mit der Vertretung der EU-Kommission und dem Verbindungsbüro des Europäischen Parlaments in Österreich. Ziel ist es, die Europäische Union dort greifbar zu machen, wo Menschen ihren Alltag leben.

## Was Europa-Gemeinderäte tun

Die Aufgaben sind bewusst offen gehalten. Typisch sind:

- **Informieren:** Europa-Gemeinderäte beantworten Fragen von Bürgerinnen und Bürgern zur EU oder vermitteln an die richtigen Stellen weiter.
- **Veranstaltungen organisieren:** etwa Diskussionsabende, Schulbesuche oder Aktionen rund um den Europatag am 9. Mai.
- **EU-Projekte sichtbar machen:** Viele Gemeindeprojekte werden mit EU-Mitteln mitfinanziert. Europa-Gemeinderäte zeigen, wo das der Fall ist.
- **Anliegen weitertragen:** Sie bringen Perspektiven aus den Gemeinden in Gespräche mit EU-Institutionen ein.

Mitmachen können gewählte Mitglieder eines Gemeinderates, Bürgermeisterinnen und Bürgermeister sowie in Wien Mitglieder der Bezirksvertretungen. Eine Anmeldung erfolgt über das Bundeskanzleramt. Kosten entstehen den Teilnehmenden in der Regel nicht. Die Initiative ist überparteilich, Mitglieder kommen aus allen im Gemeinderat vertretenen Parteien und aus allen Bundesländern – von Vorarlberg bis ins Burgenland.

## Angebote für Europa-Gemeinderäte

Die teilnehmenden Kommunalpolitikerinnen und Kommunalpolitiker erhalten regelmäßige Informationen zu aktuellen EU-Themen und Zugang zu Weiterbildungen. Ein Höhepunkt sind Informationsreisen nach Brüssel, bei denen sie Einrichtungen wie die EU-Kommission, das Europäische Parlament und die Ständige Vertretung Österreichs bei der EU besuchen. Eine solche Reise fand zuletzt etwa im April 2026 statt. Dazu kommen Vernetzungstreffen in Österreich, bei denen sich Gemeinden über gute Beispiele austauschen.

## Warum Europa-Gemeinderäte für Gemeinden wichtig sind

Ein großer Teil der EU-Gesetzgebung wird letztlich auf Gemeindeebene umgesetzt – von Vergaberegeln über Umweltstandards bis zu Vorgaben für Trinkwasser oder Abfall. Gleichzeitig profitieren Gemeinden von EU-Förderprogrammen wie LEADER oder Interreg. Europa-Gemeinderäte helfen dabei, diese Zusammenhänge zu erklären und Fördermöglichkeiten bekannt zu machen.

Für die Bevölkerung sind sie oft die erste persönliche Verbindung zur EU. Wer eine Frage zur Europäischen Union hat, kann in der eigenen Gemeinde nachfragen, ob es dort einen Europa-Gemeinderat gibt. Eine Übersicht stellt das Bundeskanzleramt bereit.

## Europa-Gemeinderäte und die Kommunalpolitik

Die Initiative ergänzt andere Angebote zur EU-Information, etwa die Europe-Direct-Informationszentren in den Bundesländern. Für Gemeinden kann sie auch ein Anstoß sein, Europa stärker in die eigene Arbeit einzubeziehen, etwa durch Partnerschaften mit Gemeinden in anderen EU-Staaten oder durch die Teilnahme an europäischen Netzwerken. In Zeiten, in denen viele Menschen der EU skeptisch gegenüberstehen, setzt das Programm bewusst auf persönliche Gespräche vor Ort.

## Europa-Gemeinderäte im Netzwerk

Ein Vorteil der Initiative ist die Vernetzung. Kommunalpolitikerinnen und Kommunalpolitiker aus kleinen Gemeinden profitieren von den Erfahrungen größerer Städte und umgekehrt. Bei Treffen werden etwa Fragen zu EU-Förderanträgen, zu Gemeindepartnerschaften oder zur Umsetzung neuer EU-Vorgaben besprochen. Wer in der eigenen Gemeinde Interesse an der Funktion hat, kann sich direkt beim Bundeskanzleramt melden und erhält dort weitere Informationen zur Teilnahme.','politik','Europa','vorarlberg','ratgeber','Presseinfo Redaktion','/assets/img/artikel/europa-gemeinderaete-oesterreich-initiative.webp',NULL,NULL,'published','2026-10-11T10:37:00.000Z','2026-10-22T00:17:07.896Z','Europa-Gemeinderäte: Die EU in der Gemeinde','Europa-Gemeinderäte bringen die EU in Österreichs Gemeinden. Was sie tun, wer mitmachen kann und welche Angebote es gibt – jetzt lesen.','Europa-Gemeinderäte','["Europa-Gemeinderäte","Europa-Gemeinderat werden","EU in der Gemeinde","Europa-Gemeinderäte Brüssel Reise","Bundeskanzleramt Europa Initiative","Europa vor Ort","EU-Information Gemeinde","Kommunalpolitik Europa"]','Gemeindesaal vor einer Informationsveranstaltung als Symbolbild zu Europa-Gemeinderäte','Photorealistic editorial photo of a small community hall in a Vorarlberg village prepared for an evening information event, rows of wooden chairs, a projector beam on a blank wall, alpine village visible through windows at dusk, no text, no logos, no readable signs, no people','[{"q":"Wer kann Europa-Gemeinderat werden?","a":"Gewählte Gemeinderatsmitglieder, Bürgermeisterinnen und Bürgermeister sowie in Wien Bezirksrätinnen und Bezirksräte. Die Anmeldung erfolgt beim Bundeskanzleramt."},{"q":"Seit wann gibt es die Europa-Gemeinderäte?","a":"Die Initiative besteht in Österreich seit 2010."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('buergermeister-direktwahl-bundeslaender-ueberblick','Bürgermeister-Direktwahl: In welchen Bundesländern es sie gibt','In Salzburg wird der Bürgermeister direkt gewählt, in Niederösterreich vom Gemeinderat. Ein Überblick über die Regeln in den neun Bundesländern.','Die Bürgermeister-Direktwahl ist in Österreich nicht einheitlich geregelt, weil die Gemeindeordnungen Landessache sind. In sechs Bundesländern bestimmen die Wahlberechtigten ihren Ortschef direkt, in den übrigen wählt ihn der Gemeinderat. Das hat Auswirkungen auf Wahlkämpfe, auf die Stellung des Bürgermeisters und auf die Zusammenarbeit im Gemeinderat.

## Bürgermeister-Direktwahl: Diese Bundesländer haben sie

Direkt gewählt wird der Bürgermeister in:

- **Burgenland**
- **Kärnten**
- **Oberösterreich**
- **Salzburg**
- **Tirol**
- **Vorarlberg** (unter bestimmten Voraussetzungen, etwa wenn kein Wahlvorschlag eingebracht wird, wählt dort die Gemeindevertretung)

Die Direktwahl findet meist gemeinsam mit der Gemeinderatswahl statt. Wer im ersten Wahlgang mehr als die Hälfte der gültigen Stimmen erhält, ist gewählt. Erreicht niemand die absolute Mehrheit, kommt es in der Regel einige Wochen später zu einer Stichwahl zwischen den zwei Bestplatzierten.

## Wahl durch den Gemeinderat

In **Niederösterreich**, der **Steiermark** und **Wien** wird der Bürgermeister vom Gemeinderat gewählt. Die Bevölkerung entscheidet also nur indirekt, indem sie bei der Gemeinderatswahl eine Partei oder Liste wählt. Meist stellt die stärkste Fraktion den Bürgermeister, notwendig ist aber eine Mehrheit im Gemeinderat. Bei knappen Verhältnissen kann es daher auch zu Bündnissen kommen, die eine kleinere Partei an die Spitze bringen.

In Wien ist der Bürgermeister zugleich Landeshauptmann und wird vom Gemeinderat gewählt, der auch Landtag ist.

## Vor- und Nachteile der Direktwahl

Befürworterinnen und Befürworter argumentieren, die Direktwahl stärke die Legitimation des Bürgermeisters und gebe den Bürgerinnen und Bürgern mehr Einfluss. Persönlichkeiten können auch dann gewinnen, wenn ihre Partei im Gemeinderat keine Mehrheit hat.

Kritikerinnen und Kritiker verweisen genau auf diesen Punkt: Wenn Bürgermeister und Gemeinderatsmehrheit aus unterschiedlichen Lagern kommen, kann das die Zusammenarbeit erschweren. Beschlüsse über Budget, Flächenwidmung oder Gebühren fasst nämlich weiterhin der Gemeinderat.

## Wer bei der Bürgermeisterwahl wählen darf

Wahlberechtigt sind grundsätzlich alle, die auch bei der Gemeinderatswahl wählen dürfen. Dazu zählen auch Bürgerinnen und Bürger anderer EU-Staaten mit Hauptwohnsitz in der Gemeinde. Für die Kandidatur zum Bürgermeisteramt verlangen manche Länder hingegen die österreichische Staatsbürgerschaft. Das Mindestalter für das aktive Wahlrecht liegt bei 16 Jahren.

## Bürgermeister-Direktwahl: Was Wählerinnen und Wähler wissen sollten

Bei kombinierten Wahlen erhalten Wahlberechtigte meist zwei Stimmzettel oder einen Stimmzettel mit zwei Teilen: einen für den Gemeinderat und einen für die Bürgermeisterwahl. Man kann dabei unterschiedlich entscheiden, also etwa eine Partei für den Gemeinderat und eine Kandidatin einer anderen Liste für das Bürgermeisteramt wählen. Auch bei Gemeindewahlen gibt es die Möglichkeit der Briefwahl mit Wahlkarte, die Fristen legen die Länder fest. Die amtliche Wahlinformation der Gemeinde nennt alle Termine.

Wie lange eine Funktionsperiode dauert, ist ebenfalls Landessache. In den meisten Bundesländern wird der Gemeinderat alle fünf Jahre gewählt, in Oberösterreich alle sechs Jahre. Die Bürgermeister-Direktwahl findet jeweils im selben Rhythmus statt. Scheidet ein direkt gewählter Bürgermeister vorzeitig aus, regeln die Gemeindewahlordnungen, ob eine Neuwahl stattfindet oder der Gemeinderat für den Rest der Periode wählt.','politik','Gemeinden','oberoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/buergermeister-direktwahl-bundeslaender-ueberblick.webp',NULL,NULL,'published','2026-10-14T14:52:00.000Z','2026-10-22T00:17:07.896Z','Bürgermeister-Direktwahl: Bundesländer im Überblick','Bürgermeister-Direktwahl: In sechs Bundesländern wählt das Volk den Ortschef direkt, sonst der Gemeinderat. Alle Regeln – jetzt lesen.','Bürgermeister-Direktwahl','["Bürgermeister-Direktwahl","Bürgermeisterwahl","Bürgermeister wählen Österreich","Stichwahl Bürgermeister","Gemeinderatswahl Bürgermeister","Bürgermeister Oberösterreich Wahl","Bürgermeister Niederösterreich Gemeinderat","Gemeindeordnung Bürgermeister"]','Marktplatz mit Rathaus in Oberösterreich als Symbolbild zur Bürgermeister-Direktwahl','Photorealistic editorial photo of a traditional Upper Austrian market town square with a baroque town hall, church spire and colorful facades, early morning autumn mist lifting, low angle from the cobblestones, no text, no logos, no readable signs, no identifiable people','[{"q":"In welchen Bundesländern wird der Bürgermeister direkt gewählt?","a":"Im Burgenland, in Kärnten, Oberösterreich, Salzburg, Tirol und Vorarlberg. In Niederösterreich, der Steiermark und Wien wählt der Gemeinderat."},{"q":"Gibt es bei der Bürgermeisterwahl eine Stichwahl?","a":"Ja, erreicht in Bundesländern mit Direktwahl niemand die absolute Mehrheit, folgt meist eine Stichwahl der beiden Bestplatzierten."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('gemeinderat-aufgaben-sitzungen-buerger','Gemeinderat: Aufgaben, Sitzungen und Rechte der Bürger','Der Gemeinderat entscheidet über Budget, Bauland und Gebühren vor Ort. Wie er arbeitet und wie sich Bürgerinnen und Bürger einbringen können.','Der Gemeinderat ist das wichtigste Organ jeder österreichischen Gemeinde. Er wird von der Bevölkerung gewählt und entscheidet über Fragen, die den Alltag unmittelbar betreffen – vom Kindergartenplatz bis zur Müllgebühr. Rund 2.100 Gemeinden gibt es in Österreich, jede hat ihren eigenen Gemeinderat.

## Gemeinderat: Die wichtigsten Aufgaben

Die Gemeindeordnungen der Bundesländer legen fest, was der Gemeinderat entscheidet. Zu den zentralen Aufgaben gehören:

- **Voranschlag und Rechnungsabschluss:** Der Gemeinderat beschließt das Budget der Gemeinde und kontrolliert, wie das Geld verwendet wurde.
- **Flächenwidmung und Bebauungsplan:** Er legt fest, wo gebaut werden darf und was als Grünland erhalten bleibt.
- **Gebühren und Abgaben:** etwa für Wasser, Kanal und Müll sowie bestimmte Gemeindeabgaben.
- **Große Investitionen und Darlehen:** Bau eines Kindergartens, Sanierung von Straßen, Aufnahme von Krediten.
- **Wahl des Bürgermeisters:** in Niederösterreich, der Steiermark und Wien; in den übrigen Ländern wird er direkt gewählt.

Laufende Geschäfte erledigt dagegen der Bürgermeister mit dem Gemeindeamt. Zusätzlich gibt es ein kleineres Gremium, das je nach Bundesland Gemeindevorstand oder in Städten Stadtrat heißt und bestimmte Angelegenheiten vorbereitet oder selbst entscheidet.

## Wie oft der Gemeinderat tagt

Die Gemeindeordnungen schreiben eine Mindestzahl an Sitzungen vor, häufig mindestens vier pro Jahr. In größeren Gemeinden und Städten tagt der Gemeinderat deutlich öfter. Ein Teil der Mitglieder kann zudem eine Sitzung verlangen, die der Bürgermeister dann einberufen muss. Die Einladung samt Tagesordnung wird an der Amtstafel kundgemacht und zunehmend auch online veröffentlicht.

## Gemeinderat: Sitzungen sind öffentlich

Gemeinderatssitzungen sind grundsätzlich öffentlich. Jede Bürgerin und jeder Bürger kann zuhören, ohne Anmeldung. Ausgenommen sind einzelne Tagesordnungspunkte, etwa Personalangelegenheiten oder Fragen, bei denen Datenschutz eine Rolle spielt. Diese werden in nicht öffentlicher Sitzung behandelt. Zuhörerinnen und Zuhörer dürfen sich nicht in die Debatte einmischen, manche Gemeinden bieten aber eine Bürgerfragestunde vor oder nach der Sitzung an.

## Protokolle und Beschlüsse einsehen

Über jede Sitzung wird ein Protokoll geführt. Die Protokolle öffentlicher Sitzungen können in der Regel im Gemeindeamt eingesehen werden, viele Gemeinden stellen sie auch online. Voranschlag und Rechnungsabschluss werden vor dem Beschluss öffentlich aufgelegt, sodass Bürgerinnen und Bürger Stellung nehmen können. Bei Änderungen der Flächenwidmung gibt es ebenfalls eine Auflagefrist, in der Einwendungen möglich sind.

## So bringen Sie sich im Gemeinderat ein

Wer ein Anliegen hat, kann sich an die Fraktionen im Gemeinderat wenden, die Sprechstunde des Bürgermeisters nutzen oder schriftlich eine Anregung einbringen. Viele Gemeindeordnungen sehen außerdem Bürgerversammlungen, Volksbefragungen oder Bürgerbegehren auf Gemeindeebene vor. Die Voraussetzungen unterscheiden sich je nach Bundesland.

Das im Oktober 2026 vorgestellte Gemeindepaket der Reformpartnerschaft sieht übrigens vor, dass Kundmachungen künftig stärker digital erfolgen können. Für Bürgerinnen und Bürger könnte es damit noch einfacher werden, Tagesordnungen und Beschlüsse ihres Gemeinderates zu verfolgen.

Wer selbst im Gemeinderat mitarbeiten möchte, kann bei der nächsten Gemeinderatswahl auf der Liste einer Partei oder einer eigenen Bürgerliste kandidieren. Für einen Wahlvorschlag braucht es in der Regel eine bestimmte Zahl an Unterstützungserklärungen von Wahlberechtigten der Gemeinde. Die genauen Voraussetzungen und Fristen stehen in der Gemeindewahlordnung des jeweiligen Bundeslandes.','politik','Gemeinden','niederoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/gemeinderat-aufgaben-sitzungen-buerger.webp',NULL,NULL,'published','2026-10-21T06:09:00.000Z','2026-10-22T00:17:07.897Z','Gemeinderat: Aufgaben und Rechte der Bürger','Gemeinderat erklärt: Was er beschließt, wie oft er tagt und wie Sie als Bürger Sitzungen besuchen, Protokolle lesen und Anliegen einbringen. Jetzt lesen.','Gemeinderat','["Gemeinderat","Gemeinderat Aufgaben","Gemeinderatssitzung öffentlich","Gemeindevorstand","Gemeinderat Niederösterreich","Voranschlag Gemeinde","Flächenwidmung Gemeinderat","Protokoll Gemeinderatssitzung"]','Sitzungssaal einer Gemeinde in Niederösterreich als Symbolbild zum Gemeinderat','Photorealistic editorial photo of a municipal council chamber in a Lower Austrian small town hall, horseshoe-shaped wooden tables with microphones, a few empty visitor chairs at the back, evening light through arched windows, no text, no logos, no readable signs, no people','[{"q":"Sind Gemeinderatssitzungen öffentlich?","a":"Ja, grundsätzlich können alle zuhören. Einzelne Punkte wie Personalangelegenheiten werden aber nicht öffentlich behandelt."},{"q":"Was beschließt der Gemeinderat?","a":"Unter anderem das Gemeindebudget, Flächenwidmungen, Gebühren für Wasser, Kanal und Müll sowie größere Investitionen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('raiffeisen-konjunktur-oesterreich-2026-halbes-prozent','Konjunktur Österreich: Raiffeisen erwartet 2026 nur 0,5 Prozent Plus','Raiffeisen Research rechnet für heuer nur mit rund einem halben Prozent Wachstum. Auch 2027 und 2028 bleibt Österreich hinter der Eurozone und Deutschland zurück.','Die Konjunktur Österreich kommt 2026 kaum vom Fleck: Raiffeisen Research erwartet für heuer nur ein Wirtschaftswachstum von rund 0,5 Prozent. Das hat Ökonom Matthias Reith beim Business-Frühstück der Raiffeisenlandesbank Kärnten am 14. Oktober in Velden am Wörthersee dargelegt. Damit liegt Österreich deutlich unter dem Durchschnitt der Eurozone.

## Konjunktur Österreich: schwaches erstes Halbjahr

Im ersten Halbjahr 2026 ist die heimische Wirtschaft laut Raiffeisen Research nahezu stagniert. Österreich sei von hohen Energiepreisen, dem Zinsniveau und der allgemeinen Unsicherheit stärker getroffen worden als die meisten anderen europäischen Länder. Lichtblick ist die Stimmung in den Unternehmen: Sie hat sich zuletzt verbessert. Die Analysten gehen daher davon aus, dass die zweite Jahreshälfte etwas besser ausfällt als die erste.

Die Lage in den einzelnen Branchen ist allerdings uneinheitlich:

- Der Aufschwung in der Industrie hat an Tempo verloren.
- Die Bauwirtschaft steckt weiterhin in der Rezession.
- Auch im Dienstleistungsbereich bleibt die Entwicklung schwach.

## Prognose 2027 und 2028: rund ein Prozent pro Jahr

Für 2027 und 2028 rechnet Raiffeisen Research mit einem Wachstum von jeweils etwa einem Prozent. Das wäre zwar eine Verbesserung, Österreich würde aber auch in diesen Jahren langsamer wachsen als die Eurozone und als Deutschland. Die erwartete Erholung werde zudem weniger stark von Investitionen und Exporten getragen sein als frühere Aufschwünge.

Als Grund nennen die Ökonomen vor allem die gesunkene Profitabilität vieler Unternehmen. Sie bremst langfristige Investitionen und damit auch die Aussichten für die Produktivität. Die Finanzierungsbedingungen bieten aus Sicht von Raiffeisen derzeit wenig Rückenwind.

## Wettbewerbsfähigkeit als Schwachstelle

Ein zentrales Problem sehen die Analysten bei den Lohnstückkosten. Diese sind in Österreich in den vergangenen Jahren stärker gestiegen als im Durchschnitt der Eurozone. Das verschlechtert die preisliche Wettbewerbsfähigkeit heimischer Betriebe auf den internationalen Märkten und dürfte das Exportwachstum dämpfen. Gerade für eine exportorientierte Volkswirtschaft wie Österreich ist das ein empfindlicher Punkt.

Raiffeisen Research fordert deshalb Reformen, die die Rahmenbedingungen für Investitionen und die Wettbewerbsfähigkeit des Standorts verbessern. Konkrete Einzelmaßnahmen wurden in der Präsentation nicht im Detail beziffert.

## Zinsen und Inflation: EZB bleibt vorsichtig

Auch zur Geldpolitik äußerte sich Raiffeisen Research. Die Europäische Zentralbank dürfte die Leitzinsen in den kommenden Monaten noch mindestens einmal anheben, um sogenannte Zweitrundeneffekte der Inflation zu verhindern. Erst wenn die Teuerung 2027 nachlässt, sehe man Spielraum für vorsichtige Zinssenkungen.

Bei den langfristigen Kapitalmarktzinsen erwarten die Experten nur begrenzten Rückgang. Sorgen um die öffentlichen Finanzen in den USA und in Europa würden verhindern, dass die Renditen deutlich fallen. Für Kreditnehmer und Häuslbauer bedeutet das: Eine rasche Rückkehr zu sehr niedrigen Finanzierungskosten ist vorerst nicht in Sicht.

## Was die Prognose für Betriebe bedeutet

Für Unternehmen in Kärnten und ganz Österreich zeichnet die Prognose ein Bild langsamer Erholung. Wer Investitionen plant, muss weiter mit vergleichsweise hohen Zinsen und schwacher Nachfrage im Inland rechnen. Gleichzeitig deutet die bessere Stimmung darauf hin, dass der Tiefpunkt in vielen Bereichen erreicht sein könnte. Ob daraus ein nachhaltiger Aufschwung wird, hängt laut Raiffeisen stark davon ab, ob die Politik Reformen für den Standort umsetzt.','wirtschaft','Konjunktur','kaernten','news','Presseinfo Redaktion','/assets/img/artikel/raiffeisen-konjunktur-oesterreich-2026-halbes-prozent.webp','Raiffeisenlandesbank Kärnten','https://www.raiffeisen.at/ktn/rlb/de/meine-bank/aktuelles/2026/business-fruehstueck-2026.html','published','2026-10-14T13:23:00.000Z','2026-10-22T00:17:07.898Z','Konjunktur Österreich: Raiffeisen sieht 0,5 % Wachstum','Konjunktur Österreich: Raiffeisen Research erwartet 2026 nur rund 0,5 % Wachstum und mahnt Reformen ein. Alle Prognosen und Gründe im Überblick.','Konjunktur Österreich','["Konjunktur Österreich","Wirtschaftsprognose 2026","Raiffeisen Research Prognose","Wirtschaftswachstum Österreich 2027","österreich wirtschaft wächst langsamer als eurozone","konjunktur kärnten business frühstück","lohnstückkosten österreich wettbewerbsfähigkeit","ezb zinsen prognose 2027"]','Konjunktur Österreich: Veranstaltungssaal in Velden für Wirtschaftsprognose von Raiffeisen Research','Photorealistic editorial photo of an empty modern conference hall at a lakeside venue in Carinthia, Austria, rows of chairs facing a stage with a blank screen, morning light from large windows, view of Wörthersee in the background, no people, no text, no logos, no readable signs','[{"q":"Wie stark wächst Österreichs Wirtschaft 2026 laut Raiffeisen?","a":"Raiffeisen Research erwartet für 2026 ein Wachstum von rund 0,5 Prozent und damit deutlich weniger als in der Eurozone."},{"q":"Was erwartet Raiffeisen für 2027 und 2028?","a":"Für beide Jahre rechnen die Ökonomen mit jeweils etwa einem Prozent Wachstum, immer noch weniger als Eurozone und Deutschland."},{"q":"Warum wächst Österreich langsamer?","a":"Genannt werden höhere Energiepreise, Zinsen, Unsicherheit, gesunkene Unternehmensgewinne und stark gestiegene Lohnstückkosten."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('wifo-ihs-prognose-oktober-2026-wachstum-inflation','WIFO-Prognose Oktober 2026: 0,9 Prozent Wachstum, Inflation bei 3,3','WIFO und IHS sehen Österreichs Wirtschaft 2026 um 0,8 bis 0,9 Prozent wachsen. Die Inflation bleibt mit über drei Prozent hoch, die Arbeitslosenquote steigt auf 7,6 Prozent.','Die neue WIFO-Prognose vom Oktober 2026 zeigt eine Wirtschaft, die langsam wieder wächst, aber unter hoher Teuerung leidet. Das Wirtschaftsforschungsinstitut WIFO erwartet für heuer ein reales Wachstum von 0,9 Prozent, das Institut für Höhere Studien (IHS) geht von 0,8 Prozent aus. Die gemeinsame Herbstprognose wurde am 14. Oktober vorgelegt.

## WIFO-Prognose: die wichtigsten Zahlen

Für 2027 rechnen beide Institute mit einer leichten Beschleunigung. Das WIFO erwartet dann 1,3 Prozent Wachstum, das IHS 1,0 Prozent. Die Kernzahlen im Überblick:

- Wirtschaftswachstum 2026: 0,9 Prozent (WIFO) bzw. 0,8 Prozent (IHS)
- Wirtschaftswachstum 2027: 1,3 Prozent (WIFO) bzw. 1,0 Prozent (IHS)
- Inflation 2026: 3,3 Prozent (WIFO) bzw. 3,1 Prozent (IHS)
- Inflation 2027: 2,6 Prozent (WIFO) bzw. 2,8 Prozent (IHS)
- Arbeitslosenquote 2026: 7,6 Prozent laut beiden Instituten
- Arbeitslosenquote 2027: 7,3 Prozent (WIFO) bzw. 7,4 Prozent (IHS)

Zum Vergleich: In der Prognose vom Dezember 2025 hatten WIFO und IHS für 2026 noch mit 1,2 bzw. 1,0 Prozent Wachstum und einer Inflation von rund 2,5 Prozent gerechnet. Die Erwartungen wurden also nach unten korrigiert, vor allem wegen der gestiegenen Energiepreise.

## Industrie und Export ziehen an, Bau bleibt schwach

Lichtblick ist die Industrie. Die Wertschöpfung in der Warenherstellung soll laut WIFO heuer um 2,3 Prozent zulegen, getragen von stärkerer Nachfrage aus dem Ausland. Das Niveau von 2022 wird aber weiterhin klar verfehlt. Auch die Exporte erholen sich: Das WIFO erwartet ein Plus von 2,3 Prozent, das IHS von 2,0 Prozent. Bei den Ausrüstungsinvestitionen rechnen die Institute mit einem Zuwachs von 1,9 bzw. 2,5 Prozent.

Die Bauwirtschaft bleibt dagegen das Sorgenkind. Die Bauinvestitionen gehen 2026 laut WIFO um 0,6 Prozent und laut IHS um 1,5 Prozent zurück. Der private Konsum wächst nur leicht, um 0,4 bis 0,5 Prozent. Gestützt wird er vor allem dadurch, dass die Haushalte weniger sparen, obwohl die Reallöhne leicht sinken. Der öffentliche Konsum verlangsamt sich wegen der Budgetkonsolidierung.

## Inflation und Arbeitsmarkt in der WIFO-Prognose

Die Teuerung bleibt das größte Problem für Haushalte. Mit 3,1 bis 3,3 Prozent liegt die erwartete Jahresinflation 2026 deutlich über dem Ziel der Europäischen Zentralbank von zwei Prozent. Erst 2027 soll sie wieder etwas zurückgehen.

Am Arbeitsmarkt ist noch keine Trendwende in Sicht. Die Beschäftigung wächst zwar um 0,4 bis 0,5 Prozent, die Arbeitslosenquote nach nationaler Definition steigt aber auf 7,6 Prozent. Für 2027 wird ein leichter Rückgang erwartet.

## Risiken: Nahost und Energiepreise

Als größte Abwärtsrisiken nennen die Institute den Konflikt im Nahen Osten und dauerhaft hohe Energiepreise. Dazu kommen die Konkurrenz aus China, die schwankende Handelspolitik der USA und eine möglicherweise strengere Budgetsanierung. Positiv könnten sich eine rasche diplomatische Lösung im Nahen Osten und eine kräftigere Erholung der deutschen Industrie auswirken.

Für Unternehmen und Haushalte bedeutet die WIFO-Prognose vor allem eines: Die Erholung kommt, aber sie bleibt zäh. Betriebe in der Industrie können mit etwas besseren Auftragslagen rechnen, während Bauunternehmen und Handel weiter unter Druck stehen. Für Kreditnehmer bleibt die Lage angespannt, solange die Inflation über dem Zielwert der EZB liegt. Die Prognose ist zudem Grundlage für die Budgetplanung des Bundes und für die laufenden Lohnverhandlungen im Herbst. Die nächste Prognose von WIFO und IHS ist für den Winter geplant.','wirtschaft','Konjunktur',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/wifo-ihs-prognose-oktober-2026-wachstum-inflation.webp','WKO – Konjunkturprognose WIFO/IHS 3/2026','https://www.wko.at/oe/news/konjunkturprognose-wifo-ihs-3-2026.pdf','published','2026-10-14T09:07:00.000Z','2026-10-22T00:17:07.898Z','WIFO-Prognose 2026: Wachstum, Inflation, Arbeitslose','WIFO-Prognose Oktober 2026: WIFO und IHS erwarten heuer bis zu 0,9 % Wachstum und über 3 % Inflation. Alle Zahlen für 2026 und 2027 im Überblick.','WIFO-Prognose','["WIFO-Prognose","IHS Prognose","Konjunkturprognose Oktober 2026","Wirtschaftswachstum Österreich 2026","inflation österreich prognose 2027","arbeitslosenquote österreich 2026 prognose","wifo ihs herbstprognose zahlen","bauinvestitionen österreich 2026"]','WIFO-Prognose: Containerhafen an der Donau als Symbol für Exporte und Konjunktur','Photorealistic editorial photo of a large Austrian industrial port area on the Danube near Linz at dusk, cranes and stacked shipping containers, cargo barge on the river, soft orange sky, wide angle, no people, no text, no logos, no readable signs','[{"q":"Wie hoch ist das Wachstum laut WIFO-Prognose 2026?","a":"Das WIFO erwartet 0,9 Prozent, das IHS 0,8 Prozent reales Wachstum für 2026."},{"q":"Welche Inflation erwarten WIFO und IHS?","a":"Für 2026 rechnen sie mit 3,3 bzw. 3,1 Prozent, für 2027 mit 2,6 bzw. 2,8 Prozent."},{"q":"Wie entwickelt sich die Arbeitslosigkeit?","a":"Die Arbeitslosenquote steigt 2026 laut beiden Instituten auf 7,6 Prozent und soll 2027 leicht sinken."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('inflation-oesterreich-september-2026-3-6-prozent','Inflation Österreich: Teuerung steigt im September auf 3,6 Prozent','Die Inflation ist im September laut Schnellschätzung von 3,2 auf 3,6 Prozent gestiegen. Verantwortlich dafür sind vor allem höhere Preise für Treibstoff und Heizöl.','Die Inflation Österreich hat im September wieder angezogen. Laut Schnellschätzung der Statistik Austria lag die Teuerungsrate bei 3,6 Prozent, nach 3,2 Prozent im August. Die Daten wurden Anfang Oktober veröffentlicht, die endgültigen Werte folgen Mitte des Monats.

## Inflation Österreich: Energie als Haupttreiber

Der Anstieg um 0,4 Prozentpunkte geht laut Statistik Austria vollständig auf höhere Preise für Treibstoffe und Heizöl zurück. Generaldirektorin Manuela Lenk verwies darauf, dass andere Bereiche den Anstieg nicht verursacht haben. Energie insgesamt verteuerte sich im Jahresvergleich um 14,5 Prozent, nach 9,9 Prozent im August.

Hintergrund sind die internationalen Energiepreise, die wegen geopolitischer Krisen gestiegen sind. Die Arbeiterkammer verwies auf den Anstieg des Ölpreises nach den Angriffen Israels und der USA auf den Iran.

## Dienstleistungen und Lebensmittel

Abseits der Energie zeigt sich ein gemischtes Bild:

- Dienstleistungen verteuerten sich um 4,2 Prozent, nach 4,4 Prozent im August.
- Nahrungsmittel, Alkohol und Tabak stiegen um 1,0 Prozent (August: 0,3 Prozent).
- Industriegüter lagen mit plus 0,7 Prozent klar unter dem Durchschnitt.

Die Dienstleistungen bleiben damit ein hartnäckiger Preistreiber, auch wenn sich der Anstieg leicht abgeschwächt hat. Bei Lebensmitteln ist die Teuerung im längeren Vergleich weiterhin moderat.

## Vergleich mit dem Euroraum

Der nach europäischen Regeln berechnete harmonisierte Verbraucherpreisindex (HVPI) lag in Österreich vorläufig bei rund 3,5 Prozent. Für den gesamten Euroraum wurde eine Inflation von 3,8 Prozent geschätzt, der höchste Wert seit drei Jahren. Österreich liegt damit nach HVPI-Berechnung erstmals seit längerer Zeit unter dem Durchschnitt der Eurozone.

Zum Vergleich: Im Juni hatte die Inflation in Österreich noch 3,2 Prozent betragen, im Mai 3,7 Prozent. Die Teuerung pendelt also seit Monaten deutlich über dem Ziel der Europäischen Zentralbank von zwei Prozent.

## Spritpreisbremse soll dämpfen

Seit 1. Oktober gilt in Österreich eine Spritpreisbremse, die vorerst bis 30. November befristet ist. Sie soll den Liter Treibstoff um rund 12 Cent verbilligen. Ob und wie stark sich das in den Oktober-Daten niederschlägt, wird die nächste Schnellschätzung zeigen. Ökonomen erwarten jedenfalls, dass die Energiepreise auch in den kommenden Monaten die Inflation bestimmen werden.

Für Haushalte mit hohem Treibstoff- oder Heizölverbrauch ist die aktuelle Entwicklung besonders spürbar, etwa für Pendlerinnen und Pendler im ländlichen Raum oder Haushalte mit Ölheizung. Die Inflationsrate ist auch Grundlage für viele Anpassungen, etwa bei indexierten Mieten, Versicherungsprämien oder den Verhandlungen über Kollektivverträge in der Herbstlohnrunde.

## Inflation Österreich: wie es weitergeht

WIFO und IHS haben in ihrer Herbstprognose vom 14. Oktober für das Gesamtjahr 2026 eine Inflation von 3,1 bis 3,3 Prozent vorhergesagt. Für 2027 rechnen sie mit einem Rückgang auf 2,6 bis 2,8 Prozent. Entscheidend wird sein, wie sich die Ölpreise entwickeln. Sollten sich die Spannungen im Nahen Osten entschärfen, könnte die Teuerung schneller zurückgehen. Bleiben die Energiepreise hoch, droht dagegen, dass sich die Preissteigerungen über höhere Löhne und Dienstleistungspreise verfestigen. Haushalte sollten daher Energieverträge vergleichen und Fixpreisangebote prüfen. Die endgültigen Septemberdaten veröffentlicht die Statistik Austria rund zwei Wochen nach der Schnellschätzung.','wirtschaft','Konjunktur',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/inflation-oesterreich-september-2026-3-6-prozent.webp','Vienna.at','https://www.vienna.at/inflation-erhoehte-sich-im-september-auf-36-prozent/10512623','published','2026-10-02T08:14:00.000Z','2026-10-22T00:17:07.898Z','Inflation Österreich September 2026: 3,6 Prozent','Inflation Österreich: Laut Schnellschätzung stieg die Teuerung im September 2026 auf 3,6 %. Treibstoff und Heizöl sind schuld. Alle Details lesen.','Inflation Österreich','["Inflation Österreich","Inflation September 2026","Teuerung Österreich","Schnellschätzung Statistik Austria","energiepreise österreich september 2026","heizöl treibstoff preise inflation","inflation euroraum september 2026","verbraucherpreisindex österreich aktuell"]','Inflation Österreich: Einkaufskorb an der Supermarktkassa als Symbol für steigende Preise','Photorealistic editorial close-up of a shopping basket with groceries and a paper receipt on a supermarket checkout belt in Vienna, shallow depth of field, cool fluorescent light, no people faces, no text, no logos, no readable signs','[{"q":"Wie hoch war die Inflation in Österreich im September 2026?","a":"Laut Schnellschätzung der Statistik Austria lag sie bei 3,6 Prozent, nach 3,2 Prozent im August."},{"q":"Was treibt die Inflation derzeit?","a":"Der Anstieg geht laut Statistik Austria vollständig auf höhere Preise für Treibstoffe und Heizöl zurück."},{"q":"Wie hoch ist die Inflation im Euroraum?","a":"Für den Euroraum wurden für September 3,8 Prozent geschätzt, der höchste Wert seit drei Jahren."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('spritpreisbremse-oesterreich-12-cent-oktober-2026','Spritpreisbremse Österreich: 12 Cent weniger pro Liter bis November','Seit 1. Oktober gilt die Spritpreisbremse: Mineralölsteuer und Händlermargen sollen den Liter um rund 12 Cent verbilligen. Die Maßnahme läuft vorerst bis Ende November.','Die Spritpreisbremse ist seit Donnerstag, 1. Oktober 2026, in Kraft. Sie soll Benzin und Diesel in Österreich um rund 12 Cent pro Liter verbilligen und ist vorerst auf zwei Monate bis 30. November befristet. Hintergrund sind die stark gestiegenen Energiepreise, die zuletzt auch die Inflation nach oben getrieben haben.

## Wie die Spritpreisbremse funktioniert

Die Maßnahme besteht aus zwei Teilen. Einerseits wird die Mineralölsteuer gesenkt, andererseits werden die Margen der Händler begrenzt. Eine bereits bestehende Steuersenkung ist in der neuen Entlastung nicht eingerechnet. Die zusätzliche Wirkung des neuen Pakets allein liegt bei etwa 10 Cent pro Liter, insgesamt soll der Preis um rund 12 Cent sinken.

Die Margenbegrenzung war politisch umstritten. ÖVP, NEOS und Wirtschaftsvertreter lehnten einen Eingriff in die Preisgestaltung ab, die SPÖ unterstützte ihn. Die nun beschlossene Lösung ist ein Kompromiss, der zunächst nur für Oktober und November gilt.

## Erste Preise nach dem Start

Unmittelbar vor dem Start waren die Preise noch leicht gestiegen. Diesel kostete laut Daten vom Mittwoch im Schnitt rund 2,25 Euro je Liter, Superbenzin knapp 1,94 Euro. Am ersten Tag der Spritpreisbremse beobachtete der ÖAMTC in einer Stichprobe Senkungen von etwa 6 bis 10 Cent, an einigen Tankstellen bis zu 12 Cent. Der ARBÖ sah am frühen Nachmittag noch wenig Bewegung und meldete Durchschnittspreise von 2,221 Euro für Diesel und 1,921 Euro für Super.

Wie bei früheren Preisänderungen dürfte es einige Tage dauern, bis die Entlastung flächendeckend an den Zapfsäulen ankommt.

## Kritik an der Spritpreisbremse

Die Maßnahme stößt auf unterschiedliche Reaktionen:

- Der Energiehandel warnt vor einem Tankstellensterben, weil die Margen gerade kleiner Betreiber ohnehin knapp seien.
- OeNB-Gouverneur Martin Kocher schlug als Alternative vor, gezielt besonders betroffene Pendlerinnen und Pendler zu entlasten.
- In Tirol, wo Treibstoff im Regelfall am teuersten ist, warf die Opposition der Landesregierung mangelnde Verantwortung vor. Landeshauptmann Anton Mattle wies die Kritik zurück.

## Was Autofahrer jetzt beachten sollten

Für Autofahrerinnen und Autofahrer lohnt es sich weiterhin, Preise zu vergleichen. Die E-Control betreibt den Spritpreisrechner, der die günstigsten Tankstellen in der Umgebung anzeigt. Tankstellen dürfen ihre Preise in Österreich nur einmal täglich zu Mittag erhöhen, Senkungen sind jederzeit möglich. Wer flexibel ist, kann daher am späten Vormittag tanken, bevor mögliche Erhöhungen greifen.

Ob die Spritpreisbremse über den 30. November hinaus verlängert wird, ist offen. Das dürfte stark davon abhängen, wie sich die internationalen Ölpreise in den kommenden Wochen entwickeln.

Ökonominnen und Ökonomen verweisen darauf, dass solche Preisbremsen die gemessene Inflation zwar kurzfristig senken, das Budget aber belasten. Zudem profitieren alle Autofahrerinnen und Autofahrer gleichermaßen, unabhängig vom Einkommen. Befürworter halten dagegen, dass gerade Pendler im ländlichen Raum, Handwerksbetriebe und Transportunternehmen auf das Auto angewiesen sind und die hohen Preise kaum ausweichen können. Für Betriebe mit Fuhrpark lohnt es sich, die Tankabrechnungen im Oktober und November genau zu vergleichen. So lässt sich nachvollziehen, ob die Entlastung tatsächlich weitergegeben wird.','wirtschaft','Konjunktur',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/spritpreisbremse-oesterreich-12-cent-oktober-2026.webp','News.at','https://www.news.at/wirtschaft/zweimonatige-spritpreisbremse-tritt-in-kraft','published','2026-10-01T07:42:00.000Z','2026-10-22T00:17:07.898Z','Spritpreisbremse Österreich: So funktioniert sie','Spritpreisbremse Österreich: Seit 1. Oktober soll Treibstoff um 12 Cent je Liter billiger sein. Wie die Maßnahme wirkt und wer sie kritisiert.','Spritpreisbremse','["Spritpreisbremse","Spritpreisbremse Österreich","Spritpreise Oktober 2026","Mineralölsteuer Senkung","dieselpreis österreich aktuell","spritpreisbremse wie lange gilt","tankstellen margen begrenzung","pendler entlastung treibstoff"]','Spritpreisbremse Österreich: Zapfsäule an einer Tankstelle am frühen Morgen','Photorealistic editorial photo of a petrol station fuel pump nozzle in close-up at an Austrian countryside gas station in early morning fog, wet asphalt reflections, muted colors, no people, no text, no logos, no readable signs, no price displays','[{"q":"Wie lange gilt die Spritpreisbremse?","a":"Sie gilt seit 1. Oktober 2026 und ist vorerst bis 30. November befristet."},{"q":"Um wie viel wird Sprit billiger?","a":"Ziel sind rund 12 Cent pro Liter durch eine Senkung der Mineralölsteuer und eine Begrenzung der Händlermargen."},{"q":"Wann darf eine Tankstelle die Preise erhöhen?","a":"Preiserhöhungen sind in Österreich nur einmal täglich zu Mittag erlaubt, Senkungen jederzeit."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('inflation-berechnen-vpi-hvpi-kerninflation-erklaert','Inflation berechnen: Was VPI, HVPI und Kerninflation bedeuten','Wie entsteht die Inflationsrate, die jeden Monat in den Nachrichten steht? Ein Überblick über Warenkorb, VPI, HVPI und Kerninflation und warum die eigene Teuerung oft anders aussieht.','Wer die Inflation berechnen oder verstehen will, stößt schnell auf Abkürzungen wie VPI und HVPI. Jeden Monat veröffentlicht die Statistik Austria eine Schnellschätzung und später die endgültige Inflationsrate. Dahinter steckt ein aufwendiges Verfahren, das die Preisentwicklung eines typischen Haushalts abbilden soll.

## Inflation berechnen mit dem Warenkorb

Grundlage ist der sogenannte Warenkorb. Er enthält mehrere hundert Waren und Dienstleistungen, die Haushalte in Österreich regelmäßig kaufen: von Brot und Milch über Mieten und Energie bis zu Friseurbesuchen, Pauschalreisen und Versicherungen. Erhebungspersonen und automatisierte Verfahren erfassen dafür jeden Monat eine große Zahl an Einzelpreisen in ganz Österreich.

Jede Position im Warenkorb hat ein Gewicht, das ihrem Anteil an den Ausgaben der Haushalte entspricht. Wohnen und Energie fallen daher stärker ins Gewicht als etwa Schreibwaren. Die Gewichtung wird regelmäßig überarbeitet, damit sie dem tatsächlichen Konsum entspricht.

Die Inflationsrate ist dann die prozentuelle Veränderung des Preisniveaus gegenüber dem gleichen Monat des Vorjahres. Eine Rate von 3,6 Prozent bedeutet also: Der gesamte Warenkorb kostet im Schnitt 3,6 Prozent mehr als zwölf Monate zuvor.

## VPI und HVPI: der Unterschied

Der Verbraucherpreisindex (VPI) ist die nationale Messgröße. Er ist in Österreich für viele Verträge relevant, etwa für Wertsicherungsklauseln bei Mieten, Unterhaltszahlungen oder Versicherungen. Wenn in Nachrichten von „der Inflation“ die Rede ist, ist meist der VPI gemeint.

Der harmonisierte Verbraucherpreisindex (HVPI) wird nach einheitlichen Regeln in allen EU-Staaten berechnet. Er dient dem Vergleich innerhalb Europas und ist Maßstab für die Geldpolitik der Europäischen Zentralbank. Weil die Gewichtung anders ist, etwa durch die Ausgaben ausländischer Touristen, können VPI und HVPI leicht voneinander abweichen.

## Kerninflation und andere Kennzahlen

Die Kerninflation klammert stark schwankende Bereiche aus, meist Energie und unverarbeitete Lebensmittel. Sie zeigt, wie hartnäckig die Teuerung im Rest der Wirtschaft ist. Ökonomen schauen darauf, um zu beurteilen, ob sich Preissteigerungen dauerhaft festsetzen.

Daneben gibt es weitere Indizes:

- Der Mikrowarenkorb bildet den täglichen Einkauf ab, etwa Lebensmittel.
- Der Miniwarenkorb enthält den wöchentlichen Einkauf inklusive Treibstoff.
- Der Pensionistenpreisindex gewichtet Ausgaben älterer Haushalte stärker.

## Persönliche Inflation: warum sie abweicht

Viele Menschen haben das Gefühl, dass die Teuerung höher ist als die offizielle Zahl. Das kann stimmen, denn die persönliche Inflation hängt vom eigenen Konsum ab. Wer viel pendelt, mit Öl heizt oder eine indexierte Miete zahlt, spürt Preissprünge bei Energie und Wohnen stärker. Wer wenig fährt und im Eigentum wohnt, ist weniger betroffen.

Die Statistik Austria bietet online einen persönlichen Inflationsrechner an. Dort lassen sich die eigenen Ausgabenanteile eintragen, um eine individuelle Teuerungsrate zu ermitteln.

## Wofür die Inflationsrate wichtig ist

Die Inflationsrate beeinflusst Lohnverhandlungen, Pensionsanpassungen, Mieten und Zinsen. Bei Kollektivvertragsverhandlungen wird oft die durchschnittliche Inflation der vergangenen zwölf Monate herangezogen. Wer einen Vertrag mit Wertsicherung unterschreibt, sollte genau prüfen, welcher Index und welcher Ausgangsmonat vereinbart sind.','wirtschaft','Konjunktur',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/inflation-berechnen-vpi-hvpi-kerninflation-erklaert.webp',NULL,NULL,'published','2026-09-29T06:16:00.000Z','2026-10-22T00:17:07.898Z','Inflation berechnen: VPI, HVPI und Kerninflation','Inflation berechnen leicht erklärt: So misst Statistik Austria die Teuerung, was VPI, HVPI und Kerninflation unterscheidet. Jetzt verständlich lesen.','Inflation berechnen','["Inflation berechnen","VPI Österreich","HVPI","Kerninflation","warenkorb statistik austria erklärt","unterschied vpi hvpi österreich","persönliche inflationsrate berechnen","wertsicherung miete vpi"]','Inflation berechnen: Taschenrechner, Münzen und Haushaltsbuch auf einem Küchentisch','Photorealistic editorial flat lay on a wooden kitchen table: a calculator, coins in euro, a handwritten household budget notebook without readable writing, a coffee cup, soft morning window light in a Viennese apartment, no text, no logos, no readable signs','[{"q":"Was ist der Unterschied zwischen VPI und HVPI?","a":"Der VPI ist der nationale Index für Österreich, der HVPI wird EU-weit einheitlich berechnet und dient dem europäischen Vergleich."},{"q":"Was ist die Kerninflation?","a":"Sie misst die Teuerung ohne stark schwankende Bereiche wie Energie und unverarbeitete Lebensmittel."},{"q":"Kann ich meine persönliche Inflation berechnen?","a":"Ja, die Statistik Austria bietet online einen persönlichen Inflationsrechner an, in den man die eigenen Ausgaben einträgt."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('firmenpleiten-oesterreich-2026-ksv1870-drei-quartale','Firmenpleiten Österreich: KSV1870 zählt 19 Insolvenzen pro Tag','Mehr als 5.100 Unternehmen sind heuer bis Mitte September insolvent geworden. Besonders auffällig: Immer mehr Verfahren werden mangels Vermögen gar nicht eröffnet.','Die Firmenpleiten Österreich bleiben auf hohem Niveau. Laut Hochrechnung des Kreditschutzverbands KSV1870 mussten in den ersten drei Quartalen 2026 insgesamt 5.139 Unternehmen Insolvenz anmelden. Das sind um 0,4 Prozent mehr als im Vorjahreszeitraum und im Schnitt rund 19 Betriebe pro Tag. Stichtag der Auswertung war der 16. September.

## Firmenpleiten Österreich: alarmierender Trend bei Abweisungen

Auffällig ist vor allem die Entwicklung bei den nicht eröffneten Verfahren. Rund 43 Prozent der Fälle, insgesamt 2.204, wurden mangels Kostendeckung gar nicht eröffnet. Das heißt, die betroffenen Firmen hatten nicht einmal genug Vermögen, um die Kosten eines Insolvenzverfahrens zu decken. Diese Fälle stiegen um 12,6 Prozent, während die Zahl der eröffneten Verfahren um 7,2 Prozent zurückging. Der KSV1870 bezeichnet diese Entwicklung als alarmierend.

Für Gläubiger ist das besonders bitter: Wird ein Verfahren nicht eröffnet, gibt es in der Regel keine Quote. Lieferanten, Vermieter oder Dienstleister bleiben dann meist auf ihren Forderungen sitzen.

## Handel, Bau und Gastronomie am stärksten betroffen

Nach Branchen ergibt sich folgendes Bild:

- Der Handel liegt mit 861 Fällen weiter an der Spitze, verzeichnet aber um 3,5 Prozent weniger Insolvenzen. Die nicht eröffneten Verfahren stiegen hier allerdings um 17,2 Prozent.
- Das Baugewerbe folgt mit 719 Fällen, das ist ein leichtes Minus von 0,3 Prozent.
- Gastronomie und Beherbergung liegen auf Rang drei und legten um 9,8 Prozent zu. Als Gründe nennt der KSV hohe Betriebskosten und Personalmangel.
- Im Grundstücks- und Wohnungswesen ging die Gesamtzahl um zehn Prozent zurück, die nicht eröffneten Verfahren stiegen aber um fast 30 Prozent.

## Passiva sinken, mehr Beschäftigte betroffen

Die geschätzten Verbindlichkeiten belaufen sich auf rund sechs Milliarden Euro und liegen damit um sieben Prozent unter dem Vorjahr. Die bisher größte Insolvenz des Jahres ist jene der Laura Privatstiftung mit Passiva von rund 1,7 Milliarden Euro.

Von den Pleiten sind heuer bisher rund 15.700 Beschäftigte betroffen, ein Plus von 4,7 Prozent. Die Zahl der betroffenen Gläubigerinnen und Gläubiger stieg um 8,7 Prozent auf etwa 36.300.

## Prognose und Forderungen des KSV1870

Für das Gesamtjahr 2026 erwartet der KSV1870 rund 6.800 Unternehmensinsolvenzen, also etwa so viele wie im Vorjahr. Der Gläubigerschutzverband fordert eine gesetzliche Regelung für Fälle, die mangels Masse abgewiesen werden. Außerdem spricht er sich gegen eine automatische Erhöhung der Arbeitgeberbeiträge zum Insolvenz-Entgelt-Fonds aus, aus dem offene Löhne betroffener Beschäftigter bezahlt werden.

## Was Betriebe daraus lernen können

Die Zahlen zeigen, wie wichtig ein funktionierendes Forderungsmanagement ist. Wer Kunden auf Rechnung beliefert, sollte deren Bonität prüfen, Zahlungsziele kurz halten und bei Verzug rasch reagieren. Für eigene Liquiditätsengpässe gilt: Je früher ein Unternehmen gegensteuert, desto größer sind die Chancen auf eine Sanierung statt eines Konkurses.

Bereits zur Jahresmitte hatte der KSV1870 rund 3.400 Firmenpleiten gezählt, ein leichtes Minus gegenüber dem Vorjahr. Damals fiel vor allem Vorarlberg mit einem Anstieg von 38 Prozent auf, während Tirol einen deutlichen Rückgang verzeichnete. Dass die Zahl nun über das Vorjahresniveau gestiegen ist, zeigt, dass sich die Lage im Sommer nicht entspannt hat. Ökonomen sehen in den hohen Energiepreisen, der schwachen Nachfrage am Bau und den gestiegenen Personalkosten die wichtigsten Belastungen für kleinere Betriebe.','wirtschaft','Unternehmen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/firmenpleiten-oesterreich-2026-ksv1870-drei-quartale.webp','Leadersnet','https://www.leadersnet.at/news/103744,in-diesen-branchen-gehen-die-meisten-unternehmen-pleite.html','published','2026-09-22T05:48:00.000Z','2026-10-22T00:17:07.899Z','Firmenpleiten Österreich 2026: 19 Insolvenzen pro Tag','Firmenpleiten Österreich: Laut KSV1870 gab es in drei Quartalen 2026 über 5.100 Insolvenzen. Welche Branchen betroffen sind, lesen Sie hier.','Firmenpleiten Österreich','["Firmenpleiten Österreich","Insolvenzen 2026","KSV1870 Hochrechnung","Unternehmensinsolvenzen Österreich","insolvenzen handel bau gastronomie 2026","mangels kostendeckung abgewiesen","größte pleite 2026 österreich","insolvenzstatistik drei quartale"]','Firmenpleiten Österreich: leeres, geschlossenes Geschäftslokal mit leeren Regalen','Photorealistic editorial photo of an empty closed shop interior in an Austrian town, bare shelves, dust in sunlight beams through a large display window, a stack of cardboard boxes on the floor, melancholic mood, no people, no text, no logos, no readable signs','[{"q":"Wie viele Firmenpleiten gab es 2026 in Österreich?","a":"Laut KSV1870 waren es in den ersten drei Quartalen 5.139 Unternehmensinsolvenzen, im Schnitt rund 19 pro Tag."},{"q":"Welche Branchen sind am stärksten betroffen?","a":"Am häufigsten betroffen sind Handel, Bau sowie Gastronomie und Beherbergung."},{"q":"Was bedeutet mangels Kostendeckung abgewiesen?","a":"Das Unternehmen hat nicht genug Vermögen, um die Verfahrenskosten zu decken. Das Verfahren wird nicht eröffnet, Gläubiger erhalten meist nichts."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('insolvenzen-wien-2026-creditreform-hoechste-quote','Insolvenzen Wien: Bundeshauptstadt mit höchster Pleitenquote','Wien führt die Insolvenzstatistik an: 2.584 Privatkonkurse und eine Firmenpleitenquote von fast 23 pro 1.000 Unternehmen. Die Zahl der Firmenpleiten ist aber leicht gesunken.','Bei den Insolvenzen Wien liegt die Bundeshauptstadt auch heuer an der Spitze aller Bundesländer. Laut Auswertung des Gläubigerschutzverbands Creditreform für die ersten drei Quartale 2026 wurden in Wien 2.584 Privatinsolvenzen eröffnet, um 105 Fälle oder 4,2 Prozent mehr als im Vorjahreszeitraum. Gemessen an der Bevölkerung ist das der höchste Wert in Österreich.

## Insolvenzen Wien: die Zahlen im Detail

Pro 10.000 Erwachsene kamen in Wien 16,2 Privatkonkurse zusammen. Der österreichweite Durchschnitt liegt bei 10,7. Bei den Unternehmen zeigt sich ein ähnliches Bild: Mit rund 22,8 Firmeninsolvenzen pro 1.000 Unternehmen weist Wien ebenfalls die höchste Quote auf, im Bundesschnitt sind es 13,9.

Allerdings ist die Zahl der Firmenpleiten in Wien leicht gesunken. Mit 1.885 Fällen gab es um 2,7 Prozent weniger Unternehmensinsolvenzen als in den ersten drei Quartalen des Vorjahres.

## Bundesländer im Vergleich

Die Creditreform-Daten zeigen deutliche regionale Unterschiede:

- Bei den Privatinsolvenzen folgen auf Wien Vorarlberg mit 12,0, Kärnten mit 10,5, Tirol mit 10,4 und Oberösterreich mit 10,2 Fällen pro 10.000 Erwachsene.
- Am niedrigsten ist die Quote im Burgenland mit 5,0.
- Bei den Firmenpleiten verzeichnete Vorarlberg den stärksten Anstieg mit fast 49 Prozent.
- Tirol hat mit 7,2 Fällen pro 1.000 Unternehmen die niedrigste Firmenpleitenquote, Niederösterreich liegt bei 13,2, die Steiermark bei 12,4 und Kärnten bei 13,8.

Die Privatinsolvenzen sind laut Creditreform in allen Bundesländern gestiegen.

## Warum die Privatkonkurse zunehmen

Ein wesentlicher Grund für den Anstieg bei den Privatinsolvenzen ist das Auslaufen einer Sonderregel. Seit der Reform des Insolvenzrechts konnten sich Schuldner in einem vereinfachten Verfahren innerhalb von drei Jahren entschulden. Diese Möglichkeit endete Mitte Juli 2026. Viele Betroffene haben deshalb noch vor Ablauf der Frist einen Antrag gestellt. Bereits im Sommer hatte Creditreform von sprunghaft steigenden Schuldenregulierungsverfahren berichtet, im Juli um fast 70 Prozent mehr als ein Jahr zuvor.

## Hohe Dichte an Kleinunternehmen

Dass Wien bei den Firmenpleiten so hoch liegt, hat auch strukturelle Gründe. In der Stadt gibt es besonders viele Ein-Personen-Unternehmen und junge Firmen, etwa im Handel, in der Gastronomie und bei unternehmensbezogenen Dienstleistungen. Diese Betriebe haben oft geringe Rücklagen und sind anfälliger für steigende Kosten.

## Hilfe bei Schulden in Wien

Wer private Zahlungsprobleme hat, sollte nicht zu lange warten. Die staatlich anerkannten Schuldenberatungen, in Wien die Schuldnerberatung der Stadt, helfen kostenlos bei der Erstellung eines Haushaltsplans, bei Verhandlungen mit Gläubigern und bei einem möglichen Schuldenregulierungsverfahren. Für Unternehmer bieten die Wirtschaftskammer und spezialisierte Sanierungsberater Unterstützung.

Wichtig ist, frühzeitig zu handeln: Wer Mahnungen ignoriert, riskiert zusätzliche Kosten durch Inkasso, Zinsen und Exekution. Ein Schuldenregulierungsverfahren kann auch nach dem Ende der Sonderregel sinnvoll sein. Seit Mitte Juli gilt wieder die reguläre Dauer des Tilgungsplans, die länger ist als die zuletzt mögliche dreijährige Variante. Die Details sollten Betroffene mit einer Schuldenberatung klären. Erste Anlaufstellen sind auch die Arbeiterkammer und, für Selbstständige, die Wirtschaftskammer Wien.','wirtschaft','Unternehmen','wien','news','Presseinfo Redaktion','/assets/img/artikel/insolvenzen-wien-2026-creditreform-hoechste-quote.webp','MeinBezirk.at','https://www.meinbezirk.at/wien/c-wirtschaft/wien-bei-insolvenzen-oesterreichischer-spitzenreiter_a8940603','published','2026-10-07T10:34:00.000Z','2026-10-22T00:17:07.899Z','Insolvenzen Wien 2026: höchste Quote Österreichs','Insolvenzen Wien: Laut Creditreform hat Wien 2026 die höchste Pleitenquote bei Firmen und Privaten. Zahlen und Bundesländervergleich im Überblick.','Insolvenzen Wien','["Insolvenzen Wien","Privatkonkurs Wien","Firmeninsolvenzen Wien 2026","Creditreform Insolvenzstatistik","privatinsolvenzen österreich bundesländer vergleich","insolvenzquote pro 1000 unternehmen","schuldenregulierungsverfahren anstieg 2026","pleiten vorarlberg anstieg"]','Insolvenzen Wien: Gang in einem historischen Wiener Gerichtsgebäude','Photorealistic editorial photo of a historic Viennese courthouse corridor with high arched ceilings, marble floor and wooden benches, late afternoon light, empty, symbolizing insolvency court, no people, no text, no logos, no readable signs','[{"q":"Wie viele Privatkonkurse gab es 2026 in Wien?","a":"Laut Creditreform wurden in den ersten drei Quartalen 2026 in Wien 2.584 Privatinsolvenzen eröffnet."},{"q":"Welches Bundesland hat die meisten Firmenpleiten?","a":"Gemessen an der Zahl der Unternehmen hat Wien mit rund 22,8 Fällen pro 1.000 Firmen die höchste Quote."},{"q":"Wo gibt es in Wien Hilfe bei Schulden?","a":"Die staatlich anerkannte Schuldnerberatung der Stadt Wien berät kostenlos und unterstützt auch beim Schuldenregulierungsverfahren."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('insolvenzverfahren-oesterreich-konkurs-sanierung-ablauf','Insolvenzverfahren Österreich: Konkurs oder Sanierung – der Ablauf','Konkurs, Sanierungsverfahren, Eigenverwaltung: Wer zahlungsunfähig wird, hat mehrere Wege. Ein Überblick über Antrag, Fristen, Quoten und die Folgen für Beschäftigte.','Ein Insolvenzverfahren Österreich wird beim zuständigen Landesgericht geführt, in Wien beim Handelsgericht. Ziel ist es, das Vermögen eines zahlungsunfähigen oder überschuldeten Unternehmens geordnet zu verwerten oder das Unternehmen zu sanieren. Das österreichische Recht kennt dafür im Wesentlichen zwei Wege: den Konkurs und das Sanierungsverfahren.

## Wann ein Insolvenzverfahren Österreich nötig ist

Ein Insolvenzantrag ist zu stellen, wenn ein Unternehmen zahlungsunfähig ist, also seine fälligen Schulden nicht mehr bezahlen kann und sich daran in absehbarer Zeit nichts ändert. Bei Kapitalgesellschaften wie der GmbH ist zusätzlich die Überschuldung ein Insolvenzgrund. Die Geschäftsführung muss den Antrag ohne schuldhaftes Zögern stellen, spätestens aber binnen 60 Tagen nach Eintritt der Zahlungsunfähigkeit. Wer zu lange wartet, riskiert eine persönliche Haftung und strafrechtliche Folgen.

Auch Gläubiger, etwa Lieferanten, die Krankenkasse oder das Finanzamt, können einen Antrag stellen.

## Konkursverfahren: Verwertung des Vermögens

Im Konkursverfahren bestellt das Gericht einen Insolvenzverwalter. Er übernimmt die Verwaltung, prüft die angemeldeten Forderungen und verwertet das Vermögen. Der Erlös wird nach Abzug der Verfahrenskosten an die Gläubiger verteilt. Meist wird das Unternehmen am Ende geschlossen. Möglich ist aber auch, dass Teile oder der ganze Betrieb an einen Investor verkauft werden.

Auch im Konkurs kann der Schuldner einen Sanierungsplan anbieten. Wird er angenommen, kann das Unternehmen weiter bestehen.

## Sanierungsverfahren mit und ohne Eigenverwaltung

Beim Sanierungsverfahren steht die Fortführung im Vordergrund. Der Schuldner bietet den Gläubigern einen Sanierungsplan an. Die Mindestquote beträgt 20 Prozent der Forderungen, zahlbar innerhalb von zwei Jahren. Die Mehrheit der anwesenden Gläubiger muss zustimmen, und zwar sowohl nach Köpfen als auch nach der Höhe der Forderungen.

Bietet der Schuldner mindestens 30 Prozent an und legt er bereits mit dem Antrag einen vollständigen Finanzplan vor, kann er ein Sanierungsverfahren mit Eigenverwaltung beantragen. Dann bleibt die Geschäftsführung im Amt und wird nur von einem Sanierungsverwalter überwacht.

## Folgen für Beschäftigte und Gläubiger

Für Arbeitnehmerinnen und Arbeitnehmer gibt es einen wichtigen Schutz: Offene Löhne, Gehälter und Abfertigungen werden unter bestimmten Voraussetzungen aus dem Insolvenz-Entgelt-Fonds bezahlt. Den Antrag stellen Betroffene bei der IEF-Service GmbH, unterstützt von Arbeiterkammer oder Gewerkschaft. Dafür gelten Fristen, die man nicht versäumen sollte.

Gläubiger melden ihre Forderungen beim Insolvenzgericht an. Wichtige Schritte im Überblick:

1. Insolvenz in der Ediktsdatei prüfen und Aktenzeichen notieren
2. Forderung schriftlich mit Belegen anmelden, Fristen beachten
3. Prüfungstagsatzung abwarten, bei der die Forderungen anerkannt oder bestritten werden
4. Über den Sanierungsplan abstimmen oder sich vertreten lassen

## Frühzeitig Hilfe holen

Je früher ein Unternehmen Probleme erkennt, desto besser die Chancen auf eine Sanierung. Steuerberater, Rechtsanwälte und die Wirtschaftskammer bieten Beratung. Gläubigerschutzverbände wie KSV1870, AKV oder Creditreform vertreten Gläubiger in den Verfahren. Die genauen Voraussetzungen und Fristen sollten im Einzelfall immer mit Fachleuten geklärt werden.

Für Selbstständige und Ein-Personen-Unternehmen ist zudem wichtig: Betrifft die Insolvenz einen Einzelunternehmer oder eine Einzelunternehmerin, haftet die Person mit ihrem gesamten Privatvermögen. Hier kommen je nach Situation ein Sanierungsverfahren oder später auch ein Schuldenregulierungsverfahren in Frage. Bei einer GmbH ist die Haftung grundsätzlich auf das Gesellschaftsvermögen beschränkt, Geschäftsführer können aber bei Pflichtverletzungen persönlich haften.','wirtschaft','Unternehmen',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/insolvenzverfahren-oesterreich-konkurs-sanierung-ablauf.webp',NULL,NULL,'published','2026-09-25T07:21:00.000Z','2026-10-22T00:17:07.899Z','Insolvenzverfahren Österreich: Konkurs vs. Sanierung','Insolvenzverfahren Österreich erklärt: Unterschied zwischen Konkurs und Sanierungsverfahren, Fristen, Quoten und Ablauf. Jetzt Überblick holen.','Insolvenzverfahren Österreich','["Insolvenzverfahren Österreich","Sanierungsverfahren","Konkursverfahren","Eigenverwaltung","insolvenz anmelden frist 60 tage","sanierungsplan quote 20 prozent","insolvenz entgelt fonds iesg","insolvenzantrag landesgericht"]','Insolvenzverfahren Österreich: Schreibtisch mit Ordnern und Füllfeder in einer Kanzlei','Photorealistic editorial photo of a lawyer''s desk in an Austrian office with thick binders, a fountain pen and a closed laptop, rain on the window, overcast daylight, serious mood, no people, no text, no logos, no readable signs','[{"q":"Was ist der Unterschied zwischen Konkurs und Sanierungsverfahren?","a":"Im Konkurs wird das Vermögen meist verwertet und der Betrieb geschlossen. Im Sanierungsverfahren soll das Unternehmen mit einem Sanierungsplan weitergeführt werden."},{"q":"Wie hoch muss die Quote beim Sanierungsplan sein?","a":"Mindestens 20 Prozent innerhalb von zwei Jahren, bei Eigenverwaltung mindestens 30 Prozent."},{"q":"Wer zahlt Löhne, wenn der Arbeitgeber insolvent ist?","a":"Offene Ansprüche werden unter bestimmten Voraussetzungen aus dem Insolvenz-Entgelt-Fonds bezahlt. Der Antrag geht an die IEF-Service GmbH."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('forderung-anmelden-insolvenz-glaeubiger-tipps','Forderung anmelden bei Insolvenz: So kommen Gläubiger zu ihrem Geld','Wenn ein Kunde pleitegeht, zählt jeder Tag. Wie Lieferanten und Dienstleister ihre Forderung richtig anmelden und welche Rechte sie im Verfahren haben.','Wer als Lieferant oder Dienstleister von der Pleite eines Kunden betroffen ist, muss seine Forderung anmelden, um überhaupt eine Chance auf Zahlung zu haben. Das gilt für offene Rechnungen genauso wie für Schadenersatz oder Mietrückstände. Wer die Anmeldung versäumt, geht bei der Verteilung leer aus oder hat zusätzliche Kosten.

## Insolvenz erkennen: die Ediktsdatei

Insolvenzverfahren werden in Österreich in der Ediktsdatei der Justiz veröffentlicht. Dort finden Gläubiger das zuständige Gericht, das Aktenzeichen, den Namen des Insolvenzverwalters und die wichtigen Termine. Es lohnt sich, die wichtigsten Kunden regelmäßig zu prüfen. Gläubigerschutzverbände und Wirtschaftsauskunfteien bieten dafür auch automatische Benachrichtigungen an.

## Forderung anmelden: so funktioniert es

Die Anmeldung erfolgt schriftlich beim Insolvenzgericht. Sie sollte mindestens enthalten:

- Name und Anschrift des Gläubigers
- Aktenzeichen des Verfahrens
- Höhe der Forderung samt Zinsen und Kosten, getrennt aufgelistet
- Rechtsgrund, etwa Lieferung, Werkleistung oder Darlehen
- Belege wie Rechnungen, Lieferscheine, Verträge und Mahnungen
- Hinweise auf besondere Rechte, etwa Eigentumsvorbehalt oder Pfandrechte

Im Edikt ist eine Anmeldefrist angegeben. Spätere Anmeldungen sind zwar oft noch möglich, verursachen aber Kosten und können bei bestimmten Abstimmungen nicht mehr berücksichtigt werden. Für die Anmeldung fällt eine Pauschalgebühr an.

## Vertretung durch Gläubigerschutzverbände

Viele Unternehmen lassen sich von einem bevorrechteten Gläubigerschutzverband vertreten, etwa KSV1870, AKV oder Creditreform. Diese übernehmen die Anmeldung, nehmen an den Tagsatzungen teil und stimmen im Auftrag ab. Für kleinere Forderungen ist das oft effizienter als eigene Anwaltskosten. Die konkreten Konditionen sollte man vorab erfragen.

## Rechte im Verfahren nutzen

Nach der Anmeldung prüft der Insolvenzverwalter die Forderung. Bei der Prüfungstagsatzung wird sie anerkannt oder bestritten. Wird eine Forderung bestritten, kann der Gläubiger sie mit einer Klage durchsetzen. Dafür gibt es eine Frist.

Besondere Bedeutung hat der Eigentumsvorbehalt. Wurde vereinbart, dass gelieferte Ware bis zur vollständigen Bezahlung im Eigentum des Lieferanten bleibt, kann er sie unter Umständen aussondern lassen. Das sollte möglichst rasch beim Verwalter geltend gemacht werden.

Im Sanierungsverfahren stimmen die Gläubiger über den Sanierungsplan ab. Die gesetzliche Mindestquote beträgt 20 Prozent, bei Eigenverwaltung 30 Prozent. Wer nicht zustimmt, ist trotzdem an einen mehrheitlich angenommenen Plan gebunden.

## Vorbeugen: Forderungsausfälle vermeiden

Gerade weil laut KSV1870 rund 43 Prozent der Insolvenzen mangels Vermögen gar nicht eröffnet werden, ist Vorbeugung entscheidend. Bewährte Maßnahmen sind:

1. Bonität neuer Kunden vor großen Aufträgen prüfen
2. Anzahlungen oder Teilrechnungen vereinbaren, vor allem am Bau
3. Eigentumsvorbehalt in die Geschäftsbedingungen aufnehmen
4. Zahlungsziele kurz halten und Mahnungen konsequent verschicken
5. Bei Verdacht auf Zahlungsschwierigkeiten rasch Sicherheiten verlangen

Die genauen Fristen und Gebühren ändern sich und hängen vom Einzelfall ab. Im Zweifel sollten Gläubiger einen Gläubigerschutzverband oder eine Rechtsanwältin beiziehen.

Ein Tipp zum Schluss: Bewahren Sie alle Unterlagen zu einer Geschäftsbeziehung sorgfältig auf, also Angebote, Auftragsbestätigungen, Lieferscheine und den E-Mail-Verkehr. Im Insolvenzverfahren muss jede Forderung belegt werden. Je vollständiger die Dokumentation ist, desto geringer ist das Risiko, dass der Insolvenzverwalter eine Forderung bestreitet und ein aufwendiger Prozess nötig wird.','wirtschaft','Unternehmen',NULL,'ratgeber','Presseinfo Redaktion','/assets/img/artikel/forderung-anmelden-insolvenz-glaeubiger-tipps.webp',NULL,NULL,'published','2026-10-09T12:06:00.000Z','2026-10-22T00:17:07.899Z','Forderung anmelden bei Insolvenz: Tipps für Gläubiger','Forderung anmelden bei Insolvenz: Welche Fristen gelten, welche Unterlagen nötig sind und wie Gläubiger ihre Quote sichern. Jetzt Schritt für Schritt.','Forderung anmelden','["Forderung anmelden","Insolvenz Gläubiger","Ediktsdatei","Forderungsanmeldung Insolvenz","forderung anmelden insolvenz frist österreich","gläubigerschutzverband vertretung","eigentumsvorbehalt insolvenz","quote sanierungsplan gläubiger"]','Forderung anmelden: Unternehmer sortiert offene Rechnungen in der Werkstatt','Photorealistic editorial photo of a small business owner''s hands sorting unpaid invoices and a folder on a workshop counter in a Styrian craft business, warm desk lamp light, tools blurred in background, face not visible, no text, no logos, no readable signs','[{"q":"Wo melde ich eine Forderung bei Insolvenz an?","a":"Beim zuständigen Insolvenzgericht, das in der Ediktsdatei angegeben ist, schriftlich und mit Belegen."},{"q":"Was passiert, wenn ich die Anmeldefrist versäume?","a":"Eine spätere Anmeldung ist oft noch möglich, kostet aber extra und kann bei Abstimmungen nicht mehr berücksichtigt werden."},{"q":"Kann mich ein Gläubigerschutzverband vertreten?","a":"Ja, KSV1870, AKV oder Creditreform übernehmen Anmeldung, Teilnahme an Tagsatzungen und Abstimmungen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('bonitaet-pruefen-firma-oesterreich-firmenbuch-ediktsdatei','Bonität prüfen: So checken Sie eine Firma in Österreich','Bevor ein großer Auftrag auf Rechnung geht, lohnt ein Blick auf den Geschäftspartner. Welche Register in Österreich öffentlich sind und worauf man achten sollte.','Wer regelmäßig auf Rechnung liefert, sollte die Bonität prüfen, bevor er einen größeren Auftrag annimmt. Das gilt besonders in Zeiten hoher Insolvenzzahlen. In Vorarlberg etwa stiegen die Firmenpleiten laut KSV1870 im ersten Halbjahr 2026 um 38 Prozent. In Österreich gibt es mehrere öffentliche Register, die schnell Hinweise auf die Verlässlichkeit eines Geschäftspartners liefern.

## Bonität prüfen mit dem Firmenbuch

Das Firmenbuch ist das zentrale Register für eingetragene Unternehmen wie GmbH, AG, OG, KG oder eingetragene Einzelunternehmer (e.U.). Über die Justiz und zugelassene Verrechnungsstellen kann jeder gegen eine geringe Gebühr einen Firmenbuchauszug abrufen. Er zeigt unter anderem:

- den genauen Firmenwortlaut und die Firmenbuchnummer
- Sitz und Geschäftsanschrift
- Geschäftsführer und vertretungsbefugte Personen
- Gesellschafter und Stammkapital bei einer GmbH
- eingereichte Jahresabschlüsse

Gerade die Jahresabschlüsse sind aufschlussreich. Kapitalgesellschaften müssen sie einreichen. Fehlen sie über Jahre oder zeigen sie negatives Eigenkapital, ist Vorsicht angebracht. Häufige Wechsel bei Geschäftsführung oder Sitz können ebenfalls ein Warnsignal sein.

## Ediktsdatei: laufende Insolvenzen

In der Ediktsdatei der Justiz werden Insolvenzverfahren veröffentlicht, aber auch Versteigerungen. Die Abfrage ist kostenlos. Wer einen neuen Kunden prüft, sollte nachsehen, ob gegen ihn oder gegen frühere Firmen der Geschäftsführer bereits Verfahren gelaufen sind.

## GISA und UID-Nummer

Im Gewerbeinformationssystem Austria, kurz GISA, sieht man, ob und welche Gewerbeberechtigungen ein Unternehmen hat. Das ist wichtig, wenn etwa ein Baubetrieb oder ein Installateur beauftragt wird. Fehlt die passende Berechtigung, drohen Probleme bei Gewährleistung und Haftung.

Die Umsatzsteuer-Identifikationsnummer kann über das MIAS-System der EU-Kommission oder über FinanzOnline überprüft werden. Bei Geschäften mit Partnern im EU-Ausland ist diese Prüfung ohnehin Pflicht, wenn ohne Umsatzsteuer fakturiert wird.

## Bonitätsauskunft von Auskunfteien

Kreditschutzverbände und Wirtschaftsauskunfteien bieten kostenpflichtige Bonitätsauskünfte an. Sie verknüpfen Daten aus Firmenbuch und Ediktsdatei mit Zahlungserfahrungen und vergeben eine Bonitätsnote. Für regelmäßige Geschäftspartner lohnt sich oft ein Monitoring, das bei Verschlechterungen automatisch warnt.

## Checkliste vor dem großen Auftrag

1. Firmenbuchauszug abrufen und Jahresabschlüsse ansehen
2. Ediktsdatei auf Insolvenzen prüfen
3. Gewerbeberechtigung im GISA kontrollieren
4. UID-Nummer verifizieren
5. Bei hohen Summen eine Bonitätsauskunft einholen
6. Anzahlung oder Sicherheiten vereinbaren und einen Eigentumsvorbehalt festhalten

Auch im Alltag gibt es Warnsignale. Nicht jeder Hinweis steht in einem Register. Auch das Zahlungsverhalten verrät viel. Kunden, die plötzlich längere Zahlungsziele verlangen, nur noch Teilbeträge überweisen oder schwer erreichbar sind, sollten genauer beobachtet werden. Eine rasche, freundliche Nachfrage und eine klare Mahnpolitik schützen vor bösen Überraschungen.

Für kleine Betriebe ist der Aufwand überschaubar. Ein Firmenbuchauszug ist in wenigen Minuten abgerufen, die Ediktsdatei und das GISA lassen sich kostenlos online durchsuchen. Wer diese Prüfungen zur Routine macht, etwa bei jedem Auftrag über einer selbst festgelegten Summe, senkt das Risiko von Forderungsausfällen deutlich. Gerade für Handwerksbetriebe, die Material vorfinanzieren, kann eine einzige geplatzte Rechnung existenzbedrohend sein. Wer zusätzlich eine Kreditversicherung abschließt, kann größere Ausfälle absichern.','wirtschaft','Unternehmen','vorarlberg','ratgeber','Presseinfo Redaktion','/assets/img/artikel/bonitaet-pruefen-firma-oesterreich-firmenbuch-ediktsdatei.webp',NULL,NULL,'published','2026-10-16T06:52:00.000Z','2026-10-22T00:17:07.900Z','Bonität prüfen: Firma in Österreich richtig checken','Bonität prüfen in Österreich: Mit Firmenbuch, Ediktsdatei, GISA und Auskunfteien erkennen Sie riskante Geschäftspartner. Checkliste jetzt lesen.','Bonität prüfen','["Bonität prüfen","Firmenbuchauszug","Ediktsdatei","Bonitätsauskunft Firma","firma überprüfen österreich kostenlos","gisa gewerbeinformationssystem abfrage","jahresabschluss firmenbuch einsehen","uid nummer prüfen"]','Bonität prüfen: Laptop und Lupe im Büro mit Blick auf die Vorarlberger Berge','Photorealistic editorial photo of a laptop on a desk in a modern office in Vorarlberg with mountain view through the window, screen showing an abstract blurred spreadsheet, magnifying glass next to it, crisp autumn daylight, no people, no text, no logos, no readable signs','[{"q":"Wie kann ich eine Firma in Österreich kostenlos überprüfen?","a":"Kostenlos sind etwa die Ediktsdatei für Insolvenzen und das GISA für Gewerbeberechtigungen. Der Firmenbuchauszug kostet eine geringe Gebühr."},{"q":"Was zeigt ein Firmenbuchauszug?","a":"Er zeigt Firmenwortlaut, Sitz, Geschäftsführung, Gesellschafter, Stammkapital und eingereichte Jahresabschlüsse."},{"q":"Wann lohnt sich eine Bonitätsauskunft?","a":"Vor größeren Aufträgen auf Rechnung und bei neuen Kunden, über die man wenig weiß."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('arbeitnehmerveranlagung-steuerausgleich-tipps-geld-zurueck','Arbeitnehmerveranlagung: So holen Sie sich Geld vom Finanzamt zurück','Viele Beschäftigte verschenken Geld, weil sie keinen Steuerausgleich machen. Welche Kosten zählen, wie lange man Zeit hat und wie der Antrag online funktioniert.','Die Arbeitnehmerveranlagung, umgangssprachlich Steuerausgleich, bringt vielen Beschäftigten in Österreich Geld zurück. Das Finanzamt berechnet dabei die Lohnsteuer für das abgelaufene Jahr neu und berücksichtigt Ausgaben, die beim laufenden Lohnsteuerabzug noch nicht eingerechnet wurden. Wer keinen Antrag stellt, verschenkt oft einen dreistelligen Betrag oder mehr.

## Wer von der Arbeitnehmerveranlagung profitiert

Besonders lohnend ist der Antrag in folgenden Fällen:

- Das Einkommen war im Jahr unterschiedlich hoch, etwa wegen eines Jobwechsels, Arbeitslosigkeit oder Karenz.
- Es gab Werbungskosten wie Fortbildungen, Fachliteratur oder Arbeitsmittel.
- Sonderausgaben wie Kirchenbeitrag, Spenden an begünstigte Organisationen oder Steuerberatungskosten sind angefallen.
- Es gibt außergewöhnliche Belastungen, etwa Krankheitskosten über dem Selbstbehalt.
- Familienleistungen wie der Familienbonus Plus wurden noch nicht über den Arbeitgeber berücksichtigt.
- Bei geringem Einkommen kann es eine Gutschrift der Sozialversicherungsbeiträge geben, die sogenannte Negativsteuer.

Kirchenbeitrag, Spenden und bestimmte Beiträge werden heute in vielen Fällen automatisch von den Empfängern an das Finanzamt gemeldet. Trotzdem lohnt sich ein Blick darauf, ob alles korrekt übernommen wurde.

## Werbungskosten: was absetzbar ist

Werbungskosten sind Ausgaben, die mit dem Beruf zusammenhängen. Dazu zählen etwa Kurse und Weiterbildungen, die mit der ausgeübten oder einer verwandten Tätigkeit zu tun haben, Arbeitskleidung, die privat nicht getragen werden kann, Fachbücher und berufliche Software, ein Anteil an Arbeitsmitteln wie Laptop oder Handy sowie Mitgliedsbeiträge zu Berufsverbänden. Pendlerpauschale und Pendlereuro werden meist bereits über die Lohnverrechnung berücksichtigt, können aber auch in der Veranlagung beantragt werden.

Eine pauschale Werbungskostenpauschale wird automatisch abgezogen. Nur wenn die tatsächlichen Kosten höher sind, wirken sie sich zusätzlich aus. Die aktuellen Beträge und Grenzen sollten immer auf der Website des Finanzministeriums nachgelesen werden.

## Arbeitnehmerveranlagung über FinanzOnline

Am einfachsten ist der Antrag über FinanzOnline, das Online-Portal der Finanzverwaltung. Der Zugang erfolgt heute über die ID Austria. Das Formular L1 ist dort elektronisch hinterlegt, viele Daten wie Lohnzettel und gemeldete Sonderausgaben sind bereits vorausgefüllt. Wer lieber auf Papier einreicht, kann das Formular beim Finanzamt abgeben.

Die Frist ist großzügig: Eine freiwillige Arbeitnehmerveranlagung kann bis zu fünf Jahre rückwirkend beantragt werden. Wer für ein früheres Jahr noch keinen Antrag gestellt hat, kann ihn also nachholen.

## Antragslose Veranlagung und Pflichtveranlagung

Wer bis Ende Juni keinen Antrag gestellt hat und nach den Daten des Finanzamts eine Gutschrift bekommt, erhält diese unter bestimmten Voraussetzungen automatisch im Rahmen der antragslosen Arbeitnehmerveranlagung. Absetzbare Kosten, die das Finanzamt nicht kennt, fehlen dabei aber. Ein eigener Antrag ist daher oft günstiger.

In manchen Fällen besteht dagegen eine Pflicht zur Veranlagung, etwa wenn gleichzeitig zwei Dienstverhältnisse bestanden oder bestimmte Nebeneinkünfte über einer Grenze lagen. Dann kann es auch zu einer Nachzahlung kommen.

## Tipps für einen erfolgreichen Antrag

1. Belege während des Jahres in einem Ordner oder digital sammeln
2. Lohnzettel in FinanzOnline auf Vollständigkeit prüfen
3. Werbungskosten und außergewöhnliche Belastungen nachvollziehbar aufschlüsseln
4. Belege mindestens sieben Jahre aufbewahren, falls das Finanzamt nachfragt
5. Bei Unsicherheit die kostenlose Steuerberatung der Arbeiterkammer nutzen

In Wien bietet die Arbeiterkammer regelmäßig Beratungstermine und Ausfüllhilfen an. Das lohnt sich vor allem beim ersten Antrag oder bei komplizierten Fällen.','wirtschaft','Finanzen','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/arbeitnehmerveranlagung-steuerausgleich-tipps-geld-zurueck.webp',NULL,NULL,'published','2026-09-23T05:31:00.000Z','2026-10-22T00:17:07.901Z','Arbeitnehmerveranlagung: Geld vom Finanzamt zurück','Arbeitnehmerveranlagung in Österreich: Welche Ausgaben absetzbar sind, welche Fristen gelten und wie der Antrag über FinanzOnline klappt. Jetzt lesen.','Arbeitnehmerveranlagung','["Arbeitnehmerveranlagung","Steuerausgleich","FinanzOnline","Werbungskosten absetzen","arbeitnehmerveranlagung frist 5 jahre","sonderausgaben kirchenbeitrag spenden","antraglose arbeitnehmerveranlagung","familienbonus plus beantragen"]','Arbeitnehmerveranlagung: Hände am Laptop mit Belegen auf dem Küchentisch in Wien','Photorealistic editorial photo of a person''s hands typing on a laptop at a kitchen table in a Viennese Altbau apartment in the evening, warm lamp light, a folder of receipts and a cup of tea beside, face not visible, screen blurred, no text, no logos, no readable signs','[{"q":"Wie lange kann ich die Arbeitnehmerveranlagung rückwirkend machen?","a":"Eine freiwillige Arbeitnehmerveranlagung ist bis zu fünf Jahre rückwirkend möglich."},{"q":"Wie beantrage ich den Steuerausgleich online?","a":"Über FinanzOnline mit ID Austria, dort wird das Formular L1 elektronisch ausgefüllt."},{"q":"Bekomme ich Geld auch ohne Antrag zurück?","a":"Teilweise ja, über die antragslose Veranlagung. Absetzbare Kosten fehlen dabei aber, ein eigener Antrag bringt oft mehr."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('kleinunternehmerregelung-oesterreich-umsatzgrenze-erklaert','Kleinunternehmerregelung Österreich: Umsatzgrenze und Vorsteuer','Wer wenig Umsatz macht, muss keine Umsatzsteuer verrechnen. Die Kleinunternehmerregelung spart Aufwand, hat aber auch Nachteile, etwa beim Vorsteuerabzug.','Die Kleinunternehmerregelung befreit Unternehmen mit geringem Umsatz von der Umsatzsteuer. Wer darunter fällt, stellt Rechnungen ohne Umsatzsteuer aus und muss in der Regel keine Umsatzsteuervoranmeldungen abgeben. Für viele Gründerinnen und Gründer in Österreich, etwa im Handwerk, in der Beratung oder im Kreativbereich, ist das ein wichtiger Vorteil in der Anfangsphase.

## Kleinunternehmerregelung: die Umsatzgrenze

Seit 2025 liegt die Grenze für Kleinunternehmer in Österreich bei 55.000 Euro Bruttoumsatz pro Jahr. Maßgeblich sind die Umsätze im laufenden und im vorangegangenen Kalenderjahr. Wird die Grenze im laufenden Jahr überschritten, entfällt die Befreiung nach den aktuellen Regeln ab dem Umsatz, mit dem die Grenze überschritten wird. Eine geringfügige Überschreitung kann unter bestimmten Bedingungen toleriert werden.

Nicht alle Umsätze zählen zur Grenze. Bestimmte steuerfreie Umsätze, etwa aus ärztlicher Tätigkeit oder bestimmte Vermietungen, werden nicht eingerechnet. Da sich die Regeln in den letzten Jahren mehrfach geändert haben, sollten die Details beim Finanzamt, bei der Wirtschaftskammer oder beim Steuerberater geprüft werden.

## Vorteile für Kleinunternehmer

- Rechnungen ohne Umsatzsteuer sind für Privatkunden günstiger.
- Es fällt weniger Verwaltungsaufwand an, etwa keine laufenden Voranmeldungen.
- Die Buchhaltung bleibt übersichtlich, was gerade in der Gründungsphase Zeit spart.

Auf jeder Rechnung muss ein Hinweis stehen, dass die Kleinunternehmerregelung angewendet wird. Üblich ist eine Formulierung wie „Umsatzsteuerbefreit – Kleinunternehmer“.

## Nachteile: kein Vorsteuerabzug

Die Befreiung hat eine Kehrseite. Kleinunternehmer dürfen die Umsatzsteuer, die ihnen andere Unternehmen verrechnen, nicht als Vorsteuer abziehen. Wer am Anfang viel investiert, etwa in Maschinen, ein Firmenauto oder Einrichtung, zahlt die volle Umsatzsteuer und bekommt sie nicht zurück.

Auch bei Geschäftskunden ist die Regelung oft kein Vorteil. Unternehmen können sich die Umsatzsteuer ohnehin als Vorsteuer zurückholen. Für sie macht es keinen Unterschied, ob auf der Rechnung Umsatzsteuer steht oder nicht.

## Option zur Regelbesteuerung

Kleinunternehmer können freiwillig auf die Befreiung verzichten und zur sogenannten Regelbesteuerung optieren. Dann verrechnen sie Umsatzsteuer und dürfen die Vorsteuer abziehen. Dieser Verzicht bindet das Unternehmen für mehrere Jahre. Er lohnt sich vor allem bei hohen Anfangsinvestitionen oder wenn fast nur Geschäftskunden betreut werden.

## Was Gründer jetzt prüfen sollten

1. Erwarteten Jahresumsatz realistisch schätzen
2. Kundengruppe analysieren: überwiegend Privat- oder Geschäftskunden?
3. Geplante Investitionen und mögliche Vorsteuer berechnen
4. Hinweis auf der Rechnung korrekt anbringen
5. Umsatz laufend beobachten, um die Grenze nicht unbemerkt zu überschreiten

Wichtig: Die Kleinunternehmerregelung betrifft nur die Umsatzsteuer. Einkommensteuer und Sozialversicherung fallen unabhängig davon an. Wer die Regelung nutzt, muss trotzdem eine Einkommensteuererklärung abgeben, sobald die Einkünfte über der jeweiligen Grenze liegen.

Die Gründerservices der Wirtschaftskammer in allen Bundesländern, auch in der Steiermark, beraten kostenlos zu diesen Fragen. Bei größeren Investitionen ist ein Gespräch mit einer Steuerberaterin sinnvoll, um die günstigste Variante zu finden.

Ein Rechenbeispiel zeigt den Unterschied: Eine Grafikerin, die vor allem für Unternehmen arbeitet und im ersten Jahr einen Computer, Software und Büromöbel um mehrere tausend Euro anschafft, kann bei Regelbesteuerung die darin enthaltene Umsatzsteuer zurückholen. Ihre Geschäftskunden stört die zusätzlich ausgewiesene Umsatzsteuer nicht. Ein Masseur oder eine Fußpflegerin mit überwiegend Privatkundschaft profitiert dagegen meist von der Befreiung, weil die Preise für Endkunden niedriger bleiben können. Welche Variante sich rechnet, ist also immer eine Frage des Einzelfalls.','wirtschaft','Finanzen','steiermark','ratgeber','Presseinfo Redaktion','/assets/img/artikel/kleinunternehmerregelung-oesterreich-umsatzgrenze-erklaert.webp',NULL,NULL,'published','2026-09-30T11:47:00.000Z','2026-10-22T00:17:07.901Z','Kleinunternehmerregelung Österreich einfach erklärt','Kleinunternehmerregelung in Österreich: Wann keine Umsatzsteuer anfällt, welche Umsatzgrenze gilt und was Gründer beachten müssen. Jetzt nachlesen.','Kleinunternehmerregelung','["Kleinunternehmerregelung","Kleinunternehmer Österreich","Umsatzsteuerbefreiung","Umsatzgrenze 55.000 Euro","kleinunternehmerregelung rechnung hinweis","vorsteuerabzug kleinunternehmer","regelbesteuerung option","umsatzsteuer gründer österreich"]','Kleinunternehmerregelung: Werkbank einer kleinen Keramikwerkstatt in der Steiermark','Photorealistic editorial photo of a small craft workshop in a Styrian village, a ceramic artisan''s workbench with finished bowls and a notebook, natural light from a side window, autumn colors outside, no people, no text, no logos, no readable signs','[{"q":"Wie hoch ist die Umsatzgrenze für Kleinunternehmer in Österreich?","a":"Seit 2025 liegt sie bei 55.000 Euro Bruttoumsatz pro Jahr. Details zu Überschreitung und Berechnung sollten beim Finanzamt oder Steuerberater geprüft werden."},{"q":"Was muss auf der Rechnung eines Kleinunternehmers stehen?","a":"Ein Hinweis, dass die Kleinunternehmerregelung angewendet wird und daher keine Umsatzsteuer ausgewiesen ist."},{"q":"Kann ich auf die Kleinunternehmerregelung verzichten?","a":"Ja, durch Option zur Regelbesteuerung. Dann darf man die Vorsteuer abziehen, ist aber mehrere Jahre gebunden."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('rechnung-schreiben-oesterreich-pflichtangaben','Rechnung schreiben in Österreich: Diese Pflichtangaben braucht es','Fehlt auf einer Rechnung eine Pflichtangabe, kann der Kunde die Vorsteuer verlieren. Welche Merkmale eine korrekte Rechnung in Österreich enthalten muss.','Wer in Österreich eine Rechnung schreiben muss, sollte die Pflichtangaben des Umsatzsteuergesetzes kennen. Fehlen Merkmale, ist die Rechnung zwar meist zivilrechtlich gültig, der Kunde kann aber die Vorsteuer verlieren. Das sorgt für Ärger und kostet Zeit, weil Rechnungen korrigiert werden müssen.

## Rechnung schreiben: die Pflichtangaben

Eine Rechnung über mehr als 400 Euro brutto muss unter anderem folgende Angaben enthalten:

- Name und Anschrift des leistenden Unternehmens
- Name und Anschrift des Kunden
- Menge und handelsübliche Bezeichnung der Waren oder Art und Umfang der Leistung
- Tag oder Zeitraum der Lieferung bzw. Leistung
- Nettobetrag, Steuersatz und Steuerbetrag
- Ausstellungsdatum
- eine fortlaufende Rechnungsnummer
- die UID-Nummer des leistenden Unternehmens

Liegt der Gesamtbetrag über 10.000 Euro brutto, muss zusätzlich die UID-Nummer des Kunden angeführt werden, wenn der Kunde ein Unternehmen ist.

## Kleinbetragsrechnung bis 400 Euro

Für Rechnungen bis 400 Euro brutto gibt es Erleichterungen. Bei einer sogenannten Kleinbetragsrechnung reichen Name und Anschrift des Ausstellers, Menge und Bezeichnung der Leistung, Tag der Leistung, Bruttobetrag und Steuersatz. Name und Anschrift des Kunden sowie die UID-Nummer sind nicht nötig. Das betrifft etwa Kassenbons im Handel oder kleinere Handwerkerleistungen.

## Sonderfälle bei Rechnungen

Einige Konstellationen verlangen besondere Hinweise:

- Kleinunternehmer weisen keine Umsatzsteuer aus und vermerken die Befreiung.
- Beim Reverse-Charge-Verfahren, etwa bei Bauleistungen zwischen Unternehmen oder bei Leistungen an Unternehmen im EU-Ausland, schuldet der Kunde die Steuer. Auf der Rechnung muss darauf hingewiesen und die UID-Nummer des Kunden angegeben werden.
- Bei innergemeinschaftlichen Lieferungen ist ein Hinweis auf die Steuerfreiheit nötig.
- Anzahlungsrechnungen und Schlussrechnungen müssen sauber aufeinander abgestimmt sein, damit die Steuer nicht doppelt ausgewiesen wird.

## Fortlaufende Nummer und Aufbewahrung

Die Rechnungsnummer muss einmalig vergeben werden und einer nachvollziehbaren Systematik folgen. Lücken sollten vermieden werden. Rechnungen sind in Österreich grundsätzlich sieben Jahre aufzubewahren, bei Grundstücken teils länger. Die Aufbewahrung kann auch elektronisch erfolgen, wenn die Echtheit und Lesbarkeit gesichert sind.

## E-Rechnung und Software

Für Leistungen an den Bund ist eine elektronische Rechnung in einem strukturierten Format über das Unternehmensserviceportal vorgeschrieben. Auf EU-Ebene sind weitere Schritte zur verpflichtenden E-Rechnung zwischen Unternehmen geplant. Wann und wie diese in Österreich umgesetzt werden, sollten Betriebe laufend verfolgen.

Viele Unternehmen nutzen heute Rechnungsprogramme, die Pflichtangaben automatisch einfügen und fortlaufende Nummern vergeben. Das reduziert Fehler deutlich. Auch für Kleinbetriebe in Oberösterreich und anderswo gibt es günstige Online-Lösungen.

Häufige Fehler, die man vermeiden sollte:

1. Leistungszeitraum vergessen, etwa bei Monatsabrechnungen
2. Pauschale Bezeichnungen wie „Diverse Arbeiten“ statt konkreter Leistung
3. Falscher Steuersatz, etwa bei unterschiedlichen Sätzen für Waren
4. Fehlende UID-Nummer des Kunden bei Rechnungen über 10.000 Euro
5. Rechnungsnummer doppelt vergeben

Wer unsicher ist, lässt seine Rechnungsvorlage einmal von einer Steuerberaterin prüfen. Das Merkblatt des Finanzministeriums zu den Rechnungsmerkmalen bietet ebenfalls eine gute Übersicht über die aktuelle Rechtslage.','wirtschaft','Finanzen','oberoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/rechnung-schreiben-oesterreich-pflichtangaben.webp',NULL,NULL,'published','2026-10-06T08:28:00.000Z','2026-10-22T00:17:07.901Z','Rechnung schreiben Österreich: alle Pflichtangaben','Rechnung schreiben in Österreich: Welche Pflichtangaben gelten, was eine Kleinbetragsrechnung ist und welche Fehler Vorsteuer kosten. Checkliste lesen.','Rechnung schreiben','["Rechnung schreiben","Rechnungsmerkmale Österreich","Kleinbetragsrechnung","UID-Nummer Rechnung","rechnung pflichtangaben über 10000 euro","rechnungsnummer fortlaufend","e-rechnung österreich unternehmen","reverse charge rechnung hinweis"]','Rechnung schreiben: Drucker gibt ein Rechnungsblatt in einem Handwerksbüro aus','Photorealistic editorial photo of a printer outputting a blank white invoice sheet in a small office of an Upper Austrian trades business, toolbox and safety helmet on a shelf in background, morning light, no people, no text, no logos, no readable signs','[{"q":"Was ist eine Kleinbetragsrechnung?","a":"Eine Rechnung bis 400 Euro brutto, für die vereinfachte Angaben genügen, etwa ohne Name des Kunden und UID-Nummer."},{"q":"Ab wann muss die UID-Nummer des Kunden auf die Rechnung?","a":"Bei Rechnungen an Unternehmen über 10.000 Euro brutto sowie bei Reverse-Charge-Leistungen."},{"q":"Wie lange muss ich Rechnungen aufbewahren?","a":"Grundsätzlich sieben Jahre, bei Grundstücken teilweise länger."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('sparen-inflation-tagesgeld-einlagensicherung-tipps','Sparen bei Inflation: Tagesgeld, Festgeld und Einlagensicherung','Bei 3,6 Prozent Inflation verliert Geld auf dem Konto an Wert. Wie Sparerinnen und Sparer reagieren können und warum die Einlagensicherung wichtig ist.','Sparen bei Inflation ist eine Herausforderung: Liegt die Teuerung über den Zinsen, verliert das Ersparte real an Kaufkraft. Im September lag die Inflation in Österreich laut Schnellschätzung bei 3,6 Prozent. Wer sein Geld auf einem täglich fälligen Konto mit niedriger Verzinsung liegen lässt, wird also real ärmer. Mit einigen Grundregeln lässt sich der Verlust zumindest verringern.

## Sparen bei Inflation: Realzins verstehen

Entscheidend ist der Realzins, also der Zinssatz nach Abzug der Inflation. Bei einem Zins von zwei Prozent und einer Inflation von 3,6 Prozent liegt der Realzins bei minus 1,6 Prozent. Dazu kommt die Kapitalertragsteuer: Auf Sparzinsen werden in Österreich 25 Prozent KESt automatisch von der Bank abgezogen. Der tatsächliche Ertrag ist also noch geringer.

Ein positiver Realzins ist mit klassischen Sparprodukten derzeit kaum zu erreichen. Ziel ist daher oft, den Kaufkraftverlust so gering wie möglich zu halten.

## Tagesgeld und Festgeld im Vergleich

- Tagesgeld ist jederzeit verfügbar und eignet sich für den Notgroschen. Die Zinsen können sich aber laufend ändern.
- Festgeld bindet das Geld für einen bestimmten Zeitraum zu einem fixen Zinssatz. Vorzeitige Auflösung ist meist nicht oder nur mit Verlust möglich.
- Das klassische Sparbuch bietet häufig die niedrigsten Zinsen.

Ein Vergleich zwischen Banken lohnt sich, denn die Konditionen unterscheiden sich deutlich. Lockangebote gelten oft nur für Neukunden oder für wenige Monate. Wichtig ist, auch auf Kontoführungsgebühren zu achten, die den Ertrag schmälern.

## Einlagensicherung: Schutz bis 100.000 Euro

Guthaben auf Konten und Sparbüchern sind in Österreich durch die gesetzliche Einlagensicherung pro Person und Bank bis 100.000 Euro geschützt. Geht eine Bank pleite, erhalten Kundinnen und Kunden ihr Geld bis zu dieser Grenze zurück. Bei bestimmten Ereignissen, etwa nach einem Wohnungsverkauf, gilt vorübergehend ein höherer Schutz.

Bei ausländischen Banken gilt die Einlagensicherung des jeweiligen Landes. Wer über Online-Plattformen bei Banken im EU-Ausland anlegt, sollte prüfen, welche Sicherung gilt und wie die Steuer abgewickelt wird.

## Notgroschen zuerst

Bevor Geld langfristig angelegt wird, sollte ein Notgroschen auf einem täglich verfügbaren Konto liegen. Häufig empfohlen werden drei bis sechs Nettomonatsgehälter. Damit lassen sich unerwartete Ausgaben wie eine kaputte Waschmaschine oder eine Autoreparatur bezahlen, ohne teure Kredite oder den Überziehungsrahmen zu nutzen.

## Langfristig: breiter streuen

Wer Geld viele Jahre nicht braucht, kann einen Teil auch in Wertpapiere investieren, etwa in breit gestreute Fonds. Aktien schwanken stärker, haben langfristig aber in der Vergangenheit oft höhere Erträge gebracht als Sparprodukte. Eine Garantie gibt es nicht. Vor einer Entscheidung sollte man das eigene Risiko realistisch einschätzen und sich unabhängig beraten lassen.

Die wichtigsten Tipps im Überblick:

1. Notgroschen auf Tagesgeld halten
2. Zinsangebote mehrerer Banken vergleichen
3. Festgeld nur für Beträge, die sicher nicht gebraucht werden
4. Einlagensicherungsgrenze von 100.000 Euro pro Bank beachten
5. Gebühren und Steuern in die Rechnung einbeziehen
6. Bei langfristigen Anlagen breit streuen und Beratung einholen

Die Arbeiterkammer und die Konsumentenschützer veröffentlichen regelmäßig Vergleiche zu Sparzinsen. Auch Verbraucherschützer in Salzburg bieten Beratung zu Geldanlage und Bankgebühren an.','wirtschaft','Finanzen','salzburg','ratgeber','Presseinfo Redaktion','/assets/img/artikel/sparen-inflation-tagesgeld-einlagensicherung-tipps.webp',NULL,NULL,'published','2026-10-12T14:12:00.000Z','2026-10-22T00:17:07.901Z','Sparen bei Inflation: Tipps für Ihr Erspartes','Sparen bei Inflation: Wie Tagesgeld, Festgeld und Anleihen im Vergleich abschneiden und wie die Einlagensicherung schützt. Jetzt Tipps lesen.','Sparen bei Inflation','["Sparen bei Inflation","Tagesgeld Österreich","Festgeld Vergleich","Einlagensicherung 100.000 Euro","realzins negativ was tun","kest auf sparzinsen 25 prozent","notgroschen wie viel","sparbuch alternative"]','Sparen bei Inflation: Sparschwein auf einem Fensterbrett mit Blick über Salzburg','Photorealistic editorial photo of an old ceramic piggy bank on a windowsill of a traditional Salzburg house, rooftops and the fortress hill softly blurred in background, golden autumn evening light, no people, no text, no logos, no readable signs','[{"q":"Wie viel ist durch die Einlagensicherung geschützt?","a":"Guthaben sind pro Person und Bank bis 100.000 Euro gesetzlich gesichert."},{"q":"Wie hoch ist die Steuer auf Sparzinsen?","a":"In Österreich werden 25 Prozent Kapitalertragsteuer automatisch von der Bank abgezogen."},{"q":"Wie hoch sollte ein Notgroschen sein?","a":"Häufig empfohlen werden drei bis sechs Nettomonatsgehälter auf einem täglich verfügbaren Konto."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('steuern-kmu-oesterreich-einkommensteuer-sv-vorauszahlung','Steuern für KMU in Österreich: Fristen, Vorauszahlungen, SVS','Einkommensteuer, Umsatzsteuer, Sozialversicherung: Kleine Betriebe müssen viele Fristen im Blick behalten. Ein Überblick, wie Unternehmer Nachzahlungen vermeiden.','Steuern KMU betreffen in Österreich gleich mehrere Ebenen: Einkommen- oder Körperschaftsteuer, Umsatzsteuer, Sozialversicherung und bei Beschäftigten die Lohnabgaben. Gerade junge Unternehmen unterschätzen oft, wie hoch die Belastung im zweiten und dritten Jahr ausfallen kann. Wer die Fristen kennt und Rücklagen bildet, vermeidet unangenehme Überraschungen.

## Steuern KMU: die wichtigsten Abgaben

Einzelunternehmer und Personengesellschafter zahlen Einkommensteuer nach dem progressiven Tarif. Für eine GmbH fällt Körperschaftsteuer an, die seit 2024 bei 23 Prozent liegt. Gewinnausschüttungen an die Gesellschafter werden zusätzlich mit Kapitalertragsteuer belastet.

Dazu kommen:

- Umsatzsteuer, sofern das Unternehmen nicht unter die Kleinunternehmerregelung fällt
- Beiträge zur Sozialversicherung der Selbständigen (SVS) für Pensions-, Kranken- und Unfallversicherung
- Lohnsteuer, Sozialversicherungsbeiträge und Lohnnebenkosten für Beschäftigte
- je nach Gemeinde und Tätigkeit weitere Abgaben wie die Kommunalsteuer

## Vorauszahlungen: die Falle im zweiten Jahr

Nach dem ersten Steuerbescheid setzt das Finanzamt Vorauszahlungen für die Folgejahre fest. Sie sind vierteljährlich fällig, jeweils Mitte Februar, Mai, August und November. Gleichzeitig kommt die Nachzahlung für das erste Jahr. Ähnlich ist es bei der SVS: In den ersten Jahren werden Beiträge auf Basis einer Mindestgrundlage vorgeschrieben, nach Vorliegen des Einkommensteuerbescheids folgt eine Nachbemessung.

Das kann dazu führen, dass in einem Jahr mehrere Zahlungen zusammenfallen. Wer kein Geld zurückgelegt hat, gerät schnell in Liquiditätsprobleme. Vorauszahlungen können auf Antrag angepasst werden, wenn der Gewinn deutlich geringer ausfällt.

## Umsatzsteuervoranmeldung

Unternehmen über einer bestimmten Umsatzgrenze müssen die Umsatzsteuer monatlich oder vierteljährlich voranmelden und abführen. Fällig ist sie in der Regel am 15. des zweitfolgenden Monats. Die Umsatzsteuer ist kein Einkommen, sondern gehört dem Finanzamt. Sie sollte daher am besten auf einem eigenen Konto geparkt werden.

## Gewinnfreibetrag und andere Entlastungen

Natürliche Personen mit betrieblichen Einkünften können den Gewinnfreibetrag nutzen. Ein Grundfreibetrag steht automatisch zu, darüber hinaus ist ein investitionsbedingter Freibetrag möglich, wenn in bestimmte Wirtschaftsgüter oder Wertpapiere investiert wird. Daneben gibt es Pauschalierungen für bestimmte Branchen und die Möglichkeit, geringwertige Wirtschaftsgüter sofort abzuschreiben. Die genauen Grenzen ändern sich regelmäßig und sollten aktuell geprüft werden.

## Praktische Tipps für die Liquidität

1. Einen festen Prozentsatz jeder Einnahme auf ein Steuer-Rücklagenkonto überweisen
2. Umsatzsteuer getrennt verwalten
3. Den Steuerkalender mit allen Fälligkeiten anlegen
4. Vorauszahlungen bei sinkendem Gewinn rechtzeitig herabsetzen lassen
5. Bei Engpässen beim Finanzamt um Stundung oder Ratenzahlung ansuchen, bevor Säumniszuschläge anfallen
6. Einmal jährlich mit der Steuerberatung eine Planungsrechnung erstellen

Die Wirtschaftskammer bietet Mitgliedern kostenlose Erstberatungen und Merkblätter, auch die Wirtschaftskammer Tirol mit ihren Bezirksstellen. Für die laufende Buchhaltung und Bilanz ist eine Steuerberatung oder Buchhaltung meist gut investiertes Geld. Die Kosten sind wiederum als Betriebsausgabe absetzbar.

Eine Faustregel, die viele Beraterinnen und Berater nennen: Mindestens ein Drittel des Gewinns sollte für Steuern und Sozialversicherung zurückgelegt werden, bei höheren Gewinnen eher mehr. Diese Quote ist nur ein grober Richtwert, ersetzt aber in der Anfangsphase oft das böse Erwachen. Wer seine Zahlen monatlich überblickt, etwa mit einer einfachen Einnahmen-Ausgaben-Übersicht, erkennt früh, ob die Rücklagen ausreichen.','wirtschaft','Finanzen','tirol','ratgeber','Presseinfo Redaktion','/assets/img/artikel/steuern-kmu-oesterreich-einkommensteuer-sv-vorauszahlung.webp',NULL,NULL,'published','2026-10-19T07:58:00.000Z','2026-10-22T00:17:07.902Z','Steuern KMU Österreich: Fristen und Vorauszahlungen','Steuern für KMU in Österreich: Welche Abgaben anfallen, wann Vorauszahlungen fällig sind und wie Betriebe Liquiditätsengpässe vermeiden. Jetzt lesen.','Steuern KMU','["Steuern KMU","Einkommensteuer Vorauszahlung","SVS Beiträge","Umsatzsteuervoranmeldung","steuerkalender unternehmer österreich","gewinnfreibetrag selbstständige","steuerrücklage bilden selbstständig","körperschaftsteuer gmbh österreich"]','Steuern KMU: Ordner und Kalender im Büro eines Tiroler Familienbetriebs','Photorealistic editorial photo of a wall calendar and a stack of folders in a small Tyrolean family business office with wooden furniture, alpine village visible through the window, overcast autumn light, no people, no text, no logos, no readable signs','[{"q":"Wann sind Einkommensteuer-Vorauszahlungen fällig?","a":"Vierteljährlich, jeweils Mitte Februar, Mai, August und November."},{"q":"Wie hoch ist die Körperschaftsteuer in Österreich?","a":"Seit 2024 beträgt sie 23 Prozent des Gewinns einer Kapitalgesellschaft."},{"q":"Kann ich Vorauszahlungen senken lassen?","a":"Ja, auf Antrag beim Finanzamt, wenn der erwartete Gewinn deutlich geringer ist."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('arbeitsmarkt-wien-september-2026-arbeitslosigkeit-sinkt','Arbeitsmarkt Wien: Arbeitslosigkeit sinkt erstmals seit sieben Jahren','In Wien sind im September sowohl die Arbeitslosigkeit als auch die Zahl der Schulungsteilnehmer gesunken. Das gab es laut AMS zuletzt vor sieben Jahren.','Der Arbeitsmarkt Wien zeigt erstmals seit Langem wieder eine positive Entwicklung. Ende September waren beim AMS Wien 123.444 Menschen arbeitslos gemeldet, um 1,1 Prozent weniger als ein Jahr zuvor. Gleichzeitig sank die Zahl der Schulungsteilnehmerinnen und -teilnehmer um 4,6 Prozent auf 32.524. Zusammen ergibt das ein Minus von 1,9 Prozent.

## Arbeitsmarkt Wien: erstmals seit sieben Jahren beide Werte im Minus

Dass Arbeitslosigkeit und Schulungsteilnahmen gleichzeitig zurückgehen, hat es in Wien laut AMS seit sieben Jahren nicht mehr gegeben. AMS-Wien-Chef Winfried Göschl sprach von einem bemerkenswerten Ergebnis. Er betonte, dass die tatsächliche Lage am Wiener Arbeitsmarkt deutlich besser sei als die allgemeine Stimmung. Für Schwarzmalerei gebe es aus seiner Sicht keinen Grund.

Bemerkenswert ist die Entwicklung auch im Vergleich zum Bund. Österreichweit stieg die Zahl der Arbeitslosen im September im Jahresvergleich um 2,5 Prozent, die bundesweite Arbeitslosenquote lag bei 7,1 Prozent. In Niederösterreich und der Steiermark gab es teils deutliche Zuwächse.

## Branchen: Bau erholt sich, Handel unter Druck

Ein Blick auf die einzelnen Branchen zeigt große Unterschiede:

- Im Bau ging die Arbeitslosigkeit um 6,8 Prozent zurück.
- In Hotellerie und Gastronomie sank sie um 2,7 Prozent.
- Im Einzelhandel stieg sie dagegen um 3,3 Prozent.
- In der Warenproduktion gab es ein Plus von 2,9 Prozent.

Der Rückgang am Bau ist bemerkenswert, weil die Branche österreichweit weiter in einer schwierigen Lage steckt. Im Handel macht sich die schwache Konsumnachfrage bemerkbar, die auch in den Insolvenzzahlen sichtbar wird.

## Junge profitieren, Ältere haben es schwerer

Auch bei den Altersgruppen gibt es klare Unterschiede. Bei Menschen unter 25 Jahren sank die Arbeitslosigkeit um 5,4 Prozent. Bei Personen über 50 Jahren stieg sie dagegen um 2,7 Prozent. Ältere Arbeitsuchende haben es weiterhin besonders schwer, eine neue Stelle zu finden. Sie bleiben auch länger arbeitslos als Jüngere.

## Weniger Schulungen: was dahintersteckt

Der Rückgang bei den Schulungsteilnahmen hängt auch mit dem Budget des AMS zusammen. Die öffentlichen Mittel sind wegen der Budgetkonsolidierung knapp. Gleichzeitig setzt das AMS auf gezielte Qualifizierung in Bereichen, in denen Fachkräfte gesucht werden, etwa in Gesundheit, Pflege, Technik und Elektrotechnik.

## Ausblick für Wien

Ob sich der positive Trend fortsetzt, hängt stark von der Konjunktur ab. WIFO und IHS rechnen für ganz Österreich 2026 mit einer Arbeitslosenquote von 7,6 Prozent und erst 2027 mit einem leichten Rückgang. Saisonal steigt die Arbeitslosigkeit im Herbst und Winter ohnehin, vor allem am Bau. Für Wien ist der September-Wert dennoch ein Signal, dass sich der Arbeitsmarkt der Hauptstadt stabilisiert.

Wer in Wien eine Stelle sucht, findet Unterstützung bei den regionalen Geschäftsstellen des AMS sowie beim Wiener ArbeitnehmerInnen Förderungsfonds (waff), der Weiterbildungen fördert.

Für Unternehmen bleibt die Suche nach Fachkräften trotz der höheren Arbeitslosigkeit in vielen Branchen schwierig. Gerade im Handwerk, in technischen Berufen und in der Pflege melden Wiener Betriebe weiterhin offene Stellen, die sich nur schwer besetzen lassen. Das AMS Wien bietet Arbeitgebern Unterstützung bei der Personalsuche und Förderungen für die Einstellung bestimmter Zielgruppen an, etwa älterer Arbeitsuchender oder Langzeitarbeitsloser.','wirtschaft','Arbeit & Karriere','wien','news','Presseinfo Redaktion','/assets/img/artikel/arbeitsmarkt-wien-september-2026-arbeitslosigkeit-sinkt.webp','AMS Wien','https://www.ams.at/regionen/wien/news/2026/10/erstmals-seit-sieben-jahren-gehen-arbeitslosigkeit-und-schulungs','published','2026-10-01T09:39:00.000Z','2026-10-22T00:17:07.902Z','Arbeitsmarkt Wien: Arbeitslosigkeit sinkt im September','Arbeitsmarkt Wien im September 2026: Arbeitslosigkeit und Schulungen sinken gleichzeitig, erstmals seit sieben Jahren. Zahlen und Branchen lesen.','Arbeitsmarkt Wien','["Arbeitsmarkt Wien","Arbeitslosigkeit Wien","AMS Wien September 2026","Arbeitslose Wien aktuell","ams wien schulungsteilnehmer rückgang","arbeitslosigkeit über 50 wien","jobs bau wien 2026","arbeitsmarktdaten september 2026"]','Arbeitsmarkt Wien: Pendler auf einem U-Bahn-Bahnsteig im Morgenverkehr','Photorealistic editorial photo of a busy Vienna U-Bahn station platform during morning rush hour, commuters as blurred silhouettes in motion, modern station architecture, cool morning light, no recognizable faces, no text, no logos, no readable signs','[{"q":"Wie viele Arbeitslose gab es im September 2026 in Wien?","a":"Laut AMS Wien waren Ende September 123.444 Menschen arbeitslos, um 1,1 Prozent weniger als im Vorjahr."},{"q":"In welchen Branchen sank die Arbeitslosigkeit in Wien?","a":"Vor allem im Bau mit minus 6,8 Prozent sowie in Hotellerie und Gastronomie mit minus 2,7 Prozent."},{"q":"Wie hoch war die Arbeitslosenquote in ganz Österreich?","a":"Österreichweit lag sie Ende September bei 7,1 Prozent."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('arbeitslosigkeit-niederoesterreich-steiermark-september-2026','Arbeitslosigkeit Niederösterreich: Plus 7,7 Prozent im September','In Niederösterreich ist die Arbeitslosigkeit im September deutlich stärker gestiegen als im Bundesschnitt. Auch in der Steiermark gibt es mehr Arbeitslose und weniger offene Stellen.','Die Arbeitslosigkeit Niederösterreich ist im September deutlich gestiegen. Ende des Monats waren 46.163 Menschen beim AMS Niederösterreich arbeitslos vorgemerkt, um 7,7 Prozent mehr als ein Jahr zuvor. Rechnet man die Schulungsteilnehmerinnen und -teilnehmer dazu, waren es 56.613 Personen. Die Arbeitslosenquote stieg um 0,4 Prozentpunkte auf 6,5 Prozent.

## Arbeitslosigkeit Niederösterreich über dem Bundesschnitt

Österreichweit nahm die Arbeitslosigkeit im selben Zeitraum um 2,5 Prozent zu, die Quote lag bei 7,1 Prozent. Niederösterreich liegt bei der Quote zwar weiterhin unter dem Bundesschnitt, der Anstieg ist aber deutlich stärker. Das AMS spricht von einem Nachholeffekt: Das Bundesland habe sich während der langen Wachstumsschwäche zunächst robuster gehalten als andere Regionen.

Die geschätzte Zahl der unselbständig Beschäftigten lag bei rund 664.000, ein leichtes Minus von 0,2 Prozent. Die Zahl der offenen Stellen sank um 3,4 Prozent auf 12.666, bei den offenen Lehrstellen gab es ein Minus von 2,3 Prozent auf 915.

## Frauen und Ältere stärker betroffen

Bei Frauen stieg die Arbeitslosigkeit mit 11,3 Prozent deutlich stärker als bei Männern mit 4,4 Prozent. Bei Menschen ab 50 Jahren gab es ein Plus von 9,5 Prozent, im Haupterwerbsalter von 7,2 Prozent. Bei Jugendlichen bis 24 Jahren fiel der Anstieg mit 3,9 Prozent geringer aus.

Nach Branchen stieg die Arbeitslosigkeit besonders stark im Gesundheits- und Sozialwesen mit 11,7 Prozent, in der öffentlichen Verwaltung mit 9,0 Prozent und im Handel mit 8,5 Prozent. Unterdurchschnittlich waren die Zuwächse in der Warenherstellung, am Bau und in der Gastronomie. Bei den offenen Stellen gab es starke Rückgänge in Verkehr und Lagerei, ein deutliches Plus dagegen bei sonstigen wirtschaftlichen Dienstleistungen wie Arbeitskräfteüberlassung und Gebäudebetreuung.

## Steiermark: plus 5,9 Prozent

Auch in der Steiermark nahm die Arbeitslosigkeit zu. Ende September waren laut AMS Steiermark 37.501 Menschen arbeitslos, um 5,9 Prozent mehr als im Vorjahr. Inklusive Schulungsteilnehmenden waren es 45.771 Personen. Die geschätzte Arbeitslosenquote stieg auf 6,4 Prozent. Auch hier traf der Anstieg Frauen mit plus 8,2 Prozent stärker als Männer mit plus 3,9 Prozent.

Die Beschäftigung blieb in der Steiermark mit rund 553.000 Personen nahezu stabil. Die sofort verfügbaren offenen Stellen gingen um 3,3 Prozent zurück, neu gemeldete Stellen sogar um 8,7 Prozent. Der steirische AMS-Landesgeschäftsführer Karl-Heinz Snobe rechnet im vierten Quartal saisonbedingt mit weiter steigender Arbeitslosigkeit und im Jahresschnitt 2026 mit rund 41.000 arbeitslosen Menschen.

## Was Arbeitsuchende jetzt tun können

Das AMS setzt in beiden Bundesländern verstärkt auf Qualifizierung. In Niederösterreich haben heuer bereits fast 19.000 Jobsuchende an einer AMS-Schulung teilgenommen. Wer arbeitslos wird, sollte sich möglichst früh beim AMS melden, idealerweise schon während der Kündigungsfrist. So gehen keine Ansprüche verloren und die Unterstützung bei der Jobsuche kann rasch beginnen.

Für Arbeitgeber in Niederösterreich und der Steiermark bedeutet die Entwicklung, dass sich die Personalsuche in manchen Bereichen etwas entspannt. In technischen Berufen und im Handwerk bleiben qualifizierte Fachkräfte aber gefragt. Wer Lehrstellen anbietet, findet beim AMS ebenfalls Unterstützung, etwa über Förderungen für die betriebliche Lehrausbildung.','wirtschaft','Arbeit & Karriere','niederoesterreich','news','Presseinfo Redaktion','/assets/img/artikel/arbeitslosigkeit-niederoesterreich-steiermark-september-2026.webp','AMS Niederösterreich','https://www.ams.at/regionen/niederoesterreich/news/2026/10/092026','published','2026-10-01T13:04:00.000Z','2026-10-22T00:17:07.902Z','Arbeitslosigkeit NÖ und Steiermark im September 2026','Arbeitslosigkeit Niederösterreich steigt im September 2026 um 7,7 %, auch die Steiermark legt zu. Zahlen, Branchen und Ausblick des AMS lesen.','Arbeitslosigkeit Niederösterreich','["Arbeitslosigkeit Niederösterreich","Arbeitslosigkeit Steiermark","AMS Niederösterreich","Arbeitsmarkt September 2026","arbeitslosenquote nö 6,5 prozent","offene stellen niederösterreich rückgang","arbeitslosigkeit frauen anstieg","ams steiermark prognose 2026"]','Arbeitslosigkeit Niederösterreich: leerer Wartebereich einer AMS-Geschäftsstelle in einer Bezirksstadt','Photorealistic editorial photo of an empty modern employment office waiting area in a Lower Austrian district town, rows of chairs, potted plant, large windows with autumn trees outside, soft daylight, no people, no text, no logos, no readable signs','[{"q":"Wie hoch ist die Arbeitslosenquote in Niederösterreich?","a":"Ende September 2026 lag sie bei 6,5 Prozent, um 0,4 Prozentpunkte höher als ein Jahr zuvor."},{"q":"Wie viele Arbeitslose gab es in der Steiermark?","a":"Laut AMS Steiermark waren es Ende September 37.501, um 5,9 Prozent mehr als im Vorjahr."},{"q":"Wann sollte ich mich beim AMS melden?","a":"Möglichst früh, idealerweise schon während der Kündigungsfrist, damit keine Ansprüche verloren gehen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('gehaltsverhandlung-tipps-oesterreich-kollektivvertrag','Gehaltsverhandlung: Tipps für mehr Gehalt in Österreich','Wer mehr verdienen will, muss gut vorbereitet ins Gespräch gehen. Wie man realistische Ziele setzt, den Kollektivvertrag nutzt und Argumente richtig einsetzt.','Eine Gehaltsverhandlung ist für viele Beschäftigte unangenehm. Dabei lohnt sich gute Vorbereitung: Schon ein moderates Plus beim Monatsgehalt summiert sich über die Jahre, zumal in Österreich in der Regel 14 Gehälter ausbezahlt werden. In Zeiten hoher Inflation ist das Thema zudem besonders aktuell.

## Gehaltsverhandlung: der Kollektivvertrag als Basis

Für die meisten Arbeitsverhältnisse in Österreich gilt ein Kollektivvertrag. Er legt Mindestgehälter fest, die von Einstufung, Verwendungsgruppe und Berufsjahren abhängen. Jährlich verhandeln Gewerkschaften und Arbeitgeber über die Erhöhung dieser Mindestgehälter und oft auch der Ist-Gehälter. Diese Erhöhung bekommt man automatisch.

Bei einer individuellen Gehaltsverhandlung geht es daher meist um eine Überzahlung über dem Kollektivvertrag oder um eine höhere Einstufung. Ein erster Schritt ist, die eigene Einstufung zu prüfen. Stimmen Verwendungsgruppe und angerechnete Vordienstzeiten? Manchmal liegt hier bereits ein Anspruch auf mehr Geld.

## Den eigenen Marktwert kennen

Wer verhandelt, braucht eine realistische Zahl. Hilfreich sind:

- Gehaltsrechner und Gehaltsstudien von Arbeiterkammer, Gewerkschaften und Jobplattformen
- die Gehaltsangaben in Stellenanzeigen, die in Österreich verpflichtend das kollektivvertragliche Mindestentgelt und eine mögliche Überzahlung nennen müssen
- Gespräche mit Kolleginnen und Kollegen in der Branche

Regionale Unterschiede spielen ebenfalls eine Rolle. In Oberösterreich zahlen etwa Industriebetriebe oft anders als kleinere Dienstleister.

## Gute Argumente sammeln

Entscheidend sind Leistungen, nicht persönliche Bedürfnisse. Gute Argumente sind:

1. zusätzliche Aufgaben und Verantwortung seit der letzten Erhöhung
2. konkrete Erfolge, etwa gewonnene Kunden, eingesparte Kosten oder abgeschlossene Projekte
3. neue Qualifikationen und Weiterbildungen
4. Marktvergleich mit ähnlichen Positionen

Weniger überzeugend sind Hinweise auf gestiegene Lebenshaltungskosten oder private Ausgaben. Sie sind zwar nachvollziehbar, aber kein Grund für den Arbeitgeber, mehr zu zahlen.

## Der richtige Zeitpunkt

Gute Gelegenheiten sind das jährliche Mitarbeitergespräch, der Abschluss eines erfolgreichen Projekts oder die Übernahme neuer Aufgaben. Ungünstig sind Phasen, in denen das Unternehmen gerade Personal abbaut oder schwierige Zahlen meldet. Es empfiehlt sich, um einen eigenen Termin zu bitten statt zwischen Tür und Angel zu fragen.

## Im Gespräch: klar und vorbereitet

Nennen Sie eine konkrete Zahl, am besten als Bruttomonatsgehalt, und setzen Sie den Einstieg leicht über Ihrem Ziel an. Hören Sie die Antwort ab, ohne sofort nachzugeben. Kommt ein Nein, fragen Sie nach den Gründen und nach Bedingungen für eine Erhöhung zu einem späteren Zeitpunkt. Halten Sie Vereinbarungen schriftlich fest.

Ist beim Grundgehalt wenig Spielraum, können andere Leistungen verhandelt werden: zusätzliche Weiterbildung, Homeoffice-Tage, ein Jobticket, Prämien oder mehr Urlaub. Steuerlich begünstigte Benefits wie Essensgutscheine oder Zuschüsse zum öffentlichen Verkehr können netto mehr bringen als eine kleine Bruttoerhöhung. Was davon steuerfrei ist, hängt von den aktuellen Regeln ab.

Betriebsrat und Arbeiterkammer beraten bei Fragen zur Einstufung und zum Kollektivvertrag kostenlos.

Ein letzter Tipp: Üben Sie das Gespräch vorher, etwa mit einer vertrauten Person. Wer seine Argumente einmal laut ausgesprochen hat, wirkt im echten Gespräch souveräner. Notieren Sie sich außerdem Ihre Untergrenze, also den Betrag, unter dem Sie nicht zustimmen wollen. Und bleiben Sie in jedem Fall sachlich: Auch wenn das Ergebnis nicht wie erhofft ausfällt, ist ein gutes Verhältnis zur Führungskraft die Basis für die nächste Verhandlung.','wirtschaft','Arbeit & Karriere','oberoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/gehaltsverhandlung-tipps-oesterreich-kollektivvertrag.webp',NULL,NULL,'published','2026-10-05T05:22:00.000Z','2026-10-22T00:17:07.902Z','Gehaltsverhandlung: Tipps für mehr Gehalt','Gehaltsverhandlung in Österreich: Wie Sie sich vorbereiten, den Kollektivvertrag nutzen und überzeugend argumentieren. Praxistipps jetzt lesen.','Gehaltsverhandlung','["Gehaltsverhandlung","Gehaltserhöhung","Kollektivvertrag Gehalt","Gehalt verhandeln Tipps","gehaltsverhandlung vorbereitung argumente","überzahlung kollektivvertrag","gehaltsrechner österreich","mitarbeitergespräch gehalt"]','Gehaltsverhandlung: Besprechungstisch mit zwei Kaffeetassen in einem Büro in Linz','Photorealistic editorial photo of two coffee cups and a notepad on a meeting table in a bright modern office in Linz, Danube river visible through glass wall, two chairs facing each other, morning light, no people, no text, no logos, no readable signs','[{"q":"Wann ist der beste Zeitpunkt für eine Gehaltsverhandlung?","a":"Etwa beim Mitarbeitergespräch, nach einem erfolgreichen Projekt oder bei Übernahme neuer Aufgaben."},{"q":"Muss mein Gehalt über dem Kollektivvertrag liegen?","a":"Nein, der Kollektivvertrag legt das Mindestgehalt fest. Eine Überzahlung ist Verhandlungssache."},{"q":"Wo finde ich Vergleichswerte für mein Gehalt?","a":"In Gehaltsrechnern von AK und Jobplattformen, in Stellenanzeigen und im jeweiligen Kollektivvertrag."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('kuendigungsfristen-oesterreich-angestellte-arbeiter','Kündigungsfristen in Österreich: Was für Angestellte und Arbeiter gilt','Seit der Angleichung gelten für Arbeiter und Angestellte grundsätzlich dieselben Kündigungsfristen. Wie lange sie dauern und welche Ausnahmen es gibt.','Kündigungsfristen regeln, wie lange ein Arbeitsverhältnis nach der Kündigung noch besteht. In Österreich wurden die Fristen für Arbeiter und Angestellte schrittweise angeglichen. Seit Oktober 2021 gelten grundsätzlich für beide Gruppen die Regeln des Angestelltengesetzes. Es gibt jedoch Ausnahmen, etwa für Branchen mit vielen Saisonbetrieben.

## Kündigungsfristen bei Kündigung durch den Arbeitgeber

Kündigt der Arbeitgeber, hängt die Frist von der Dauer des Arbeitsverhältnisses ab:

- im ersten und zweiten Dienstjahr: sechs Wochen
- ab dem dritten Dienstjahr: zwei Monate
- ab dem sechsten Dienstjahr: drei Monate
- ab dem 16. Dienstjahr: vier Monate
- ab dem 26. Dienstjahr: fünf Monate

Gekündigt werden kann grundsätzlich nur zum Quartalsende. Im Arbeitsvertrag kann aber vereinbart werden, dass die Kündigung auch zum 15. oder zum Letzten eines Monats möglich ist. Kollektivverträge können für Branchen mit überwiegend Saisonbetrieben abweichende, kürzere Fristen festlegen, etwa im Tourismus.

## Kündigung durch Arbeitnehmerinnen und Arbeitnehmer

Wer selbst kündigt, hat grundsätzlich eine Kündigungsfrist von einem Monat, und zwar zum Monatsletzten. Diese Frist kann vertraglich verlängert werden, aber höchstens auf die Dauer, die auch für den Arbeitgeber gilt. Viele Arbeitsverträge enthalten solche Regelungen, daher lohnt sich ein genauer Blick in den eigenen Vertrag und den anwendbaren Kollektivvertrag.

## Probezeit und befristete Verträge

Während der Probezeit, die höchstens einen Monat dauern darf, können beide Seiten das Arbeitsverhältnis jederzeit ohne Frist und ohne Angabe von Gründen beenden. Bei Lehrlingen gelten eigene Regeln. Befristete Arbeitsverhältnisse enden automatisch mit Ablauf der Befristung. Eine vorzeitige Kündigung ist nur möglich, wenn das ausdrücklich vereinbart wurde und die Befristung entsprechend lang ist.

## Einvernehmliche Auflösung und Entlassung

Neben der Kündigung gibt es die einvernehmliche Auflösung. Dabei vereinbaren beide Seiten ein Ende des Arbeitsverhältnisses, Fristen und Termine müssen nicht eingehalten werden. Arbeitnehmer sollten vorher prüfen, welche Folgen das etwa für das Arbeitslosengeld hat, und sich im Zweifel beraten lassen.

Eine Entlassung oder ein vorzeitiger Austritt beendet das Arbeitsverhältnis sofort. Dafür braucht es einen wichtigen Grund, etwa grobe Pflichtverletzungen. Ob dieser vorliegt, landet nicht selten vor dem Arbeits- und Sozialgericht.

## Was während der Kündigungsfrist gilt

Während der Frist läuft das Arbeitsverhältnis normal weiter, das Gehalt ist zu zahlen und Urlaub kann verbraucht werden. Bei Kündigung durch den Arbeitgeber steht in der Regel eine Freizeit für die Jobsuche zu, die sogenannte Postensuchtage, meist ein Fünftel der wöchentlichen Arbeitszeit. Der Arbeitgeber kann Beschäftigte auch dienstfrei stellen, muss dann aber weiterhin bezahlen.

Wichtige Tipps zum Schluss:

1. Kündigung immer nachweisbar aussprechen, am besten schriftlich
2. Fristen und Termine im Vertrag und Kollektivvertrag prüfen
3. Bei Kündigung durch den Arbeitgeber rasch beim AMS melden
4. Ansprüche wie Urlaubsersatzleistung und Sonderzahlungen kontrollieren
5. Bei Unklarheiten die Arbeiterkammer, im Burgenland etwa die AK Burgenland, kontaktieren

Die genaue Rechtslage hängt immer vom Einzelfall und vom anwendbaren Kollektivvertrag ab.','wirtschaft','Arbeit & Karriere','burgenland','ratgeber','Presseinfo Redaktion','/assets/img/artikel/kuendigungsfristen-oesterreich-angestellte-arbeiter.webp',NULL,NULL,'published','2026-10-13T06:09:00.000Z','2026-10-22T00:17:07.902Z','Kündigungsfristen Österreich: Regeln im Überblick','Kündigungsfristen in Österreich: Welche Fristen und Termine für Angestellte und Arbeiter gelten und was bei Kündigung zu beachten ist. Jetzt nachlesen.','Kündigungsfristen','["Kündigungsfristen","Kündigungsfrist Angestellte","Kündigungsfrist Arbeiter","Kündigungstermin","kündigungsfrist arbeitnehmer 1 monat","kündigung probezeit österreich","einvernehmliche auflösung","dienstfreistellung kündigungsfrist"]','Kündigungsfristen: Briefkuvert und Stift auf Schreibtisch mit Blick auf Weingärten im Burgenland','Photorealistic editorial photo of an envelope and a pen on a wooden desk next to a window overlooking vineyards in Burgenland, autumn harvest colors, soft late morning light, no people, no text, no logos, no readable signs','[{"q":"Wie lange ist die Kündigungsfrist für Arbeitnehmer in Österreich?","a":"Grundsätzlich ein Monat zum Monatsletzten, sofern im Vertrag nichts anderes vereinbart ist."},{"q":"Gelten für Arbeiter und Angestellte dieselben Fristen?","a":"Seit Oktober 2021 grundsätzlich ja. Kollektivverträge für Saisonbranchen können Ausnahmen vorsehen."},{"q":"Kann ich in der Probezeit ohne Frist kündigen?","a":"Ja, während der höchstens einmonatigen Probezeit können beide Seiten jederzeit ohne Frist beenden."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('brutto-netto-gehalt-oesterreich-13-14-gehalt','Brutto netto Gehalt Österreich: So wird Ihr Lohn berechnet','Vom Bruttogehalt bleibt netto deutlich weniger übrig. Wie sich Sozialversicherung und Lohnsteuer zusammensetzen und warum Urlaubs- und Weihnachtsgeld begünstigt sind.','Beim Brutto netto Gehalt erleben viele eine Überraschung: Vom vereinbarten Bruttobetrag kommt deutlich weniger auf dem Konto an. Der Grund sind Sozialversicherungsbeiträge und Lohnsteuer, die der Arbeitgeber direkt einbehält und abführt. Wer die Abzüge versteht, kann den eigenen Lohnzettel besser lesen und Gehaltsangebote realistisch vergleichen.

## Brutto netto Gehalt: die Abzüge im Überblick

Vom Bruttogehalt werden zunächst die Sozialversicherungsbeiträge des Arbeitnehmers abgezogen. Sie umfassen Kranken-, Pensions- und Arbeitslosenversicherung sowie weitere kleinere Beiträge, etwa die Arbeiterkammerumlage und den Wohnbauförderungsbeitrag. Insgesamt liegt der Arbeitnehmeranteil bei einem durchschnittlichen Einkommen bei rund 18 Prozent. Bei geringen Einkommen ist der Beitrag zur Arbeitslosenversicherung reduziert.

Erst vom verbleibenden Betrag wird die Lohnsteuer berechnet. Österreich hat einen progressiven Tarif: Bis zu einer bestimmten Jahresgrenze ist das Einkommen steuerfrei, darüber steigen die Steuersätze stufenweise. Die Grenzen werden seit 2023 jährlich an die Inflation angepasst, um die kalte Progression zu dämpfen. Die aktuellen Werte veröffentlicht das Finanzministerium.

## Das 13. und 14. Gehalt

Eine österreichische Besonderheit sind die Sonderzahlungen, also Urlaubs- und Weihnachtsgeld. Sie stehen nicht per Gesetz, aber in fast allen Kollektivverträgen zu. Steuerlich sind sie begünstigt: Innerhalb des sogenannten Jahressechstels werden sie nach einem Freibetrag mit einem festen Satz von sechs Prozent besteuert, bei sehr hohen Einkommen höher. Dadurch bleibt vom 13. und 14. Gehalt netto deutlich mehr als von einem regulären Monatsgehalt.

## Absetzbeträge senken die Steuer

Verschiedene Absetzbeträge verringern die Lohnsteuer direkt:

- der Verkehrsabsetzbetrag, den alle Arbeitnehmer erhalten
- der Familienbonus Plus für Kinder
- der Alleinverdiener- oder Alleinerzieherabsetzbetrag
- Pendlerpauschale und Pendlereuro bei entsprechend langem Arbeitsweg

Einige davon werden direkt über die Lohnverrechnung berücksichtigt, wenn der Arbeitgeber die nötigen Formulare erhält. Andere können in der Arbeitnehmerveranlagung geltend gemacht werden.

## Was der Arbeitgeber zusätzlich zahlt

Für Unternehmen kostet ein Arbeitsplatz deutlich mehr als das Bruttogehalt. Dazu kommen Dienstgeberbeiträge zur Sozialversicherung, der Dienstgeberbeitrag zum Familienlastenausgleichsfonds, die Kommunalsteuer, die betriebliche Mitarbeitervorsorge und weitere Abgaben. Diese Lohnnebenkosten sind in Österreich vergleichsweise hoch. Die Regierung hat im Rahmen des Doppelbudgets 2027/28 eine Senkung ab 2028 angekündigt. Die konkrete Ausgestaltung stand zuletzt noch nicht in allen Details fest.

## Brutto-Netto-Rechner nutzen

Das Finanzministerium bietet online einen Brutto-Netto-Rechner an. Damit lässt sich das voraussichtliche Nettogehalt inklusive Sonderzahlungen berechnen. Auch Arbeiterkammer und Jobplattformen haben ähnliche Rechner. Für eine genaue Berechnung sollten Familienstand, Kinder und Pendelstrecke angegeben werden.

Auf der monatlichen Gehaltsabrechnung finden sich Brutto, die einzelnen Sozialversicherungsbeiträge, die Bemessungsgrundlage für die Lohnsteuer, die Lohnsteuer selbst und schließlich der Auszahlungsbetrag. Wer Fehler vermutet, etwa bei Zulagen oder Überstunden, sollte zuerst die Personalabteilung und bei Bedarf Betriebsrat oder Arbeiterkammer kontaktieren. In Kärnten etwa bietet die AK Kärnten eine kostenlose Lohnzettelprüfung an.

Ein Tipp für Jobwechsler: Vergleichen Sie Angebote immer auf Basis des Jahresbruttos inklusive Sonderzahlungen. Manche Stellenanzeigen nennen ein Monatsgehalt mal 14, andere ein Jahresgehalt. Zusätzliche Leistungen wie Überstundenpauschalen, Prämien oder ein Firmenwagen beeinflussen das Nettoergebnis ebenfalls und sollten in die Rechnung einbezogen werden.','wirtschaft','Arbeit & Karriere','kaernten','ratgeber','Presseinfo Redaktion','/assets/img/artikel/brutto-netto-gehalt-oesterreich-13-14-gehalt.webp',NULL,NULL,'published','2026-10-20T11:17:00.000Z','2026-10-22T00:17:07.903Z','Brutto netto Gehalt Österreich einfach erklärt','Brutto netto Gehalt in Österreich: Welche Abzüge es gibt, warum das 13. und 14. Gehalt begünstigt ist und wie der Lohnzettel aufgebaut ist. Jetzt lesen.','Brutto netto Gehalt','["Brutto netto Gehalt","Brutto Netto Rechner Österreich","13. und 14. Gehalt","Lohnsteuer Österreich","sozialversicherung arbeitnehmer anteil","sechstelbegünstigung sonderzahlung","lohnzettel lesen","lohnsteuertarif 2026"]','Brutto netto Gehalt: Lohnzettel und Taschenrechner am Schreibtisch mit Blick auf einen Kärntner See','Photorealistic editorial photo of a payslip-like blank paper sheet and a calculator on a desk next to a window overlooking a Carinthian lake in autumn fog, muted morning tones, no people, no text, no logos, no readable signs','[{"q":"Wie viel Sozialversicherung zahlt man als Arbeitnehmer?","a":"Bei durchschnittlichem Einkommen liegt der Arbeitnehmeranteil bei rund 18 Prozent des Bruttogehalts."},{"q":"Warum ist das 13. und 14. Gehalt netto höher?","a":"Sonderzahlungen werden innerhalb des Jahressechstels nach einem Freibetrag mit festen sechs Prozent besteuert."},{"q":"Wo kann ich mein Nettogehalt berechnen?","a":"Mit dem Brutto-Netto-Rechner des Finanzministeriums oder den Rechnern der Arbeiterkammer."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('unternehmensgruendungen-wien-2026-plus-8-prozent','Unternehmensgründungen Wien: 8,5 Prozent mehr im ersten Halbjahr','In Wien wurden im ersten Halbjahr 2026 mehr als 6.100 Unternehmen gegründet, deutlich mehr als im Vorjahr. Auch österreichweit legten die Gründungen zu.','Die Unternehmensgründungen Wien haben im ersten Halbjahr 2026 deutlich zugelegt. Laut Wirtschaftskammer Wien wurden von Jänner bis Juni 6.106 neue Unternehmen gegründet. Im Vergleichszeitraum des Vorjahres waren es 5.625. Das entspricht einem Plus von 8,5 Prozent. Die Bundeshauptstadt ist damit für rund 26 Prozent aller Neugründungen in Österreich verantwortlich.

## Unternehmensgründungen Wien: Wissen als Wachstumstreiber

Auffällig ist die Struktur der neuen Wiener Unternehmen. Rund 27 Prozent entfallen auf wissensintensive Dienstleistungen, die in der Statistik der Sparte Information und Consulting zugeordnet sind. Österreichweit liegt dieser Anteil nur bei 19,5 Prozent. Dazu zählen etwa Unternehmensberatung, IT-Dienstleistungen, Werbung und Buchhaltung. Wien profitiert hier von seiner Rolle als Standort für Universitäten, Konzernzentralen und Kreativwirtschaft.

## Österreich: 21.718 Gründungen im Halbjahr

Auch bundesweit gab es mehr Gründungen. Laut Wirtschaftskammer Österreich wurden im ersten Halbjahr 2026 insgesamt 21.718 neue Unternehmen gegründet, ohne selbständige Personenbetreuung. Das sind um 4,5 Prozent mehr als ein Jahr zuvor. Die meisten Gründungen entfielen auf die Sparte Gewerbe und Handwerk mit 37,8 Prozent, gefolgt von Information und Consulting mit 23,4 Prozent und dem Handel mit 22,9 Prozent. Am stärksten wuchs der Bereich Transport und Verkehr mit einem Plus von 30 Prozent.

Die gründungsstärksten Branchen waren Unternehmensberatung, Buchhaltung und Informationstechnologie mit zusammen 2.661 neuen Betrieben.

## Einzelunternehmen dominieren

Die meisten Gründerinnen und Gründer starten klein. Österreichweit wählten 82,6 Prozent die Rechtsform des Einzelunternehmens. Rund 78 Prozent aller Neugründungen sind nicht im Firmenbuch eingetragen, es handelt sich also überwiegend um kleine Einzelunternehmen ohne Eintragungspflicht. Bei den Einzelunternehmen lag der Frauenanteil laut WKÖ bei 42,5 Prozent.

## Gründen trotz schwacher Konjunktur

Bemerkenswert ist das Plus vor dem Hintergrund der schwachen Konjunktur. Die Wirtschaft wächst heuer nur langsam, gleichzeitig ist die Zahl der Insolvenzen hoch. Gründungen in Krisenzeiten haben oft mehrere Ursachen: Manche Menschen wagen den Schritt aus einer unsicheren Anstellung, andere sehen gezielt Chancen in neuen Märkten, etwa bei Digitalisierung oder Energie. Für die Stabilität der Wirtschaft ist entscheidend, wie viele der neuen Betriebe sich langfristig halten.

## Unterstützung für Gründer in Wien

Wer in Wien ein Unternehmen gründen will, findet beim Gründerservice der Wirtschaftskammer Wien kostenlose Beratung zu Gewerbeanmeldung, Rechtsform, Steuern und Sozialversicherung. Daneben gibt es Förderungen von Stadt und Bund, etwa über die Wirtschaftsagentur Wien und die Austria Wirtschaftsservice. Wichtig für Neugründer ist das Neugründungs-Förderungsgesetz, das unter bestimmten Bedingungen Gebühren und Abgaben bei der Gründung erspart. Die genauen Voraussetzungen sollten vorab beim Gründerservice geklärt werden.

Für Gründerinnen und Gründer, die eine Gewerbeberechtigung oder eine Konzession benötigen, lohnt es sich, frühzeitig zu prüfen, welche Nachweise verlangt werden. Das verkürzt die Zeit bis zum Start deutlich.

Für die Wiener Wirtschaft sind die neuen Betriebe ein wichtiger Faktor. Ein großer Teil der Gründerinnen und Gründer schafft zunächst nur den eigenen Arbeitsplatz. Mit der Zeit stellen viele aber Mitarbeitende ein. Studien der Wirtschaftskammer zeigen regelmäßig, dass ein erheblicher Teil der neu gegründeten Unternehmen nach fünf Jahren noch aktiv ist. Wie sich der aktuelle Jahrgang entwickelt, wird angesichts der schwierigen Konjunktur besonders genau beobachtet. Die Gesamtzahlen für 2026 veröffentlicht die Wirtschaftskammer zu Beginn des kommenden Jahres.','wirtschaft','Gründen','wien','news','Presseinfo Redaktion','/assets/img/artikel/unternehmensgruendungen-wien-2026-plus-8-prozent.webp','Wirtschaftskammer Wien','https://www.wko.at/wien/news/zahlen-und-fakten-zu-unternehmensneugruendungen-2026','published','2026-09-22T08:43:00.000Z','2026-10-22T00:17:07.903Z','Unternehmensgründungen Wien 2026: deutliches Plus','Unternehmensgründungen Wien: Im ersten Halbjahr 2026 entstanden 6.106 neue Firmen, ein Plus von 8,5 %. Zahlen, Branchen und Rechtsformen hier lesen.','Unternehmensgründungen Wien','["Unternehmensgründungen Wien","Neugründungen 2026","Gründungsstatistik WKO","Firma gründen Wien","einzelunternehmen anteil gründungen","gründungen österreich erstes halbjahr 2026","wissensintensive dienstleistungen wien","gründerservice wirtschaftskammer wien"]','Unternehmensgründungen Wien: heller Coworking-Space in einem Wiener Gründerzeithaus','Photorealistic editorial photo of a bright coworking space in a converted Viennese Gründerzeit building, high ceilings, long shared wooden desks with laptops and plants, large arched windows, morning sunlight, people only as distant blurred silhouettes, no text, no logos, no readable signs','[{"q":"Wie viele Unternehmen wurden 2026 in Wien gegründet?","a":"Im ersten Halbjahr 2026 waren es laut WK Wien 6.106 Neugründungen, um 8,5 Prozent mehr als im Vorjahr."},{"q":"Welche Rechtsform wählen die meisten Gründer?","a":"Österreichweit gründen 82,6 Prozent als Einzelunternehmen."},{"q":"Wo bekomme ich in Wien Hilfe bei der Gründung?","a":"Beim Gründerservice der Wirtschaftskammer Wien, das kostenlos zu Gewerbe, Rechtsform und Steuern berät."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('gewerbe-anmelden-oesterreich-ablauf-kosten-gisa','Gewerbe anmelden in Österreich: Ablauf, Kosten und Unterlagen','Wer selbstständig arbeiten will, braucht meist eine Gewerbeberechtigung. Wie die Anmeldung funktioniert, welche Unterlagen nötig sind und was es kostet.','Wer in Österreich selbstständig tätig werden will, muss in vielen Fällen ein Gewerbe anmelden. Die Gewerbeordnung regelt, welche Tätigkeiten dafür eine Berechtigung brauchen. Ausgenommen sind etwa freie Berufe wie Ärztinnen, Rechtsanwälte oder Künstler sowie Neue Selbständige, die keine Gewerbeberechtigung benötigen. Für alle anderen gilt: Erst anmelden, dann loslegen.

## Gewerbe anmelden: frei oder reglementiert?

Die Gewerbeordnung unterscheidet zwei Arten von Gewerben:

- Freie Gewerbe dürfen ohne besonderen Befähigungsnachweis ausgeübt werden. Beispiele sind Handelsgewerbe, Werbeagenturen, viele Dienstleistungen in der Datenverarbeitung oder Hausbetreuung.
- Reglementierte Gewerbe erfordern einen Befähigungsnachweis, etwa eine Meisterprüfung, eine Befähigungsprüfung oder einschlägige Ausbildung und Praxis. Dazu zählen zum Beispiel Baumeister, Elektrotechnik, Installateure, Friseure oder Unternehmensberatung.

Für einige reglementierte Gewerbe wird zusätzlich die Zuverlässigkeit geprüft. Welche Gewerbe genau dazugehören, findet man im Gewerbeinformationssystem GISA und bei der Wirtschaftskammer.

## Wo und wie die Anmeldung erfolgt

Zuständig ist die Gewerbebehörde am Standort: In Niederösterreich und den anderen Bundesländern ist das die Bezirkshauptmannschaft, in Statutarstädten der Magistrat, in Wien das Magistratische Bezirksamt. Die Anmeldung kann persönlich, beim Gründerservice der Wirtschaftskammer oder online über das Unternehmensserviceportal USP erfolgen. Für die Online-Variante braucht man die ID Austria.

Typischerweise werden benötigt:

1. Ausweis oder Reisepass
2. bei Nicht-EU-Bürgern ein Aufenthaltstitel, der selbstständige Tätigkeit erlaubt
3. bei reglementierten Gewerben der Befähigungsnachweis
4. bei längerer Wohnsitzdauer im Ausland Strafregisterbescheinigungen
5. Angaben zum Standort und zur genauen Bezeichnung des Gewerbes

Die Gewerbeberechtigung entsteht bei freien Gewerben grundsätzlich mit der Anmeldung. Bei manchen reglementierten Gewerben darf erst nach Bescheid der Behörde begonnen werden.

## Kosten der Gewerbeanmeldung

Für Neugründer ist die Gewerbeanmeldung häufig gebührenfrei, wenn die Voraussetzungen des Neugründungs-Förderungsgesetzes erfüllt sind. Dafür muss vorab eine Beratung, etwa beim Gründerservice, erfolgen und ein Formular bestätigt werden. Ohne diese Befreiung fallen Verwaltungsabgaben und Gebühren an. Die aktuellen Beträge erfahren Gründer bei der Behörde oder der Wirtschaftskammer.

## Was nach der Anmeldung passiert

Mit der Gewerbeanmeldung wird man automatisch Mitglied der Wirtschaftskammer und in der Regel bei der Sozialversicherung der Selbständigen (SVS) pflichtversichert. Die Meldung an das Finanzamt muss man selbst erledigen: Neue Unternehmer müssen die Aufnahme der Tätigkeit binnen eines Monats melden. Dafür gibt es das Formular Verf24 oder die elektronische Meldung.

Bei Gewerben mit Betriebsanlage, etwa einer Werkstatt oder einem Lokal, kann zusätzlich eine Betriebsanlagengenehmigung nötig sein. Auch Baurecht und Flächenwidmung spielen dann eine Rolle.

## Tipps für den Start

- Gewerbewortlaut genau festlegen, damit alle geplanten Tätigkeiten gedeckt sind
- prüfen, ob ein Befähigungsnachweis nötig ist oder ein gewerberechtlicher Geschäftsführer bestellt werden kann
- Beratung beim Gründerservice nutzen, um die Gebührenbefreiung zu sichern
- Versicherungsschutz und Haftung vor dem ersten Auftrag klären

Wer unsicher ist, welche Berechtigung für die geplante Tätigkeit nötig ist, sollte vorab die Wirtschaftskammer oder einen spezialisierten Dienstleister für Gewerbe- und Konzessionsfragen kontaktieren.

Nach erfolgreicher Anmeldung wird die Berechtigung im GISA eingetragen. Ein GISA-Auszug dient als Nachweis gegenüber Kunden, Banken und Behörden. Auch spätere Änderungen, etwa ein neuer Standort, eine weitere Betriebsstätte oder das Ruhendmelden des Gewerbes, werden über die Gewerbebehörde oder online abgewickelt. Wer das Gewerbe vorübergehend nicht ausübt, kann es bei der Wirtschaftskammer ruhend melden und spart so unter Umständen Beiträge.','wirtschaft','Gründen','niederoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/gewerbe-anmelden-oesterreich-ablauf-kosten-gisa.webp',NULL,NULL,'published','2026-09-24T10:18:00.000Z','2026-10-22T00:17:07.903Z','Gewerbe anmelden Österreich: so geht es Schritt für Schritt','Gewerbe anmelden in Österreich: Freies oder reglementiertes Gewerbe, nötige Unterlagen, Online-Anmeldung und Kosten. Jetzt Schritt für Schritt lesen.','Gewerbe anmelden','["Gewerbe anmelden","Gewerbeanmeldung Österreich","freies Gewerbe","reglementiertes Gewerbe","gewerbe anmelden online usp","gewerbeschein kosten neufög","gisa auszug gewerbe","gewerbe anmelden niederösterreich bezirkshauptmannschaft"]','Gewerbe anmelden: Eingang einer Bezirkshauptmannschaft in einer niederösterreichischen Kleinstadt','Photorealistic editorial photo of a district administration building entrance in a Lower Austrian small town, historic facade with modern glass door, autumn leaves on the steps, cloudy daylight, no people, no text, no logos, no readable signs','[{"q":"Was kostet eine Gewerbeanmeldung in Österreich?","a":"Für Neugründer ist sie bei Erfüllung des Neugründungs-Förderungsgesetzes oft gebührenfrei. Sonst fallen Abgaben an, deren Höhe die Behörde nennt."},{"q":"Kann ich ein Gewerbe online anmelden?","a":"Ja, über das Unternehmensserviceportal USP mit ID Austria."},{"q":"Was ist der Unterschied zwischen freiem und reglementiertem Gewerbe?","a":"Freie Gewerbe brauchen keinen Befähigungsnachweis, reglementierte Gewerbe schon, etwa eine Meister- oder Befähigungsprüfung."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('konzession-gewerberechtlicher-geschaeftsfuehrer-befaehigungsnachweis','Konzession und Befähigungsnachweis: Was Gründer wissen müssen','Für Baumeister, Installateure oder Transportunternehmen reicht eine einfache Anmeldung nicht. Welche Nachweise nötig sind und wie Gründer ohne eigene Prüfung starten können.','Eine Konzession oder ein Befähigungsnachweis ist in Österreich für viele Tätigkeiten Voraussetzung, bevor ein Unternehmen starten darf. Wer etwa als Baumeister, Elektrotechniker oder Installateur arbeiten oder Güter und Personen gewerblich befördern will, muss bestimmte Qualifikationen nachweisen. Für Gründerinnen und Gründer ist das oft die größte Hürde auf dem Weg zum eigenen Betrieb.

## Konzession und reglementiertes Gewerbe: Begriffe klären

Früher sprach man in der Gewerbeordnung von konzessionierten Gewerben. Heute gibt es im allgemeinen Gewerberecht den Begriff der reglementierten Gewerbe, die einen Befähigungsnachweis erfordern. Im Alltag wird das Wort Konzession aber weiterhin häufig verwendet. Ausdrücklich als Konzession bezeichnet werden etwa Berechtigungen im Güterbeförderungs- und im Gelegenheitsverkehrsgesetz, also für Transportunternehmen, Taxi- und Mietwagenbetriebe. Dort sind zusätzlich finanzielle Leistungsfähigkeit, Zuverlässigkeit und fachliche Eignung nachzuweisen.

## So wird die Befähigung nachgewiesen

Für reglementierte Gewerbe legt eine eigene Zugangsverordnung fest, welche Nachweise ausreichen. Möglich sind je nach Gewerbe:

- eine Meister- oder Befähigungsprüfung
- ein einschlägiger Studien- oder Schulabschluss in Kombination mit fachlicher Praxis
- eine Lehrabschlussprüfung plus mehrjährige Berufserfahrung
- eine Unternehmerprüfung, die teilweise in anderen Prüfungen enthalten ist

Erfüllt jemand die Vorgaben nicht genau, kann ein individueller Befähigungsnachweis beantragt werden. Dabei prüft die Behörde, ob Ausbildung und Erfahrung gleichwertig sind. Das Verfahren dauert meist länger und erfordert gute Unterlagen wie Dienstzeugnisse und Projektnachweise.

## Gewerberechtlicher Geschäftsführer als Lösung

Wer selbst keinen Befähigungsnachweis hat, kann einen gewerberechtlichen Geschäftsführer bestellen. Diese Person bringt die Qualifikation ein und ist gegenüber der Behörde für die Einhaltung der gewerberechtlichen Vorschriften verantwortlich. Sie muss sich im Betrieb entsprechend betätigen können. Bei einer juristischen Person wie der GmbH ist ein gewerberechtlicher Geschäftsführer ohnehin immer zu bestellen.

In vielen Fällen muss der gewerberechtliche Geschäftsführer zumindest in einem bestimmten Ausmaß im Unternehmen angestellt sein. Die genauen Anforderungen hängen vom Gewerbe ab. Hier sollten Gründer besonders genau prüfen, um später keine Probleme mit der Behörde zu bekommen.

## Ablauf des Verfahrens

1. Genaues Gewerbe und Wortlaut festlegen
2. erforderliche Nachweise laut Zugangsverordnung prüfen
3. Unterlagen sammeln: Zeugnisse, Prüfungen, Praxisnachweise
4. Anmeldung bei der Bezirkshauptmannschaft oder dem Magistrat
5. Bei Bedarf Bescheid abwarten, bevor die Tätigkeit beginnt

In Oberösterreich und den anderen Bundesländern unterscheiden sich die Abläufe kaum, da die Gewerbeordnung Bundesrecht ist. Die Bearbeitungsdauer kann aber je nach Behörde variieren.

## Kosten und Dauer

Die Kosten setzen sich aus Gebühren der Behörde, möglichen Prüfungsgebühren und gegebenenfalls dem Gehalt eines gewerberechtlichen Geschäftsführers zusammen. Bei Neugründern können manche Gebühren über das Neugründungs-Förderungsgesetz entfallen. Für Meisterprüfungen gibt es teils Förderungen der Länder, die regelmäßig angepasst werden.

Fehler bei der Gewerbeberechtigung können teuer werden: Wer ohne passende Berechtigung arbeitet, riskiert Verwaltungsstrafen und Probleme bei Gewährleistung und Versicherung. Die Wirtschaftskammer, spezialisierte Berater und Konzessionsdienstleister unterstützen bei der Prüfung der Voraussetzungen und bei der Suche nach geeigneten gewerberechtlichen Geschäftsführern.','wirtschaft','Gründen','oberoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/konzession-gewerberechtlicher-geschaeftsfuehrer-befaehigungsnachweis.webp',NULL,NULL,'published','2026-10-02T12:55:00.000Z','2026-10-22T00:17:07.904Z','Konzession und Befähigungsnachweis in Österreich','Konzession und Befähigungsnachweis: Welche Gewerbe Voraussetzungen haben und wie ein gewerberechtlicher Geschäftsführer hilft. Überblick jetzt lesen.','Konzession','["Konzession","Befähigungsnachweis","gewerberechtlicher Geschäftsführer","reglementiertes Gewerbe","konzession taxi güterbeförderung","baumeister gewerbe voraussetzungen","individueller befähigungsnachweis","meisterprüfung gewerbe österreich"]','Konzession: Betriebshof eines Bau- und Transportunternehmens in Oberösterreich bei Sonnenaufgang','Photorealistic editorial photo of a parked white delivery truck and a small construction company yard in Upper Austria at sunrise, gravel ground, stacked building materials, rolling hills in background, no people, no text, no logos, no readable signs, no license plates','[{"q":"Brauche ich für jedes Gewerbe eine Konzession?","a":"Nein. Freie Gewerbe brauchen keinen Nachweis. Reglementierte Gewerbe und Bereiche wie Güterbeförderung oder Taxi setzen Befähigung bzw. Konzession voraus."},{"q":"Was macht ein gewerberechtlicher Geschäftsführer?","a":"Er bringt den Befähigungsnachweis ein und ist gegenüber der Behörde für die Einhaltung der Gewerbevorschriften verantwortlich."},{"q":"Was ist ein individueller Befähigungsnachweis?","a":"Eine Prüfung durch die Behörde, ob Ausbildung und Praxis gleichwertig mit den vorgeschriebenen Nachweisen sind."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('gmbh-gruenden-oesterreich-stammkapital-kosten-ablauf','GmbH gründen in Österreich: Stammkapital, Kosten und Ablauf','Die GmbH ist die beliebteste Kapitalgesellschaft in Österreich. Seit 2024 reicht ein geringeres Stammkapital. Was Gründer über Ablauf, Kosten und Haftung wissen müssen.','Wer eine GmbH gründen will, wählt die in Österreich am häufigsten genutzte Kapitalgesellschaft. Ihr großer Vorteil: Die Haftung der Gesellschafter ist grundsätzlich auf ihre Einlage beschränkt. Seit 2024 ist die Gründung zudem günstiger geworden, weil das Mindeststammkapital gesenkt wurde.

## GmbH gründen: das Stammkapital

Seit 1. Jänner 2024 beträgt das Mindeststammkapital einer GmbH 10.000 Euro, davor waren es 35.000 Euro. Bei der Gründung muss mindestens die Hälfte der Bareinlagen, also 5.000 Euro, eingezahlt sein. Die frühere Gründungsprivilegierung, die eine geringere Einzahlung erlaubte, wurde mit dieser Reform abgeschafft. Das Kapital steht der Gesellschaft für den Geschäftsbetrieb zur Verfügung und muss nicht auf dem Konto liegen bleiben.

## Die Schritte zur GmbH

1. Gesellschafter, Geschäftsführer und Unternehmensgegenstand festlegen
2. Firmenwortlaut prüfen, damit er unterscheidbar und zulässig ist
3. Gesellschaftsvertrag bzw. Erklärung über die Errichtung bei einer Ein-Personen-GmbH aufsetzen
4. Notariatsakt errichten lassen
5. Bankkonto eröffnen und Stammeinlage einzahlen
6. Anmeldung zum Firmenbuch mit Musterzeichnung des Geschäftsführers
7. Gewerbe anmelden und gewerberechtlichen Geschäftsführer bestellen
8. Meldung beim Finanzamt für Steuernummer und UID-Nummer

Mit der Eintragung im Firmenbuch entsteht die GmbH als juristische Person. Vorher handelt es sich um eine Vorgesellschaft, bei der die Handelnden persönlich haften können.

## Vereinfachte Gründung und FlexCo

Für Ein-Personen-GmbHs mit einer Person als Gesellschafter und Geschäftsführer gibt es eine vereinfachte Gründung ohne Notar. Sie erfolgt elektronisch über das Unternehmensserviceportal und eine Bank, die die Identität prüft. Der Gesellschaftsvertrag ist dabei standardisiert.

Seit 2024 gibt es zusätzlich die Flexible Kapitalgesellschaft, kurz FlexCo. Sie ähnelt der GmbH, erlaubt aber etwa Unternehmenswertanteile für Mitarbeitende und einfachere Formvorschriften bei bestimmten Übertragungen. Für Start-ups mit Investoren kann sie interessant sein.

## Kosten der GmbH-Gründung

Zu den Gründungskosten zählen Notar- oder Rechtsanwaltshonorare, die Eintragungsgebühr beim Firmenbuch, Kosten für Beglaubigungen und gegebenenfalls Beratung durch die Steuerberatung. Unter dem Neugründungs-Förderungsgesetz können manche Gebühren entfallen. Die genauen Kosten hängen vom Umfang des Gesellschaftsvertrags ab und sollten vorab angefragt werden.

Laufend kommen Kosten für die doppelte Buchhaltung, den Jahresabschluss und dessen Offenlegung beim Firmenbuch dazu. Außerdem fällt eine Mindestkörperschaftsteuer an, auch wenn die GmbH keinen Gewinn macht.

## Haftung und Pflichten der Geschäftsführung

Auch wenn die Gesellschafter grundsätzlich nicht persönlich haften, tragen Geschäftsführer Verantwortung. Sie müssen die Bücher ordnungsgemäß führen, Steuern und Abgaben abführen und bei Zahlungsunfähigkeit rechtzeitig einen Insolvenzantrag stellen. Bei Verstößen droht eine persönliche Haftung. Banken verlangen bei Krediten an kleine GmbHs zudem oft persönliche Bürgschaften der Gesellschafter.

Eine GmbH lohnt sich vor allem bei höheren Gewinnen, wegen der Haftungsbeschränkung und wenn mehrere Gesellschafter beteiligt sind. Für kleine Tätigkeiten ist ein Einzelunternehmen oft einfacher und günstiger. Die Gründerservices der Wirtschaftskammer, auch in der Steiermark, und Steuerberater helfen, die passende Rechtsform zu finden.

Ein weiterer Punkt ist die Sozialversicherung: Gesellschafter-Geschäftsführer einer GmbH mit wesentlicher Beteiligung sind in der Regel bei der SVS versichert, Fremdgeschäftsführer meist bei der ÖGK als Angestellte. Auch das wirkt sich auf die Gesamtkosten aus und sollte bei der Planung berücksichtigt werden. Ein Vergleich mit realistischen Gewinnszenarien zeigt, ab wann sich die GmbH steuerlich lohnt.','wirtschaft','Gründen','steiermark','ratgeber','Presseinfo Redaktion','/assets/img/artikel/gmbh-gruenden-oesterreich-stammkapital-kosten-ablauf.webp',NULL,NULL,'published','2026-10-08T07:36:00.000Z','2026-10-22T00:17:07.904Z','GmbH gründen Österreich: Kapital, Kosten, Ablauf','GmbH gründen in Österreich: Wie hoch das Stammkapital ist, welche Schritte nötig sind und was Notar und Firmenbuch kosten. Überblick für Gründer lesen.','GmbH gründen','["GmbH gründen","GmbH Stammkapital","GmbH Gründung Kosten","Firmenbuch Eintragung","gmbh gründen 10000 euro stammkapital","vereinfachte gmbh gründung usp","flexco österreich","gesellschaftsvertrag notariatsakt"]','GmbH gründen: Besprechungsraum in einem Notariat in Graz mit Dokumentenmappe','Photorealistic editorial photo of a notary office meeting room in Graz with dark wooden table, two fountain pens and a closed leather document folder, historic window with view on red rooftops, soft afternoon light, no people, no text, no logos, no readable signs','[{"q":"Wie hoch ist das Stammkapital einer GmbH in Österreich?","a":"Seit 2024 beträgt es mindestens 10.000 Euro, davon müssen bei Gründung mindestens 5.000 Euro bar eingezahlt sein."},{"q":"Brauche ich für die GmbH-Gründung einen Notar?","a":"In der Regel ja. Für Ein-Personen-GmbHs gibt es eine vereinfachte elektronische Gründung über das USP und eine Bank."},{"q":"Wann entsteht die GmbH?","a":"Mit der Eintragung im Firmenbuch. Davor besteht eine Vorgesellschaft mit möglicher persönlicher Haftung."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('eu-eingetragener-unternehmer-firmenbuch-vorteile','e.U. gründen: Eingetragener Unternehmer im Firmenbuch','Viele Einzelunternehmer starten ohne Firmenbuch. Die Eintragung als e.U. kann dennoch sinnvoll sein, etwa für einen eigenen Firmennamen. Ab einer Umsatzgrenze ist sie Pflicht.','Wer als Einzelperson ein Unternehmen startet, kann ein e.U. gründen, also sich als eingetragener Unternehmer im Firmenbuch registrieren lassen. Die Rechtsform bleibt dabei ein Einzelunternehmen. Die Eintragung bringt aber einige Vorteile und ist ab einer bestimmten Unternehmensgröße auch verpflichtend.

## e.U. gründen: wann die Eintragung Pflicht ist

Einzelunternehmer müssen sich in das Firmenbuch eintragen lassen, wenn sie nach dem Unternehmensgesetzbuch rechnungslegungspflichtig sind. Das ist in der Regel der Fall, wenn der Umsatz in zwei aufeinanderfolgenden Jahren jeweils 700.000 Euro übersteigt oder in einem Jahr eine Million Euro. Dann gilt auch die Pflicht zur doppelten Buchhaltung. Ausnahmen gibt es für freie Berufe sowie für Land- und Forstwirtschaft.

Unterhalb dieser Grenzen ist die Eintragung freiwillig. Laut Wirtschaftskammer sind rund 78 Prozent aller Neugründungen nicht im Firmenbuch eingetragen, die meisten davon Einzelunternehmen.

## Vorteile der Eintragung als e.U.

- **Eigener Firmenname:** Nur eingetragene Unternehmer dürfen eine Fantasiebezeichnung oder Sachbezeichnung als Firma führen, ergänzt um den Zusatz „e.U.“. Nicht eingetragene Einzelunternehmer treten unter ihrem eigenen Namen auf.
- **Seriöser Auftritt:** Der Eintrag im öffentlichen Register schafft Vertrauen bei Geschäftspartnern und Banken.
- **Prokura:** Ein e.U. kann einen Prokuristen bestellen.
- **Firmenschutz:** Der eingetragene Firmenwortlaut ist im jeweiligen Gerichtssprengel geschützt.

## Nachteile und Pflichten

Die Eintragung ist mit Gebühren und etwas Verwaltungsaufwand verbunden. Änderungen, etwa des Sitzes oder des Namens, müssen gemeldet werden. Die Haftung bleibt wie beim nicht eingetragenen Einzelunternehmen unbeschränkt: Der Unternehmer haftet mit seinem gesamten Privatvermögen. Ein e.U. ist also keine Haftungsbegrenzung wie bei einer GmbH.

Solange keine Rechnungslegungspflicht besteht, darf ein e.U. weiterhin die Einnahmen-Ausgaben-Rechnung verwenden. Die freiwillige Eintragung führt also nicht automatisch zur doppelten Buchhaltung.

## So läuft die Eintragung ab

1. Firmenwortlaut wählen und auf Unterscheidbarkeit prüfen
2. Antrag auf Eintragung beim Firmenbuchgericht mit beglaubigter Unterschrift stellen
3. Angaben zu Sitz, Geschäftsanschrift und Geschäftszweig machen
4. Gebühren entrichten, sofern keine Befreiung nach dem Neugründungs-Förderungsgesetz vorliegt
5. Firmenbuchnummer auf Geschäftspapieren und Website angeben

Für die Prüfung des Firmenwortlauts kann eine Stellungnahme der Wirtschaftskammer eingeholt werden. Das beschleunigt das Verfahren, weil Unklarheiten vorab geklärt werden. Zuständig ist das Landesgericht oder in Wien das Handelsgericht.

## Pflichtangaben auf Geschäftspapieren

Eingetragene Unternehmer müssen auf Geschäftsbriefen, Bestellscheinen und der Website bestimmte Angaben machen: den Firmenwortlaut samt Zusatz „e.U.“, den Sitz, die Firmenbuchnummer und das Firmenbuchgericht. Diese Angaben gehören auch ins Impressum nach dem E-Commerce-Gesetz und der Offenlegung nach dem Mediengesetz.

Die Eintragung ist vor allem für Unternehmer interessant, die mit einem Markennamen auftreten wollen, etwa ein Geschäft in der Salzburger Altstadt, eine Agentur oder ein Handwerksbetrieb mit Wachstumsplänen. Wer nur nebenbei selbstständig ist, kommt oft ohne Eintragung aus. Das Gründerservice der Wirtschaftskammer berät kostenlos zur passenden Variante.

Wichtig für spätere Entwicklungen: Ein e.U. kann bei Wachstum relativ einfach in eine GmbH umgewandelt werden, etwa durch Einbringung des Betriebs. Das ist steuerlich unter bestimmten Bedingungen begünstigt. Wer von Anfang an mit Wachstum rechnet, sollte diese Möglichkeit bei der Wahl der Rechtsform im Blick behalten.','wirtschaft','Gründen','salzburg','ratgeber','Presseinfo Redaktion','/assets/img/artikel/eu-eingetragener-unternehmer-firmenbuch-vorteile.webp',NULL,NULL,'published','2026-10-15T15:24:00.000Z','2026-10-22T00:17:07.904Z','e.U. gründen: Vorteile der Firmenbuch-Eintragung','e.U. gründen: Wann Einzelunternehmer ins Firmenbuch müssen, welche Vorteile die Eintragung bringt und wie sie abläuft. Jetzt alle Infos lesen.','e.U. gründen','["e.U. gründen","eingetragener Unternehmer","Einzelunternehmen Firmenbuch","Firmenwortlaut e.U.","rechnungslegungspflicht 700000 euro","einzelunternehmen haftung privatvermögen","firmenbuch eintragung einzelunternehmer kosten","unterschied einzelunternehmen e.u."]','e.U. gründen: kleines Geschäft in einer Altstadtgasse in Salzburg am Abend','Photorealistic editorial photo of a small boutique shop front in a narrow old town lane in Salzburg, wooden door, shop window with handmade goods softly blurred, evening street lamps starting to glow, no people, no text, no logos, no readable signs','[{"q":"Wann muss sich ein Einzelunternehmer ins Firmenbuch eintragen?","a":"In der Regel, wenn der Umsatz in zwei Jahren hintereinander 700.000 Euro übersteigt oder in einem Jahr eine Million Euro."},{"q":"Haftet ein e.U. beschränkt?","a":"Nein, der eingetragene Unternehmer haftet weiterhin unbeschränkt mit seinem Privatvermögen."},{"q":"Welchen Vorteil hat ein e.U.?","a":"Vor allem einen eigenen Firmennamen mit Zusatz e.U., einen seriöseren Auftritt und die Möglichkeit einer Prokura."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('presseaussendung-schreiben-aufbau-laenge-fehler','Presseaussendung schreiben: Aufbau, Länge und typische Fehler','Redaktionen bekommen täglich hunderte Aussendungen. Wie eine Presseaussendung aufgebaut sein muss, damit sie gelesen und übernommen wird, und welche Fehler man vermeiden sollte.','Wer eine Presseaussendung schreiben will, sollte sich zuerst in die Lage der Redaktion versetzen. Journalistinnen und Journalisten entscheiden oft in wenigen Sekunden, ob eine Meldung relevant ist. Eine gute Presseaussendung liefert deshalb sofort die wichtigste Information, ist sachlich formuliert und lässt sich mit wenig Aufwand weiterverarbeiten.

## Presseaussendung schreiben: der richtige Aufbau

Bewährt hat sich der Aufbau nach dem Prinzip der umgekehrten Pyramide. Das Wichtigste steht ganz oben, Details folgen weiter unten. So kann die Redaktion den Text von hinten kürzen, ohne dass die Kernaussage verloren geht.

1. **Titel:** kurz, konkret und mit dem wichtigsten Begriff am Anfang. Er sagt, was passiert ist, nicht, wie toll das Unternehmen ist.
2. **Untertitel:** ergänzt eine zweite wichtige Information.
3. **Lead:** der erste Absatz beantwortet die wichtigsten W-Fragen: Wer, was, wann, wo, wie und warum.
4. **Haupttext:** Hintergründe, Zahlen, Zusammenhänge und ein Zitat einer verantwortlichen Person.
5. **Unternehmensinfo:** zwei bis drei Sätze zum Absender, der sogenannte Boilerplate.
6. **Pressekontakt:** Name, Telefonnummer und E-Mail einer erreichbaren Ansprechperson.

Ort und Datum stehen üblicherweise am Beginn des Leads, etwa „Wien, 22. Oktober 2026“.

## Die ideale Länge

Eine Presseaussendung sollte in der Regel nicht länger als eine A4-Seite sein, das entspricht etwa 2.500 bis 3.000 Zeichen. Bei komplexen Themen kann es mehr sein, dann sollte man aber zusätzliches Material wie Factsheets oder Hintergrundpapiere als Anhang oder Link anbieten. Der Lead sollte nicht mehr als drei Sätze umfassen.

## Sprache: nüchtern statt werblich

Redaktionen übernehmen keine Werbetexte. Superlative wie „einzigartig“, „revolutionär“ oder „Marktführer“ ohne Beleg wirken unseriös. Besser sind überprüfbare Fakten: Zahlen, Daten, konkrete Beispiele. Die Sprache sollte aktiv und verständlich sein, Fachbegriffe sind zu erklären. Zitate dürfen persönlicher sein, sollten aber eine Einschätzung oder Meinung enthalten und nicht nur die Fakten wiederholen.

## Typische Fehler beim Presseaussendung schreiben

- kein erkennbarer Nachrichtenwert, etwa bei reinen Produktwerbungen
- die eigentliche Neuigkeit erst im dritten Absatz
- zu lange Texte ohne Zwischenüberschriften
- fehlende oder nicht erreichbare Pressekontakte
- Anhänge mit riesigen Dateien statt Links zu Bildern
- falsche Ansprechpartner im Verteiler oder Massenmails ohne Bezug zum Ressort
- Rechtschreibfehler und falsche Namen

## Versand und Timing

Presseaussendungen werden per E-Mail an ausgewählte Redaktionen oder über Verteilerdienste wie APA-OTS verbreitet. Der Text gehört direkt in die Mail, nicht nur als PDF im Anhang. Gute Zeitpunkte sind in der Regel Vormittage unter der Woche. Am Freitagnachmittag oder vor Feiertagen gehen Meldungen leichter unter. Bei Terminen wie Pressekonferenzen sollte die Einladung einige Tage vorher verschickt werden.

Eine Presseaussendung mit einem passenden, druckfähigen Pressefoto hat deutlich bessere Chancen. Wichtig sind ein klarer Bildnachweis und die Freigabe zur honorarfreien Nutzung im Zusammenhang mit der Meldung. Außerdem sollte die genannte Ansprechperson am Versandtag tatsächlich erreichbar sein, denn Rückfragen kommen oft kurzfristig.

Nach dem Versand lohnt sich ein Blick auf die Ergebnisse: Welche Medien haben berichtet, welche nicht? Wer sich die Rückmeldungen notiert, kann Verteiler, Themen und Formulierungen beim nächsten Mal gezielt verbessern.','wirtschaft','Medien & PR','wien','ratgeber','Presseinfo Redaktion','/assets/img/artikel/presseaussendung-schreiben-aufbau-laenge-fehler.webp',NULL,NULL,'published','2026-09-26T09:05:00.000Z','2026-10-22T00:17:07.904Z','Presseaussendung schreiben: Aufbau und Tipps','Presseaussendung schreiben: Wie Titel, Lead und Text aufgebaut sind, wie lang sie sein soll und welche Fehler Redaktionen abschrecken. Jetzt lesen.','Presseaussendung schreiben','["Presseaussendung schreiben","Pressemitteilung Aufbau","Presseaussendung Vorlage","Pressetext Länge","presseaussendung schreiben tipps kmu","w-fragen lead pressetext","pressekontakt presseaussendung","pressemitteilung fehler vermeiden"]','Presseaussendung schreiben: Redaktionsschreibtisch mit Bildschirmen in einem Wiener Büro','Photorealistic editorial photo of a newsroom desk in Vienna with several monitors showing blurred abstract layouts, a notepad, a smartphone and a coffee cup, evening city lights through the window, no people, no text, no logos, no readable signs','[{"q":"Wie lang sollte eine Presseaussendung sein?","a":"In der Regel maximal eine A4-Seite, also etwa 2.500 bis 3.000 Zeichen."},{"q":"Was gehört in den Lead einer Presseaussendung?","a":"Die wichtigsten W-Fragen: wer, was, wann, wo, wie und warum, in maximal drei Sätzen."},{"q":"Wann verschickt man eine Presseaussendung am besten?","a":"Meist an Vormittagen unter der Woche. Freitagnachmittag und Tage vor Feiertagen sind ungünstig."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('sperrfrist-embargo-o-ton-begriffe-pressearbeit','Sperrfrist, Embargo, O-Ton: Die wichtigsten Begriffe der Pressearbeit','Wer mit Medien arbeitet, begegnet Fachbegriffen wie Sperrfrist, O-Ton oder Hintergrundgespräch. Was sie bedeuten und welche Regeln dahinterstehen.','Die Sperrfrist ist einer der wichtigsten Begriffe der Pressearbeit. Sie legt fest, ab wann eine Information veröffentlicht werden darf. Daneben gibt es weitere Fachbegriffe, die Unternehmen, Vereine und Behörden kennen sollten, wenn sie mit Journalistinnen und Journalisten zusammenarbeiten.

## Sperrfrist und Embargo: was sie bedeuten

Eine Sperrfrist, international Embargo genannt, ist eine Bitte an die Redaktionen, eine Information erst ab einem bestimmten Zeitpunkt zu veröffentlichen. Sie wird gut sichtbar über die Presseaussendung gesetzt, etwa „Sperrfrist: 23. Oktober 2026, 10:00 Uhr“. Typische Anlässe sind Studienergebnisse, Bilanzen, Reden oder Preisverleihungen. Die Redaktionen bekommen so Zeit, den Inhalt vorzubereiten, Rückfragen zu stellen und zum vereinbarten Zeitpunkt sauber zu berichten.

Rechtlich ist eine Sperrfrist meist nicht durchsetzbar. Sie beruht auf Vertrauen und journalistischer Fairness. Seriöse Medien halten sich in der Regel daran, nicht zuletzt, um weiter frühzeitig informiert zu werden. Wer eine Sperrfrist bricht, riskiert, künftig von Vorabinformationen ausgeschlossen zu werden.

## Wann eine Sperrfrist sinnvoll ist

- bei komplexen Inhalten, die Vorbereitung brauchen
- wenn mehrere Medien zeitgleich berichten sollen
- bei Terminen mit festem Zeitpunkt, etwa einer Rede oder Pressekonferenz
- bei börsenrelevanten Informationen, für die zusätzlich strenge gesetzliche Regeln gelten

Nicht sinnvoll ist eine Sperrfrist bei gewöhnlichen Meldungen ohne besonderen Anlass. Das wirkt eher wichtigtuerisch.

## O-Ton und Zitat

Ein O-Ton ist eine Originalaufnahme einer Person, etwa im Radio oder Fernsehen. In Printmedien entspricht dem das direkte Zitat. Für Pressearbeit heißt das: Wer einen O-Ton gibt, sollte vorbereitete Kernbotschaften haben und sich kurz fassen. Für Radio und TV werden oft nur wenige Sekunden verwendet. Ein guter O-Ton enthält eine klare Aussage in einem Satz.

## Hintergrundgespräch und Vertraulichkeit

Bei einem Hintergrundgespräch informieren Unternehmen oder Politik Journalisten ausführlicher, ohne dass alles zitiert werden soll. Wichtig ist, die Regeln vorher klar zu vereinbaren. In der Praxis haben sich drei Stufen etabliert:

1. Die Information darf mit Namen und Funktion zitiert werden.
2. Die Information darf verwendet werden, aber ohne Nennung der Quelle, etwa „aus Unternehmenskreisen“.
3. Die Information ist nur zum Verständnis gedacht und darf nicht veröffentlicht werden, oft als „off the record“ bezeichnet.

Diese Vereinbarungen gelten nur, wenn sie vor dem Gespräch getroffen wurden. Nachträglich etwas für vertraulich zu erklären, funktioniert meist nicht.

## Autorisierung von Interviews

Bei Interviews in Printmedien ist es in Österreich und Deutschland üblich, dass Gesprächspartner ihre Zitate vor Veröffentlichung autorisieren dürfen. Das sollte vorab vereinbart werden. Die Autorisierung dient dazu, sachliche Fehler zu korrigieren, nicht dazu, das Gespräch neu zu schreiben. Medien können sich bei übermäßigen Änderungen entscheiden, das Interview nicht zu bringen.

Weitere Begriffe kurz erklärt:

- **Pressemappe:** Sammlung von Informationen, Fotos und Kontakten zu einem Thema oder Unternehmen
- **Boilerplate:** kurzer Standardtext über das Unternehmen am Ende einer Aussendung
- **Pressespiegel:** Sammlung der Berichterstattung über ein Unternehmen oder Thema
- **Exklusivmeldung:** Information, die nur ein Medium erhält, meist gegen frühere Veröffentlichung

Wer diese Begriffe kennt und die damit verbundenen Regeln respektiert, schafft Vertrauen bei Redaktionen. Das ist die Grundlage jeder erfolgreichen Medienarbeit, egal ob in Wien, Innsbruck oder in einer kleinen Gemeinde.','wirtschaft','Medien & PR','tirol','ratgeber','Presseinfo Redaktion','/assets/img/artikel/sperrfrist-embargo-o-ton-begriffe-pressearbeit.webp',NULL,NULL,'published','2026-10-07T13:51:00.000Z','2026-10-22T00:17:07.905Z','Sperrfrist, Embargo, O-Ton: Pressebegriffe erklärt','Sperrfrist, Embargo und O-Ton einfach erklärt: Was die wichtigsten Begriffe der Pressearbeit bedeuten und wie man sie richtig einsetzt. Jetzt lesen.','Sperrfrist','["Sperrfrist","Embargo Presse","O-Ton","Hintergrundgespräch","sperrfrist presseaussendung formulieren","off the record bedeutung","unter drei journalismus","autorisierung interview zitat"]','Sperrfrist und O-Ton: Mikrofon und Aufnahmegerät auf einem Tisch bei einer Pressekonferenz','Photorealistic editorial photo of a professional microphone and a small audio recorder on a press conference table in an Innsbruck conference room, mountains visible through window, blurred chairs, cool daylight, no people, no text, no logos, no readable signs','[{"q":"Was bedeutet Sperrfrist bei einer Presseaussendung?","a":"Die Redaktion soll die Information erst ab dem angegebenen Zeitpunkt veröffentlichen. Sie beruht meist auf Vertrauen, nicht auf Gesetz."},{"q":"Was ist ein O-Ton?","a":"Eine Originalaufnahme einer Person im Radio oder Fernsehen, vergleichbar mit einem direkten Zitat in Printmedien."},{"q":"Was heißt off the record?","a":"Die Information dient nur dem Verständnis und darf nicht veröffentlicht werden. Das muss vor dem Gespräch vereinbart werden."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pressefotos-richtig-liefern-format-bildrechte','Pressefotos richtig liefern: Format, Auflösung und Bildrechte','Ein gutes Pressefoto erhöht die Chance auf Berichterstattung deutlich. Welche technischen Anforderungen Redaktionen haben und wie man Bildrechte sauber klärt.','Pressefotos entscheiden oft darüber, ob eine Meldung veröffentlicht wird und wie prominent sie platziert wird. Online wie in Print brauchen Redaktionen passende Bilder. Wer gleich mit der Presseaussendung hochwertige, rechtlich saubere Fotos liefert, erleichtert die Arbeit und erhöht die Chance auf Berichterstattung.

## Pressefotos: technische Anforderungen

Für Online-Medien reichen Bilder mit einer Breite von etwa 1.500 bis 2.000 Pixeln. Für den Druck sind höhere Auflösungen nötig. Als Faustregel gelten 300 dpi in der gewünschten Druckgröße, das entspricht für ein Foto über eine halbe Zeitungsseite einer Datei mit mehreren Millionen Pixeln. Am besten stellt man eine hochauflösende Version bereit, die Redaktionen selbst verkleinern können.

Weitere Tipps:

- Dateiformat JPG in hoher Qualität, für Logos zusätzlich PNG oder Vektorformate
- Farbprofil sRGB für Online, für Print gegebenenfalls nach Absprache
- Querformat und Hochformat anbieten, weil Layouts unterschiedlich sind
- aussagekräftige Dateinamen statt „IMG_4711.jpg“
- keine Wasserzeichen, Rahmen oder eingefügten Texte

## Motive, die Redaktionen nutzen

Gestellte Gruppenfotos mit Händedruck vor einer Fotowand werden selten groß gedruckt. Besser sind authentische Bilder mit Handlung: Menschen bei der Arbeit, Produkte im Einsatz, Baustellen, Veranstaltungen mit Atmosphäre. Ein Porträt der zitierten Person sollte immer verfügbar sein. Für regionale Medien, etwa im Burgenland, sind Bilder mit erkennbarem Bezug zur Region besonders interessant.

## Bildnachweis und Bildunterschrift

Zu jedem Pressefoto gehört ein Bildnachweis, also die Angabe, wer das Foto gemacht hat, etwa „Foto: Name Fotograf“ oder „Foto: Unternehmen“. Außerdem sollte eine Bildunterschrift mitgeliefert werden, die beschreibt, was und wer zu sehen ist. Personen werden in der Regel von links nach rechts mit Namen und Funktion genannt.

Diese Angaben stehen am besten direkt in der Presseaussendung und zusätzlich in den Metadaten der Bilddatei. Viele Redaktionssysteme lesen die Metadaten automatisch aus.

## Bildrechte klären

Wer Pressefotos weitergibt, muss die nötigen Rechte haben. Das betrifft zwei Ebenen:

1. **Urheberrecht:** Der Fotograf oder die Fotografin hat die Rechte am Bild. Für die Weitergabe an Medien braucht das Unternehmen eine entsprechende Nutzungsvereinbarung. Das sollte schon bei der Beauftragung schriftlich geregelt werden.
2. **Recht am eigenen Bild:** Abgebildete Personen haben einen Anspruch auf Schutz ihrer berechtigten Interessen. Bei Mitarbeitenden, Kunden oder Kindern sollte eine schriftliche Zustimmung zur Veröffentlichung eingeholt werden, besonders bei Porträts.

In der Presseaussendung sollte klar stehen, dass die Fotos im Zusammenhang mit der Meldung honorarfrei verwendet werden dürfen und welcher Bildnachweis anzugeben ist. Für andere Zwecke kann die Nutzung ausgeschlossen werden.

## Fotos richtig versenden

Große Bilddateien gehören nicht in den Anhang einer Massenmail. Sie verstopfen Postfächer und landen oft im Spamfilter. Besser ist ein Link zu einem Downloadbereich auf der eigenen Website, einem Pressebereich oder einem Cloud-Ordner. Eine kleine Vorschau direkt in der Mail hilft, das Motiv schnell zu erkennen. Bei Verteilerdiensten wie APA-OTS können Fotos direkt mit der Aussendung veröffentlicht werden.

Unternehmen, die regelmäßig Pressearbeit machen, sollten auf ihrer Website einen Pressebereich mit aktuellen Fotos, Logos, Porträts der Geschäftsführung und Firmeninformationen anbieten. Veraltete Bilder, etwa von Personen, die nicht mehr im Unternehmen sind, sollten konsequent entfernt werden.','wirtschaft','Medien & PR','burgenland','ratgeber','Presseinfo Redaktion','/assets/img/artikel/pressefotos-richtig-liefern-format-bildrechte.webp',NULL,NULL,'published','2026-10-10T08:37:00.000Z','2026-10-22T00:17:07.905Z','Pressefotos liefern: Format, Auflösung, Bildrechte','Pressefotos richtig liefern: Welche Auflösung und welches Format Redaktionen brauchen, wie der Bildnachweis aussieht und was erlaubt ist. Jetzt lesen.','Pressefotos','["Pressefotos","Pressefoto Auflösung","Bildnachweis","Bildrechte Presse","pressefoto 300 dpi format","honorarfrei pressefoto nutzung","recht am eigenen bild österreich","pressefotos download bereich"]','Pressefotos: Profikamera auf einem Holztisch mit dem Neusiedler See im Hintergrund','Photorealistic editorial photo of a professional camera with a large lens resting on a wooden table at an outdoor event setup near Lake Neusiedl in Burgenland, reeds and water in soft focus behind, golden hour light, no people, no text, no logos, no readable signs','[{"q":"Welche Auflösung brauchen Pressefotos?","a":"Für Print gelten 300 dpi in Druckgröße als Faustregel, für Online reichen etwa 1.500 bis 2.000 Pixel Breite."},{"q":"Was ist ein Bildnachweis?","a":"Die Angabe, wer ein Foto gemacht hat oder die Rechte hält, etwa Foto: Name Fotograf."},{"q":"Brauche ich die Zustimmung abgebildeter Personen?","a":"Bei Porträts und erkennbaren Personen sollte eine schriftliche Zustimmung zur Veröffentlichung eingeholt werden."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('presseverteiler-aufbauen-medienkontakte-oesterreich','Presseverteiler aufbauen: So finden KMU die richtigen Medienkontakte','Die beste Presseaussendung nützt nichts, wenn sie bei den falschen Leuten landet. Wie kleine Betriebe einen gezielten Presseverteiler aufbauen und pflegen.','Wer einen Presseverteiler aufbauen will, sollte auf Qualität statt Masse setzen. Redaktionen erhalten täglich eine Flut an Aussendungen. Eine Mail, die nicht zum Ressort passt, wird meist sofort gelöscht. Für kleine und mittlere Unternehmen ist ein gezielter, gut gepflegter Verteiler deshalb wichtiger als eine lange Liste gekaufter Adressen.

## Presseverteiler aufbauen: Zielmedien festlegen

Am Anfang steht die Frage, wen man erreichen will. Daraus ergeben sich die passenden Medien:

- **Regionalmedien:** Bezirkszeitungen, regionale Tageszeitungen und Lokalradios berichten gerne über Betriebe aus ihrer Region, etwa über neue Standorte, Lehrlinge oder Jubiläen.
- **Fachmedien:** Branchenmagazine für Bau, Handwerk, Handel oder IT erreichen Fachpublikum und Entscheider.
- **Wirtschaftsressorts:** Für größere Nachrichten wie Investitionen oder Übernahmen kommen die Wirtschaftsredaktionen der überregionalen Medien in Frage.
- **Online-Portale und Blogs:** Spezialisierte Plattformen haben oft eine hohe Reichweite in der Zielgruppe.

Für einen Handwerksbetrieb in Niederösterreich sind die Bezirksausgaben regionaler Wochenzeitungen meist wichtiger als ein bundesweites Magazin.

## Die richtigen Ansprechpersonen finden

Statt allgemeiner Redaktionsadressen sind persönliche Kontakte wertvoller. Hinweise liefern:

1. Impressum und Redaktionsseiten der Medien
2. Artikel zu ähnlichen Themen und deren Autorinnen und Autoren
3. Medienverzeichnisse und Datenbanken, die teils kostenpflichtig sind
4. Veranstaltungen, Pressekonferenzen und Branchenevents
5. Netzwerke wie LinkedIn, wo viele Journalisten aktiv sind

Wichtig ist, Ressort und Zuständigkeit festzuhalten. Eine Wirtschaftsredakteurin interessiert sich nicht für die Sportveranstaltung des Firmenvereins.

## Kontakte richtig pflegen

Ein Verteiler veraltet schnell, weil Journalisten Medium oder Ressort wechseln. Er sollte daher mindestens einmal im Jahr überprüft werden. Bounces und Abmeldungen müssen sofort berücksichtigt werden. Hilfreich ist eine einfache Tabelle oder ein CRM mit Name, Medium, Ressort, Kontaktdaten, Themeninteressen und bisherigen Kontakten.

Eine persönliche Beziehung entsteht nicht durch Massenmails. Ein kurzes Telefonat, ein Hinweis auf ein passendes Thema oder eine Einladung zu einem Betriebsbesuch wirken oft mehr als zehn Aussendungen.

## Datenschutz beachten

Auch dienstliche E-Mail-Adressen von Journalisten sind personenbezogene Daten. Die Datenschutz-Grundverordnung gilt daher auch für Presseverteiler. Unternehmen sollten dokumentieren, woher die Kontakte stammen, nur Daten speichern, die sie brauchen, und in jeder Aussendung eine einfache Möglichkeit zur Abmeldung anbieten. Gekaufte Adresslisten sind rechtlich und praktisch problematisch.

## Verteilerdienste als Ergänzung

Neben dem eigenen Verteiler können Unternehmen Dienste wie APA-OTS nutzen, über die Aussendungen an Redaktionen in ganz Österreich verbreitet und online veröffentlicht werden. Auch Presseportale bieten die Möglichkeit, Meldungen zu veröffentlichen und damit in Suchmaschinen sichtbar zu werden. Das ersetzt aber nicht den direkten Kontakt zu den wichtigsten Redaktionen.

Ein Verteiler lebt von Relevanz. Wer jede Kleinigkeit verschickt, wird schnell ignoriert. Besser sind wenige, gut aufbereitete Meldungen mit echtem Nachrichtenwert, etwa neue Arbeitsplätze, Investitionen, Auszeichnungen oder Studien. Für interne Neuigkeiten eignen sich eher die eigenen Kanäle wie Website, Newsletter oder Social Media.

Ein praktischer Tipp für den Start: Beginnen Sie mit einer Liste von zehn bis zwanzig wirklich relevanten Kontakten. Notieren Sie, welche Themen die jeweiligen Journalisten zuletzt behandelt haben, und passen Sie Ihre Aussendungen daran an. Ein kurzer persönlicher Satz am Beginn der Mail, warum das Thema für genau dieses Medium interessant ist, erhöht die Chance auf eine Antwort deutlich.','wirtschaft','Medien & PR','niederoesterreich','ratgeber','Presseinfo Redaktion','/assets/img/artikel/presseverteiler-aufbauen-medienkontakte-oesterreich.webp',NULL,NULL,'published','2026-10-17T11:29:00.000Z','2026-10-22T00:17:07.905Z','Presseverteiler aufbauen: Medienkontakte für KMU','Presseverteiler aufbauen: Wie kleine Unternehmen in Österreich passende Redaktionen finden, Kontakte pflegen und DSGVO-konform bleiben. Jetzt lesen.','Presseverteiler aufbauen','["Presseverteiler aufbauen","Medienkontakte","Presseverteiler Österreich","Regionalmedien","journalisten kontakt finden","presseverteiler dsgvo","bezirksblätter regionale presse","apa ots verteiler"]','Presseverteiler aufbauen: Stapel regionaler Zeitungen auf einem Kaffeehaustisch in Niederösterreich','Photorealistic editorial photo of a stack of regional Austrian newspapers and magazines on a café table in a Lower Austrian town square, mastheads not readable, cup of melange coffee next to them, morning sun, no people, no text, no logos, no readable signs','[{"q":"Wie finde ich die richtigen Journalisten für meinen Presseverteiler?","a":"Über Impressen, Artikel zu ähnlichen Themen, Medienverzeichnisse, Events und Netzwerke wie LinkedIn."},{"q":"Gilt die DSGVO auch für Presseverteiler?","a":"Ja, auch dienstliche E-Mail-Adressen sind personenbezogene Daten. Herkunft dokumentieren und Abmeldung ermöglichen."},{"q":"Wie oft sollte ich meinen Verteiler aktualisieren?","a":"Mindestens einmal im Jahr, Bounces und Abmeldungen sofort."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pressekonferenz-organisieren-ablauf-checkliste','Pressekonferenz organisieren: Ablauf, Einladung und Checkliste','Eine Pressekonferenz ist aufwendig und lohnt sich nur bei echten Neuigkeiten. Wie Unternehmen sie richtig planen, einladen und durchführen.','Wer eine Pressekonferenz organisieren will, sollte sich zuerst eine Frage stellen: Ist die Neuigkeit wirklich so wichtig, dass Journalistinnen und Journalisten dafür ihre Redaktion verlassen? Personal in Redaktionen ist knapp, Termine werden genau abgewogen. Eine Pressekonferenz lohnt sich daher nur bei Themen mit hohem Nachrichtenwert.

## Pressekonferenz organisieren: wann sie sich lohnt

Typische Anlässe sind große Investitionen oder Standortentscheidungen, die Präsentation von Studien oder Bilanzen, Krisen mit großem öffentlichen Interesse oder Kooperationen mit bekannten Partnern. Für kleinere Themen sind Alternativen oft besser geeignet: eine gut geschriebene Presseaussendung, ein Pressegespräch mit wenigen ausgewählten Medien oder ein Vor-Ort-Termin, etwa in einem neuen Betrieb.

## Die Einladung

Die Presseeinladung sollte etwa eine Woche vorher verschickt werden, mit einer Erinnerung ein bis zwei Tage vor dem Termin. Sie enthält:

- Thema und Anlass in einem klaren Satz
- Datum, Uhrzeit und Dauer
- genauen Ort mit Anfahrtsinfo und Parkmöglichkeiten
- Namen und Funktionen der Sprecherinnen und Sprecher
- Hinweis auf Foto- und Filmmöglichkeiten
- Kontaktperson und Bitte um Anmeldung

Das eigentliche Thema darf neugierig machen, aber nicht alles verraten. Sonst bleibt kein Grund, persönlich zu kommen.

## Zeitpunkt und Ort

Bewährt haben sich Vormittage zwischen 9:30 und 11:00 Uhr an Wochentagen, idealerweise Dienstag bis Donnerstag. So haben Medien genug Zeit für die Berichterstattung am selben Tag. Der Ort sollte gut erreichbar sein und eine ruhige Akustik haben. Für Fernsehen und Fotografen ist ein ansprechender Hintergrund wichtig, etwa die Produktionshalle statt eines fensterlosen Besprechungsraums.

## Ablauf der Pressekonferenz

1. Begrüßung durch die Moderation und kurze Vorstellung der Sprecher
2. Statements, insgesamt nicht länger als 20 bis 30 Minuten
3. Fragerunde für die anwesenden Medien
4. Möglichkeit für Einzelinterviews, Fotos und O-Töne

Weniger ist mehr: Maximal drei Sprecher, klare Botschaften, keine langen Präsentationen mit vielen Folien.

## Pressemappe und Unterlagen

Am Termin und digital danach sollte eine Pressemappe bereitstehen. Sie enthält die Presseaussendung, Hintergrundinformationen, Zahlen und Fakten, Porträts der Sprecher sowie Fotos zum Download. Medien, die nicht teilnehmen konnten, erhalten die Unterlagen unmittelbar nach dem Termin. Eine Sperrfrist kann sinnvoll sein, wenn Unterlagen vorab verteilt werden.

Seit einigen Jahren bieten viele Veranstalter zusätzlich einen Livestream oder eine Online-Teilnahme an. Das erhöht die Reichweite, vor allem für Medien aus anderen Bundesländern. Für Fragen online sollte eine eigene Person zuständig sein. Technik muss vorher getestet werden.

Checkliste für den Tag:

- Raum, Technik, Mikrofone und Strom für Kameras prüfen
- Teilnehmerliste und Namensschilder vorbereiten
- Getränke bereitstellen, aufwendiges Catering ist nicht nötig
- Pressemappe gedruckt und digital bereithalten
- Sprecher auf mögliche kritische Fragen vorbereiten
- nach dem Termin Unterlagen versenden und Berichterstattung im Pressespiegel sammeln

Eine gut organisierte Pressekonferenz in Klagenfurt, Wien oder Graz folgt denselben Grundregeln: Relevanz, Pünktlichkeit und gute Unterlagen. Wer diese einhält, wird von Redaktionen auch beim nächsten Mal ernst genommen.','wirtschaft','Medien & PR','kaernten','ratgeber','Presseinfo Redaktion','/assets/img/artikel/pressekonferenz-organisieren-ablauf-checkliste.webp',NULL,NULL,'published','2026-10-21T06:44:00.000Z','2026-10-22T00:17:07.905Z','Pressekonferenz organisieren: Ablauf und Checkliste','Pressekonferenz organisieren: Wann sie sich lohnt, wie Einladung, Ablauf und Pressemappe aussehen und welche Fehler zu vermeiden sind. Checkliste lesen.','Pressekonferenz organisieren','["Pressekonferenz organisieren","Pressekonferenz Ablauf","Presseeinladung","Pressemappe","pressekonferenz checkliste kmu","pressetermin uhrzeit","pressegespräch statt pressekonferenz","pressekonferenz livestream"]','Pressekonferenz organisieren: vorbereiteter Raum mit Podium und Mikrofonen in Klagenfurt','Photorealistic editorial photo of an empty press conference setup in a modern hotel meeting room in Klagenfurt, a small podium with microphones, rows of chairs, a blank projection screen, warm spotlights, no people, no text, no logos, no readable signs','[{"q":"Wann lohnt sich eine Pressekonferenz?","a":"Nur bei Themen mit hohem Nachrichtenwert, etwa großen Investitionen, Studien, Bilanzen oder Krisen."},{"q":"Wann sollte ich zur Pressekonferenz einladen?","a":"Etwa eine Woche vorher, mit einer Erinnerung ein bis zwei Tage vor dem Termin."},{"q":"Welche Uhrzeit ist für eine Pressekonferenz ideal?","a":"Meist Vormittage zwischen 9:30 und 11:00 Uhr an Wochentagen, idealerweise Dienstag bis Donnerstag."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
